-- ===================================================================
-- 20261001007500_plan_credits_fix.sql
-- ===================================================================
-- 007500: Sửa lỗi "Không tính được phí" khi tạo thử thách / giải chạy cho CLB Pro + báo giá biết gói đang dùng.
-- Sự cố (09/2026): CLB được admin bật Pro bằng tay (NO BEER NO RUN) → tạo thử thách báo "Không tính được phí".
-- Nguyên nhân: private.issue_credits (003800) có biến vòng lặp tên "c" trùng bí danh bảng "clubs c" trong câu lấy pro_until
-- → lỗi 'record "c" is not assigned yet' mỗi lần báo giá / tạo cho CLB Pro không có đơn mua gói.
-- Sửa: đổi tên biến. Báo giá quote_challenge trả thêm:
--   plan: gói đang hiệu lực của bên trả phí (VIP / CLB Pro) — để giao diện ẩn phần phí khi đã được gói bao;
--   best_pass_slots: quy mô lớn nhất mà lượt tạo miễn phí còn lại bao được.
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

create or replace function private.issue_credits(p_owner_type text, p_owner uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_plan jsonb := private.active_plan(p_owner);
  v_code text;
  v_until timestamptz;
  v_month timestamptz := private.vn_month_start(now());
  v_next timestamptz := private.vn_month_start(private.vn_month_start(now()) + interval '32 days');
  r_credit record;
  n integer := 0;
begin
  if v_plan <> 'null'::jsonb then
    v_code := v_plan->>'plan_code'; v_until := (v_plan->>'ends_at')::timestamptz;
  elsif p_owner_type = 'CLUB' and private.club_is_pro(p_owner) then           -- CLB Pro do admin bật tay
    v_code := 'CLUB_PRO'; v_until := coalesce((select cl.pro_until from public.clubs cl where cl.id = p_owner), v_next);
  else
    return 0;
  end if;
  for r_credit in select pc.capacity, pc.per_month from public.plan_credits pc where pc.plan_code = v_code loop
    insert into public.challenge_passes (owner_type, owner_id, max_slots, total, remaining, expires_at, note, source_key)
    values (p_owner_type, p_owner, r_credit.capacity, r_credit.per_month, r_credit.per_month, least(v_next, v_until),
            'Lượt tạo ' || coalesce((select p.name from public.plans p where p.code = v_code), v_code) || ' tháng '
              || to_char(v_month at time zone 'Asia/Ho_Chi_Minh', 'MM/YYYY'),
            'credit:' || p_owner || ':' || v_code || ':' || to_char(v_month at time zone 'Asia/Ho_Chi_Minh', 'YYYY-MM') || ':' || r_credit.capacity)
    on conflict (source_key) where source_key is not null do nothing;
    n := n + 1;
  end loop;
  return n;
end $$;

-- Gói đang hiệu lực của một người / CLB (CLB Pro bật tay cũng tính)
create or replace function private.plan_badge(p_owner uuid, p_is_club boolean) returns jsonb
language sql stable security definer set search_path = public as $$
  select case
    when private.active_plan(p_owner) <> 'null'::jsonb
      then jsonb_build_object('code', private.active_plan(p_owner)->>'plan_code', 'name', private.active_plan(p_owner)->>'name')
    when p_is_club and private.club_is_pro(p_owner)
      then jsonb_build_object('code', 'CLUB_PRO', 'name', coalesce((select p.name from public.plans p where p.code = 'CLUB_PRO'), 'CLB Pro'))
    else null end
$$;

create or replace function public.quote_challenge(p_max_slots integer, p_format text default 'RANKED', p_club_id uuid default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_slots integer := case when p_format = 'DUEL' then 2 when p_format = 'SOLO_GOAL' then 1 else greatest(coalesce(p_max_slots, 1), 1) end;
  v_fee integer := private.challenge_creation_fee(p_format = 'TEAM', v_slots, now(), now() + interval '1 day');
  v_payer uuid := case when p_club_id is not null and public.club_is_staff(p_club_id) then p_club_id else v_uid end;
  v_pass public.challenge_passes;
begin
  perform private.issue_credits(case when v_payer = v_uid then 'USER' else 'CLUB' end, v_payer);
  v_pass := (select t.x from (select x, row_number() over (order by x.expires_at nulls last, x.max_slots, x.created_at) as rn
                                from public.challenge_passes x
                               where x.owner_id = v_payer and x.remaining > 0 and x.max_slots >= v_slots
                                 and (x.expires_at is null or x.expires_at > now())) t where t.rn = 1);
  return jsonb_build_object(
    'fee', v_fee, 'tier', private.capacity_tier(v_slots), 'custom', private.capacity_tier(v_slots)->>'xu' is null,
    'payer', case when v_payer = v_uid then 'USER' else 'CLUB' end,
    'payer_balance', private.balance(v_payer), 'wallet_balance', private.balance(v_uid),
    'pass', case when v_pass.id is null or v_fee = 0 then null
                 else jsonb_build_object('id', v_pass.id, 'remaining', v_pass.remaining, 'max_slots', v_pass.max_slots,
                                         'expires_at', v_pass.expires_at, 'note', v_pass.note) end,
    'plan', private.plan_badge(v_payer, v_payer <> v_uid),
    'best_pass_slots', coalesce((select max(x.max_slots) from public.challenge_passes x
                                  where x.owner_id = v_payer and x.remaining > 0 and (x.expires_at is null or x.expires_at > now())), 0),
    'xu_vnd', (private.economy_config()->>'xuVnd')::numeric,
    'policy', private.economy_config());
end $$;

revoke all on function private.issue_credits(text, uuid), private.plan_badge(uuid, boolean) from public, anon, authenticated;
revoke all on function public.quote_challenge(integer, text, uuid) from public, anon;
grant execute on function public.quote_challenge(integer, text, uuid) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001007600_recurring_challenges.sql
-- ===================================================================
-- 007600: Thử thách tự lặp lại (hằng tuần / tháng / quý / năm) — học từ Tucana.
-- Ban quản trị tạo "Thử thách tuần của CLB" MỘT lần, bật lặp lại; trước khi kỳ hiện tại kết thúc ~1,5 ngày, cron hằng
-- ngày (/api/cron/challenges) tự tạo kỳ kế tiếp với cùng luật chơi (luật km/pace, mục tiêu tự đăng ký, nhịp tim, thể lệ).
-- Kỳ mới được tạo ĐÚNG như người tạo tự bấm tạo (gọi create_challenge_v2 dưới danh nghĩa người tạo): kiểm tra quyền
-- ban quản trị CLB, tính phí theo quy mô, dùng lượt miễn phí VIP / CLB Pro, trừ quỹ — không có đường tắt miễn phí.
-- Không tạo được (hết Xu / quỹ, không còn là ban quản trị…) → ghi lý do + báo người tạo; ngày sau cron thử lại.
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

alter table public.challenges add column if not exists recurrence text not null default 'NONE';
alter table public.challenges add column if not exists series_id uuid;
alter table public.challenges add column if not exists occurrence integer not null default 1;
alter table public.challenges add column if not exists recur_next_id uuid;
alter table public.challenges add column if not exists recur_error text;
alter table public.challenges drop constraint if exists challenges_recurrence_check;
alter table public.challenges add constraint challenges_recurrence_check check (recurrence in ('NONE', 'WEEKLY', 'MONTHLY', 'QUARTERLY', 'YEARLY'));
create index if not exists challenges_recurring_idx on public.challenges (end_date) where recurrence <> 'NONE' and recur_next_id is null;

create or replace function private.recurrence_step(p_recurrence text) returns interval
language sql immutable as $$
  select case p_recurrence when 'WEEKLY' then interval '7 days' when 'MONTHLY' then interval '1 month'
                           when 'QUARTERLY' then interval '3 months' when 'YEARLY' then interval '1 year' end
$$;

-- Bật / tắt lặp lại (ban quản trị thử thách). Tắt thì kỳ hiện tại vẫn chạy bình thường, chỉ không sinh kỳ mới.
create or replace function public.set_challenge_recurrence(p_challenge_id uuid, p_recurrence text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  c public.challenges := (select x from public.challenges x where x.id = p_challenge_id for update);
  v_rec text := upper(coalesce(p_recurrence, 'NONE'));
begin
  perform private.require_uid();
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not private.challenge_is_manager(c) then raise exception 'FORBIDDEN'; end if;
  if v_rec not in ('NONE', 'WEEKLY', 'MONTHLY', 'QUARTERLY', 'YEARLY') then raise exception 'INVALID_RECURRENCE'; end if;
  if v_rec <> 'NONE' and c.format = 'DUEL' then raise exception 'RECURRENCE_NOT_SUPPORTED'; end if;
  if v_rec <> 'NONE' and c.status = 'CANCELLED' then raise exception 'CHALLENGE_CLOSED'; end if;
  if v_rec <> 'NONE' and c.end_date - c.start_date > private.recurrence_step(v_rec) then raise exception 'RECURRENCE_TOO_SHORT'; end if;
  update public.challenges set recurrence = v_rec, series_id = coalesce(series_id, id), recur_error = null where id = c.id;
  return jsonb_build_object('recurrence', v_rec, 'series_id', coalesce(c.series_id, c.id));
end $$;

-- Tạo kỳ kế tiếp cho một thử thách lặp lại (gọi từ cron, quyền service_role)
create or replace function private.spawn_next_occurrence(p_id uuid) returns uuid
language plpgsql security definer set search_path = public, extensions as $$
declare
  c public.challenges := (select x from public.challenges x where x.id = p_id for update);
  v_step interval;
  v_start timestamptz;
  v_end timestamptz;
  v_base text;
  v_payload jsonb;
  v_old_claims text := current_setting('request.jwt.claims', true);
  v_old_sub text := current_setting('request.jwt.claim.sub', true);
  v_new uuid;
  v_n integer := 0;
begin
  if c.id is null or c.recurrence = 'NONE' or c.recur_next_id is not null or c.status = 'CANCELLED' or c.created_by is null then return null; end if;
  v_step := private.recurrence_step(c.recurrence);
  v_start := c.start_date + v_step;
  v_end := c.end_date + v_step;
  while v_end <= now() + interval '1 hour' and v_n < 60 loop          -- bỏ lỡ nhiều kỳ (cron dừng): nhảy tới kỳ còn hiệu lực
    v_start := v_start + v_step; v_end := v_end + v_step; v_n := v_n + 1;
  end loop;
  if c.format = 'TEAM' and v_start < now() + interval '15 minutes' then v_start := now() + interval '15 minutes'; end if;
  v_base := regexp_replace(c.title, '\s*·\s*Kỳ \d+$', '');
  v_payload := jsonb_build_object(
    'title', left(v_base, 108) || ' · Kỳ ' || (c.occurrence + 1), 'description', c.description, 'format', c.format,
    'objective', c.objective, 'game_mode', c.game_mode, 'target_value', c.target_value, 'min_km', c.min_km,
    'min_pace', c.min_pace, 'max_pace', c.max_pace, 'daily_cap_km', c.daily_cap_km,
    'start_date', v_start, 'end_date', v_end, 'max_slots', c.max_slots, 'audience', c.target_audience,
    'club_id', c.target_club_id, 'team_size', c.fixed_team_size, 'reward_xu', c.reward_xu,
    'reward_source', c.reward_source, 'reward_split', c.reward_split,
    'team_names', coalesce((select jsonb_agg(t.name order by t.position) from public.challenge_teams t where t.challenge_id = c.id), '[]'::jsonb));

  -- Tạo như chính người tạo bấm tạo: mọi kiểm tra quyền / phí / lượt / quỹ giữ nguyên
  perform set_config('request.jwt.claims', json_build_object('sub', c.created_by, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', c.created_by::text, true);
  begin
    v_new := (public.create_challenge_v2(v_payload, 'recur:' || c.id)->>'challenge_id')::uuid;
  exception when others then
    perform set_config('request.jwt.claims', coalesce(v_old_claims, ''), true);
    perform set_config('request.jwt.claim.sub', coalesce(v_old_sub, ''), true);
    if c.recur_error is distinct from sqlerrm then
      update public.challenges set recur_error = left(sqlerrm, 200) where id = c.id;
      perform private.notify(c.created_by, c.target_club_id, 'CHALLENGE_RECUR_FAILED', 'Chưa tạo được kỳ mới: ' || left(c.title, 80),
        case when sqlerrm like '%INSUFFICIENT%' then 'Ví / quỹ CLB không đủ Xu cho phí tạo. Nạp thêm hoặc giảm quy mô — hệ thống thử lại mỗi ngày.'
             when sqlerrm like '%FORBIDDEN%' then 'Bạn không còn là ban quản trị CLB. Tắt lặp lại hoặc nhờ ban quản trị tạo.'
             else 'Hệ thống thử lại mỗi ngày. Lý do: ' || left(sqlerrm, 120) end,
        '/challenges/' || c.id, null, true);
    end if;
    return null;
  end;
  perform set_config('request.jwt.claims', coalesce(v_old_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_old_sub, ''), true);

  -- Chép phần thiết lập thêm (nhịp tim, mục tiêu tự đăng ký, thể lệ) và nối chuỗi kỳ
  update public.challenges n set
    require_hr = c.require_hr, rules_info = c.rules_info, rules_updated_at = case when c.rules_info <> '{}'::jsonb then now() end,
    pledge_enabled = c.pledge_enabled, pledge_options = c.pledge_options, pledge_min_km = c.pledge_min_km,
    pledge_max_km = c.pledge_max_km, pledge_cap_pct = c.pledge_cap_pct, pledge_team_size = c.pledge_team_size,
    game_mode = case when c.pledge_enabled and c.format = 'TEAM' then 'TEAM_SUM' else n.game_mode end,
    recurrence = c.recurrence, series_id = coalesce(c.series_id, c.id), occurrence = c.occurrence + 1
  where n.id = v_new;
  update public.challenges set recur_next_id = v_new, recur_error = null, series_id = coalesce(series_id, id) where id = c.id;
  return v_new;
end $$;

create or replace function public.spawn_recurring_challenges() returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in select id from public.challenges
            where recurrence <> 'NONE' and recur_next_id is null and status <> 'CANCELLED'
              and end_date <= now() + interval '36 hours'
            order by end_date loop
    if private.spawn_next_occurrence(r.id) is not null then n := n + 1; end if;
  end loop;
  return n;
end $$;

-- Danh sách các kỳ trong một chuỗi (để xem lại kết quả kỳ trước)
create or replace function public.challenge_series(p_challenge_id uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'title', x.title, 'occurrence', x.occurrence, 'status', x.status,
                                              'start_date', x.start_date, 'end_date', x.end_date) order by x.occurrence desc), '[]'::jsonb)
    from public.challenges x
   where x.series_id = (select coalesce(c.series_id, c.id) from public.challenges c where c.id = p_challenge_id)
     and x.status <> 'CANCELLED'
$$;

revoke all on function private.recurrence_step(text), private.spawn_next_occurrence(uuid) from public, anon, authenticated;
revoke all on function public.set_challenge_recurrence(uuid, text), public.challenge_series(uuid), public.spawn_recurring_challenges() from public, anon;
grant execute on function public.set_challenge_recurrence(uuid, text), public.challenge_series(uuid) to authenticated;
revoke all on function public.spawn_recurring_challenges() from authenticated;
grant execute on function public.spawn_recurring_challenges() to service_role;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001007700_club_boost_days.sql
-- ===================================================================
-- 007700: "Ngày vàng" ×1,5 / ×2 / ×3 của CLB — học từ Tucana.
-- Ban quản trị CLB chọn ngày đặc biệt (sinh nhật CLB, 30/4, trước giải lớn…): km chạy trong ngày đó (giờ VN) được NHÂN
-- khi tính thử thách nội bộ CLB (thử thách tính theo km) và bảng xếp hạng CLB (club_leaderboard_v2: km thật + km thưởng).
-- KHÔNG nhân XP, Xu, huy hiệu, giải chạy ảo, CLB đấu CLB / thách đấu nhiều CLB (công bằng giữa các CLB; XP chỉ từ km thật).
-- Phải đặt trước (từ ngày mai trở đi) để mọi người biết và bài đã tính không bị đổi; tối đa 4 ngày vàng mỗi tháng.
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

create table if not exists public.club_boost_days (
  club_id uuid not null references public.clubs(id) on delete cascade,
  day date not null,
  multiplier numeric not null check (multiplier in (1.5, 2, 3)),
  title text not null check (char_length(title) between 2 and 80),
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (club_id, day)
);
alter table public.club_boost_days enable row level security;
revoke all on public.club_boost_days from anon, authenticated;

alter table public.challenge_progress_events add column if not exists boost numeric not null default 1;

create or replace function private.vn_today() returns date
language sql stable as $$ select (now() at time zone 'Asia/Ho_Chi_Minh')::date $$;

create or replace function private.club_boost(p_club uuid, p_day date) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce((select b.multiplier from public.club_boost_days b where b.club_id = p_club and b.day = p_day), 1)
$$;

-- Thử thách: bản 007000 + nhân km ngày vàng cho thử thách nội bộ CLB tính theo km
create or replace function private.challenge_apply_activity(p_activity_id uuid, p_only_participant uuid default null) returns integer
language plpgsql security definer set search_path = public as $$
declare
  a public.activities := (select x from public.activities x where x.id = p_activity_id);
  r record;
  v_day date;
  v_km numeric;
  v_already numeric;
  v_counted numeric;
  v_boost numeric;
  n integer := 0;
begin
  if a.id is null or a.user_id is null or a.validation_status is distinct from 'APPROVED'
     or not public.activity_is_countable(a.status, a.validation_status) or not a.shared then
    return 0;
  end if;
  v_km := greatest(coalesce(nullif(a.moving_distance_m, 0), a.distance_m, 0), 0) / 1000.0;
  v_day := (a.started_at at time zone 'Asia/Ho_Chi_Minh')::date;

  for r in
    select p.id as pid, c.*
      from public.challenge_participants p join public.challenges c on c.id = p.challenge_id
     where p.profile_id = a.user_id and p.status in ('JOINED', 'COMPLETED')
       and (p_only_participant is null or p.id = p_only_participant)
       and c.status = 'ACTIVE'
       and a.started_at >= c.start_date and a.started_at < c.end_date
  loop
    -- Luật: cự ly tối thiểu mỗi bài (trừ chuỗi ngày — cộng dồn trong ngày), khoảng pace, bắt buộc nhịp tim
    if r.objective <> 'STREAK_DAYS' and v_km < coalesce(r.min_km, 0) then continue; end if;
    if coalesce(a.avg_pace_s, 0) > 0 and (a.avg_pace_s < coalesce(r.min_pace, 0) * 60
                                          or a.avg_pace_s > coalesce(r.max_pace, 99) * 60) then continue; end if;
    if r.require_hr and coalesce(a.avg_heartrate, 0) <= 0 then continue; end if;

    v_counted := v_km * 1000;
    if coalesce(r.daily_cap_km, 0) > 0 then
      -- trần mỗi ngày tính trên km thật (chia lại hệ số đã nhân)
      v_already := (select coalesce(sum(e.counted_m / e.boost), 0) from public.challenge_progress_events e
                     where e.participant_id = r.pid and e.day = v_day and e.activity_id <> a.id);
      v_counted := least(v_counted, greatest(r.daily_cap_km * 1000 - v_already, 0));
    end if;
    v_boost := case when r.target_club_id is not null and r.objective = 'DISTANCE' then private.club_boost(r.target_club_id, v_day) else 1 end;

    insert into public.challenge_progress_events (challenge_id, participant_id, activity_id, day, distance_m, counted_m, moving_s, boost)
    values (r.id, r.pid, a.id, v_day, v_km * 1000, v_counted * v_boost, coalesce(a.moving_time_s, 0), v_boost)
    on conflict (participant_id, activity_id) do nothing;
    if found then
      perform private.challenge_recompute_participant(r.pid);
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;

-- BXH CLB kèm km thưởng ngày vàng (giữ nguyên club_leaderboard cũ để app bản cũ vẫn chạy)
create or replace function public.club_leaderboard_v2(p_club_id uuid, p_period text default 'WEEK') returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.club_is_member(p_club_id) then raise exception 'NOT_A_MEMBER'; end if;
  if upper(coalesce(p_period, '')) not in ('WEEK', 'MONTH', 'ALL') then raise exception 'INVALID_PERIOD'; end if;
  return (
    with totals as (
      select m.user_id, m.role,
             coalesce(sum(a.distance_m), 0)::numeric as distance_m,
             coalesce(sum(a.distance_m * (b.multiplier - 1)), 0)::numeric as bonus_m,
             count(a.id)::int as run_count,
             coalesce(sum(a.moving_time_s), 0)::bigint as moving_s
        from public.club_members m
        left join public.activities a
          on a.user_id = m.user_id and a.validation_status = 'APPROVED' and a.shared
         and coalesce(a.status, '') <> 'DELETED' and a.started_at >= private.period_start(p_period)
        left join public.club_boost_days b
          on b.club_id = p_club_id and b.day = (a.started_at at time zone 'Asia/Ho_Chi_Minh')::date
       where m.club_id = p_club_id and m.status = 'APPROVED'
       group by m.user_id, m.role
    ), ranked as (
      select (rank() over (order by t.distance_m + t.bonus_m desc))::int as rank, t.*, pr.avatar_url, coalesce(pr.level, 1)::int as level,
             private.display_name(t.user_id) as display_name
        from totals t join public.profiles pr on pr.id = t.user_id
    )
    select coalesce(jsonb_agg(jsonb_build_object('rank', r.rank, 'user_id', r.user_id, 'display_name', r.display_name,
             'avatar_url', r.avatar_url, 'level', r.level, 'role', r.role, 'distance_m', r.distance_m, 'bonus_m', r.bonus_m,
             'run_count', r.run_count, 'moving_s', r.moving_s)
             order by r.distance_m + r.bonus_m desc, r.run_count desc, r.display_name), '[]'::jsonb)
      from ranked r);
end $$;

-- Danh sách ngày vàng (30 ngày trước → 1 năm tới)
create or replace function public.club_boost_days(p_club_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.club_is_member(p_club_id) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('day', b.day, 'multiplier', b.multiplier, 'title', b.title,
                                                       'editable', b.day > private.vn_today()) order by b.day)
                     from public.club_boost_days b
                    where b.club_id = p_club_id and b.day between private.vn_today() - 30 and private.vn_today() + 366), '[]'::jsonb);
end $$;

create or replace function public.set_club_boost_day(p_club_id uuid, p_day date, p_multiplier numeric, p_title text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_title text := trim(coalesce(p_title, ''));
  v_name text := (select c.name from public.clubs c where c.id = p_club_id);
  v_new boolean := not exists (select 1 from public.club_boost_days b where b.club_id = p_club_id and b.day = p_day);
begin
  if not public.club_is_staff(p_club_id) then raise exception 'FORBIDDEN'; end if;
  if p_day is null or p_day <= private.vn_today() or p_day > private.vn_today() + 366 then raise exception 'BOOST_DAY_TOO_LATE'; end if;
  if p_multiplier is null or p_multiplier not in (1.5, 2, 3) then raise exception 'INVALID_MULTIPLIER'; end if;
  if char_length(v_title) not between 2 and 80 then raise exception 'INVALID_TITLE'; end if;
  if v_new and (select count(*) from public.club_boost_days b where b.club_id = p_club_id
                   and date_trunc('month', b.day) = date_trunc('month', p_day)) >= 4 then
    raise exception 'BOOST_DAYS_LIMIT';
  end if;
  insert into public.club_boost_days (club_id, day, multiplier, title, created_by) values (p_club_id, p_day, p_multiplier, v_title, v_uid)
  on conflict (club_id, day) do update set multiplier = excluded.multiplier, title = excluded.title;
  if v_new then
    perform private.notify_club(p_club_id, false, 'CLUB_BOOST_DAY',
      'Ngày vàng ×' || trim(to_char(p_multiplier, 'FM9.9')) || ' ở ' || v_name || ': ' || to_char(p_day, 'DD/MM'),
      v_title || ' — km chạy trong ngày được nhân ×' || trim(to_char(p_multiplier, 'FM9.9')) || ' trên BXH và thử thách của CLB.',
      '/clubs/' || p_club_id || '/leaderboard', v_uid);
  end if;
  return public.club_boost_days(p_club_id);
end $$;

create or replace function public.delete_club_boost_day(p_club_id uuid, p_day date) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform private.require_uid();
  if not public.club_is_staff(p_club_id) then raise exception 'FORBIDDEN'; end if;
  if p_day <= private.vn_today() then raise exception 'BOOST_DAY_TOO_LATE'; end if;
  delete from public.club_boost_days where club_id = p_club_id and day = p_day;
  return public.club_boost_days(p_club_id);
end $$;

revoke all on function private.vn_today(), private.club_boost(uuid, date) from public, anon, authenticated;
revoke all on function public.club_leaderboard_v2(uuid, text), public.club_boost_days(uuid), public.set_club_boost_day(uuid, date, numeric, text),
  public.delete_club_boost_day(uuid, date) from public, anon;
grant execute on function public.club_leaderboard_v2(uuid, text), public.club_boost_days(uuid), public.set_club_boost_day(uuid, date, numeric, text),
  public.delete_club_boost_day(uuid, date) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001007800_hall_of_fame_milestones.sql
-- ===================================================================
-- 007800: Đại sảnh danh vọng của CLB + cột mốc tự đăng bảng tin — học từ Tucana ("Marathon Hall of Fame", milestones).
-- • Cột mốc (user_milestones): 100 / 500 / 1.000 / 2.000 / 5.000 / 10.000 km tích luỹ, Half Marathon đầu tiên (≥ 21,1 km một bài),
--   Full Marathon đầu tiên (≥ 42,2 km), Ultra đầu tiên (≥ 50 km). Chạm mốc bằng một bài HỢP LỆ và ĐANG CHIA SẺ → mỗi CLB
--   runner đang là thành viên có một bài "cột mốc" trên bảng tin (thành viên vào cổ vũ / tặng quà như bài thường).
--   Mốc đã đạt trước khi chạy migration được ghi nhận lặng lẽ (không đăng bài dồn dập).
-- • Đại sảnh (club_hall_of_fame): người hoàn thành Full / Half Marathon, kỷ lục CLB 5K / 10K / 21K / 42K (ước tính từ bài chạy có
--   cự ly sát mốc), BXH km trong năm, cột mốc gần đây. Chỉ tính bài hợp lệ + đang chia sẻ.
-- • Lỗi ở phần này không bao giờ làm hỏng việc nhận bài chạy (ghi vào nhật ký lỗi 006900).
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

alter table public.club_posts drop constraint if exists club_posts_kind_check;
alter table public.club_posts add constraint club_posts_kind_check
  check (kind in ('POST', 'ANNOUNCEMENT', 'AUTO_RUN', 'AUTO_JOIN', 'RECAP', 'CHALLENGE', 'NEWS', 'MILESTONE'));

create table if not exists public.user_milestones (
  user_id uuid not null references public.profiles(id) on delete cascade,
  code text not null,
  activity_id uuid references public.activities(id) on delete set null,
  total_km numeric,
  reached_at timestamptz not null default now(),
  primary key (user_id, code)
);
alter table public.user_milestones enable row level security;
revoke all on public.user_milestones from anon, authenticated;

create or replace function private.milestone_defs() returns table (code text, need_m numeric, single boolean, label text, sort integer)
language sql immutable as $$
  values ('KM_100', 100000::numeric, false, 'đạt 100 km cùng RaceHub', 10), ('KM_500', 500000, false, 'đạt 500 km', 20),
         ('KM_1000', 1000000, false, 'cán mốc 1.000 km', 30), ('KM_2000', 2000000, false, 'cán mốc 2.000 km', 40),
         ('KM_5000', 5000000, false, 'cán mốc 5.000 km', 50), ('KM_10000', 10000000, false, 'cán mốc 10.000 km', 60),
         ('FIRST_HM', 21097.5, true, 'hoàn thành Half Marathon đầu tiên', 70),
         ('FIRST_FM', 42195, true, 'hoàn thành Full Marathon đầu tiên', 80),
         ('FIRST_ULTRA', 50000, true, 'chinh phục Ultra (≥ 50 km) đầu tiên', 90)
$$;

create or replace function private.countable_km_m(p_user uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(sum(x.distance_m), 0) from public.activities x
   where x.user_id = p_user and x.validation_status = 'APPROVED' and public.activity_is_countable(x.status, x.validation_status)
$$;

create or replace function private.check_milestones(p_user uuid, p_activity uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  a public.activities := (select x from public.activities x where x.id = p_activity);
  v_total numeric := private.countable_km_m(p_user);
  v_name text := private.display_name(p_user);
  d record;
  c record;
  n integer := 0;
begin
  if a.id is null or a.user_id <> p_user or not a.shared or a.validation_status is distinct from 'APPROVED'
     or not public.activity_is_countable(a.status, a.validation_status) then
    return 0;
  end if;
  for d in select * from private.milestone_defs() m
            where (not m.single and v_total >= m.need_m) or (m.single and coalesce(a.distance_m, 0) >= m.need_m)
            order by m.sort loop
    insert into public.user_milestones (user_id, code, activity_id, total_km) values (p_user, d.code, a.id, round(v_total / 1000, 1))
    on conflict (user_id, code) do nothing;
    if found then
      n := n + 1;
      for c in select cm.club_id from public.club_members cm where cm.user_id = p_user and cm.status = 'APPROVED' loop
        insert into public.club_posts (club_id, author_id, kind, title, body, activity_id, meta)
        values (c.club_id, p_user, 'MILESTONE', v_name || ' ' || d.label, '', a.id,
                jsonb_build_object('code', d.code, 'total_km', round(v_total / 1000, 1), 'distance_m', a.distance_m,
                                   'moving_s', a.moving_time_s, 'activity_id', a.id));
      end loop;
    end if;
  end loop;
  return n;
end $$;

create or replace function private.milestones_on_activity() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.user_id is not null and new.validation_status = 'APPROVED' and new.shared
     and public.activity_is_countable(new.status, new.validation_status) then
    begin
      perform private.check_milestones(new.user_id, new.id);
    exception when others then
      perform private.log_notify_error('milestone', 'MILESTONE', new.user_id, sqlstate, sqlerrm);
    end;
  end if;
  return null;
end $$;
drop trigger if exists trg_milestones_on_activity on public.activities;
create trigger trg_milestones_on_activity after insert or update of validation_status, status, shared on public.activities
  for each row execute function private.milestones_on_activity();

-- Ghi nhận lặng lẽ các mốc đã đạt trước đó (không đăng bài)
insert into public.user_milestones (user_id, code, total_km)
select t.user_id, m.code, round(t.total / 1000, 1)
  from (select x.user_id, sum(x.distance_m) as total from public.activities x
         where x.user_id is not null and x.validation_status = 'APPROVED' and public.activity_is_countable(x.status, x.validation_status)
         group by x.user_id) t
  join private.milestone_defs() m on not m.single and t.total >= m.need_m
on conflict (user_id, code) do nothing;
insert into public.user_milestones (user_id, code, activity_id)
select distinct on (x.user_id, m.code) x.user_id, m.code, x.id
  from public.activities x join private.milestone_defs() m on m.single and x.distance_m >= m.need_m
 where x.user_id is not null and x.validation_status = 'APPROVED' and public.activity_is_countable(x.status, x.validation_status)
 order by x.user_id, m.code, x.started_at
on conflict (user_id, code) do nothing;

-- Đại sảnh danh vọng của CLB
create or replace function public.club_hall_of_fame(p_club_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_year timestamptz := date_trunc('year', now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh';
begin
  if not public.club_is_member(p_club_id) then raise exception 'NOT_A_MEMBER'; end if;
  return (
    with mem as (
      select m.user_id from public.club_members m where m.club_id = p_club_id and m.status = 'APPROVED'
    ), runs as (
      select x.id, x.user_id, x.distance_m, x.moving_time_s, x.started_at
        from public.activities x join mem on mem.user_id = x.user_id
       where x.validation_status = 'APPROVED' and x.shared and public.activity_is_countable(x.status, x.validation_status)
         and coalesce(x.distance_m, 0) > 0
    ), finishers as (
      select r.user_id, d.kind, count(*)::int as times, min(r.started_at) as first_at,
             min(case when r.distance_m <= d.need * 1.06 and r.moving_time_s > 0 then round(r.moving_time_s * d.need / r.distance_m) end)::int as best_s
        from runs r join (values ('FM', 42195::numeric), ('HM', 21097.5)) d(kind, need) on r.distance_m >= d.need
       group by r.user_id, d.kind
    ), rec as (
      select d.label, d.need, r.user_id, min(round(r.moving_time_s * d.need / r.distance_m))::int as best_s
        from runs r join (values ('5K', 5000::numeric), ('10K', 10000), ('21K', 21097.5), ('42K', 42195)) d(label, need)
          on r.distance_m >= d.need and r.distance_m <= d.need * 1.05 and r.moving_time_s > 0
       group by d.label, d.need, r.user_id
    ), rec_ranked as (
      select rec.*, row_number() over (partition by rec.label order by rec.best_s) as rn from rec
    ), yr as (
      select r.user_id, sum(r.distance_m) as distance_m, count(*)::int as runs,
             row_number() over (order by sum(r.distance_m) desc) as rn
        from runs r where r.started_at >= v_year group by r.user_id
    ), ms as (
      select um.user_id, um.code, um.reached_at, row_number() over (order by um.reached_at desc) as rn
        from public.user_milestones um join mem on mem.user_id = um.user_id
       where um.activity_id is not null
    )
    select jsonb_build_object(
      'marathon', coalesce((select jsonb_agg(jsonb_build_object('user_id', f.user_id, 'name', private.display_name(f.user_id),
                    'avatar_url', p.avatar_url, 'times', f.times, 'first_at', f.first_at, 'best_s', f.best_s) order by f.first_at)
                  from finishers f join public.profiles p on p.id = f.user_id where f.kind = 'FM'), '[]'::jsonb),
      'half', coalesce((select jsonb_agg(jsonb_build_object('user_id', f.user_id, 'name', private.display_name(f.user_id),
                    'avatar_url', p.avatar_url, 'times', f.times, 'first_at', f.first_at, 'best_s', f.best_s) order by f.first_at)
                  from finishers f join public.profiles p on p.id = f.user_id where f.kind = 'HM'), '[]'::jsonb),
      'records', coalesce((select jsonb_agg(jsonb_build_object('label', rr.label, 'rank', rr.rn, 'user_id', rr.user_id,
                    'name', private.display_name(rr.user_id), 'avatar_url', p.avatar_url, 'best_s', rr.best_s) order by rr.need, rr.rn)
                  from rec_ranked rr join public.profiles p on p.id = rr.user_id where rr.rn <= 3), '[]'::jsonb),
      'year', coalesce((select jsonb_agg(jsonb_build_object('rank', y.rn, 'user_id', y.user_id, 'name', private.display_name(y.user_id),
                    'avatar_url', p.avatar_url, 'distance_m', y.distance_m, 'runs', y.runs) order by y.rn)
                  from yr y join public.profiles p on p.id = y.user_id where y.rn <= 10), '[]'::jsonb),
      'milestones', coalesce((select jsonb_agg(jsonb_build_object('user_id', ms.user_id, 'name', private.display_name(ms.user_id),
                    'avatar_url', p.avatar_url, 'code', ms.code, 'label', d.label, 'reached_at', ms.reached_at) order by ms.reached_at desc)
                  from ms join public.profiles p on p.id = ms.user_id join private.milestone_defs() d on d.code = ms.code
                 where ms.rn <= 20), '[]'::jsonb),
      'year_start', v_year));
end $$;

revoke all on function private.milestone_defs(), private.countable_km_m(uuid), private.check_milestones(uuid, uuid),
  private.milestones_on_activity() from public, anon, authenticated;
revoke all on function public.club_hall_of_fame(uuid) from public, anon;
grant execute on function public.club_hall_of_fame(uuid) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001007900_club_shop.sql
-- ===================================================================
-- 007900: Cửa hàng CLB — đặt áo, BIB, mũ… ngay trong app (học từ Tucana) mà RaceHub KHÔNG giữ tiền.
-- • Ban quản trị CLB đăng sản phẩm (ảnh, giá, size, hạn chốt đơn, số lượng giới hạn).
-- • Thành viên đặt → app hiện mã VietQR chuyển THẲNG vào tài khoản ngân hàng của CLB (đã khai ở tab Quỹ), nội dung CK
--   là mã đơn. RaceHub chỉ ghi đơn; ban quản trị đối soát sao kê rồi bấm "Đã nhận tiền" → "Đã giao".
-- • Bảng tổng hợp size cho xưởng may, xuất CSV. Không có thanh toán qua RaceHub, không thu phí trên đơn.
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

create table if not exists public.club_products (
  id uuid primary key default gen_random_uuid(),
  club_id uuid not null references public.clubs(id) on delete cascade,
  title text not null check (char_length(title) between 2 and 80),
  description text check (description is null or char_length(description) <= 1000),
  image_url text check (image_url is null or image_url ~ '^https://'),
  price_vnd integer not null check (price_vnd between 0 and 50000000),
  sizes text[] not null default '{}' check (cardinality(sizes) <= 12),
  stock integer check (stock is null or stock between 1 and 100000),
  max_per_order integer not null default 5 check (max_per_order between 1 and 50),
  order_deadline timestamptz,
  status text not null default 'OPEN' check (status in ('OPEN', 'CLOSED', 'HIDDEN')),
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists club_products_club_idx on public.club_products (club_id, created_at desc);

create table if not exists public.club_orders (
  id uuid primary key default gen_random_uuid(),
  club_id uuid not null references public.clubs(id) on delete cascade,
  product_id uuid not null references public.club_products(id) on delete cascade,
  user_id uuid references public.profiles(id) on delete set null,
  items jsonb not null,                        -- [{ "size": "M", "qty": 2 }]
  quantity integer not null check (quantity between 1 and 50),
  amount_vnd bigint not null check (amount_vnd >= 0),
  note text check (note is null or char_length(note) <= 200),
  code text not null unique,
  status text not null default 'PENDING' check (status in ('PENDING', 'PAID', 'DELIVERED', 'CANCELLED')),
  status_note text,
  paid_at timestamptz,
  delivered_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists club_orders_product_idx on public.club_orders (product_id, created_at desc);
create index if not exists club_orders_user_idx on public.club_orders (user_id, created_at desc);

alter table public.club_products enable row level security;
alter table public.club_orders enable row level security;
revoke all on public.club_products, public.club_orders from anon, authenticated;

create or replace function private.club_bank(p_club uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when c.bank_bin is null or c.bank_account_no is null then null
              else jsonb_build_object('bin', c.bank_bin, 'account_no', c.bank_account_no, 'account_name', c.bank_account_name) end
    from public.clubs c where c.id = p_club
$$;

create or replace function private.club_order_json(o public.club_orders) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', o.id, 'product_id', o.product_id, 'product_title', (select p.title from public.club_products p where p.id = o.product_id),
    'user_id', o.user_id, 'buyer', private.display_name(o.user_id), 'items', o.items, 'quantity', o.quantity, 'amount_vnd', o.amount_vnd,
    'note', o.note, 'code', o.code, 'status', o.status, 'status_note', o.status_note, 'paid_at', o.paid_at,
    'delivered_at', o.delivered_at, 'created_at', o.created_at)
$$;

-- Số đã đặt (không tính đơn huỷ) của một sản phẩm
create or replace function private.club_product_sold(p_product uuid) returns integer
language sql stable security definer set search_path = public as $$
  select coalesce(sum(o.quantity), 0)::int from public.club_orders o where o.product_id = p_product and o.status <> 'CANCELLED'
$$;

-- Cửa hàng: sản phẩm + đơn của tôi (+ số liệu cho ban quản trị)
create or replace function public.club_shop(p_club_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_staff boolean := public.club_is_staff(p_club_id);
begin
  if not public.club_is_member(p_club_id) then raise exception 'NOT_A_MEMBER'; end if;
  return jsonb_build_object(
    'is_staff', v_staff,
    'bank', private.club_bank(p_club_id),
    'products', coalesce((select jsonb_agg(to_jsonb(p) - 'created_by'
                   || jsonb_build_object('sold', private.club_product_sold(p.id),
                        'open', p.status = 'OPEN' and (p.order_deadline is null or p.order_deadline > now())
                                and (p.stock is null or private.club_product_sold(p.id) < p.stock),
                        'pending', case when v_staff then (select count(*) from public.club_orders o where o.product_id = p.id and o.status = 'PENDING') end,
                        'paid', case when v_staff then (select count(*) from public.club_orders o where o.product_id = p.id and o.status in ('PAID', 'DELIVERED')) end)
                   order by (p.status = 'OPEN') desc, p.created_at desc)
                  from public.club_products p where p.club_id = p_club_id and (p.status <> 'HIDDEN' or v_staff)), '[]'::jsonb),
    'my_orders', coalesce((select jsonb_agg(private.club_order_json(o) order by o.created_at desc)
                  from public.club_orders o where o.club_id = p_club_id and o.user_id = v_uid), '[]'::jsonb));
end $$;

create or replace function public.save_club_product(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_club uuid := coalesce((select x.club_id from public.club_products x where x.id = v_id), nullif(p->>'club_id', '')::uuid);
  v_sizes text[] := coalesce((select array_agg(left(trim(s), 10)) from jsonb_array_elements_text(coalesce(p->'sizes', '[]'::jsonb)) s where trim(s) <> ''), '{}');
begin
  if v_club is null or not public.club_is_staff(v_club) then raise exception 'FORBIDDEN'; end if;
  if char_length(trim(coalesce(p->>'title', ''))) not between 2 and 80 then raise exception 'INVALID_TITLE'; end if;
  if coalesce((p->>'price_vnd')::bigint, -1) not between 0 and 50000000 then raise exception 'INVALID_PRICE'; end if;
  if coalesce(p->>'status', 'OPEN') not in ('OPEN', 'CLOSED', 'HIDDEN') then raise exception 'INVALID_STATUS'; end if;
  if v_id is null then
    v_id := gen_random_uuid();
    insert into public.club_products (id, club_id, title, description, image_url, price_vnd, sizes, stock, max_per_order, order_deadline, status, created_by)
    values (v_id, v_club, trim(p->>'title'), nullif(trim(coalesce(p->>'description', '')), ''), nullif(p->>'image_url', ''), (p->>'price_vnd')::int,
            v_sizes, nullif(p->>'stock', '')::int, coalesce(nullif(p->>'max_per_order', '')::int, 5), nullif(p->>'order_deadline', '')::timestamptz,
            coalesce(p->>'status', 'OPEN'), v_uid);
    if coalesce(p->>'status', 'OPEN') = 'OPEN' then
      perform private.notify_club(v_club, false, 'CLUB_SHOP', 'Cửa hàng CLB: ' || trim(p->>'title'),
        'Mở đặt hàng' || case when nullif(p->>'order_deadline', '') is not null
                              then ' tới ' || to_char((p->>'order_deadline')::timestamptz at time zone 'Asia/Ho_Chi_Minh', 'DD/MM') else '' end || '. Xem và đặt ngay trong CLB.',
        '/clubs/' || v_club || '/shop', v_uid);
    end if;
  else
    update public.club_products set title = trim(p->>'title'), description = nullif(trim(coalesce(p->>'description', '')), ''),
      image_url = nullif(p->>'image_url', ''), price_vnd = (p->>'price_vnd')::int, sizes = v_sizes, stock = nullif(p->>'stock', '')::int,
      max_per_order = coalesce(nullif(p->>'max_per_order', '')::int, 5), order_deadline = nullif(p->>'order_deadline', '')::timestamptz,
      status = coalesce(p->>'status', 'OPEN'), updated_at = now()
    where id = v_id;
  end if;
  return v_id;
end $$;

create or replace function public.place_club_order(p_product_id uuid, p_items jsonb, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_new_id uuid;
  v_uid uuid := private.require_uid();
  pr public.club_products := (select x from public.club_products x where x.id = p_product_id for update);
  v_items jsonb;
  v_qty integer;
  v_code text;
  o public.club_orders;
begin
  if pr.id is null or pr.status = 'HIDDEN' then raise exception 'PRODUCT_NOT_FOUND'; end if;
  if not public.club_is_member(pr.club_id) then raise exception 'NOT_A_MEMBER'; end if;
  if pr.status <> 'OPEN' or (pr.order_deadline is not null and pr.order_deadline <= now()) then raise exception 'ORDERS_CLOSED'; end if;
  if private.club_bank(pr.club_id) is null then raise exception 'CLUB_BANK_MISSING'; end if;
  v_items := (select coalesce(jsonb_agg(jsonb_build_object('size', nullif(trim(coalesce(i->>'size', '')), ''), 'qty', (i->>'qty')::int)), '[]'::jsonb)
                from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i where coalesce((i->>'qty')::int, 0) > 0);
  v_qty := (select coalesce(sum((i->>'qty')::int), 0) from jsonb_array_elements(v_items) i);
  if v_qty < 1 or v_qty > pr.max_per_order then raise exception 'INVALID_QUANTITY'; end if;
  if cardinality(pr.sizes) > 0 and exists (select 1 from jsonb_array_elements(v_items) i where not ((i->>'size') = any (pr.sizes))) then
    raise exception 'INVALID_SIZE';
  end if;
  if pr.stock is not null and private.club_product_sold(pr.id) + v_qty > pr.stock then raise exception 'OUT_OF_STOCK'; end if;
  loop
    v_code := 'RH' || upper(substr(md5(gen_random_uuid()::text), 1, 6));
    exit when not exists (select 1 from public.club_orders x where x.code = v_code);
  end loop;
  v_new_id := gen_random_uuid();
  insert into public.club_orders (id, club_id, product_id, user_id, items, quantity, amount_vnd, note, code)
  values (v_new_id, pr.club_id, pr.id, v_uid, v_items, v_qty, pr.price_vnd::bigint * v_qty, nullif(left(trim(coalesce(p_note, '')), 200), ''), v_code);
  o := (select t from public.club_orders t where t.id = v_new_id);
  return private.club_order_json(o) || jsonb_build_object('bank', private.club_bank(pr.club_id));
end $$;

create or replace function public.cancel_my_club_order(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.club_orders := (select x from public.club_orders x where x.id = p_order_id for update);
begin
  if o.id is null or o.user_id is distinct from v_uid then raise exception 'ORDER_NOT_FOUND'; end if;
  if o.status <> 'PENDING' then raise exception 'ORDER_LOCKED'; end if;
  update public.club_orders set status = 'CANCELLED', status_note = 'Người đặt huỷ' where id = o.id;
  o := (select t from public.club_orders t where t.id = o.id);
  return private.club_order_json(o);
end $$;

-- Ban quản trị: danh sách đơn + tổng hợp size
create or replace function public.club_orders_admin(p_product_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare pr public.club_products := (select x from public.club_products x where x.id = p_product_id);
begin
  if pr.id is null or not public.club_is_staff(pr.club_id) then raise exception 'FORBIDDEN'; end if;
  return jsonb_build_object(
    'orders', coalesce((select jsonb_agg(private.club_order_json(o) order by o.created_at desc) from public.club_orders o where o.product_id = pr.id), '[]'::jsonb),
    'sizes', coalesce((select jsonb_agg(jsonb_build_object('size', t.size, 'qty', t.qty, 'paid_qty', t.paid_qty) order by t.size)
                from (select coalesce(i->>'size', '—') as size, sum((i->>'qty')::int) as qty,
                             sum(case when o.status in ('PAID', 'DELIVERED') then (i->>'qty')::int else 0 end) as paid_qty
                        from public.club_orders o cross join jsonb_array_elements(o.items) i
                       where o.product_id = pr.id and o.status <> 'CANCELLED'
                       group by coalesce(i->>'size', '—')) t), '[]'::jsonb),
    'totals', (select jsonb_build_object('orders', count(*) filter (where o.status <> 'CANCELLED'),
                        'paid_vnd', coalesce(sum(o.amount_vnd) filter (where o.status in ('PAID', 'DELIVERED')), 0),
                        'pending_vnd', coalesce(sum(o.amount_vnd) filter (where o.status = 'PENDING'), 0))
                 from public.club_orders o where o.product_id = pr.id));
end $$;

create or replace function public.set_club_order_status(p_order_id uuid, p_status text, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.club_orders := (select x from public.club_orders x where x.id = p_order_id for update);
  v_to text := upper(coalesce(p_status, ''));
begin
  if o.id is null or not public.club_is_staff(o.club_id) then raise exception 'FORBIDDEN'; end if;
  if not ((o.status = 'PENDING' and v_to in ('PAID', 'CANCELLED')) or (o.status = 'PAID' and v_to in ('DELIVERED', 'PENDING', 'CANCELLED'))
          or (o.status = 'DELIVERED' and v_to = 'PAID')) then
    raise exception 'INVALID_STATUS';
  end if;
  update public.club_orders set status = v_to, status_note = nullif(left(trim(coalesce(p_note, '')), 200), ''),
    paid_at = case when v_to = 'PAID' then coalesce(paid_at, now()) when v_to = 'PENDING' then null else paid_at end,
    delivered_at = case when v_to = 'DELIVERED' then now() when v_to = 'PAID' then null else delivered_at end
  where id = o.id;
  o := (select t from public.club_orders t where t.id = o.id);
  if o.user_id is not null and v_to in ('PAID', 'DELIVERED', 'CANCELLED') then
    perform private.notify(o.user_id, o.club_id, 'CLUB_SHOP',
      case v_to when 'PAID' then 'CLB đã nhận tiền đơn ' || o.code when 'DELIVERED' then 'Đơn ' || o.code || ' đã giao'
                else 'Đơn ' || o.code || ' đã bị huỷ' end,
      coalesce(nullif(trim(coalesce(p_note, '')), ''), (select p.title from public.club_products p where p.id = o.product_id)),
      '/clubs/' || o.club_id || '/shop', v_uid, true);
  end if;
  return private.club_order_json(o);
end $$;

revoke all on function private.club_bank(uuid), private.club_order_json(public.club_orders), private.club_product_sold(uuid) from public, anon, authenticated;
revoke all on function public.club_shop(uuid), public.save_club_product(jsonb), public.place_club_order(uuid, jsonb, text),
  public.cancel_my_club_order(uuid), public.club_orders_admin(uuid), public.set_club_order_status(uuid, text, text) from public, anon;
grant execute on function public.club_shop(uuid), public.save_club_product(jsonb), public.place_club_order(uuid, jsonb, text),
  public.cancel_my_club_order(uuid), public.club_orders_admin(uuid), public.set_club_order_status(uuid, text, text) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001008000_club_public_page.sql
-- ===================================================================
-- 008000: Trang công khai của CLB Pro — racehub.vn/c/<link-riêng> (học từ Tucana: "nhà" của CLB trên web).
-- Người chưa đăng nhập cũng xem được: tên, logo, màu, giới thiệu, số thành viên, năm thành lập, số buổi chạy nhóm /
-- thử thách đã tổ chức, nút Tham gia. KHÔNG có dữ liệu bài chạy / tên thành viên (quyền riêng tư + điều khoản Strava).
-- Chỉ CLB Pro còn hạn có link riêng (như resolve_club_slug của 002800).
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

create or replace function public.club_public_page(p_slug text) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', c.id, 'slug', c.slug, 'name', c.name, 'description', c.description, 'avatar_url', c.avatar_url,
    'accent_color', c.accent_color, 'member_count', c.member_count, 'join_policy', c.join_policy, 'founded_at', c.created_at,
    'events_held', (select count(*) from public.club_events e where e.club_id = c.id and e.starts_at < now()),
    'events_upcoming', (select count(*) from public.club_events e where e.club_id = c.id and e.starts_at >= now()),
    'challenges_held', (select count(*) from public.challenges ch where ch.target_club_id = c.id and ch.status <> 'CANCELLED'))
    from public.clubs c
   where c.slug = lower(trim(coalesce(p_slug, ''))) and c.plan = 'PRO' and (c.pro_until is null or c.pro_until > now())
$$;

revoke all on function public.club_public_page(text) from public;
grant execute on function public.club_public_page(text) to anon, authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001008100_club_pro_wall_exchange.sql
-- ===================================================================
-- 008100: (1) "Tường nhà" CLB Pro — ảnh bìa, khẩu hiệu, chủ đề màu; (2) Thư mời giao lưu offline giữa các CLB.
-- (1) CLB Pro còn hạn: ban quản trị đặt ảnh bìa (vị trí lấy nét dọc 0–100%), khẩu hiệu ≤ 80 ký tự, chủ đề nền. Hết Pro:
--     dữ liệu giữ nguyên nhưng giao diện quay về dạng thường (club_branding trả về active = false).
-- (2) Ban quản trị CLB A gửi thư mời tới CLB B (tiêu đề, giờ, địa điểm, cự ly, pace, số khách tối đa, lời mời). Ban quản trị
--     B nhận thông báo → Nhận lời / Từ chối (kèm lời nhắn). Nhận lời: tự tạo buổi chạy trong LỊCH của CẢ HAI CLB (RSVP, điểm
--     danh QR như buổi chạy thường), đăng bảng tin + báo thành viên hai bên. Huỷ sau khi nhận lời → huỷ cả hai buổi.
--     Chặn spam: mỗi cặp CLB chỉ 1 lời mời đang chờ; mỗi CLB tối đa 5 lời mời đang chờ.
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

-- ---------------------------------------------------------------------
-- 1. Tường nhà CLB Pro
-- ---------------------------------------------------------------------
alter table public.clubs add column if not exists cover_url text;
alter table public.clubs add column if not exists cover_position integer not null default 50;
alter table public.clubs add column if not exists tagline text;
alter table public.clubs add column if not exists theme text;
alter table public.clubs drop constraint if exists clubs_cover_url_check;
alter table public.clubs add constraint clubs_cover_url_check check (cover_url is null or cover_url ~ '^https://');
alter table public.clubs drop constraint if exists clubs_cover_position_check;
alter table public.clubs add constraint clubs_cover_position_check check (cover_position between 0 and 100);
alter table public.clubs drop constraint if exists clubs_tagline_check;
alter table public.clubs add constraint clubs_tagline_check check (tagline is null or char_length(tagline) <= 80);
alter table public.clubs drop constraint if exists clubs_theme_check;
alter table public.clubs add constraint clubs_theme_check check (theme is null or theme in ('AURORA', 'SUNSET', 'OCEAN', 'FOREST', 'GOLD', 'NIGHT'));
-- Cột mới của clubs mặc định không đọc được (003400) → mở rõ ràng
grant select (cover_url, cover_position, tagline, theme) on public.clubs to anon, authenticated;

create or replace function public.set_club_branding(p_club_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_cover text := nullif(trim(coalesce(p->>'cover_url', '')), '');
  v_tag text := nullif(trim(coalesce(p->>'tagline', '')), '');
  v_theme text := nullif(upper(trim(coalesce(p->>'theme', ''))), '');
begin
  if not public.club_is_staff(p_club_id) then raise exception 'FORBIDDEN'; end if;
  if not private.club_is_pro(p_club_id) and (v_cover is not null or v_tag is not null or v_theme is not null) then raise exception 'PRO_REQUIRED'; end if;
  if v_cover is not null and v_cover !~ '^https://' then raise exception 'INVALID_URL'; end if;
  if v_tag is not null and char_length(v_tag) > 80 then raise exception 'TAGLINE_TOO_LONG'; end if;
  if v_theme is not null and v_theme not in ('AURORA', 'SUNSET', 'OCEAN', 'FOREST', 'GOLD', 'NIGHT') then raise exception 'INVALID_THEME'; end if;
  update public.clubs set cover_url = v_cover, tagline = v_tag, theme = v_theme,
         cover_position = least(greatest(coalesce((p->>'cover_position')::int, 50), 0), 100)
   where id = p_club_id;
  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_uid, 'CLUB_BRANDING', p_club_id::text, jsonb_build_object('cover', v_cover is not null, 'tagline', v_tag, 'theme', v_theme));
  return jsonb_build_object('cover_url', v_cover, 'tagline', v_tag, 'theme', v_theme);
end $$;

-- Trang công khai (008000) thêm ảnh bìa / khẩu hiệu / chủ đề
create or replace function public.club_public_page(p_slug text) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', c.id, 'slug', c.slug, 'name', c.name, 'description', c.description, 'avatar_url', c.avatar_url,
    'accent_color', c.accent_color, 'member_count', c.member_count, 'join_policy', c.join_policy, 'founded_at', c.created_at,
    'cover_url', c.cover_url, 'cover_position', c.cover_position, 'tagline', c.tagline, 'theme', c.theme,
    'events_held', (select count(*) from public.club_events e where e.club_id = c.id and e.starts_at < now()),
    'events_upcoming', (select count(*) from public.club_events e where e.club_id = c.id and e.starts_at >= now()),
    'challenges_held', (select count(*) from public.challenges ch where ch.target_club_id = c.id and ch.status <> 'CANCELLED'))
    from public.clubs c
   where c.slug = lower(trim(coalesce(p_slug, ''))) and c.plan = 'PRO' and (c.pro_until is null or c.pro_until > now())
$$;

-- ---------------------------------------------------------------------
-- 2. Thư mời giao lưu giữa các CLB
-- ---------------------------------------------------------------------
alter table public.club_events add column if not exists exchange_id uuid;

create table if not exists public.club_exchange_invites (
  id uuid primary key default gen_random_uuid(),
  from_club uuid not null references public.clubs(id) on delete cascade,
  to_club uuid not null references public.clubs(id) on delete cascade,
  created_by uuid references public.profiles(id) on delete set null,
  title text not null check (char_length(title) between 3 and 80),
  message text check (message is null or char_length(message) <= 1000),
  starts_at timestamptz not null,
  duration_min integer not null default 90 check (duration_min between 15 and 720),
  location_name text not null check (char_length(location_name) between 2 and 120),
  lat double precision check (lat is null or lat between -90 and 90),
  lng double precision check (lng is null or lng between -180 and 180),
  distance_km numeric(5, 1) check (distance_km is null or (distance_km > 0 and distance_km <= 200)),
  pace_text text check (pace_text is null or char_length(pace_text) <= 40),
  guest_capacity integer check (guest_capacity is null or guest_capacity between 2 and 1000),
  status text not null default 'PENDING' check (status in ('PENDING', 'ACCEPTED', 'DECLINED', 'CANCELLED')),
  response_note text check (response_note is null or char_length(response_note) <= 300),
  responded_by uuid references public.profiles(id) on delete set null,
  responded_at timestamptz,
  host_event_id uuid references public.club_events(id) on delete set null,
  guest_event_id uuid references public.club_events(id) on delete set null,
  created_at timestamptz not null default now(),
  check (from_club <> to_club),
  check ((lat is null) = (lng is null))
);
create index if not exists club_exchange_from_idx on public.club_exchange_invites (from_club, created_at desc);
create index if not exists club_exchange_to_idx on public.club_exchange_invites (to_club, created_at desc);
alter table public.club_exchange_invites enable row level security;
revoke all on public.club_exchange_invites from anon, authenticated;

create or replace function private.exchange_json(x public.club_exchange_invites) returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(x) || jsonb_build_object(
    'from', (select jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
                                       'member_count', c.member_count) from public.clubs c where c.id = x.from_club),
    'to', (select jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
                                     'member_count', c.member_count) from public.clubs c where c.id = x.to_club),
    'sender_name', private.display_name(x.created_by), 'responder_name', private.display_name(x.responded_by))
$$;

create or replace function public.send_club_exchange(p_from_club uuid, p_to_club uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_new_id uuid;
  v_uid uuid := private.require_uid();
  v_start timestamptz := nullif(p->>'starts_at', '')::timestamptz;
  v_from text := (select c.name from public.clubs c where c.id = p_from_club);
  x public.club_exchange_invites;
begin
  if not public.club_is_staff(p_from_club) then raise exception 'FORBIDDEN'; end if;
  if p_to_club is null or p_to_club = p_from_club or not exists (select 1 from public.clubs c where c.id = p_to_club) then raise exception 'CLUB_NOT_FOUND'; end if;
  if v_start is null or v_start < now() + interval '2 hours' or v_start > now() + interval '180 days' then raise exception 'INVALID_TIME_RANGE'; end if;
  if exists (select 1 from public.club_exchange_invites e where e.from_club = p_from_club and e.to_club = p_to_club and e.status = 'PENDING') then
    raise exception 'EXCHANGE_PENDING';
  end if;
  if (select count(*) from public.club_exchange_invites e where e.from_club = p_from_club and e.status = 'PENDING') >= 5 then
    raise exception 'EXCHANGE_LIMIT';
  end if;
  v_new_id := gen_random_uuid();
  insert into public.club_exchange_invites (id, from_club, to_club, created_by, title, message, starts_at, duration_min, location_name,
                                            lat, lng, distance_km, pace_text, guest_capacity)
  values (v_new_id, p_from_club, p_to_club, v_uid, trim(coalesce(p->>'title', '')), nullif(trim(coalesce(p->>'message', '')), ''), v_start,
          coalesce(nullif(p->>'duration_min', '')::int, 90), trim(coalesce(p->>'location_name', '')),
          nullif(p->>'lat', '')::double precision, nullif(p->>'lng', '')::double precision,
          nullif(p->>'distance_km', '')::numeric, nullif(trim(coalesce(p->>'pace_text', '')), ''), nullif(p->>'guest_capacity', '')::int);
  x := (select t from public.club_exchange_invites t where t.id = v_new_id);
  perform private.notify_club(p_to_club, true, 'CLUB_EXCHANGE', v_from || ' mời CLB giao lưu: ' || x.title,
    to_char(x.starts_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM') || ' · ' || x.location_name || '. Mở thư mời để nhận lời.',
    '/clubs/' || p_to_club || '/exchange', v_uid);
  return private.exchange_json(x);
end $$;

create or replace function public.respond_club_exchange(p_invite_id uuid, p_accept boolean, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  x public.club_exchange_invites := (select i from public.club_exchange_invites i where i.id = p_invite_id for update);
  v_from text;
  v_to text;
  v_host uuid;
  v_guest uuid;
  v_desc text;
begin
  if x.id is null then raise exception 'EXCHANGE_NOT_FOUND'; end if;
  if not public.club_is_staff(x.to_club) then raise exception 'FORBIDDEN'; end if;
  if x.status <> 'PENDING' then raise exception 'EXCHANGE_CLOSED'; end if;
  if p_accept and x.starts_at <= now() then raise exception 'EXCHANGE_EXPIRED'; end if;
  v_from := (select c.name from public.clubs c where c.id = x.from_club);
  v_to := (select c.name from public.clubs c where c.id = x.to_club);
  if not p_accept then
    update public.club_exchange_invites set status = 'DECLINED', responded_by = v_uid, responded_at = now(),
           response_note = nullif(left(trim(coalesce(p_note, '')), 300), '') where id = x.id;
    x := (select t from public.club_exchange_invites t where t.id = x.id);
    perform private.notify_club(x.from_club, true, 'CLUB_EXCHANGE', v_to || ' chưa nhận lời giao lưu',
      coalesce(x.response_note, x.title), '/clubs/' || x.from_club || '/exchange', v_uid);
    return private.exchange_json(x);
  end if;

  v_desc := coalesce(x.message || E'\n\n', '') || 'Buổi giao lưu ' || v_from || ' × ' || v_to || '.';
  v_host := gen_random_uuid();
  insert into public.club_events (id, club_id, created_by, title, description, starts_at, duration_min, location_name, lat, lng,
                                  distance_km, pace_text, capacity, exchange_id)
  values (v_host, x.from_club, x.created_by, left('Giao lưu × ' || v_to, 80), left(v_desc, 1000), x.starts_at, x.duration_min, x.location_name,
          x.lat, x.lng, x.distance_km, x.pace_text, null, x.id);
  v_guest := gen_random_uuid();
  insert into public.club_events (id, club_id, created_by, title, description, starts_at, duration_min, location_name, lat, lng,
                                  distance_km, pace_text, capacity, exchange_id)
  values (v_guest, x.to_club, v_uid, left('Giao lưu × ' || v_from, 80), left(v_desc, 1000), x.starts_at, x.duration_min, x.location_name,
          x.lat, x.lng, x.distance_km, x.pace_text, x.guest_capacity, x.id);
  insert into private.club_event_secrets (event_id, secret) values (v_host, encode(extensions.gen_random_bytes(24), 'hex')), (v_guest, encode(extensions.gen_random_bytes(24), 'hex'))
  on conflict (event_id) do nothing;
  update public.club_exchange_invites set status = 'ACCEPTED', responded_by = v_uid, responded_at = now(),
         response_note = nullif(left(trim(coalesce(p_note, '')), 300), ''), host_event_id = v_host, guest_event_id = v_guest
   where id = x.id;
  x := (select t from public.club_exchange_invites t where t.id = x.id);

  insert into public.club_posts (club_id, author_id, kind, title, body, is_pinned)
  values (x.from_club, x.created_by, 'ANNOUNCEMENT', 'Giao lưu với ' || v_to || ' — ' || x.title,
          to_char(x.starts_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI "ngày" DD/MM') || ' tại ' || x.location_name || '. Đăng ký ở tab Lịch.', false),
         (x.to_club, v_uid, 'ANNOUNCEMENT', 'Giao lưu với ' || v_from || ' — ' || x.title,
          to_char(x.starts_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI "ngày" DD/MM') || ' tại ' || x.location_name || '. Đăng ký ở tab Lịch.', false);
  perform private.notify_club(x.from_club, false, 'CLUB_EXCHANGE', v_to || ' đã nhận lời giao lưu!', x.title || ' · ' || x.location_name,
    '/clubs/' || x.from_club || '/events/' || v_host, v_uid);
  perform private.notify_club(x.to_club, false, 'CLUB_EXCHANGE', 'Giao lưu với ' || v_from || ': ' || x.title, x.location_name || ' — đăng ký tham gia ở tab Lịch',
    '/clubs/' || x.to_club || '/events/' || v_guest, v_uid);
  return private.exchange_json(x);
end $$;

create or replace function public.cancel_club_exchange(p_invite_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  x public.club_exchange_invites := (select i from public.club_exchange_invites i where i.id = p_invite_id for update);
  v_reason text := trim(coalesce(p_reason, ''));
begin
  if x.id is null then raise exception 'EXCHANGE_NOT_FOUND'; end if;
  if not (public.club_is_staff(x.from_club) or (x.status = 'ACCEPTED' and public.club_is_staff(x.to_club))) then raise exception 'FORBIDDEN'; end if;
  if x.status not in ('PENDING', 'ACCEPTED') then raise exception 'EXCHANGE_CLOSED'; end if;
  if char_length(v_reason) < 3 then raise exception 'REASON_REQUIRED'; end if;
  update public.club_events set status = 'CANCELLED', cancel_reason = left('Huỷ giao lưu: ' || v_reason, 300)
   where id in (x.host_event_id, x.guest_event_id) and status <> 'CANCELLED';
  update public.club_exchange_invites set status = 'CANCELLED', response_note = left(v_reason, 300) where id = x.id;
  x := (select t from public.club_exchange_invites t where t.id = x.id);
  perform private.notify_club(case when public.club_is_staff(x.from_club) then x.to_club else x.from_club end, true, 'CLUB_EXCHANGE',
    'Đã huỷ giao lưu: ' || x.title, v_reason, '/clubs/' || case when public.club_is_staff(x.from_club) then x.to_club else x.from_club end || '/exchange', v_uid);
  return private.exchange_json(x);
end $$;

-- Thư mời của một CLB: gửi đi + nhận được (ban quản trị); thành viên chỉ thấy các buổi đã nhận lời
create or replace function public.club_exchanges(p_club_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_staff boolean := public.club_is_staff(p_club_id);
begin
  if not public.club_is_member(p_club_id) then raise exception 'NOT_A_MEMBER'; end if;
  return jsonb_build_object('is_staff', v_staff,
    'incoming', coalesce((select jsonb_agg(private.exchange_json(x) order by x.created_at desc) from public.club_exchange_invites x
                           where x.to_club = p_club_id and (v_staff or x.status = 'ACCEPTED')), '[]'::jsonb),
    'outgoing', coalesce((select jsonb_agg(private.exchange_json(x) order by x.created_at desc) from public.club_exchange_invites x
                           where x.from_club = p_club_id and (v_staff or x.status = 'ACCEPTED')), '[]'::jsonb));
end $$;

revoke all on function private.exchange_json(public.club_exchange_invites) from public, anon, authenticated;
revoke all on function public.set_club_branding(uuid, jsonb), public.send_club_exchange(uuid, uuid, jsonb), public.respond_club_exchange(uuid, boolean, text),
  public.cancel_club_exchange(uuid, text), public.club_exchanges(uuid) from public, anon;
grant execute on function public.set_club_branding(uuid, jsonb), public.send_club_exchange(uuid, uuid, jsonb), public.respond_club_exchange(uuid, boolean, text),
  public.cancel_club_exchange(uuid, text), public.club_exchanges(uuid) to authenticated;
revoke all on function public.club_public_page(text) from public;
grant execute on function public.club_public_page(text) to anon, authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001008200_club_challenge_quota.sql
-- ===================================================================
-- 008200: Hạn mức thử thách CLB theo gói (tham khảo Tucana: Free 30 thành viên / 2 sự kiện đồng thời → Pro → Enterprise)
-- và chặn "CLB một người" dùng miễn phí.
-- • Thử thách NỘI BỘ CLB (chỉ thành viên tham gia) được tạo MIỄN PHÍ trong hạn mức gói:
--     CLB Free: tối đa 2 thử thách đang diễn ra cùng lúc, mỗi thử thách ≤ 50 người,
--               và CLB phải có ≥ 5 thành viên THẬT (đã duyệt, có bài chạy hợp lệ trong 30 ngày).
--     CLB Pro : tối đa 20 thử thách đang diễn ra cùng lúc, mỗi thử thách ≤ 1.000 người, không cần điều kiện thành viên.
--   Ngoài hạn mức (CLB ít người chạy, quá số thử thách đồng thời, quá quy mô) → tính như cũ: lượt tạo của gói, rồi Xu từ quỹ CLB.
--   Không chặn ai: CLB vẫn tạo được, chỉ là mất phí → đủ động lực nâng Pro mà không làm hỏng việc của CLB.
-- • Thử thách công khai / cá nhân: giữ nguyên biểu phí theo quy mô + lượt VIP (một người lập CLB không lách được phí này,
--   vì thử thách CLB chỉ thành viên CLB mới vào được).
-- • Mọi con số nằm trong cấu hình kinh tế, khoá "clubChallenge" — admin sửa ở Quản trị → Chính sách.
-- • create_challenge_v2 được viết lại (bỏ SELECT INTO / LIMIT để chạy được trong SQL Editor), chỉ thêm phần hạn mức CLB.
-- Cần 0700, 2800, 3700, 3800, 7500. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại an toàn.

create or replace function private.club_challenge_policy() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('freeMinActiveMembers', 5, 'activeWindowDays', 30, 'freeMaxSlots', 50, 'freeMaxOpen', 2,
                            'proMaxSlots', 1000, 'proMaxOpen', 20)
         || coalesce(case when jsonb_typeof(private.economy_config()->'clubChallenge') = 'object'
                          then private.economy_config()->'clubChallenge' end, '{}'::jsonb)
$$;

-- Admin chỉnh hạn mức ở Quản trị → Chính sách: kiểm tra giá trị như 003700 + khoá clubChallenge
create or replace function private.valid_economy_v2(c jsonb) returns boolean
language sql immutable as $$
  select jsonb_typeof(c) = 'object'
     and coalesce((c->>'xuVnd')::numeric, 100) between 1 and 1000000
     and coalesce((c->>'xpPerKm')::numeric, 10) between 0 and 1000
     and coalesce((c->'run'->>'freeKm')::numeric, 2) between 0 and 100
     and coalesce((c->'run'->>'dailyCap')::numeric, 20) between 0 and 100000
     and not exists (select 1 from jsonb_array_elements(coalesce(c->'run'->'tiers', '[]'::jsonb)) e
                      where (e->>'upToKm')::numeric not between 0 and 1000 or (e->>'rate')::numeric not between 0 and 1000)
     and coalesce((c->>'checkinXu')::numeric, 1) between 0 and 10000
     and coalesce((c->>'giftDailyCapXu')::numeric, 20000) between 0 and 100000000
     and not exists (select 1 from jsonb_array_elements(coalesce(c->'capacityTiers', '[]'::jsonb)) e
                      where (e->>'max')::int not between 1 and 1000000 or (e->>'xu')::numeric not between 0 and 10000000)
     and not exists (select 1 from jsonb_array_elements(coalesce(c->'streakRewards', '[]'::jsonb)) e
                      where (e->>'weeks')::int not between 1 and 520 or (e->>'xu')::numeric not between 0 and 100000)
     and coalesce((c->'referral'->>'inviterXu')::numeric, 0) between 0 and 100000
     and coalesce((c->'referral'->>'refereeXu')::numeric, 0) between 0 and 100000
     and coalesce((c->'referral'->>'monthlyCap')::numeric, 10) between 0 and 1000
     and coalesce((c->'comeback'->>'xu')::numeric, 10) between 0 and 10000
     and coalesce((c->'comeback'->>'minRestDays')::numeric, 28) between 7 and 365
     and coalesce((c->'comeback'->>'cooldownDays')::numeric, 90) between 0 and 3650
     and coalesce((c->'game'->>'shieldPrice')::numeric, 200) between 0 and 100000
     and coalesce((c->'clubChallenge'->>'freeMinActiveMembers')::numeric, 5) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'activeWindowDays')::numeric, 30) between 1 and 365
     and coalesce((c->'clubChallenge'->>'freeMaxSlots')::numeric, 50) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'freeMaxOpen')::numeric, 2) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'proMaxSlots')::numeric, 1000) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'proMaxOpen')::numeric, 20) between 0 and 10000
$$;

-- Thành viên "thật": đã duyệt và có ít nhất một bài chạy hợp lệ trong N ngày gần nhất
create or replace function private.club_active_members(p_club uuid, p_days integer) returns integer
language sql stable security definer set search_path = public as $$
  select count(*)::int from public.club_members m
   where m.club_id = p_club and m.status = 'APPROVED'
     and exists (select 1 from public.activities x
                  where x.user_id = m.user_id and x.validation_status = 'APPROVED'
                    and public.activity_is_countable(x.status, x.validation_status)
                    and x.started_at >= now() - make_interval(days => greatest(p_days, 1)))
$$;

-- Thử thách nội bộ đang diễn ra (chưa kết thúc, chưa huỷ)
create or replace function private.club_open_challenges(p_club uuid) returns integer
language sql stable security definer set search_path = public as $$
  select count(*)::int from public.challenges c
   where c.target_club_id = p_club and c.target_audience = 'CLUB_ONLY' and c.status = 'ACTIVE' and c.end_date > now()
$$;

create or replace function private.club_challenge_quota_json(p_club uuid, p_slots integer) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  pol jsonb := private.club_challenge_policy();
  v_pro boolean := private.club_is_pro(p_club);
  v_active integer := private.club_active_members(p_club, (pol->>'activeWindowDays')::int);
  v_open integer := private.club_open_challenges(p_club);
  v_min integer := case when v_pro then 0 else (pol->>'freeMinActiveMembers')::int end;
  v_max_open integer := (pol->>case when v_pro then 'proMaxOpen' else 'freeMaxOpen' end)::int;
  v_max_slots integer := (pol->>case when v_pro then 'proMaxSlots' else 'freeMaxSlots' end)::int;
  v_reason text := null;
begin
  if v_active < v_min then v_reason := 'NEED_ACTIVE_MEMBERS';
  elsif v_open >= v_max_open then v_reason := 'OPEN_LIMIT';
  elsif coalesce(p_slots, 1) > v_max_slots then v_reason := 'SLOTS_LIMIT';
  end if;
  return jsonb_build_object('plan', case when v_pro then 'PRO' else 'FREE' end, 'eligible', v_reason is null, 'reason', v_reason,
    'active_members', v_active, 'min_active_members', v_min, 'active_window_days', (pol->>'activeWindowDays')::int,
    'open', v_open, 'max_open', v_max_open, 'max_slots', v_max_slots,
    'free', jsonb_build_object('min_active_members', (pol->>'freeMinActiveMembers')::int, 'max_open', (pol->>'freeMaxOpen')::int,
                               'max_slots', (pol->>'freeMaxSlots')::int),
    'pro', jsonb_build_object('max_open', (pol->>'proMaxOpen')::int, 'max_slots', (pol->>'proMaxSlots')::int));
end $$;

-- Hạn mức thử thách của CLB (thành viên xem được — hiện ở Cài đặt CLB và trình tạo thử thách)
create or replace function public.club_challenge_quota(p_club_id uuid, p_slots integer default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform private.require_uid();
  if not public.club_is_member(p_club_id) then raise exception 'NOT_A_MEMBER'; end if;
  return private.club_challenge_quota_json(p_club_id, p_slots);
end $$;

-- Báo giá: thử thách nội bộ trong hạn mức → phí 0, kèm hạn mức để giao diện giải thích
create or replace function public.quote_challenge(p_max_slots integer, p_format text default 'RANKED', p_club_id uuid default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_slots integer := case when p_format = 'DUEL' then 2 when p_format = 'SOLO_GOAL' then 1 else greatest(coalesce(p_max_slots, 1), 1) end;
  v_fee integer := private.challenge_creation_fee(p_format = 'TEAM', v_slots, now(), now() + interval '1 day');
  v_payer uuid := case when p_club_id is not null and public.club_is_staff(p_club_id) then p_club_id else v_uid end;
  v_quota jsonb := case when v_payer <> v_uid then private.club_challenge_quota_json(v_payer, v_slots) end;
  v_list_fee integer := v_fee;
  v_pass public.challenge_passes;
begin
  if v_fee > 0 and coalesce((v_quota->>'eligible')::boolean, false) then v_fee := 0; end if;
  perform private.issue_credits(case when v_payer = v_uid then 'USER' else 'CLUB' end, v_payer);
  v_pass := (select t.x from (select x, row_number() over (order by x.expires_at nulls last, x.max_slots, x.created_at) as rn
                                from public.challenge_passes x
                               where x.owner_id = v_payer and x.remaining > 0 and x.max_slots >= v_slots
                                 and (x.expires_at is null or x.expires_at > now())) t where t.rn = 1);
  return jsonb_build_object(
    'fee', v_fee, 'list_fee', v_list_fee, 'tier', private.capacity_tier(v_slots), 'custom', private.capacity_tier(v_slots)->>'xu' is null,
    'payer', case when v_payer = v_uid then 'USER' else 'CLUB' end,
    'payer_balance', private.balance(v_payer), 'wallet_balance', private.balance(v_uid),
    'pass', case when v_pass.id is null or v_fee = 0 then null
                 else jsonb_build_object('id', v_pass.id, 'remaining', v_pass.remaining, 'max_slots', v_pass.max_slots,
                                         'expires_at', v_pass.expires_at, 'note', v_pass.note) end,
    'plan', private.plan_badge(v_payer, v_payer <> v_uid),
    'club_quota', v_quota,
    'best_pass_slots', coalesce((select max(x.max_slots) from public.challenge_passes x
                                  where x.owner_id = v_payer and x.remaining > 0 and (x.expires_at is null or x.expires_at > now())), 0),
    'xu_vnd', (private.economy_config()->>'xuVnd')::numeric,
    'policy', private.economy_config());
end $$;

-- Tạo thử thách: như 000700, thêm hạn mức thử thách nội bộ CLB (008200)
create or replace function public.create_challenge_v2(p jsonb, p_idempotency_key text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid uuid := private.require_uid();
  v_key text := 'challenge_create:' || v_uid || ':' || coalesce(p_idempotency_key, '');
  v_existing uuid;
  v_title text := trim(coalesce(p->>'title', ''));
  v_desc text := nullif(trim(coalesce(p->>'description', '')), '');
  v_format text := coalesce(p->>'format', 'RANKED');
  v_objective text := coalesce(p->>'objective', 'DISTANCE');
  v_mode text := p->>'game_mode';
  v_target numeric := coalesce((p->>'target_value')::numeric, 0);
  v_min_km numeric := coalesce((p->>'min_km')::numeric, 0);
  v_min_pace numeric := coalesce((p->>'min_pace')::numeric, 3);
  v_max_pace numeric := coalesce((p->>'max_pace')::numeric, 15);
  v_cap numeric := nullif((p->>'daily_cap_km')::numeric, 0);
  v_start timestamptz := (p->>'start_date')::timestamptz;
  v_end timestamptz := (p->>'end_date')::timestamptz;
  v_slots integer := coalesce((p->>'max_slots')::int, 100);
  v_audience text := coalesce(p->>'audience', 'PUBLIC');
  v_club uuid := (p->>'club_id')::uuid;
  v_team_size integer := greatest(coalesce((p->>'team_size')::int, 0), 0);
  v_reward numeric := round(coalesce((p->>'reward_xu')::numeric, 0), 1);
  v_source text := coalesce(p->>'reward_source', 'NONE');
  v_split text := coalesce(p->>'reward_split', 'WINNER');
  v_teams text[];
  v_fee integer := 0;
  v_id uuid;
  v_code text;
  v_club_name text;
  i integer;
  m record;
  v_colors text[] := array['#b6ff3b', '#38bdf8', '#f472b6', '#fb923c', '#a78bfa', '#facc15', '#34d399', '#f87171'];
  v_payer uuid;
  v_pass uuid;
  v_fee_waived integer := 0;
  v_need_user numeric;
  v_need_club numeric;
  v_quota jsonb;
  v_free_reason text;
begin
  if p_idempotency_key is null or length(p_idempotency_key) < 8 then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
  if exists (select 1 from public.ledger_transactions lt where lt.idempotency_key = v_key) then
    v_existing := (select lt.campaign_id from public.ledger_transactions lt where lt.idempotency_key = v_key);
    return jsonb_build_object('challenge_id', v_existing, 'duplicate', true,
                              'invite_code', (select code from public.challenge_invites where challenge_id = v_existing));
  end if;

  -- Kiểm tra dữ liệu (không tin client)
  if char_length(v_title) not between 3 and 120 then raise exception 'INVALID_TITLE'; end if;
  if v_desc is not null and char_length(v_desc) > 2000 then raise exception 'DESC_TOO_LONG'; end if;
  if v_format not in ('SOLO_GOAL', 'RANKED', 'DUEL', 'TEAM', 'COLLECTIVE') then raise exception 'INVALID_FORMAT'; end if;
  if v_objective not in ('DISTANCE', 'RUNS', 'DURATION', 'STREAK_DAYS') then raise exception 'INVALID_OBJECTIVE'; end if;
  if v_start is null or v_end is null or v_end <= v_start then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_end - v_start > interval '366 days' or v_end - v_start < interval '1 hour' then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_end <= now() then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_target < 0 or v_min_km < 0 or v_min_km > 100 or coalesce(v_cap, 0) < 0 then raise exception 'INVALID_DISTANCE'; end if;
  if v_min_pace <= 0 or v_max_pace < v_min_pace or v_max_pace > 30 then raise exception 'INVALID_PACE'; end if;
  if v_format in ('SOLO_GOAL', 'COLLECTIVE') and v_target <= 0 then raise exception 'TARGET_REQUIRED'; end if;
  if v_objective = 'STREAK_DAYS' and (v_min_km <= 0 or v_target > ceil(extract(epoch from v_end - v_start) / 86400)) then
    raise exception 'INVALID_STREAK';
  end if;
  if v_format = 'DUEL' then v_slots := 2; end if;
  if v_slots not between 1 and 10000 then raise exception 'INVALID_MAX_SLOTS'; end if;

  if v_format = 'TEAM' then
    if v_mode not in ('TEAM_SUM', 'TEAM_AVG', 'TEAM_GAP', 'LAST_MEMBER') then raise exception 'INVALID_GAME_MODE'; end if;
    v_teams := (select array_agg(trim(t.v)) from jsonb_array_elements_text(coalesce(p->'team_names', '[]'::jsonb)) as t(v)
                 where trim(t.v) <> '');
    if coalesce(array_length(v_teams, 1), 0) not between 2 and 8 then raise exception 'INVALID_TEAMS'; end if;
    if exists (select 1 from unnest(v_teams) as t(v) where char_length(v) > 40) then raise exception 'INVALID_TEAMS'; end if;
    if v_start < now() + interval '10 minutes' then raise exception 'TEAM_START_TOO_SOON'; end if;
    if v_team_size > 0 then v_slots := least(v_slots, v_team_size * array_length(v_teams, 1)); end if;
  else
    v_mode := case v_objective when 'STREAK_DAYS' then 'STREAK' else 'ACCUMULATE' end;
  end if;

  if v_audience not in ('PUBLIC', 'CLUB_ONLY', 'INVITE_ONLY') then raise exception 'INVALID_AUDIENCE'; end if;
  if v_audience = 'CLUB_ONLY' then
    if v_club is null or not public.club_is_staff(v_club) then raise exception 'FORBIDDEN'; end if;
    v_club_name := (select cl.name from public.clubs cl where cl.id = v_club);
  else
    v_club := null;
  end if;

  if v_reward < 0 or v_reward > 100000 then raise exception 'INVALID_AMOUNT'; end if;
  if v_reward = 0 then v_source := 'NONE'; end if;
  if v_source not in ('NONE', 'CREATOR', 'CLUB') then raise exception 'INVALID_REWARD'; end if;
  if v_source = 'CLUB' and v_club is null then raise exception 'FORBIDDEN'; end if;
  if v_split not in ('WINNER', 'TOP3', 'FINISHERS', 'TEAM') then raise exception 'INVALID_REWARD'; end if;
  v_split := case when v_format = 'TEAM' then 'TEAM'
                  when v_format in ('SOLO_GOAL', 'COLLECTIVE') then 'FINISHERS'
                  when v_format = 'DUEL' then 'WINNER'
                  when v_split in ('WINNER', 'TOP3') then v_split else 'WINNER' end;

  -- Phí khởi tạo theo số người tối đa (Admin → Chính sách). Thử thách CLB trả bằng quỹ CLB.
  v_fee := private.challenge_creation_fee(v_format = 'TEAM', v_slots, v_start, v_end);
  v_payer := coalesce(v_club, v_uid);
  -- 008200: thử thách nội bộ CLB miễn phí trong hạn mức gói (Free / Pro) — khoá theo CLB để hai người tạo cùng lúc không vượt hạn mức
  if v_club is not null and v_fee > 0 then
    perform pg_advisory_xact_lock(hashtext('club_challenge:' || v_club));
    v_quota := private.club_challenge_quota_json(v_club, v_slots);
    if (v_quota->>'eligible')::boolean then v_fee_waived := v_fee; v_fee := 0; v_free_reason := v_quota->>'plan'; end if;
  end if;
  -- Vé tạo miễn phí (gói VIP / Pro, admin tặng): dùng vé sắp hết hạn trước, vé nhỏ nhất đủ số người
  if v_fee > 0 then
    v_pass := (select t.id from (select x.id, row_number() over (order by x.expires_at nulls last, x.max_slots, x.created_at) as rn
                                   from public.challenge_passes x
                                  where x.owner_id = v_payer and x.remaining > 0 and x.max_slots >= v_slots
                                    and (x.expires_at is null or x.expires_at > now())) t where t.rn = 1);
    if v_pass is not null then
      perform 1 from public.challenge_passes x where x.id = v_pass for update;
      v_fee_waived := v_fee; v_fee := 0;
    end if;
  end if;
  v_need_user := case when v_club is null then v_fee else 0 end + case when v_source = 'CREATOR' then v_reward else 0 end;
  v_need_club := case when v_club is not null then v_fee else 0 end + case when v_source = 'CLUB' then v_reward else 0 end;
  if v_need_user > private.balance(v_uid) then raise exception 'INSUFFICIENT_BALANCE'; end if;
  if v_club is not null and v_need_club > private.balance(v_club) then raise exception 'INSUFFICIENT_TREASURY'; end if;

  v_id := gen_random_uuid();
  insert into public.challenges (id, 
    title, description, format, objective, challenge_type, game_mode, target_type, target_value, target_km,
    min_km, min_pace, max_pace, daily_cap_km, fixed_team_size, min_members, target_audience, target_club_id,
    creator_role, start_date, end_date, reg_deadline, max_slots, calculated_fee, fee_charged,
    reward_xu, reward_source, reward_split, status, created_by)
  values (v_id, 
    v_title, v_desc, v_format, v_objective, case when v_format = 'TEAM' then 'TEAM' else 'INDIVIDUAL' end, v_mode,
    v_objective, v_target, case when v_objective = 'DISTANCE' then v_target else 0 end,
    v_min_km, v_min_pace, v_max_pace, v_cap, v_team_size, 1, v_audience, v_club,
    case when v_club is not null then 'CLUB' else 'MEMBER' end, v_start, v_end,
    case when v_format in ('TEAM') then v_start else v_end end, v_slots, v_fee, v_fee,
    v_reward, v_source, v_split, 'ACTIVE', v_uid);

  -- Phí + dấu idempotency (cùng khóa → trả lại thử thách này)
  if v_fee > 0 then
    perform private.ledger_post('CHALLENGE_CREATION_FEE', v_key,
      case when v_club is not null then 'Phí tạo thử thách (quỹ CLB)' else 'Phí khởi tạo thử thách' end, v_uid,
      private.debit_entries(v_payer, v_fee, private.system_account()), v_id);
    if v_club is not null then
      insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
      values (v_club, v_uid, -v_fee, 'SPEND', left('Phí tạo thử thách: ' || v_title, 200));
    end if;
  else
    insert into public.ledger_transactions (type, idempotency_key, reason, created_by, campaign_id)
    values ('CHALLENGE_CREATION_FEE', v_key,
            case v_free_reason when 'PRO' then 'Miễn phí (hạn mức CLB Pro)' when 'FREE' then 'Miễn phí (hạn mức CLB)' else 'Miễn phí' end, v_uid, v_id);
  end if;

  -- Ký quỹ giải thưởng (giữ ở tài khoản hệ thống tới khi tất toán)
  if v_source = 'CREATOR' then
    perform private.ledger_post('CHALLENGE_ESCROW', 'challenge_escrow:' || v_id, 'Treo thưởng thử thách', v_uid,
      private.debit_entries(v_uid, v_reward, private.system_account()), v_id);
  elsif v_source = 'CLUB' then
    perform private.ledger_post('CHALLENGE_ESCROW', 'challenge_escrow:' || v_id, 'Treo thưởng thử thách (quỹ CLB)', v_uid,
      private.debit_entries(v_club, v_reward, private.system_account()), v_id);
    insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
    values (v_club, v_uid, -v_reward, 'REWARD', left('Treo thưởng: ' || v_title, 200));
  end if;

  if v_format = 'TEAM' then
    for i in 1 .. array_length(v_teams, 1) loop
      insert into public.challenge_teams (challenge_id, name, color, position)
      values (v_id, v_teams[i], v_colors[1 + (i - 1) % array_length(v_colors, 1)], i);
    end loop;
  end if;

  if v_audience <> 'PUBLIC' or v_format = 'DUEL' then
    loop
      v_code := substr(md5(gen_random_uuid()::text), 1, 8);
      exit when not exists (select 1 from public.challenge_invites where code = v_code);
    end loop;
    insert into public.challenge_invites (challenge_id, code) values (v_id, v_code);
  end if;

  -- Người tạo tự vào (trừ thử thách đội — người tạo chọn đội sau — và thử thách CLB do ban quản trị tổ chức)
  if v_format <> 'TEAM' and v_club is null then
    insert into public.challenge_participants (challenge_id, profile_id, status) values (v_id, v_uid, 'JOINED');
  end if;

  -- Thử thách nội bộ CLB: đăng lên bảng tin + báo cả CLB
  if v_club is not null then
    insert into public.club_posts (club_id, author_id, kind, title, body, meta, is_pinned)
    values (v_club, v_uid, 'CHALLENGE', v_title, coalesce(v_desc, ''),
            jsonb_build_object('challenge_id', v_id, 'format', v_format, 'objective', v_objective,
                               'target_value', v_target, 'start_date', v_start, 'end_date', v_end,
                               'reward_xu', v_reward), false);
    for m in select user_id from public.club_members where club_id = v_club and status = 'APPROVED' loop
      perform private.notify(m.user_id, v_club, 'CHALLENGE_NEW',
        'Thử thách mới trong ' || coalesce(v_club_name, 'CLB') || ': ' || v_title,
        case when v_reward > 0 then 'Giải thưởng ' || v_reward || ' Xu. Vào tham gia ngay!' else 'Vào tham gia ngay!' end,
        '/challenges/' || v_id, v_uid, true);
    end loop;
  end if;

  if v_pass is not null then
    update public.challenge_passes set remaining = remaining - 1, updated_at = now() where id = v_pass and remaining > 0;
    update public.challenges set pass_id = v_pass where id = v_id;
  end if;

  return jsonb_build_object('challenge_id', v_id, 'fee', v_fee, 'fee_waived', v_fee_waived, 'pass_used', v_pass is not null, 'club_free', v_free_reason,
                            'invite_code', v_code, 'remaining_balance', private.balance(v_uid));
end $$;
-- Quyền lợi CLB Pro hiển thị (chỉ sửa khi admin chưa đổi câu chữ gốc)
update public.plans set perks = '["Thử thách nội bộ miễn phí: tới 20 thử thách cùng lúc, mỗi thử thách tới 1.000 người", "Không giới hạn quản trị viên", "Tường nhà CLB: ảnh bìa, khẩu hiệu, chủ đề màu", "Link mời riêng + trang công khai /c/tên-clb", "Báo cáo chuyên cần xuất Excel", "Cửa hàng CLB, giao lưu CLB"]'::jsonb
 where code = 'CLUB_PRO'
   and perks = '["2 lượt tạo thử thách ≤100 người / tháng", "Không giới hạn quản trị viên", "Link mời riêng /c/tên-clb", "Báo cáo chuyên cần xuất Excel", "Ví CLB, thương hiệu CLB"]'::jsonb;

revoke all on function private.club_challenge_policy(), private.club_active_members(uuid, integer), private.club_open_challenges(uuid),
  private.club_challenge_quota_json(uuid, integer) from public, anon, authenticated;
revoke all on function public.club_challenge_quota(uuid, integer), public.quote_challenge(integer, text, uuid),
  public.create_challenge_v2(jsonb, text) from public, anon;
grant execute on function public.club_challenge_quota(uuid, integer), public.quote_challenge(integer, text, uuid),
  public.create_challenge_v2(jsonb, text) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001008300_organizations.sql
-- ===================================================================
-- 008300: RaceHub Doanh nghiệp / Liên CLB (gói Enterprise — báo giá riêng, tham khảo Tucana Free → Pro → Enterprise).
-- Khách hàng: doanh nghiệp (phong trào sức khoẻ nhân viên), liên đoàn / hệ thống nhiều CLB, trường học.
-- • Tổ chức (organizations): thương hiệu riêng (logo, ảnh bìa, chủ đề), đơn vị con (phòng ban / chi nhánh / lớp),
--   thành viên vào bằng mã mời (tự duyệt hoặc chờ duyệt), giới hạn số chỗ (seat) theo hợp đồng, thời hạn gói.
-- • CLB thành viên (org_clubs): tổ chức mời CLB, ban quản trị CLB đồng ý. Gói có "tài trợ CLB Pro" → CLB thành viên
--   tự lên Pro tới hết hạn hợp đồng; rời tổ chức / hết hạn → trả lại gói cũ của CLB.
-- • Chiến dịch (org_campaigns): tổng km / số buổi / số ngày chạy trong khoảng thời gian, mục tiêu chung + mục tiêu mỗi người;
--   BXH cá nhân, theo đơn vị, theo CLB. Người tham gia = thành viên tổ chức + thành viên các CLB thuộc tổ chức.
--   Chỉ tính bài HỢP LỆ + ĐANG CHIA SẺ (tắt chia sẻ bài nào thì bài đó không vào BXH tổ chức).
-- • Báo cáo cho bộ phận nhân sự / ban tổ chức: km, số buổi, số ngày chạy của từng người trong khoảng ngày (xuất CSV ở giao diện).
-- • Yêu cầu báo giá (org_leads): gửi được cả khi chưa đăng nhập (trang /doanh-nghiep), admin xử lý ở Quản trị → Doanh nghiệp.
-- • RaceHub không giữ tiền: hợp đồng + hoá đơn ngoài app; admin bật / gia hạn gói, có nhật ký.
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

-- ---------------------------------------------------------------------
-- 1. Bảng
-- ---------------------------------------------------------------------
create table if not exists public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 120),
  kind text not null default 'COMPANY' check (kind in ('COMPANY', 'FEDERATION', 'SCHOOL', 'OTHER')),
  description text check (description is null or char_length(description) <= 2000),
  logo_url text check (logo_url is null or logo_url ~ '^https://'),
  cover_url text check (cover_url is null or cover_url ~ '^https://'),
  cover_position integer not null default 50 check (cover_position between 0 and 100),
  tagline text check (tagline is null or char_length(tagline) <= 80),
  theme text check (theme is null or theme in ('AURORA', 'SUNSET', 'OCEAN', 'FOREST', 'GOLD', 'NIGHT')),
  invite_code text not null unique,
  join_policy text not null default 'APPROVAL' check (join_policy in ('OPEN', 'APPROVAL')),
  unit_label text not null default 'Phòng ban' check (char_length(unit_label) between 2 and 30),
  allow_self_unit boolean not null default true,
  seat_limit integer not null default 50 check (seat_limit between 2 and 100000),
  club_limit integer not null default 0 check (club_limit between 0 and 10000),
  include_club_pro boolean not null default false,
  status text not null default 'ACTIVE' check (status in ('ACTIVE', 'SUSPENDED')),
  active_until timestamptz,
  legal_name text check (legal_name is null or char_length(legal_name) <= 200),
  tax_code text check (tax_code is null or char_length(tax_code) <= 20),
  contact_name text check (contact_name is null or char_length(contact_name) <= 80),
  contact_phone text check (contact_phone is null or char_length(contact_phone) <= 20),
  contact_email text check (contact_email is null or char_length(contact_email) <= 120),
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create table if not exists public.org_units (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  sort integer not null default 0,
  created_at timestamptz not null default now()
);
create unique index if not exists org_units_name_key on public.org_units (org_id, lower(name));

create table if not exists public.org_members (
  org_id uuid not null references public.organizations(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  role text not null default 'MEMBER' check (role in ('OWNER', 'ADMIN', 'MEMBER')),
  status text not null default 'PENDING' check (status in ('PENDING', 'APPROVED')),
  unit_id uuid references public.org_units(id) on delete set null,
  employee_code text check (employee_code is null or char_length(employee_code) <= 40),
  joined_at timestamptz not null default now(),
  primary key (org_id, user_id)
);
create index if not exists org_members_user_idx on public.org_members (user_id);

create table if not exists public.org_clubs (
  org_id uuid not null references public.organizations(id) on delete cascade,
  club_id uuid not null references public.clubs(id) on delete cascade,
  status text not null default 'PENDING' check (status in ('PENDING', 'APPROVED')),
  invited_by uuid references public.profiles(id) on delete set null,
  responded_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  pro_granted boolean not null default false,
  prev_plan text,
  prev_pro_until timestamptz,
  granted_until timestamptz,
  primary key (org_id, club_id)
);
create unique index if not exists org_clubs_one_org on public.org_clubs (club_id) where status = 'APPROVED';

create table if not exists public.org_campaigns (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  title text not null check (char_length(title) between 3 and 120),
  description text check (description is null or char_length(description) <= 2000),
  metric text not null default 'DISTANCE' check (metric in ('DISTANCE', 'RUNS', 'ACTIVE_DAYS')),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  goal_total numeric check (goal_total is null or goal_total > 0),
  goal_per_person numeric check (goal_per_person is null or goal_per_person > 0),
  min_run_km numeric not null default 1 check (min_run_km between 0 and 100),
  status text not null default 'ACTIVE' check (status in ('ACTIVE', 'CANCELLED')),
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  check (ends_at > starts_at)
);
create index if not exists org_campaigns_org_idx on public.org_campaigns (org_id, starts_at desc);

create table if not exists public.org_leads (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.profiles(id) on delete set null,
  contact_name text not null check (char_length(contact_name) between 2 and 80),
  org_name text not null check (char_length(org_name) between 2 and 120),
  kind text not null default 'COMPANY' check (kind in ('COMPANY', 'FEDERATION', 'SCHOOL', 'OTHER')),
  size integer check (size is null or size between 1 and 1000000),
  phone text not null check (phone ~ '^[0-9+ .()-]{8,20}$'),
  email text check (email is null or char_length(email) <= 120),
  note text check (note is null or char_length(note) <= 1000),
  status text not null default 'NEW' check (status in ('NEW', 'CONTACTED', 'WON', 'LOST')),
  admin_note text check (admin_note is null or char_length(admin_note) <= 1000),
  org_id uuid references public.organizations(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists org_leads_created_idx on public.org_leads (created_at desc);

alter table public.organizations enable row level security;
alter table public.org_units enable row level security;
alter table public.org_members enable row level security;
alter table public.org_clubs enable row level security;
alter table public.org_campaigns enable row level security;
alter table public.org_leads enable row level security;
revoke all on public.organizations, public.org_units, public.org_members, public.org_clubs, public.org_campaigns, public.org_leads
  from anon, authenticated;

-- ---------------------------------------------------------------------
-- 2. Quyền trong tổ chức (admin hệ thống toàn quyền, như CLB — 007100)
-- ---------------------------------------------------------------------
create or replace function private.org_role(p_org uuid) returns text
language sql stable security definer set search_path = public as $$
  select case when public.is_system_admin() then 'OWNER'
              else (select m.role from public.org_members m
                     where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'APPROVED') end
$$;

create or replace function public.org_is_admin(p_org uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(private.org_role(p_org) in ('OWNER', 'ADMIN'), false)
$$;

create or replace function public.org_is_member(p_org uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select private.org_role(p_org) is not null
$$;

create or replace function private.org_active(p_org uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.organizations o
                  where o.id = p_org and o.status = 'ACTIVE' and (o.active_until is null or o.active_until > now()))
$$;

create or replace function private.org_seats_used(p_org uuid) returns integer
language sql stable security definer set search_path = public as $$
  select count(*)::int from public.org_members m where m.org_id = p_org and m.status = 'APPROVED'
$$;

create or replace function private.org_new_code() returns text
language sql volatile security definer set search_path = public, extensions as $$
  select upper(substr(encode(extensions.gen_random_bytes(8), 'hex'), 1, 8))
$$;

-- Thông tin công khai trong tổ chức (thành viên / người có mã mời xem được)
create or replace function private.org_json(o public.organizations) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', o.id, 'name', o.name, 'kind', o.kind, 'description', o.description, 'logo_url', o.logo_url,
    'cover_url', o.cover_url, 'cover_position', o.cover_position, 'tagline', o.tagline, 'theme', o.theme,
    'join_policy', o.join_policy, 'unit_label', o.unit_label, 'allow_self_unit', o.allow_self_unit,
    'status', o.status, 'active_until', o.active_until, 'active', private.org_active(o.id),
    'seat_limit', o.seat_limit, 'seats_used', private.org_seats_used(o.id), 'club_limit', o.club_limit,
    'include_club_pro', o.include_club_pro,
    'club_count', (select count(*)::int from public.org_clubs oc where oc.org_id = o.id and oc.status = 'APPROVED'),
    'created_at', o.created_at)
$$;

-- Người tham gia chiến dịch / báo cáo: thành viên trực tiếp + thành viên các CLB thuộc tổ chức
create or replace function private.org_people(p_org uuid)
returns table (user_id uuid, unit_id uuid, direct boolean)
language sql stable security definer set search_path = public as $$
  select p.user_id, max(p.unit_id::text)::uuid, bool_or(p.direct)
    from (select m.user_id, m.unit_id, true as direct from public.org_members m where m.org_id = p_org and m.status = 'APPROVED'
          union all
          select cm.user_id, null::uuid, false from public.org_clubs oc
            join public.club_members cm on cm.club_id = oc.club_id and cm.status = 'APPROVED'
           where oc.org_id = p_org and oc.status = 'APPROVED') p
   group by p.user_id
$$;

-- Số liệu chạy của một người trong khoảng thời gian (bài hợp lệ + đang chia sẻ, từ min_km mỗi bài)
create or replace function private.org_person_stats(p_user uuid, p_from timestamptz, p_to timestamptz, p_min_km numeric)
returns table (km numeric, runs integer, active_days integer)
language sql stable security definer set search_path = public as $$
  select coalesce(round(sum(x.distance_m) / 1000.0, 2), 0), count(*)::int,
         count(distinct (x.started_at at time zone 'Asia/Ho_Chi_Minh')::date)::int
    from public.activities x
   where x.user_id = p_user and x.validation_status = 'APPROVED' and x.shared
     and public.activity_is_countable(x.status, x.validation_status)
     and x.started_at >= p_from and x.started_at < p_to and coalesce(x.distance_m, 0) >= coalesce(p_min_km, 0) * 1000
$$;

-- ---------------------------------------------------------------------
-- 3. CLB Pro do tổ chức tài trợ: cấp khi CLB thuộc tổ chức đang hiệu lực + gói có tài trợ; trả lại gói cũ khi thôi
-- ---------------------------------------------------------------------
create or replace function private.org_sync_club_pro(p_org uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  o public.organizations := (select x from public.organizations x where x.id = p_org);
  v_on boolean := o.id is not null and o.include_club_pro and private.org_active(p_org);
  r record;
  v_until timestamptz;
  n integer := 0;
begin
  for r in select oc.*, c.plan, c.pro_until from public.org_clubs oc join public.clubs c on c.id = oc.club_id
            where oc.org_id = p_org loop
    if v_on and r.status = 'APPROVED' then
      v_until := case when r.pro_granted and r.prev_plan = 'PRO' and r.prev_pro_until is null then null
                      when not r.pro_granted and r.plan = 'PRO' and r.pro_until is null then null
                      when o.active_until is null then null
                      else greatest(coalesce(case when r.pro_granted then r.prev_pro_until else r.pro_until end, now()), o.active_until) end;
      update public.org_clubs set pro_granted = true, granted_until = v_until,
             prev_plan = case when r.pro_granted then r.prev_plan else r.plan end,
             prev_pro_until = case when r.pro_granted then r.prev_pro_until else r.pro_until end
       where org_id = r.org_id and club_id = r.club_id;
      update public.clubs set plan = 'PRO', pro_until = v_until where id = r.club_id;
      n := n + 1;
    elsif r.pro_granted then
      -- Trả lại gói cũ, trừ khi CLB đã tự gia hạn dài hơn phần tổ chức cấp
      if r.plan = 'PRO' and r.pro_until is not distinct from r.granted_until then
        update public.clubs set plan = coalesce(r.prev_plan, 'FREE'),
               pro_until = case when coalesce(r.prev_plan, 'FREE') = 'PRO' then r.prev_pro_until end
         where id = r.club_id;
      end if;
      update public.org_clubs set pro_granted = false, granted_until = null, prev_plan = null, prev_pro_until = null
       where org_id = r.org_id and club_id = r.club_id;
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------------
-- 4. Yêu cầu báo giá (khách chưa đăng nhập cũng gửi được)
-- ---------------------------------------------------------------------
create or replace function public.request_enterprise_quote(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_phone text := regexp_replace(trim(coalesce(p->>'phone', '')), '\s+', ' ', 'g');
  v_id uuid;
  a record;
begin
  if char_length(trim(coalesce(p->>'contact_name', ''))) < 2 then raise exception 'NAME_REQUIRED'; end if;
  if char_length(trim(coalesce(p->>'org_name', ''))) < 2 then raise exception 'ORG_NAME_REQUIRED'; end if;
  if v_phone !~ '^[0-9+ .()-]{8,20}$' then raise exception 'INVALID_PHONE'; end if;
  if (select count(*) from public.org_leads l where l.phone = v_phone and l.created_at > now() - interval '1 day') >= 3 then
    raise exception 'RATE_LIMITED';
  end if;
  v_id := gen_random_uuid();
  insert into public.org_leads (id, user_id, contact_name, org_name, kind, size, phone, email, note)
  values (v_id, auth.uid(), left(trim(p->>'contact_name'), 80), left(trim(p->>'org_name'), 120),
          case when p->>'kind' in ('COMPANY', 'FEDERATION', 'SCHOOL', 'OTHER') then p->>'kind' else 'OTHER' end,
          case when coalesce(p->>'size', '') ~ '^[0-9]{1,7}$' then greatest((p->>'size')::int, 1) end, v_phone,
          nullif(left(trim(coalesce(p->>'email', '')), 120), ''), nullif(left(trim(coalesce(p->>'note', '')), 1000), ''));
  for a in select pr.id from public.profiles pr where pr.role = 'SYSTEM_ADMIN' loop
    perform private.notify(a.id, null, 'ENTERPRISE_LEAD', 'Yêu cầu báo giá Doanh nghiệp: ' || left(trim(p->>'org_name'), 80),
      left(trim(p->>'contact_name'), 80) || ' · ' || v_phone, '/admin?tab=enterprise', auth.uid(), true);
  end loop;
  return jsonb_build_object('id', v_id);
end $$;

-- ---------------------------------------------------------------------
-- 5. Admin hệ thống: tạo tổ chức theo hợp đồng, gia hạn, xử lý báo giá
-- ---------------------------------------------------------------------
create or replace function public.admin_org_leads(p_status text default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform private.require_admin();
  return coalesce((select jsonb_agg(to_jsonb(l) || jsonb_build_object('org_name_linked', (select o.name from public.organizations o where o.id = l.org_id))
                                    order by l.created_at desc)
                     from public.org_leads l where p_status is null or l.status = p_status), '[]'::jsonb);
end $$;

create or replace function public.admin_set_org_lead(p_id uuid, p_status text, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare v_admin uuid := private.require_admin();
begin
  if p_status not in ('NEW', 'CONTACTED', 'WON', 'LOST') then raise exception 'INVALID_STATUS'; end if;
  update public.org_leads set status = p_status, admin_note = coalesce(nullif(left(trim(coalesce(p_note, '')), 1000), ''), admin_note)
   where id = p_id;
  if not found then raise exception 'NOT_FOUND'; end if;
  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_admin, 'ORG_LEAD_STATUS', 'org_lead:' || p_id, jsonb_build_object('status', p_status, 'note', p_note));
end $$;

create or replace function public.admin_list_orgs() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform private.require_admin();
  return coalesce((select jsonb_agg(private.org_json(o) || jsonb_build_object(
                     'owner_name', (select string_agg(private.display_name(m.user_id), ', ') from public.org_members m
                                     where m.org_id = o.id and m.role = 'OWNER'),
                     'legal_name', o.legal_name, 'tax_code', o.tax_code, 'contact_name', o.contact_name,
                     'contact_phone', o.contact_phone, 'contact_email', o.contact_email) order by o.created_at desc)
                     from public.organizations o), '[]'::jsonb);
end $$;

create or replace function public.admin_create_org(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_admin uuid := private.require_admin();
  v_owner uuid := (select u.id from auth.users u where lower(u.email) = lower(trim(coalesce(p->>'owner_email', ''))));
  v_id uuid;
  v_name text := trim(coalesce(p->>'name', ''));
  v_code text := private.org_new_code();
begin
  if char_length(v_name) < 2 then raise exception 'ORG_NAME_REQUIRED'; end if;
  if v_owner is null then raise exception 'OWNER_NOT_FOUND'; end if;
  v_id := gen_random_uuid();
  insert into public.organizations (id, name, kind, seat_limit, club_limit, include_club_pro, active_until, invite_code,
                                    legal_name, tax_code, contact_name, contact_phone, contact_email, created_by)
  values (v_id, left(v_name, 120), case when p->>'kind' in ('COMPANY', 'FEDERATION', 'SCHOOL', 'OTHER') then p->>'kind' else 'COMPANY' end,
          coalesce(nullif(p->>'seat_limit', '')::int, 50), coalesce(nullif(p->>'club_limit', '')::int, 0),
          coalesce((p->>'include_club_pro')::boolean, false), nullif(p->>'active_until', '')::timestamptz, v_code,
          nullif(trim(coalesce(p->>'legal_name', '')), ''), nullif(trim(coalesce(p->>'tax_code', '')), ''),
          nullif(trim(coalesce(p->>'contact_name', '')), ''), nullif(trim(coalesce(p->>'contact_phone', '')), ''),
          nullif(trim(coalesce(p->>'contact_email', '')), ''), v_admin);
  insert into public.org_members (org_id, user_id, role, status) values (v_id, v_owner, 'OWNER', 'APPROVED');
  if nullif(p->>'lead_id', '') is not null then
    update public.org_leads set status = 'WON', org_id = v_id where id = (p->>'lead_id')::uuid;
  end if;
  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_admin, 'ORG_CREATE', 'org:' || v_id, p - 'owner_email' || jsonb_build_object('owner_id', v_owner));
  perform private.notify(v_owner, null, 'ORG_CREATED', 'Tổ chức ' || left(v_name, 80) || ' đã sẵn sàng',
    'Bạn là quản trị viên. Mời thành viên bằng mã ' || v_code || ' và tạo chiến dịch đầu tiên.', '/orgs/' || v_id, v_admin, true);
  return jsonb_build_object('id', v_id, 'invite_code', v_code);
end $$;

create or replace function public.admin_update_org(p_org uuid, p jsonb, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_admin uuid := private.require_admin();
  v_old public.organizations := (select o from public.organizations o where o.id = p_org);
begin
  if v_old.id is null then raise exception 'ORG_NOT_FOUND'; end if;
  if char_length(trim(coalesce(p_reason, ''))) < 3 then raise exception 'REASON_REQUIRED'; end if;
  update public.organizations set
    seat_limit = coalesce(nullif(p->>'seat_limit', '')::int, seat_limit),
    club_limit = coalesce(nullif(p->>'club_limit', '')::int, club_limit),
    include_club_pro = coalesce((p->>'include_club_pro')::boolean, include_club_pro),
    active_until = case when p ? 'active_until' then nullif(p->>'active_until', '')::timestamptz else active_until end,
    status = case when p->>'status' in ('ACTIVE', 'SUSPENDED') then p->>'status' else status end,
    kind = case when p->>'kind' in ('COMPANY', 'FEDERATION', 'SCHOOL', 'OTHER') then p->>'kind' else kind end
   where id = p_org;
  perform private.org_sync_club_pro(p_org);
  insert into public.admin_audit_log (actor_id, action, target, old_value, new_value, reason)
  values (v_admin, 'ORG_UPDATE', 'org:' || p_org, to_jsonb(v_old), p, p_reason);
  return private.org_json((select o from public.organizations o where o.id = p_org));
end $$;

-- Cron hằng ngày: hết hạn hợp đồng → trả gói cũ cho CLB được tài trợ
create or replace function public.expire_org_plans() returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in select distinct oc.org_id from public.org_clubs oc where oc.pro_granted loop
    if not private.org_active(r.org_id) then n := n + private.org_sync_club_pro(r.org_id); end if;
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------------
-- 6. Tổ chức của tôi, chi tiết, mời / vào / rời
-- ---------------------------------------------------------------------
create or replace function public.my_orgs() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  return coalesce((select jsonb_agg(private.org_json(o) || jsonb_build_object('my_role', m.role, 'my_status', m.status) order by o.name)
                     from public.org_members m join public.organizations o on o.id = m.org_id where m.user_id = v_uid), '[]'::jsonb);
end $$;

create or replace function public.org_detail(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.organizations := (select x from public.organizations x where x.id = p_org);
  v_admin boolean := public.org_is_admin(p_org);
  me public.org_members := (select m from public.org_members m where m.org_id = p_org and m.user_id = v_uid);
begin
  if o.id is null then raise exception 'ORG_NOT_FOUND'; end if;
  if not public.org_is_member(p_org) then raise exception 'NOT_A_MEMBER'; end if;
  return private.org_json(o) || jsonb_build_object(
    'my_role', coalesce(private.org_role(p_org), 'MEMBER'), 'is_admin', v_admin, 'is_system_admin', public.is_system_admin(),
    'my_unit_id', me.unit_id, 'is_real_member', me.status = 'APPROVED',
    'units', coalesce((select jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name,
                 'members', (select count(*)::int from public.org_members m where m.unit_id = u.id and m.status = 'APPROVED')) order by u.sort, u.name)
               from public.org_units u where u.org_id = p_org), '[]'::jsonb),
    'clubs', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
                 'member_count', c.member_count, 'status', oc.status, 'pro_granted', oc.pro_granted) order by oc.status, c.name)
               from public.org_clubs oc join public.clubs c on c.id = oc.club_id
              where oc.org_id = p_org and (oc.status = 'APPROVED' or v_admin)), '[]'::jsonb),
    'pending_members', case when v_admin then (select count(*)::int from public.org_members m where m.org_id = p_org and m.status = 'PENDING') end,
    'invite_code', case when v_admin then o.invite_code end,
    'billing', case when v_admin then jsonb_build_object('legal_name', o.legal_name, 'tax_code', o.tax_code, 'contact_name', o.contact_name,
                                                         'contact_phone', o.contact_phone, 'contact_email', o.contact_email) end);
end $$;

create or replace function public.org_invite_preview(p_code text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.organizations := (select x from public.organizations x where x.invite_code = upper(trim(coalesce(p_code, ''))));
begin
  if o.id is null then return null; end if;
  return jsonb_build_object('id', o.id, 'name', o.name, 'kind', o.kind, 'logo_url', o.logo_url, 'cover_url', o.cover_url,
    'cover_position', o.cover_position, 'theme', o.theme, 'tagline', o.tagline, 'description', o.description,
    'join_policy', o.join_policy, 'unit_label', o.unit_label, 'allow_self_unit', o.allow_self_unit,
    'active', private.org_active(o.id), 'full', private.org_seats_used(o.id) >= o.seat_limit,
    'member_count', private.org_seats_used(o.id),
    'units', case when o.allow_self_unit then coalesce((select jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name) order by u.sort, u.name)
                                                          from public.org_units u where u.org_id = o.id), '[]'::jsonb) else '[]'::jsonb end,
    'my_status', (select m.status from public.org_members m where m.org_id = o.id and m.user_id = v_uid));
end $$;

create or replace function public.join_org(p_code text, p_unit uuid default null, p_employee_code text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.organizations := (select x from public.organizations x where x.invite_code = upper(trim(coalesce(p_code, ''))));
  v_status text;
  v_unit uuid;
  a record;
begin
  if o.id is null then raise exception 'INVALID_CODE'; end if;
  if not private.org_active(o.id) then raise exception 'ORG_INACTIVE'; end if;
  perform pg_advisory_xact_lock(hashtext('org_seats:' || o.id));
  v_status := (select m.status from public.org_members m where m.org_id = o.id and m.user_id = v_uid);
  if v_status is not null then return jsonb_build_object('org_id', o.id, 'status', v_status, 'duplicate', true); end if;
  v_unit := case when o.allow_self_unit then (select u.id from public.org_units u where u.id = p_unit and u.org_id = o.id) end;
  v_status := case when o.join_policy = 'OPEN' then 'APPROVED' else 'PENDING' end;
  if v_status = 'APPROVED' and private.org_seats_used(o.id) >= o.seat_limit then raise exception 'ORG_FULL'; end if;
  insert into public.org_members (org_id, user_id, role, status, unit_id, employee_code)
  values (o.id, v_uid, 'MEMBER', v_status, v_unit, nullif(left(trim(coalesce(p_employee_code, '')), 40), ''));
  if v_status = 'PENDING' then
    for a in select m.user_id from public.org_members m where m.org_id = o.id and m.status = 'APPROVED' and m.role in ('OWNER', 'ADMIN') loop
      perform private.notify(a.user_id, null, 'ORG_JOIN_REQUEST', private.display_name(v_uid) || ' xin vào ' || o.name,
        'Duyệt ở mục Thành viên của tổ chức.', '/orgs/' || o.id || '?tab=members', v_uid, false);
    end loop;
  end if;
  return jsonb_build_object('org_id', o.id, 'status', v_status);
end $$;

create or replace function public.leave_org(p_org uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  if (select m.role from public.org_members m where m.org_id = p_org and m.user_id = v_uid) = 'OWNER' then
    raise exception 'OWNER_CANNOT_LEAVE';
  end if;
  delete from public.org_members where org_id = p_org and user_id = v_uid;
end $$;

create or replace function public.rotate_org_invite(p_org uuid) returns text
language plpgsql security definer set search_path = public as $$
declare v_code text := private.org_new_code();
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  update public.organizations set invite_code = v_code where id = p_org;
  return v_code;
end $$;

create or replace function public.update_org(p_org uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if p ? 'name' and char_length(trim(coalesce(p->>'name', ''))) < 2 then raise exception 'ORG_NAME_REQUIRED'; end if;
  if p ? 'tagline' and char_length(coalesce(p->>'tagline', '')) > 80 then raise exception 'TAGLINE_TOO_LONG'; end if;
  if p ? 'unit_label' and char_length(trim(coalesce(p->>'unit_label', ''))) not between 2 and 30 then raise exception 'INVALID_UNIT_LABEL'; end if;
  if (p ? 'cover_url' and coalesce(p->>'cover_url', '') <> '' and p->>'cover_url' !~ '^https://')
     or (p ? 'logo_url' and coalesce(p->>'logo_url', '') <> '' and p->>'logo_url' !~ '^https://') then raise exception 'INVALID_URL'; end if;
  update public.organizations set
    name = case when p ? 'name' then left(trim(p->>'name'), 120) else name end,
    description = case when p ? 'description' then nullif(left(trim(coalesce(p->>'description', '')), 2000), '') else description end,
    logo_url = case when p ? 'logo_url' then nullif(p->>'logo_url', '') else logo_url end,
    cover_url = case when p ? 'cover_url' then nullif(p->>'cover_url', '') else cover_url end,
    cover_position = case when p ? 'cover_position' then least(greatest(coalesce((p->>'cover_position')::int, 50), 0), 100) else cover_position end,
    tagline = case when p ? 'tagline' then nullif(trim(coalesce(p->>'tagline', '')), '') else tagline end,
    theme = case when p ? 'theme' then case when p->>'theme' in ('AURORA', 'SUNSET', 'OCEAN', 'FOREST', 'GOLD', 'NIGHT') then p->>'theme' end else theme end,
    join_policy = case when p->>'join_policy' in ('OPEN', 'APPROVAL') then p->>'join_policy' else join_policy end,
    unit_label = case when p ? 'unit_label' then trim(p->>'unit_label') else unit_label end,
    allow_self_unit = coalesce((p->>'allow_self_unit')::boolean, allow_self_unit),
    legal_name = case when p ? 'legal_name' then nullif(left(trim(coalesce(p->>'legal_name', '')), 200), '') else legal_name end,
    tax_code = case when p ? 'tax_code' then nullif(left(trim(coalesce(p->>'tax_code', '')), 20), '') else tax_code end,
    contact_name = case when p ? 'contact_name' then nullif(left(trim(coalesce(p->>'contact_name', '')), 80), '') else contact_name end,
    contact_phone = case when p ? 'contact_phone' then nullif(left(trim(coalesce(p->>'contact_phone', '')), 20), '') else contact_phone end,
    contact_email = case when p ? 'contact_email' then nullif(left(trim(coalesce(p->>'contact_email', '')), 120), '') else contact_email end
   where id = p_org;
  return public.org_detail(p_org);
end $$;

-- ---------------------------------------------------------------------
-- 7. Đơn vị (phòng ban / chi nhánh / lớp) + thành viên
-- ---------------------------------------------------------------------
create or replace function public.save_org_unit(p_org uuid, p_id uuid, p_name text) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_id uuid := p_id; v_name text := trim(coalesce(p_name, ''));
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if char_length(v_name) not between 1 and 80 then raise exception 'INVALID_NAME'; end if;
  if exists (select 1 from public.org_units u where u.org_id = p_org and lower(u.name) = lower(v_name) and u.id is distinct from p_id) then
    raise exception 'UNIT_EXISTS';
  end if;
  if (select count(*) from public.org_units u where u.org_id = p_org) >= 500 and p_id is null then raise exception 'UNIT_LIMIT'; end if;
  if v_id is null then
    v_id := gen_random_uuid();
    insert into public.org_units (id, org_id, name, sort)
    values (v_id, p_org, v_name, coalesce((select max(u.sort) from public.org_units u where u.org_id = p_org), 0) + 1);
  else
    update public.org_units set name = v_name where id = p_id and org_id = p_org;
    if not found then raise exception 'NOT_FOUND'; end if;
  end if;
  return v_id;
end $$;

create or replace function public.delete_org_unit(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_org uuid := (select u.org_id from public.org_units u where u.id = p_id);
begin
  if v_org is null or not public.org_is_admin(v_org) then raise exception 'FORBIDDEN'; end if;
  delete from public.org_units where id = p_id;
end $$;

create or replace function public.org_members_list(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_admin boolean := public.org_is_admin(p_org);
begin
  if not public.org_is_member(p_org) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('user_id', m.user_id, 'name', private.display_name(m.user_id), 'avatar_url', pr.avatar_url,
             'role', m.role, 'status', m.status, 'unit_id', m.unit_id, 'unit_name', u.name, 'joined_at', m.joined_at,
             'employee_code', case when v_admin then m.employee_code end)
             order by (m.status = 'PENDING') desc, case m.role when 'OWNER' then 0 when 'ADMIN' then 1 else 2 end, private.display_name(m.user_id))
           from public.org_members m join public.profiles pr on pr.id = m.user_id left join public.org_units u on u.id = m.unit_id
          where m.org_id = p_org and (m.status = 'APPROVED' or v_admin)), '[]'::jsonb);
end $$;

create or replace function public.set_org_member(p_org uuid, p_user uuid, p jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  m public.org_members := (select x from public.org_members x where x.org_id = p_org and x.user_id = p_user);
  v_org text := (select o.name from public.organizations o where o.id = p_org);
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if m.user_id is null then raise exception 'MEMBER_NOT_FOUND'; end if;
  if p->>'action' = 'REMOVE' then
    if m.role = 'OWNER' then raise exception 'OWNER_CANNOT_LEAVE'; end if;
    delete from public.org_members where org_id = p_org and user_id = p_user;
    return;
  end if;
  perform pg_advisory_xact_lock(hashtext('org_seats:' || p_org));
  if p->>'status' = 'APPROVED' and m.status = 'PENDING' then
    if private.org_seats_used(p_org) >= (select o.seat_limit from public.organizations o where o.id = p_org) then raise exception 'ORG_FULL'; end if;
    update public.org_members set status = 'APPROVED', joined_at = now() where org_id = p_org and user_id = p_user;
    perform private.notify(p_user, null, 'ORG_APPROVED', 'Bạn đã vào ' || coalesce(v_org, 'tổ chức'), 'Xem chiến dịch đang diễn ra.',
      '/orgs/' || p_org, v_uid, false);
  end if;
  if p->>'role' in ('ADMIN', 'MEMBER') then
    if m.role = 'OWNER' then raise exception 'FORBIDDEN'; end if;
    update public.org_members set role = p->>'role' where org_id = p_org and user_id = p_user;
  end if;
  if p ? 'unit_id' then
    update public.org_members set unit_id = (select u.id from public.org_units u where u.id = nullif(p->>'unit_id', '')::uuid and u.org_id = p_org)
     where org_id = p_org and user_id = p_user;
  end if;
  if p ? 'employee_code' then
    update public.org_members set employee_code = nullif(left(trim(coalesce(p->>'employee_code', '')), 40), '') where org_id = p_org and user_id = p_user;
  end if;
end $$;

create or replace function public.set_my_org_unit(p_org uuid, p_unit uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  if not coalesce((select o.allow_self_unit from public.organizations o where o.id = p_org), false) then raise exception 'FORBIDDEN'; end if;
  update public.org_members set unit_id = (select u.id from public.org_units u where u.id = p_unit and u.org_id = p_org)
   where org_id = p_org and user_id = v_uid;
  if not found then raise exception 'NOT_A_MEMBER'; end if;
end $$;

-- ---------------------------------------------------------------------
-- 8. CLB thuộc tổ chức (liên đoàn / hệ thống CLB)
-- ---------------------------------------------------------------------
create or replace function public.org_invite_club(p_org uuid, p_club uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.organizations := (select x from public.organizations x where x.id = p_org);
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if not private.org_active(p_org) then raise exception 'ORG_INACTIVE'; end if;
  if not exists (select 1 from public.clubs c where c.id = p_club) then raise exception 'CLUB_NOT_FOUND'; end if;
  if exists (select 1 from public.org_clubs oc where oc.club_id = p_club and oc.status = 'APPROVED') then raise exception 'CLUB_IN_ORG'; end if;
  if exists (select 1 from public.org_clubs oc where oc.org_id = p_org and oc.club_id = p_club) then raise exception 'ALREADY_INVITED'; end if;
  if (select count(*) from public.org_clubs oc where oc.org_id = p_org) >= o.club_limit then raise exception 'ORG_CLUB_LIMIT'; end if;
  insert into public.org_clubs (org_id, club_id, invited_by) values (p_org, p_club, v_uid);
  perform private.notify_club(p_club, true, 'ORG_CLUB_INVITE', o.name || ' mời CLB tham gia tổ chức',
    case when o.include_club_pro then 'Tham gia: CLB được nâng Pro miễn phí trong thời hạn hợp đồng của tổ chức.' else 'Mở Cài đặt CLB để trả lời.' end,
    '/clubs/' || p_club || '/settings', v_uid);
end $$;

create or replace function public.respond_org_invite(p_org uuid, p_club uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_status text := (select oc.status from public.org_clubs oc where oc.org_id = p_org and oc.club_id = p_club);
  a record;
begin
  if not public.club_is_staff(p_club) then raise exception 'FORBIDDEN'; end if;
  if v_status is distinct from 'PENDING' then raise exception 'INVITE_NOT_FOUND'; end if;
  if not p_accept then
    delete from public.org_clubs where org_id = p_org and club_id = p_club;
    return;
  end if;
  if exists (select 1 from public.org_clubs oc where oc.club_id = p_club and oc.status = 'APPROVED') then raise exception 'CLUB_IN_ORG'; end if;
  update public.org_clubs set status = 'APPROVED', responded_by = v_uid where org_id = p_org and club_id = p_club;
  perform private.org_sync_club_pro(p_org);
  for a in select m.user_id from public.org_members m where m.org_id = p_org and m.status = 'APPROVED' and m.role in ('OWNER', 'ADMIN') loop
    perform private.notify(a.user_id, p_club, 'ORG_CLUB_JOINED', (select c.name from public.clubs c where c.id = p_club) || ' đã vào tổ chức',
      'Thành viên CLB được tính vào chiến dịch của tổ chức.', '/orgs/' || p_org || '?tab=units', v_uid, false);
  end loop;
end $$;

create or replace function public.remove_org_club(p_org uuid, p_club uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not (public.org_is_admin(p_org) or public.club_is_staff(p_club)) then raise exception 'FORBIDDEN'; end if;
  update public.org_clubs set status = 'PENDING' where org_id = p_org and club_id = p_club;   -- để đồng bộ trả gói trước khi xoá
  perform private.org_sync_club_pro(p_org);
  delete from public.org_clubs where org_id = p_org and club_id = p_club;
end $$;

-- Cho màn Cài đặt CLB: tổ chức đang thuộc + lời mời đang chờ
create or replace function public.club_orgs(p_club uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_staff boolean := public.club_is_staff(p_club);
begin
  if not public.club_is_member(p_club) then raise exception 'NOT_A_MEMBER'; end if;
  return jsonb_build_object('is_staff', v_staff,
    'current', (select private.org_json(o) || jsonb_build_object('pro_granted', oc.pro_granted, 'granted_until', oc.granted_until)
                  from public.org_clubs oc join public.organizations o on o.id = oc.org_id
                 where oc.club_id = p_club and oc.status = 'APPROVED'),
    'invites', case when v_staff then coalesce((select jsonb_agg(private.org_json(o) order by oc.created_at desc)
                  from public.org_clubs oc join public.organizations o on o.id = oc.org_id
                 where oc.club_id = p_club and oc.status = 'PENDING'), '[]'::jsonb) else '[]'::jsonb end);
end $$;

-- ---------------------------------------------------------------------
-- 9. Chiến dịch + bảng xếp hạng
-- ---------------------------------------------------------------------
create or replace function public.save_org_campaign(p_org uuid, p_id uuid, p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_id uuid := p_id;
  v_title text := trim(coalesce(p->>'title', ''));
  v_start timestamptz := nullif(p->>'starts_at', '')::timestamptz;
  v_end timestamptz := nullif(p->>'ends_at', '')::timestamptz;
  v_metric text := coalesce(p->>'metric', 'DISTANCE');
  v_org text := (select o.name from public.organizations o where o.id = p_org);
  r record;
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if not private.org_active(p_org) then raise exception 'ORG_INACTIVE'; end if;
  if char_length(v_title) not between 3 and 120 then raise exception 'TITLE_REQUIRED'; end if;
  if v_metric not in ('DISTANCE', 'RUNS', 'ACTIVE_DAYS') then raise exception 'INVALID_METRIC'; end if;
  if v_start is null or v_end is null or v_end <= v_start or v_end - v_start > interval '366 days' then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_id is null then
    v_id := gen_random_uuid();
    insert into public.org_campaigns (id, org_id, title, description, metric, starts_at, ends_at, goal_total, goal_per_person, min_run_km, created_by)
    values (v_id, p_org, v_title, nullif(left(trim(coalesce(p->>'description', '')), 2000), ''), v_metric, v_start, v_end,
            nullif(p->>'goal_total', '')::numeric, nullif(p->>'goal_per_person', '')::numeric,
            coalesce(nullif(p->>'min_run_km', '')::numeric, 1), v_uid);
    for r in select pp.user_id from private.org_people(p_org) pp loop
      perform private.notify(r.user_id, null, 'ORG_CAMPAIGN', coalesce(v_org, 'Tổ chức') || ': ' || v_title,
        'Chiến dịch mới — bài chạy hợp lệ của bạn được tính tự động.', '/orgs/' || p_org || '/campaigns/' || v_id, v_uid, false);
    end loop;
  else
    update public.org_campaigns set title = v_title, description = nullif(left(trim(coalesce(p->>'description', '')), 2000), ''),
           metric = v_metric, starts_at = v_start, ends_at = v_end,
           goal_total = nullif(p->>'goal_total', '')::numeric, goal_per_person = nullif(p->>'goal_per_person', '')::numeric,
           min_run_km = coalesce(nullif(p->>'min_run_km', '')::numeric, 1)
     where id = p_id and org_id = p_org;
    if not found then raise exception 'NOT_FOUND'; end if;
  end if;
  return v_id;
end $$;

create or replace function public.cancel_org_campaign(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_org uuid := (select c.org_id from public.org_campaigns c where c.id = p_id);
begin
  if v_org is null or not public.org_is_admin(v_org) then raise exception 'FORBIDDEN'; end if;
  update public.org_campaigns set status = 'CANCELLED' where id = p_id;
end $$;

create or replace function private.org_campaign_rows(c public.org_campaigns)
returns table (user_id uuid, unit_id uuid, direct boolean, value numeric, km numeric, runs integer, active_days integer)
language sql stable security definer set search_path = public as $$
  select pp.user_id, pp.unit_id, pp.direct,
         case c.metric when 'DISTANCE' then s.km when 'RUNS' then s.runs::numeric else s.active_days::numeric end,
         s.km, s.runs, s.active_days
    from private.org_people(c.org_id) pp
    cross join lateral private.org_person_stats(pp.user_id, c.starts_at, least(c.ends_at, now()), c.min_run_km) s
$$;

create or replace function public.org_campaigns(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.org_is_member(p_org) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(to_jsonb(c) || (
             select jsonb_build_object('total', coalesce(sum(r.value), 0), 'participants', count(*)::int,
                                       'active', count(*) filter (where r.value > 0)::int,
                                       'my_value', max(r.value) filter (where r.user_id = auth.uid()))
               from private.org_campaign_rows(c) r) order by (c.status = 'ACTIVE' and c.ends_at > now()) desc, c.starts_at desc)
           from public.org_campaigns c where c.org_id = p_org and c.status = 'ACTIVE'), '[]'::jsonb);
end $$;

create or replace function public.org_campaign_board(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.org_campaigns := (select x from public.org_campaigns x where x.id = p_id);
begin
  if c.id is null then raise exception 'NOT_FOUND'; end if;
  if not (public.org_is_member(c.org_id) or exists (select 1 from private.org_people(c.org_id) pp where pp.user_id = auth.uid())) then
    raise exception 'NOT_A_MEMBER';
  end if;
  return (
    with rows as (select * from private.org_campaign_rows(c)),
    ranked as (select r.*, row_number() over (order by r.value desc, r.km desc, r.user_id) as rn from rows r),
    units as (
      select u.id, u.name, count(r.user_id)::int as members, count(r.user_id) filter (where r.value > 0)::int as active,
             coalesce(sum(r.value), 0) as total
        from public.org_units u left join rows r on r.unit_id = u.id
       where u.org_id = c.org_id group by u.id, u.name
    ),
    clubs as (
      select cl.id, cl.name, cl.avatar_url, cl.accent_color, count(r.user_id)::int as members,
             count(r.user_id) filter (where r.value > 0)::int as active, coalesce(sum(r.value), 0) as total
        from public.org_clubs oc join public.clubs cl on cl.id = oc.club_id
        join public.club_members cm on cm.club_id = cl.id and cm.status = 'APPROVED'
        left join rows r on r.user_id = cm.user_id
       where oc.org_id = c.org_id and oc.status = 'APPROVED' group by cl.id, cl.name, cl.avatar_url, cl.accent_color
    )
    select jsonb_build_object(
      'campaign', to_jsonb(c) || jsonb_build_object('org_name', (select o.name from public.organizations o where o.id = c.org_id)),
      'is_admin', public.org_is_admin(c.org_id),
      'total', (select coalesce(sum(r.value), 0) from rows r),
      'total_km', (select coalesce(sum(r.km), 0) from rows r),
      'participants', (select count(*)::int from rows),
      'active', (select count(*)::int from rows r where r.value > 0),
      'completed', (select count(*)::int from rows r where c.goal_per_person is not null and r.value >= c.goal_per_person),
      'me', (select jsonb_build_object('rank', k.rn, 'value', k.value, 'km', k.km, 'runs', k.runs, 'active_days', k.active_days)
               from ranked k where k.user_id = auth.uid()),
      'people', coalesce((select jsonb_agg(jsonb_build_object('rank', k.rn, 'user_id', k.user_id, 'name', private.display_name(k.user_id),
                   'avatar_url', pr.avatar_url, 'unit_name', u.name, 'value', k.value, 'km', k.km, 'runs', k.runs, 'active_days', k.active_days,
                   'completed', c.goal_per_person is not null and k.value >= c.goal_per_person) order by k.rn)
                 from ranked k join public.profiles pr on pr.id = k.user_id left join public.org_units u on u.id = k.unit_id
                where k.rn <= 500), '[]'::jsonb),
      'units', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'members', x.members, 'active', x.active, 'total', x.total,
                   'avg', case when x.members > 0 then round(x.total / x.members, 2) else 0 end) order by x.total desc) from units x), '[]'::jsonb),
      'clubs', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'avatar_url', x.avatar_url, 'accent_color', x.accent_color,
                   'members', x.members, 'active', x.active, 'total', x.total,
                   'avg', case when x.members > 0 then round(x.total / x.members, 2) else 0 end) order by x.total desc) from clubs x), '[]'::jsonb)));
end $$;

-- ---------------------------------------------------------------------
-- 10. Báo cáo cho ban quản trị tổ chức (xuất CSV ở giao diện)
-- ---------------------------------------------------------------------
create or replace function public.org_report(p_org uuid, p_from timestamptz, p_to timestamptz) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '400 days' then raise exception 'INVALID_TIME_RANGE'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('user_id', pp.user_id, 'name', private.display_name(pp.user_id), 'direct', pp.direct,
             'unit_name', u.name, 'employee_code', m.employee_code,
             'clubs', (select string_agg(cl.name, ', ' order by cl.name) from public.org_clubs oc join public.clubs cl on cl.id = oc.club_id
                        join public.club_members cm on cm.club_id = cl.id and cm.user_id = pp.user_id and cm.status = 'APPROVED'
                       where oc.org_id = p_org and oc.status = 'APPROVED'),
             'km', s.km, 'runs', s.runs, 'active_days', s.active_days) order by s.km desc, private.display_name(pp.user_id))
           from private.org_people(p_org) pp
           cross join lateral private.org_person_stats(pp.user_id, p_from, p_to, 0) s
           left join public.org_members m on m.org_id = p_org and m.user_id = pp.user_id
           left join public.org_units u on u.id = pp.unit_id), '[]'::jsonb);
end $$;

-- ---------------------------------------------------------------------
-- 11. Ảnh logo / ảnh bìa tổ chức: bucket org-media, thư mục <org_id>/..., chỉ quản trị tổ chức tải lên
-- ---------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('org-media', 'org-media', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;
drop policy if exists org_media_insert on storage.objects;
create policy org_media_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'org-media' and public.org_is_admin(((storage.foldername(name))[1])::uuid));

-- ---------------------------------------------------------------------
-- 12. Quyền
-- ---------------------------------------------------------------------
revoke all on function private.org_role(uuid), private.org_active(uuid), private.org_seats_used(uuid), private.org_new_code(),
  private.org_json(public.organizations), private.org_people(uuid), private.org_person_stats(uuid, timestamptz, timestamptz, numeric),
  private.org_sync_club_pro(uuid), private.org_campaign_rows(public.org_campaigns) from public, anon, authenticated;

revoke all on function public.request_enterprise_quote(jsonb) from public;
grant execute on function public.request_enterprise_quote(jsonb) to anon, authenticated;

revoke all on function public.expire_org_plans() from public, anon, authenticated;
grant execute on function public.expire_org_plans() to service_role;

revoke all on function public.org_is_admin(uuid), public.org_is_member(uuid), public.admin_org_leads(text), public.admin_set_org_lead(uuid, text, text),
  public.admin_list_orgs(), public.admin_create_org(jsonb), public.admin_update_org(uuid, jsonb, text), public.my_orgs(), public.org_detail(uuid),
  public.org_invite_preview(text), public.join_org(text, uuid, text), public.leave_org(uuid), public.rotate_org_invite(uuid), public.update_org(uuid, jsonb),
  public.save_org_unit(uuid, uuid, text), public.delete_org_unit(uuid), public.org_members_list(uuid), public.set_org_member(uuid, uuid, jsonb),
  public.set_my_org_unit(uuid, uuid), public.org_invite_club(uuid, uuid), public.respond_org_invite(uuid, uuid, boolean),
  public.remove_org_club(uuid, uuid), public.club_orgs(uuid), public.save_org_campaign(uuid, uuid, jsonb), public.cancel_org_campaign(uuid),
  public.org_campaigns(uuid), public.org_campaign_board(uuid), public.org_report(uuid, timestamptz, timestamptz) from public, anon;
grant execute on function public.org_is_admin(uuid), public.org_is_member(uuid), public.admin_org_leads(text), public.admin_set_org_lead(uuid, text, text),
  public.admin_list_orgs(), public.admin_create_org(jsonb), public.admin_update_org(uuid, jsonb, text), public.my_orgs(), public.org_detail(uuid),
  public.org_invite_preview(text), public.join_org(text, uuid, text), public.leave_org(uuid), public.rotate_org_invite(uuid), public.update_org(uuid, jsonb),
  public.save_org_unit(uuid, uuid, text), public.delete_org_unit(uuid), public.org_members_list(uuid), public.set_org_member(uuid, uuid, jsonb),
  public.set_my_org_unit(uuid, uuid), public.org_invite_club(uuid, uuid), public.respond_org_invite(uuid, uuid, boolean),
  public.remove_org_club(uuid, uuid), public.club_orgs(uuid), public.save_org_campaign(uuid, uuid, jsonb), public.cancel_org_campaign(uuid),
  public.org_campaigns(uuid), public.org_campaign_board(uuid), public.org_report(uuid, timestamptz, timestamptz) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001008400_org_management_draws.sql
-- ===================================================================
-- 008400: Cơ chế quản lý Doanh nghiệp (học từ FoxSteps) + quay thưởng dùng chung toàn app.
-- Doanh nghiệp = nhiều nhóm nhỏ gộp lại. Bổ sung:
-- • Tên miền email công ty (tích chọn ở Cài đặt): email đúng tên miền → tự duyệt; tuỳ chọn "chỉ nhận email công ty".
-- • Nhập danh sách nhân viên từ Excel/CSV: email, đơn vị (nhiều cấp "Vùng / Chi nhánh / Phòng"), mã nhân viên, vai trò.
--   Người chưa có tài khoản → lời mời chờ, tự áp khi họ vào bằng mã mời. Tuỳ chọn gỡ người không còn trong danh sách.
-- • Đơn vị nhiều cấp (tối đa 4 cấp); BXH đơn vị cộng dồn cả đơn vị con.
-- • Trưởng đơn vị (UNIT_ADMIN) — như ban quản trị CLB: duyệt / gỡ / gán đơn vị, xem báo cáo trong đơn vị mình (và đơn vị con).
-- • Chiến dịch: trần km mỗi ngày, ngày hội ×2 / ×3, chốt kết quả + duyệt top N trước khi trao giải (loại có lý do),
--   chứng nhận hoàn thành (thiết kế như chứng nhận giải chạy ảo).
-- • Bảng tin tổ chức (mô hình như CLB): bài đăng, ảnh, thích, bình luận, ghim; tuỳ chọn chỉ quản trị được đăng.
-- • Chế độ riêng tư (tích chọn): thành viên chỉ thấy BXH đơn vị + thứ hạng của chính mình, không thấy tên người khác.
-- • Quay thưởng dùng chung: chiến dịch tổ chức, thử thách, CLB, giải chạy ảo, toàn hệ thống (admin). Chạy một lần,
--   không quay lại; thứ tự trúng = md5(seed || user_id) — công bố seed + mã băm danh sách để ai cũng kiểm tra được.
-- Cần 008300. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

-- ---------------------------------------------------------------------
-- 1. Cột / bảng mới
-- ---------------------------------------------------------------------
alter table public.organizations add column if not exists email_domains text[] not null default '{}';
alter table public.organizations add column if not exists domain_auto_approve boolean not null default false;
alter table public.organizations add column if not exists domain_only boolean not null default false;
alter table public.organizations add column if not exists privacy_mode boolean not null default false;
alter table public.organizations add column if not exists member_posts boolean not null default true;

alter table public.org_members drop constraint if exists org_members_role_check;
alter table public.org_members add constraint org_members_role_check check (role in ('OWNER', 'ADMIN', 'UNIT_ADMIN', 'MEMBER'));

alter table public.org_units add column if not exists parent_id uuid references public.org_units(id) on delete cascade;
drop index if exists public.org_units_name_key;
create unique index if not exists org_units_name_parent_key
  on public.org_units (org_id, coalesce(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(name));

create table if not exists public.org_pending_invites (
  org_id uuid not null references public.organizations(id) on delete cascade,
  email text not null check (email = lower(email) and email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  unit_id uuid references public.org_units(id) on delete set null,
  employee_code text check (employee_code is null or char_length(employee_code) <= 40),
  role text not null default 'MEMBER' check (role in ('MEMBER', 'UNIT_ADMIN')),
  created_at timestamptz not null default now(),
  primary key (org_id, email)
);

alter table public.org_campaigns add column if not exists daily_cap_km numeric check (daily_cap_km is null or daily_cap_km between 1 and 300);
alter table public.org_campaigns add column if not exists review_top integer not null default 0 check (review_top between 0 and 200);
alter table public.org_campaigns add column if not exists boost_days jsonb not null default '[]'::jsonb;
alter table public.org_campaigns add column if not exists cert_enabled boolean not null default false;
alter table public.org_campaigns add column if not exists cert_design jsonb;
alter table public.org_campaigns add column if not exists locked_at timestamptz;
alter table public.org_campaigns add column if not exists locked_by uuid references public.profiles(id) on delete set null;

create table if not exists public.org_campaign_results (
  campaign_id uuid not null references public.org_campaigns(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  unit_id uuid references public.org_units(id) on delete set null,
  direct boolean not null default true,
  value numeric not null default 0,
  km numeric not null default 0,
  runs integer not null default 0,
  active_days integer not null default 0,
  rank integer not null,
  review_status text not null default 'OK' check (review_status in ('OK', 'PENDING', 'DQ')),
  review_note text check (review_note is null or char_length(review_note) <= 300),
  reviewed_by uuid references public.profiles(id) on delete set null,
  primary key (campaign_id, user_id)
);

create table if not exists public.org_posts (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  author_id uuid references public.profiles(id) on delete set null,
  kind text not null default 'POST' check (kind in ('POST', 'ANNOUNCEMENT', 'CAMPAIGN', 'DRAW')),
  body text not null check (char_length(body) between 1 and 2000),
  image_url text check (image_url is null or image_url ~ '^https://'),
  meta jsonb not null default '{}'::jsonb,
  is_pinned boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists org_posts_feed_idx on public.org_posts (org_id, is_pinned desc, created_at desc);
create table if not exists public.org_post_likes (
  post_id uuid not null references public.org_posts(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (post_id, user_id)
);
create table if not exists public.org_post_comments (
  id uuid primary key default gen_random_uuid(),
  post_id uuid not null references public.org_posts(id) on delete cascade,
  author_id uuid references public.profiles(id) on delete set null,
  body text not null check (char_length(body) between 1 and 1000),
  created_at timestamptz not null default now()
);
create index if not exists org_post_comments_idx on public.org_post_comments (post_id, created_at);

create table if not exists public.lucky_draws (
  id uuid primary key default gen_random_uuid(),
  scope text not null check (scope in ('ORG_CAMPAIGN', 'CHALLENGE', 'CLUB', 'RACE', 'SYSTEM')),
  ref_id uuid,
  title text not null check (char_length(title) between 3 and 120),
  rule text not null default 'COMPLETED' check (rule in ('COMPLETED', 'ACTIVE', 'ALL')),
  prizes jsonb not null,
  exclude_winners boolean not null default true,
  status text not null default 'READY' check (status in ('READY', 'DONE', 'CANCELLED')),
  seed text,
  entrant_count integer,
  entrants_hash text,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  run_by uuid references public.profiles(id) on delete set null,
  run_at timestamptz,
  check ((scope = 'SYSTEM') = (ref_id is null))
);
create index if not exists lucky_draws_ref_idx on public.lucky_draws (scope, ref_id, created_at desc);
create table if not exists public.lucky_draw_winners (
  draw_id uuid not null references public.lucky_draws(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  prize text not null,
  position integer not null,
  primary key (draw_id, user_id)
);

alter table public.org_pending_invites enable row level security;
alter table public.org_campaign_results enable row level security;
alter table public.org_posts enable row level security;
alter table public.org_post_likes enable row level security;
alter table public.org_post_comments enable row level security;
alter table public.lucky_draws enable row level security;
alter table public.lucky_draw_winners enable row level security;
revoke all on public.org_pending_invites, public.org_campaign_results, public.org_posts, public.org_post_likes, public.org_post_comments,
  public.lucky_draws, public.lucky_draw_winners from anon, authenticated;

-- Ảnh bài đăng của thành viên: org-media/<org_id>/posts/<user_id>/...
drop policy if exists org_media_post_insert on storage.objects;
create policy org_media_post_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'org-media' and (storage.foldername(name))[2] = 'posts' and (storage.foldername(name))[3] = auth.uid()::text
              and public.org_is_member(((storage.foldername(name))[1])::uuid));

-- ---------------------------------------------------------------------
-- 2. Đơn vị nhiều cấp + trưởng đơn vị
-- ---------------------------------------------------------------------
create or replace function private.org_subtree(p_unit uuid) returns uuid[]
language sql stable security definer set search_path = public as $$
  with recursive t as (
    select u.id, 1 as lvl from public.org_units u where u.id = p_unit
    union all
    select u.id, t.lvl + 1 from public.org_units u join t on u.parent_id = t.id where t.lvl < 10
  )
  select coalesce(array_agg(t.id), '{}'::uuid[]) from t
$$;

create or replace function private.org_unit_depth(p_unit uuid) returns integer
language sql stable security definer set search_path = public as $$
  with recursive t as (
    select u.id, u.parent_id, 1 as lvl from public.org_units u where u.id = p_unit
    union all
    select u.id, u.parent_id, t.lvl + 1 from public.org_units u join t on u.id = t.parent_id where t.lvl < 10
  )
  select coalesce(max(t.lvl), 0) from t
$$;

-- Đơn vị người gọi được quản lý: null = toàn tổ chức (quản trị); mảng rỗng = không quản lý đơn vị nào
create or replace function private.org_my_units(p_org uuid) returns uuid[]
language sql stable security definer set search_path = public as $$
  select case when public.org_is_admin(p_org) then null
              else coalesce((select private.org_subtree(m.unit_id) from public.org_members m
                              where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'APPROVED'
                                and m.role = 'UNIT_ADMIN' and m.unit_id is not null), '{}'::uuid[]) end
$$;

create or replace function private.org_can_manage(p_org uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select private.org_my_units(p_org) is null or cardinality(private.org_my_units(p_org)) > 0
$$;

create or replace function private.user_email(p_user uuid) returns text
language sql stable security definer set search_path = public as $$
  select lower(u.email) from auth.users u where u.id = p_user
$$;

-- Thông tin công khai trong tổ chức (thêm cài đặt 008400)
create or replace function private.org_json(o public.organizations) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', o.id, 'name', o.name, 'kind', o.kind, 'description', o.description, 'logo_url', o.logo_url,
    'cover_url', o.cover_url, 'cover_position', o.cover_position, 'tagline', o.tagline, 'theme', o.theme,
    'join_policy', o.join_policy, 'unit_label', o.unit_label, 'allow_self_unit', o.allow_self_unit,
    'status', o.status, 'active_until', o.active_until, 'active', private.org_active(o.id),
    'seat_limit', o.seat_limit, 'seats_used', private.org_seats_used(o.id), 'club_limit', o.club_limit,
    'include_club_pro', o.include_club_pro,
    'club_count', (select count(*)::int from public.org_clubs oc where oc.org_id = o.id and oc.status = 'APPROVED'),
    'email_domains', to_jsonb(o.email_domains), 'domain_auto_approve', o.domain_auto_approve, 'domain_only', o.domain_only,
    'privacy_mode', o.privacy_mode, 'member_posts', o.member_posts,
    'created_at', o.created_at)
$$;

create or replace function public.org_detail(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.organizations := (select x from public.organizations x where x.id = p_org);
  v_admin boolean := public.org_is_admin(p_org);
  v_units uuid[] := private.org_my_units(p_org);
  me public.org_members := (select m from public.org_members m where m.org_id = p_org and m.user_id = v_uid);
begin
  if o.id is null then raise exception 'ORG_NOT_FOUND'; end if;
  if not public.org_is_member(p_org) then raise exception 'NOT_A_MEMBER'; end if;
  return private.org_json(o) || jsonb_build_object(
    'my_role', coalesce(private.org_role(p_org), 'MEMBER'), 'is_admin', v_admin, 'is_system_admin', public.is_system_admin(),
    'is_unit_admin', not v_admin and cardinality(v_units) > 0, 'managed_units', case when v_admin then null else to_jsonb(v_units) end,
    'my_unit_id', me.unit_id, 'is_real_member', me.status = 'APPROVED',
    'units', coalesce((select jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name, 'parent_id', u.parent_id,
                 'members', (select count(*)::int from public.org_members m where m.unit_id = u.id and m.status = 'APPROVED')) order by u.sort, u.name)
               from public.org_units u where u.org_id = p_org), '[]'::jsonb),
    'clubs', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
                 'member_count', c.member_count, 'status', oc.status, 'pro_granted', oc.pro_granted) order by oc.status, c.name)
               from public.org_clubs oc join public.clubs c on c.id = oc.club_id
              where oc.org_id = p_org and (oc.status = 'APPROVED' or v_admin)), '[]'::jsonb),
    'pending_members', case when v_admin or cardinality(v_units) > 0 then
                         (select count(*)::int from public.org_members m where m.org_id = p_org and m.status = 'PENDING'
                             and (v_admin or m.unit_id = any(v_units))) end,
    'pending_invites', case when v_admin then (select count(*)::int from public.org_pending_invites i where i.org_id = p_org) end,
    'invite_code', case when v_admin or cardinality(v_units) > 0 then o.invite_code end,
    'billing', case when v_admin then jsonb_build_object('legal_name', o.legal_name, 'tax_code', o.tax_code, 'contact_name', o.contact_name,
                                                         'contact_phone', o.contact_phone, 'contact_email', o.contact_email) end);
end $$;

create or replace function public.org_invite_preview(p_code text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.organizations := (select x from public.organizations x where x.invite_code = upper(trim(coalesce(p_code, ''))));
  v_email text := private.user_email(v_uid);
  v_invited boolean;
  v_domain_ok boolean;
begin
  if o.id is null then return null; end if;
  v_invited := exists (select 1 from public.org_pending_invites i where i.org_id = o.id and i.email = v_email);
  v_domain_ok := split_part(coalesce(v_email, ''), '@', 2) = any(o.email_domains);
  return jsonb_build_object('id', o.id, 'name', o.name, 'kind', o.kind, 'logo_url', o.logo_url, 'cover_url', o.cover_url,
    'cover_position', o.cover_position, 'theme', o.theme, 'tagline', o.tagline, 'description', o.description,
    'join_policy', o.join_policy, 'unit_label', o.unit_label, 'allow_self_unit', o.allow_self_unit,
    'active', private.org_active(o.id), 'full', private.org_seats_used(o.id) >= o.seat_limit,
    'member_count', private.org_seats_used(o.id),
    'units', case when o.allow_self_unit then coalesce((select jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name, 'parent_id', u.parent_id) order by u.sort, u.name)
                                                          from public.org_units u where u.org_id = o.id), '[]'::jsonb) else '[]'::jsonb end,
    'domain_only', o.domain_only, 'email_domains', to_jsonb(o.email_domains), 'invited', v_invited,
    'auto_approve', v_invited or o.join_policy = 'OPEN' or (o.domain_auto_approve and v_domain_ok),
    'blocked', o.domain_only and not v_domain_ok and not v_invited,
    'my_status', (select m.status from public.org_members m where m.org_id = o.id and m.user_id = v_uid));
end $$;

create or replace function public.join_org(p_code text, p_unit uuid default null, p_employee_code text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  o public.organizations := (select x from public.organizations x where x.invite_code = upper(trim(coalesce(p_code, ''))));
  v_email text := private.user_email(v_uid);
  inv public.org_pending_invites;
  v_domain_ok boolean;
  v_status text;
  v_unit uuid;
  a record;
begin
  if o.id is null then raise exception 'INVALID_CODE'; end if;
  if not private.org_active(o.id) then raise exception 'ORG_INACTIVE'; end if;
  perform pg_advisory_xact_lock(hashtext('org_seats:' || o.id));
  v_status := (select m.status from public.org_members m where m.org_id = o.id and m.user_id = v_uid);
  if v_status is not null then return jsonb_build_object('org_id', o.id, 'status', v_status, 'duplicate', true); end if;
  inv := (select i from public.org_pending_invites i where i.org_id = o.id and i.email = v_email);
  v_domain_ok := split_part(coalesce(v_email, ''), '@', 2) = any(o.email_domains);
  if o.domain_only and not v_domain_ok and inv.email is null then raise exception 'DOMAIN_REQUIRED'; end if;
  v_unit := coalesce(inv.unit_id, case when o.allow_self_unit then (select u.id from public.org_units u where u.id = p_unit and u.org_id = o.id) end);
  v_status := case when inv.email is not null or o.join_policy = 'OPEN' or (o.domain_auto_approve and v_domain_ok) then 'APPROVED' else 'PENDING' end;
  if v_status = 'APPROVED' and private.org_seats_used(o.id) >= o.seat_limit then raise exception 'ORG_FULL'; end if;
  insert into public.org_members (org_id, user_id, role, status, unit_id, employee_code)
  values (o.id, v_uid, coalesce(inv.role, 'MEMBER'), v_status, v_unit,
          coalesce(inv.employee_code, nullif(left(trim(coalesce(p_employee_code, '')), 40), '')));
  delete from public.org_pending_invites where org_id = o.id and email = v_email;
  if v_status = 'PENDING' then
    for a in select m.user_id from public.org_members m
              where m.org_id = o.id and m.status = 'APPROVED'
                and (m.role in ('OWNER', 'ADMIN') or (m.role = 'UNIT_ADMIN' and v_unit = any(private.org_subtree(m.unit_id)))) loop
      perform private.notify(a.user_id, null, 'ORG_JOIN_REQUEST', private.display_name(v_uid) || ' xin vào ' || o.name,
        'Duyệt ở mục Thành viên của tổ chức.', '/orgs/' || o.id || '?tab=members', v_uid, false);
    end loop;
  end if;
  return jsonb_build_object('org_id', o.id, 'status', v_status);
end $$;

create or replace function public.update_org(p_org uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_domains text[];
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if p ? 'name' and char_length(trim(coalesce(p->>'name', ''))) < 2 then raise exception 'ORG_NAME_REQUIRED'; end if;
  if p ? 'tagline' and char_length(coalesce(p->>'tagline', '')) > 80 then raise exception 'TAGLINE_TOO_LONG'; end if;
  if p ? 'unit_label' and char_length(trim(coalesce(p->>'unit_label', ''))) not between 2 and 30 then raise exception 'INVALID_UNIT_LABEL'; end if;
  if (p ? 'cover_url' and coalesce(p->>'cover_url', '') <> '' and p->>'cover_url' !~ '^https://')
     or (p ? 'logo_url' and coalesce(p->>'logo_url', '') <> '' and p->>'logo_url' !~ '^https://') then raise exception 'INVALID_URL'; end if;
  if p ? 'email_domains' then
    v_domains := (select coalesce(array_agg(distinct lower(trim(both '@ ' from d.v))), '{}'::text[])
                    from jsonb_array_elements_text(coalesce(p->'email_domains', '[]'::jsonb)) d(v) where trim(d.v) <> '');
    if cardinality(v_domains) > 10 or exists (select 1 from unnest(v_domains) x where x !~ '^[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$')
      then raise exception 'INVALID_DOMAIN'; end if;
    if exists (select 1 from unnest(v_domains) x where x in ('gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com'))
      then raise exception 'PUBLIC_DOMAIN'; end if;
  end if;
  update public.organizations set
    name = case when p ? 'name' then left(trim(p->>'name'), 120) else name end,
    description = case when p ? 'description' then nullif(left(trim(coalesce(p->>'description', '')), 2000), '') else description end,
    logo_url = case when p ? 'logo_url' then nullif(p->>'logo_url', '') else logo_url end,
    cover_url = case when p ? 'cover_url' then nullif(p->>'cover_url', '') else cover_url end,
    cover_position = case when p ? 'cover_position' then least(greatest(coalesce((p->>'cover_position')::int, 50), 0), 100) else cover_position end,
    tagline = case when p ? 'tagline' then nullif(trim(coalesce(p->>'tagline', '')), '') else tagline end,
    theme = case when p ? 'theme' then case when p->>'theme' in ('AURORA', 'SUNSET', 'OCEAN', 'FOREST', 'GOLD', 'NIGHT') then p->>'theme' end else theme end,
    join_policy = case when p->>'join_policy' in ('OPEN', 'APPROVAL') then p->>'join_policy' else join_policy end,
    unit_label = case when p ? 'unit_label' then trim(p->>'unit_label') else unit_label end,
    allow_self_unit = coalesce((p->>'allow_self_unit')::boolean, allow_self_unit),
    email_domains = case when p ? 'email_domains' then v_domains else email_domains end,
    domain_auto_approve = coalesce((p->>'domain_auto_approve')::boolean, domain_auto_approve),
    domain_only = coalesce((p->>'domain_only')::boolean, domain_only),
    privacy_mode = coalesce((p->>'privacy_mode')::boolean, privacy_mode),
    member_posts = coalesce((p->>'member_posts')::boolean, member_posts),
    legal_name = case when p ? 'legal_name' then nullif(left(trim(coalesce(p->>'legal_name', '')), 200), '') else legal_name end,
    tax_code = case when p ? 'tax_code' then nullif(left(trim(coalesce(p->>'tax_code', '')), 20), '') else tax_code end,
    contact_name = case when p ? 'contact_name' then nullif(left(trim(coalesce(p->>'contact_name', '')), 80), '') else contact_name end,
    contact_phone = case when p ? 'contact_phone' then nullif(left(trim(coalesce(p->>'contact_phone', '')), 20), '') else contact_phone end,
    contact_email = case when p ? 'contact_email' then nullif(left(trim(coalesce(p->>'contact_email', '')), 120), '') else contact_email end
   where id = p_org;
  if coalesce((select o.domain_only and cardinality(o.email_domains) = 0 from public.organizations o where o.id = p_org), false) then
    raise exception 'DOMAIN_REQUIRED_LIST';
  end if;
  return public.org_detail(p_org);
end $$;

drop function if exists public.save_org_unit(uuid, uuid, text);
create or replace function public.save_org_unit(p_org uuid, p_id uuid, p_name text, p_parent uuid default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_id uuid := p_id; v_name text := trim(coalesce(p_name, ''));
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if char_length(v_name) not between 1 and 80 then raise exception 'INVALID_NAME'; end if;
  if p_parent is not null then
    if not exists (select 1 from public.org_units u where u.id = p_parent and u.org_id = p_org) then raise exception 'NOT_FOUND'; end if;
    if p_id is not null and p_parent = any(private.org_subtree(p_id)) then raise exception 'UNIT_CYCLE'; end if;
    if private.org_unit_depth(p_parent) >= 4 then raise exception 'UNIT_DEPTH'; end if;
  end if;
  if exists (select 1 from public.org_units u where u.org_id = p_org and lower(u.name) = lower(v_name)
               and u.parent_id is not distinct from p_parent and u.id is distinct from p_id) then
    raise exception 'UNIT_EXISTS';
  end if;
  if p_id is null and (select count(*) from public.org_units u where u.org_id = p_org) >= 500 then raise exception 'UNIT_LIMIT'; end if;
  if v_id is null then
    v_id := gen_random_uuid();
    insert into public.org_units (id, org_id, name, parent_id, sort)
    values (v_id, p_org, v_name, p_parent, coalesce((select max(u.sort) from public.org_units u where u.org_id = p_org), 0) + 1);
  else
    update public.org_units set name = v_name, parent_id = p_parent where id = p_id and org_id = p_org;
    if not found then raise exception 'NOT_FOUND'; end if;
  end if;
  return v_id;
end $$;

create or replace function public.org_members_list(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_units uuid[] := private.org_my_units(p_org);
  v_admin boolean := v_units is null;
begin
  if not public.org_is_member(p_org) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('user_id', m.user_id, 'name', private.display_name(m.user_id), 'avatar_url', pr.avatar_url,
             'role', m.role, 'status', m.status, 'unit_id', m.unit_id, 'unit_name', u.name, 'joined_at', m.joined_at,
             'employee_code', case when v_admin or m.unit_id = any(v_units) then m.employee_code end,
             'manageable', m.role <> 'OWNER' and (v_admin or (m.role = 'MEMBER' and m.unit_id = any(v_units))))
             order by (m.status = 'PENDING') desc, case m.role when 'OWNER' then 0 when 'ADMIN' then 1 when 'UNIT_ADMIN' then 2 else 3 end,
                      private.display_name(m.user_id))
           from public.org_members m join public.profiles pr on pr.id = m.user_id left join public.org_units u on u.id = m.unit_id
          where m.org_id = p_org and (m.status = 'APPROVED' or v_admin or m.unit_id = any(v_units))), '[]'::jsonb);
end $$;

create or replace function public.set_org_member(p_org uuid, p_user uuid, p jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_units uuid[] := private.org_my_units(p_org);
  v_admin boolean := v_units is null;
  m public.org_members := (select x from public.org_members x where x.org_id = p_org and x.user_id = p_user);
  v_org text := (select o.name from public.organizations o where o.id = p_org);
  v_unit uuid;
begin
  if not v_admin and cardinality(v_units) = 0 then raise exception 'FORBIDDEN'; end if;
  if m.user_id is null then raise exception 'MEMBER_NOT_FOUND'; end if;
  -- Trưởng đơn vị: chỉ thành viên thường trong đơn vị mình
  if not v_admin and (m.role <> 'MEMBER' or m.unit_id is null or not (m.unit_id = any(v_units))) then raise exception 'FORBIDDEN'; end if;
  if p->>'action' = 'REMOVE' then
    if m.role = 'OWNER' then raise exception 'OWNER_CANNOT_LEAVE'; end if;
    delete from public.org_members where org_id = p_org and user_id = p_user;
    return;
  end if;
  perform pg_advisory_xact_lock(hashtext('org_seats:' || p_org));
  if p ? 'unit_id' then
    v_unit := (select u.id from public.org_units u where u.id = nullif(p->>'unit_id', '')::uuid and u.org_id = p_org);
    if not v_admin and (v_unit is null or not (v_unit = any(v_units))) then raise exception 'FORBIDDEN'; end if;
    update public.org_members set unit_id = v_unit where org_id = p_org and user_id = p_user;
  end if;
  if p->>'status' = 'APPROVED' and m.status = 'PENDING' then
    if private.org_seats_used(p_org) >= (select o.seat_limit from public.organizations o where o.id = p_org) then raise exception 'ORG_FULL'; end if;
    update public.org_members set status = 'APPROVED', joined_at = now() where org_id = p_org and user_id = p_user;
    perform private.notify(p_user, null, 'ORG_APPROVED', 'Bạn đã vào ' || coalesce(v_org, 'tổ chức'), 'Xem chiến dịch đang diễn ra.',
      '/orgs/' || p_org, v_uid, false);
  end if;
  if p->>'role' in ('ADMIN', 'UNIT_ADMIN', 'MEMBER') then
    if not v_admin or m.role = 'OWNER' then raise exception 'FORBIDDEN'; end if;
    if p->>'role' = 'UNIT_ADMIN' and (select x.unit_id from public.org_members x where x.org_id = p_org and x.user_id = p_user) is null then
      raise exception 'UNIT_REQUIRED';
    end if;
    update public.org_members set role = p->>'role' where org_id = p_org and user_id = p_user;
  end if;
  if p ? 'employee_code' then
    update public.org_members set employee_code = nullif(left(trim(coalesce(p->>'employee_code', '')), 40), '') where org_id = p_org and user_id = p_user;
  end if;
end $$;

-- Tìm / tạo đơn vị theo đường dẫn "Vùng 1 / Chi nhánh A / Phòng KT"
create or replace function private.org_unit_path(p_org uuid, p_path text, p_create boolean) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_parent uuid := null;
  v_id uuid;
  seg text;
  n integer := 0;
begin
  for seg in select trim(s.x) from unnest(regexp_split_to_array(coalesce(p_path, ''), '\s*[/>]\s*')) with ordinality as s(x, i)
              where trim(s.x) <> '' order by s.i loop
    n := n + 1;
    if n > 4 then raise exception 'UNIT_DEPTH'; end if;
    v_id := (select u.id from public.org_units u where u.org_id = p_org and u.parent_id is not distinct from v_parent
               and lower(u.name) = lower(left(seg, 80)));
    if v_id is null then
      if not p_create then return null; end if;
      v_id := gen_random_uuid();
      insert into public.org_units (id, org_id, name, parent_id, sort)
      values (v_id, p_org, left(seg, 80), v_parent, coalesce((select max(u.sort) from public.org_units u where u.org_id = p_org), 0) + 1);
    end if;
    v_parent := v_id;
  end loop;
  return v_parent;
end $$;

-- Nhập danh sách từ Excel / CSV (quản trị tổ chức)
create or replace function public.org_import_members(p_org uuid, p_rows jsonb, p_opts jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_create boolean := coalesce((p_opts->>'create_units')::boolean, true);
  v_remove boolean := coalesce((p_opts->>'remove_missing')::boolean, false);
  v_seats integer := (select o.seat_limit from public.organizations o where o.id = p_org);
  r jsonb;
  v_email text;
  v_user uuid;
  v_unit uuid;
  v_role text;
  v_code text;
  v_cur public.org_members;
  v_units_before integer := (select count(*) from public.org_units u where u.org_id = p_org);
  v_emails text[] := '{}';
  n_added integer := 0; n_updated integer := 0; n_invited integer := 0; n_removed integer := 0;
  v_errors jsonb := '[]'::jsonb;
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 5000 then raise exception 'INVALID_ROWS'; end if;
  perform pg_advisory_xact_lock(hashtext('org_seats:' || p_org));
  for r in select x from jsonb_array_elements(p_rows) x loop
    v_email := lower(trim(coalesce(r->>'email', '')));
    if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
      v_errors := v_errors || jsonb_build_object('email', left(v_email, 120), 'error', 'INVALID_EMAIL');
      continue;
    end if;
    v_emails := v_emails || v_email;
    begin
      v_unit := case when coalesce(trim(r->>'unit'), '') <> '' then private.org_unit_path(p_org, r->>'unit', v_create) end;
    exception when others then
      v_errors := v_errors || jsonb_build_object('email', v_email, 'error', 'UNIT_DEPTH');
      continue;
    end;
    v_role := case when upper(coalesce(r->>'role', '')) in ('UNIT_ADMIN', 'TRUONG_DON_VI') and v_unit is not null then 'UNIT_ADMIN' else 'MEMBER' end;
    v_code := nullif(left(trim(coalesce(r->>'employee_code', '')), 40), '');
    v_user := (select u.id from auth.users u where lower(u.email) = v_email);
    if v_user is null then
      insert into public.org_pending_invites (org_id, email, unit_id, employee_code, role) values (p_org, v_email, v_unit, v_code, v_role)
      on conflict (org_id, email) do update set unit_id = excluded.unit_id, employee_code = excluded.employee_code, role = excluded.role;
      n_invited := n_invited + 1;
      continue;
    end if;
    v_cur := (select m from public.org_members m where m.org_id = p_org and m.user_id = v_user);
    if v_cur.user_id is null or v_cur.status = 'PENDING' then
      if private.org_seats_used(p_org) >= v_seats then
        v_errors := v_errors || jsonb_build_object('email', v_email, 'error', 'ORG_FULL');
        continue;
      end if;
      insert into public.org_members (org_id, user_id, role, status, unit_id, employee_code)
      values (p_org, v_user, v_role, 'APPROVED', v_unit, v_code)
      on conflict (org_id, user_id) do update set status = 'APPROVED', unit_id = coalesce(excluded.unit_id, org_members.unit_id),
             employee_code = coalesce(excluded.employee_code, org_members.employee_code), role = excluded.role, joined_at = now();
      n_added := n_added + 1;
      perform private.notify(v_user, null, 'ORG_APPROVED', 'Bạn đã được thêm vào ' || (select o.name from public.organizations o where o.id = p_org),
        'Xem chiến dịch đang diễn ra.', '/orgs/' || p_org, v_uid, false);
    else
      update public.org_members set unit_id = coalesce(v_unit, unit_id), employee_code = coalesce(v_code, employee_code),
             role = case when role in ('OWNER', 'ADMIN') then role else v_role end
       where org_id = p_org and user_id = v_user;
      n_updated := n_updated + 1;
    end if;
  end loop;
  if v_remove then
    n_removed := (select count(*)::int from public.org_members m where m.org_id = p_org and m.role in ('MEMBER', 'UNIT_ADMIN')
                    and not (coalesce(private.user_email(m.user_id), '') = any(v_emails)));
    delete from public.org_members m where m.org_id = p_org and m.role in ('MEMBER', 'UNIT_ADMIN')
       and not (coalesce(private.user_email(m.user_id), '') = any(v_emails));
    delete from public.org_pending_invites i where i.org_id = p_org and not (i.email = any(v_emails));
  end if;
  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_uid, 'ORG_IMPORT', 'org:' || p_org, jsonb_build_object('rows', jsonb_array_length(p_rows), 'added', n_added, 'updated', n_updated,
          'invited', n_invited, 'removed', n_removed, 'remove_missing', v_remove));
  return jsonb_build_object('added', n_added, 'updated', n_updated, 'invited', n_invited, 'removed', n_removed,
    'units_created', (select count(*)::int from public.org_units u where u.org_id = p_org) - v_units_before, 'errors', v_errors);
end $$;

create or replace function public.org_pending_invites_list(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('email', i.email, 'unit_name', u.name, 'employee_code', i.employee_code, 'role', i.role,
             'created_at', i.created_at) order by i.created_at desc)
           from public.org_pending_invites i left join public.org_units u on u.id = i.unit_id where i.org_id = p_org), '[]'::jsonb);
end $$;

create or replace function public.delete_org_pending_invite(p_org uuid, p_email text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  delete from public.org_pending_invites where org_id = p_org and email = lower(trim(coalesce(p_email, '')));
end $$;

-- ---------------------------------------------------------------------
-- 3. Chiến dịch: trần km / ngày, ngày hội ×2 / ×3, chốt kết quả + duyệt top N
-- ---------------------------------------------------------------------
-- Số liệu theo ngày (giờ VN): km mỗi ngày bị chặn ở trần; ngày hội nhân hệ số cho km / số buổi (số ngày chạy không nhân)
create or replace function private.org_day_stats(p_user uuid, p_from timestamptz, p_to timestamptz, p_min_km numeric, p_cap numeric, p_boost jsonb)
returns table (dist_value numeric, runs_value numeric, km numeric, runs integer, active_days integer)
language sql stable security definer set search_path = public as $$
  with d as (
    select (x.started_at at time zone 'Asia/Ho_Chi_Minh')::date as day, sum(x.distance_m) / 1000.0 as km, count(*)::int as runs
      from public.activities x
     where x.user_id = p_user and x.validation_status = 'APPROVED' and x.shared
       and public.activity_is_countable(x.status, x.validation_status)
       and x.started_at >= p_from and x.started_at < p_to and coalesce(x.distance_m, 0) >= coalesce(p_min_km, 0) * 1000
     group by 1
  ), e as (
    select d.day, d.runs, least(d.km, coalesce(p_cap, d.km)) as ckm,
           coalesce((select max(least(greatest((b->>'mult')::numeric, 1), 3)) from jsonb_array_elements(coalesce(p_boost, '[]'::jsonb)) b
                      where (b->>'date') = to_char(d.day, 'YYYY-MM-DD')), 1) as mult
      from d
  )
  select coalesce(round(sum(e.ckm * e.mult), 2), 0), coalesce(sum(e.runs * e.mult), 0), coalesce(round(sum(e.ckm), 2), 0),
         coalesce(sum(e.runs), 0)::int, count(*)::int
    from e
$$;

create or replace function private.org_campaign_rows(c public.org_campaigns)
returns table (user_id uuid, unit_id uuid, direct boolean, value numeric, km numeric, runs integer, active_days integer)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  if c.locked_at is not null then
    return query select r.user_id, r.unit_id, r.direct, r.value, r.km, r.runs, r.active_days
                   from public.org_campaign_results r where r.campaign_id = c.id and r.review_status <> 'DQ';
  else
    return query select pp.user_id, pp.unit_id, pp.direct,
                        case c.metric when 'DISTANCE' then s.dist_value when 'RUNS' then s.runs_value else s.active_days::numeric end,
                        s.km, s.runs, s.active_days
                   from private.org_people(c.org_id) pp
                   cross join lateral private.org_day_stats(pp.user_id, c.starts_at, least(c.ends_at, now()), c.min_run_km, c.daily_cap_km, c.boost_days) s;
  end if;
end $$;

create or replace function private.org_clean_boost(p jsonb, p_from timestamptz, p_to timestamptz) returns jsonb
language sql stable as $$
  select coalesce(jsonb_agg(jsonb_build_object('date', t.day, 'mult', t.mult) order by t.day), '[]'::jsonb)
    from (select distinct on (b->>'date') b->>'date' as day, least(greatest(coalesce((b->>'mult')::int, 2), 2), 3) as mult
            from jsonb_array_elements(case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) b
           where coalesce(b->>'date', '') ~ '^\d{4}-\d{2}-\d{2}$'
             and (b->>'date')::date between (p_from at time zone 'Asia/Ho_Chi_Minh')::date and ((p_to - interval '1 second') at time zone 'Asia/Ho_Chi_Minh')::date
           order by b->>'date') t
$$;

create or replace function public.save_org_campaign(p_org uuid, p_id uuid, p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_id uuid := p_id;
  v_title text := trim(coalesce(p->>'title', ''));
  v_start timestamptz := nullif(p->>'starts_at', '')::timestamptz;
  v_end timestamptz := nullif(p->>'ends_at', '')::timestamptz;
  v_metric text := coalesce(p->>'metric', 'DISTANCE');
  v_org text := (select o.name from public.organizations o where o.id = p_org);
  v_boost jsonb;
  r record;
begin
  if not public.org_is_admin(p_org) then raise exception 'FORBIDDEN'; end if;
  if not private.org_active(p_org) then raise exception 'ORG_INACTIVE'; end if;
  if char_length(v_title) not between 3 and 120 then raise exception 'TITLE_REQUIRED'; end if;
  if v_metric not in ('DISTANCE', 'RUNS', 'ACTIVE_DAYS') then raise exception 'INVALID_METRIC'; end if;
  if v_start is null or v_end is null or v_end <= v_start or v_end - v_start > interval '366 days' then raise exception 'INVALID_TIME_RANGE'; end if;
  if p_id is not null and (select c.locked_at from public.org_campaigns c where c.id = p_id) is not null then raise exception 'CAMPAIGN_LOCKED'; end if;
  v_boost := private.org_clean_boost(p->'boost_days', v_start, v_end);
  if jsonb_array_length(v_boost) > 20 then raise exception 'TOO_MANY_BOOST_DAYS'; end if;
  if v_id is null then
    v_id := gen_random_uuid();
    insert into public.org_campaigns (id, org_id, title, description, metric, starts_at, ends_at, goal_total, goal_per_person, min_run_km,
                                      daily_cap_km, review_top, boost_days, cert_enabled, created_by)
    values (v_id, p_org, v_title, nullif(left(trim(coalesce(p->>'description', '')), 2000), ''), v_metric, v_start, v_end,
            nullif(p->>'goal_total', '')::numeric, nullif(p->>'goal_per_person', '')::numeric,
            coalesce(nullif(p->>'min_run_km', '')::numeric, 1), nullif(p->>'daily_cap_km', '')::numeric,
            coalesce(nullif(p->>'review_top', '')::int, 0), v_boost, coalesce((p->>'cert_enabled')::boolean, false), v_uid);
    insert into public.org_posts (org_id, author_id, kind, body, meta, is_pinned)
    values (p_org, v_uid, 'CAMPAIGN', 'Chiến dịch mới: ' || v_title || coalesce(E'\n' || nullif(left(trim(coalesce(p->>'description', '')), 400), ''), ''),
            jsonb_build_object('campaign_id', v_id), false);
    for r in select pp.user_id from private.org_people(p_org) pp loop
      perform private.notify(r.user_id, null, 'ORG_CAMPAIGN', coalesce(v_org, 'Tổ chức') || ': ' || v_title,
        'Chiến dịch mới — bài chạy hợp lệ của bạn được tính tự động.', '/orgs/' || p_org || '/campaigns/' || v_id, v_uid, false);
    end loop;
  else
    update public.org_campaigns set title = v_title, description = nullif(left(trim(coalesce(p->>'description', '')), 2000), ''),
           metric = v_metric, starts_at = v_start, ends_at = v_end,
           goal_total = nullif(p->>'goal_total', '')::numeric, goal_per_person = nullif(p->>'goal_per_person', '')::numeric,
           min_run_km = coalesce(nullif(p->>'min_run_km', '')::numeric, 1), daily_cap_km = nullif(p->>'daily_cap_km', '')::numeric,
           review_top = coalesce(nullif(p->>'review_top', '')::int, 0), boost_days = v_boost,
           cert_enabled = coalesce((p->>'cert_enabled')::boolean, cert_enabled)
     where id = p_id and org_id = p_org;
    if not found then raise exception 'NOT_FOUND'; end if;
  end if;
  return v_id;
end $$;

-- Chốt kết quả sau khi kết thúc: lưu bảng cố định; top N chờ duyệt trước khi trao giải
create or replace function public.lock_org_campaign(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.org_campaigns := (select x from public.org_campaigns x where x.id = p_id for update);
begin
  if c.id is null or not public.org_is_admin(c.org_id) then raise exception 'FORBIDDEN'; end if;
  if c.locked_at is not null then raise exception 'CAMPAIGN_LOCKED'; end if;
  if c.ends_at > now() then raise exception 'CAMPAIGN_NOT_ENDED'; end if;
  insert into public.org_campaign_results (campaign_id, user_id, unit_id, direct, value, km, runs, active_days, rank, review_status)
  select c.id, t.user_id, t.unit_id, t.direct, t.value, t.km, t.runs, t.active_days, t.rn,
         case when t.rn <= c.review_top and t.value > 0 then 'PENDING' else 'OK' end
    from (select r.*, row_number() over (order by r.value desc, r.km desc, r.user_id) as rn from private.org_campaign_rows(c) r) t
  on conflict (campaign_id, user_id) do nothing;
  update public.org_campaigns set locked_at = now(), locked_by = v_uid where id = p_id;
  return jsonb_build_object('locked', true, 'pending', (select count(*)::int from public.org_campaign_results r where r.campaign_id = p_id and r.review_status = 'PENDING'));
end $$;

create or replace function public.review_campaign_result(p_campaign uuid, p_user uuid, p_ok boolean, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.org_campaigns := (select x from public.org_campaigns x where x.id = p_campaign);
begin
  if c.id is null or not public.org_is_admin(c.org_id) then raise exception 'FORBIDDEN'; end if;
  if c.locked_at is null then raise exception 'CAMPAIGN_NOT_LOCKED'; end if;
  if not p_ok and char_length(trim(coalesce(p_note, ''))) < 3 then raise exception 'REASON_REQUIRED'; end if;
  update public.org_campaign_results set review_status = case when p_ok then 'OK' else 'DQ' end,
         review_note = nullif(left(trim(coalesce(p_note, '')), 300), ''), reviewed_by = v_uid
   where campaign_id = p_campaign and user_id = p_user;
  if not found then raise exception 'NOT_FOUND'; end if;
  if not p_ok then
    perform private.notify(p_user, null, 'ORG_CAMPAIGN_DQ', 'Kết quả chiến dịch “' || c.title || '” không được công nhận',
      left(trim(p_note), 300), '/orgs/' || c.org_id || '/campaigns/' || c.id, v_uid, true);
  end if;
end $$;

create or replace function public.org_campaign_board(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.org_campaigns := (select x from public.org_campaigns x where x.id = p_id);
  o public.organizations;
  v_admin boolean;
  v_hide boolean;
begin
  if c.id is null then raise exception 'NOT_FOUND'; end if;
  if not (public.org_is_member(c.org_id) or exists (select 1 from private.org_people(c.org_id) pp where pp.user_id = auth.uid())) then
    raise exception 'NOT_A_MEMBER';
  end if;
  o := (select x from public.organizations x where x.id = c.org_id);
  v_admin := public.org_is_admin(c.org_id);
  v_hide := o.privacy_mode and not v_admin;
  return (
    with recursive tree as (
      select u.id as anc, u.id as des, 1 as lvl from public.org_units u where u.org_id = c.org_id
      union all
      select t.anc, ch.id, t.lvl + 1 from tree t join public.org_units ch on ch.parent_id = t.des where t.lvl < 10
    ),
    rows as (select * from private.org_campaign_rows(c)),
    ranked as (select r.*, row_number() over (order by r.value desc, r.km desc, r.user_id) as rn from rows r),
    units as (
      select u.id, u.name, u.parent_id, count(r.user_id)::int as members, count(r.user_id) filter (where r.value > 0)::int as active,
             coalesce(sum(r.value), 0) as total
        from public.org_units u join tree t on t.anc = u.id left join rows r on r.unit_id = t.des
       where u.org_id = c.org_id group by u.id, u.name, u.parent_id
    ),
    clubs as (
      select cl.id, cl.name, cl.avatar_url, cl.accent_color, count(r.user_id)::int as members,
             count(r.user_id) filter (where r.value > 0)::int as active, coalesce(sum(r.value), 0) as total
        from public.org_clubs oc join public.clubs cl on cl.id = oc.club_id
        join public.club_members cm on cm.club_id = cl.id and cm.status = 'APPROVED'
        left join rows r on r.user_id = cm.user_id
       where oc.org_id = c.org_id and oc.status = 'APPROVED' group by cl.id, cl.name, cl.avatar_url, cl.accent_color
    )
    select jsonb_build_object(
      'campaign', to_jsonb(c) - 'cert_design' || jsonb_build_object('org_name', o.name, 'org_logo', o.logo_url, 'has_cert_design', c.cert_design is not null,
                                                  'cert_design', case when v_admin then c.cert_design end),
      'is_admin', v_admin, 'privacy_mode', o.privacy_mode, 'hidden', v_hide, 'locked', c.locked_at is not null,
      'pending_reviews', case when v_admin then (select count(*)::int from public.org_campaign_results x where x.campaign_id = c.id and x.review_status = 'PENDING') end,
      'disqualified', case when v_admin then coalesce((select jsonb_agg(jsonb_build_object('user_id', x.user_id, 'name', private.display_name(x.user_id),
                        'value', x.value, 'note', x.review_note)) from public.org_campaign_results x where x.campaign_id = c.id and x.review_status = 'DQ'), '[]'::jsonb) end,
      'total', (select coalesce(sum(r.value), 0) from rows r),
      'total_km', (select coalesce(sum(r.km), 0) from rows r),
      'participants', (select count(*)::int from rows),
      'active', (select count(*)::int from rows r where r.value > 0),
      'completed', (select count(*)::int from rows r where c.goal_per_person is not null and r.value >= c.goal_per_person),
      'me', (select jsonb_build_object('rank', k.rn, 'value', k.value, 'km', k.km, 'runs', k.runs, 'active_days', k.active_days,
                                       'completed', c.goal_per_person is not null and k.value >= c.goal_per_person)
               from ranked k where k.user_id = auth.uid()),
      'people', case when v_hide then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('rank', k.rn, 'user_id', k.user_id,
                   'name', private.display_name(k.user_id), 'avatar_url', pr.avatar_url, 'unit_name', u.name, 'value', k.value, 'km', k.km,
                   'runs', k.runs, 'active_days', k.active_days, 'completed', c.goal_per_person is not null and k.value >= c.goal_per_person,
                   'review_status', case when v_admin then res.review_status end) order by k.rn)
                 from ranked k join public.profiles pr on pr.id = k.user_id left join public.org_units u on u.id = k.unit_id
                 left join public.org_campaign_results res on res.campaign_id = c.id and res.user_id = k.user_id
                where k.rn <= 500), '[]'::jsonb) end,
      'units', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'parent_id', x.parent_id, 'members', x.members,
                   'active', x.active, 'total', x.total, 'avg', case when x.members > 0 then round(x.total / x.members, 2) else 0 end)
                   order by x.total desc) from units x), '[]'::jsonb),
      'clubs', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'avatar_url', x.avatar_url, 'accent_color', x.accent_color,
                   'members', x.members, 'active', x.active, 'total', x.total,
                   'avg', case when x.members > 0 then round(x.total / x.members, 2) else 0 end) order by x.total desc) from clubs x), '[]'::jsonb)));
end $$;

-- Báo cáo: quản trị xem toàn tổ chức, trưởng đơn vị xem đơn vị mình (kể cả đơn vị con)
create or replace function public.org_report(p_org uuid, p_from timestamptz, p_to timestamptz) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_units uuid[] := private.org_my_units(p_org);
begin
  if not private.org_can_manage(p_org) then raise exception 'FORBIDDEN'; end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '400 days' then raise exception 'INVALID_TIME_RANGE'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('user_id', pp.user_id, 'name', private.display_name(pp.user_id), 'direct', pp.direct,
             'unit_name', u.name, 'employee_code', m.employee_code,
             'clubs', (select string_agg(cl.name, ', ' order by cl.name) from public.org_clubs oc join public.clubs cl on cl.id = oc.club_id
                        join public.club_members cm on cm.club_id = cl.id and cm.user_id = pp.user_id and cm.status = 'APPROVED'
                       where oc.org_id = p_org and oc.status = 'APPROVED'),
             'km', s.km, 'runs', s.runs, 'active_days', s.active_days) order by s.km desc, private.display_name(pp.user_id))
           from private.org_people(p_org) pp
           cross join lateral private.org_person_stats(pp.user_id, p_from, p_to, 0) s
           left join public.org_members m on m.org_id = p_org and m.user_id = pp.user_id
           left join public.org_units u on u.id = pp.unit_id
          where v_units is null or pp.unit_id = any(v_units)), '[]'::jsonb);
end $$;

-- ---------------------------------------------------------------------
-- 4. Chứng nhận hoàn thành chiến dịch (thiết kế như chứng nhận giải chạy ảo)
-- ---------------------------------------------------------------------
create or replace function public.set_org_campaign_cert(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  c public.org_campaigns := (select x from public.org_campaigns x where x.id = p_id);
  v_prefix text;
begin
  if c.id is null or not public.org_is_admin(c.org_id) then raise exception 'FORBIDDEN'; end if;
  if p is null or jsonb_typeof(p) = 'null' then
    update public.org_campaigns set cert_design = null where id = p_id;
    return null;
  end if;
  if jsonb_typeof(p) <> 'object' or length(p::text) > 200000 or jsonb_array_length(coalesce(p->'layers', '[]'::jsonb)) > 40 then
    raise exception 'INVALID_CERT_DESIGN';
  end if;
  -- Ảnh chỉ lấy từ kho ảnh của tổ chức
  v_prefix := '/storage/v1/object/public/org-media/' || c.org_id::text || '/';
  if exists (select 1 from (select p->>'bg_url' as u union all select p->>'art_url'
                            union all select l->>'src' from jsonb_array_elements(coalesce(p->'layers', '[]'::jsonb)) l) x
              where x.u is not null and (x.u !~ '^https://' or position(v_prefix in x.u) = 0)) then
    raise exception 'INVALID_CERT_IMAGE';
  end if;
  update public.org_campaigns set cert_design = p, cert_enabled = true where id = p_id;
  return p;
end $$;

-- Dữ liệu chứng nhận của tôi: đạt mục tiêu cá nhân (hoặc có chạy, khi chiến dịch không đặt mục tiêu và đã kết thúc)
create or replace function public.org_campaign_certificate(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.org_campaigns := (select x from public.org_campaigns x where x.id = p_id);
  o public.organizations;
  me jsonb;
  v_total integer;
begin
  if c.id is null then raise exception 'NOT_FOUND'; end if;
  if not c.cert_enabled then raise exception 'CERT_DISABLED'; end if;
  o := (select x from public.organizations x where x.id = c.org_id);
  me := (select to_jsonb(k) from (select r.*, row_number() over (order by r.value desc, r.km desc, r.user_id) as rn from private.org_campaign_rows(c) r) k
          where k.user_id = v_uid);
  v_total := (select count(*)::int from private.org_campaign_rows(c));
  if me is null
     or (c.goal_per_person is not null and (me->>'value')::numeric < c.goal_per_person)
     or (c.goal_per_person is null and ((me->>'value')::numeric <= 0 or c.ends_at > now())) then
    raise exception 'NOT_ELIGIBLE';
  end if;
  return jsonb_build_object('design', c.cert_design, 'campaign', c.title, 'metric', c.metric, 'org_name', o.name, 'org_logo', o.logo_url,
    'name', private.display_name(v_uid), 'unit_name', (select u.name from public.org_units u where u.id = (me->>'unit_id')::uuid),
    'value', (me->>'value')::numeric, 'km', (me->>'km')::numeric, 'runs', (me->>'runs')::int, 'active_days', (me->>'active_days')::int,
    'rank', (me->>'rn')::int, 'participants', v_total, 'date', least(c.ends_at, now()), 'starts_at', c.starts_at, 'ends_at', c.ends_at);
end $$;

-- ---------------------------------------------------------------------
-- 5. Bảng tin tổ chức (mô hình như CLB)
-- ---------------------------------------------------------------------
create or replace function private.org_post_json(x public.org_posts) returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(x) || jsonb_build_object('author_name', private.display_name(x.author_id),
    'author_avatar', (select pr.avatar_url from public.profiles pr where pr.id = x.author_id),
    'likes', (select count(*)::int from public.org_post_likes l where l.post_id = x.id),
    'liked', exists (select 1 from public.org_post_likes l where l.post_id = x.id and l.user_id = auth.uid()),
    'comments', (select count(*)::int from public.org_post_comments cm where cm.post_id = x.id),
    'can_delete', x.author_id = auth.uid() or public.org_is_admin(x.org_id))
$$;

create or replace function public.org_feed(p_org uuid, p_before timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.org_is_member(p_org) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(private.org_post_json(t.x) order by t.rn)
           from (select x, row_number() over (order by (x.is_pinned and p_before is null) desc, x.created_at desc) as rn
                   from public.org_posts x where x.org_id = p_org and (p_before is null or x.created_at < p_before)) t
          where t.rn <= 20), '[]'::jsonb);
end $$;

create or replace function public.create_org_post(p_org uuid, p_body text, p_image_url text default null, p_announce boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_new_id uuid;
  v_uid uuid := private.require_uid();
  v_manage boolean := private.org_can_manage(p_org);
  v_post public.org_posts;
begin
  if not public.org_is_member(p_org) then raise exception 'NOT_A_MEMBER'; end if;
  if not v_manage and not coalesce((select o.member_posts from public.organizations o where o.id = p_org), false) then raise exception 'POSTS_ADMIN_ONLY'; end if;
  if char_length(trim(coalesce(p_body, ''))) not between 1 and 2000 then raise exception 'EMPTY_POST'; end if;
  if p_image_url is not null and position('/storage/v1/object/public/org-media/' || p_org::text || '/' in p_image_url) = 0 then raise exception 'INVALID_IMAGE_PATH'; end if;
  if (select count(*) from public.org_posts x where x.author_id = v_uid and x.created_at > now() - interval '1 day') >= 20 then raise exception 'RATE_LIMITED'; end if;
  v_new_id := gen_random_uuid();
  insert into public.org_posts (id, org_id, author_id, kind, body, image_url, is_pinned)
  values (v_new_id, p_org, v_uid, case when p_announce and v_manage then 'ANNOUNCEMENT' else 'POST' end, trim(p_body), p_image_url, p_announce and v_manage);
  v_post := (select t from public.org_posts t where t.id = v_new_id);
  return private.org_post_json(v_post);
end $$;

create or replace function public.delete_org_post(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare x public.org_posts := (select p from public.org_posts p where p.id = p_id);
begin
  if x.id is null then raise exception 'POST_NOT_FOUND'; end if;
  if not (x.author_id = auth.uid() or public.org_is_admin(x.org_id)) then raise exception 'FORBIDDEN'; end if;
  delete from public.org_posts where id = p_id;
end $$;

create or replace function public.pin_org_post(p_id uuid, p_pin boolean) returns void
language plpgsql security definer set search_path = public as $$
declare v_org uuid := (select p.org_id from public.org_posts p where p.id = p_id);
begin
  if v_org is null or not public.org_is_admin(v_org) then raise exception 'FORBIDDEN'; end if;
  update public.org_posts set is_pinned = coalesce(p_pin, false) where id = p_id;
end $$;

create or replace function public.toggle_org_post_like(p_id uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_org uuid := (select p.org_id from public.org_posts p where p.id = p_id);
begin
  if v_org is null or not public.org_is_member(v_org) then raise exception 'NOT_A_MEMBER'; end if;
  if exists (select 1 from public.org_post_likes l where l.post_id = p_id and l.user_id = v_uid) then
    delete from public.org_post_likes where post_id = p_id and user_id = v_uid;
    return false;
  end if;
  insert into public.org_post_likes (post_id, user_id) values (p_id, v_uid);
  return true;
end $$;

create or replace function public.org_post_comments(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_org uuid := (select p.org_id from public.org_posts p where p.id = p_id);
begin
  if v_org is null or not public.org_is_member(v_org) then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', cm.id, 'body', cm.body, 'created_at', cm.created_at, 'author_id', cm.author_id,
             'author_name', private.display_name(cm.author_id), 'author_avatar', pr.avatar_url,
             'can_delete', cm.author_id = auth.uid() or public.org_is_admin(v_org)) order by cm.created_at)
           from public.org_post_comments cm left join public.profiles pr on pr.id = cm.author_id where cm.post_id = p_id), '[]'::jsonb);
end $$;

create or replace function public.add_org_post_comment(p_id uuid, p_body text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  x public.org_posts := (select p from public.org_posts p where p.id = p_id);
begin
  if x.id is null or not public.org_is_member(x.org_id) then raise exception 'NOT_A_MEMBER'; end if;
  if char_length(trim(coalesce(p_body, ''))) not between 1 and 1000 then raise exception 'EMPTY_COMMENT'; end if;
  insert into public.org_post_comments (post_id, author_id, body) values (p_id, v_uid, trim(p_body));
  if x.author_id is not null and x.author_id <> v_uid then
    perform private.notify(x.author_id, null, 'ORG_POST_COMMENT', private.display_name(v_uid) || ' bình luận bài của bạn',
      left(trim(p_body), 120), '/orgs/' || x.org_id || '?tab=feed', v_uid, false);
  end if;
end $$;

create or replace function public.delete_org_post_comment(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  cm public.org_post_comments := (select x from public.org_post_comments x where x.id = p_id);
  v_org uuid := (select p.org_id from public.org_posts p where p.id = cm.post_id);
begin
  if cm.id is null then raise exception 'NOT_FOUND'; end if;
  if not (cm.author_id = auth.uid() or public.org_is_admin(v_org)) then raise exception 'FORBIDDEN'; end if;
  delete from public.org_post_comments where id = p_id;
end $$;

-- ---------------------------------------------------------------------
-- 6. Quay thưởng dùng chung toàn app
-- ---------------------------------------------------------------------
create or replace function private.draw_can_manage(p_scope text, p_ref uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case p_scope
    when 'ORG_CAMPAIGN' then coalesce((select public.org_is_admin(c.org_id) from public.org_campaigns c where c.id = p_ref), false)
    when 'CHALLENGE' then coalesce((select private.challenge_is_manager(c) from public.challenges c where c.id = p_ref), false)
    when 'CLUB' then public.club_is_staff(p_ref)
    when 'RACE' then coalesce((select private.race_is_manager(r) from public.virtual_races r where r.id = p_ref), false)
    when 'SYSTEM' then public.is_system_admin()
    else false end
$$;

create or replace function private.draw_can_view(p_scope text, p_ref uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() is not null and (private.draw_can_manage(p_scope, p_ref) or case p_scope
    when 'ORG_CAMPAIGN' then coalesce((select public.org_is_member(c.org_id)
                                              or exists (select 1 from private.org_people(c.org_id) pp where pp.user_id = auth.uid())
                                         from public.org_campaigns c where c.id = p_ref), false)
    when 'CHALLENGE' then public.challenge_visible(p_ref)
    when 'CLUB' then public.club_is_member(p_ref)
    when 'RACE' then coalesce((select private.race_visible(r) from public.virtual_races r where r.id = p_ref), false)
    else true end)
$$;

-- Danh sách người đủ điều kiện (COMPLETED: hoàn thành · ACTIVE: có chạy · ALL: mọi người tham gia)
create or replace function private.draw_entrants(p_scope text, p_ref uuid, p_rule text)
returns table (user_id uuid)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare c public.org_campaigns;
begin
  if p_scope = 'ORG_CAMPAIGN' then
    c := (select x from public.org_campaigns x where x.id = p_ref);
    return query select r.user_id from private.org_campaign_rows(c) r
                  where p_rule = 'ALL' or (p_rule = 'ACTIVE' and r.value > 0)
                     or (p_rule = 'COMPLETED' and (case when c.goal_per_person is null then r.value > 0 else r.value >= c.goal_per_person end));
  elsif p_scope = 'CHALLENGE' then
    return query select p.profile_id from public.challenge_participants p
                  where p.challenge_id = p_ref and p.profile_id is not null and coalesce(p.status, 'JOINED') <> 'LEFT'
                    and (p_rule = 'ALL' or (p_rule = 'ACTIVE' and (coalesce(p.current_progress, 0) > 0 or p.distance_m > 0 or p.run_count > 0))
                         or (p_rule = 'COMPLETED' and (p.completed_at is not null or p.status = 'COMPLETED')));
  elsif p_scope = 'RACE' then
    return query select g.user_id from public.race_registrations g
                  where g.race_id = p_ref and g.status <> 'WITHDRAWN' and (p_rule = 'ALL' or g.status = 'FINISHED');
  elsif p_scope = 'CLUB' then
    return query select m.user_id from public.club_members m
                  where m.club_id = p_ref and m.status = 'APPROVED'
                    and (p_rule = 'ALL' or exists (select 1 from public.activities x where x.user_id = m.user_id and x.validation_status = 'APPROVED'
                                                     and public.activity_is_countable(x.status, x.validation_status) and x.started_at > now() - interval '30 days'));
  else
    return query select pr.id from public.profiles pr
                  where p_rule = 'ALL' or exists (select 1 from public.activities x where x.user_id = pr.id and x.validation_status = 'APPROVED'
                                                    and public.activity_is_countable(x.status, x.validation_status) and x.started_at > now() - interval '30 days');
  end if;
end $$;

create or replace function private.draw_json(d public.lucky_draws, p_manage boolean) returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(d) - 'created_by' - 'run_by' || jsonb_build_object('can_manage', p_manage,
    'creator_name', private.display_name(d.created_by),
    'winners', coalesce((select jsonb_agg(jsonb_build_object('user_id', w.user_id, 'name', private.display_name(w.user_id),
                  'avatar_url', pr.avatar_url, 'prize', w.prize, 'position', w.position, 'me', w.user_id = auth.uid()) order by w.position)
                from public.lucky_draw_winners w join public.profiles pr on pr.id = w.user_id where w.draw_id = d.id), '[]'::jsonb),
    'eligible_now', case when p_manage and d.status = 'READY' then
                      (select count(*)::int from private.draw_entrants(d.scope, d.ref_id, d.rule) e
                        where not (d.exclude_winners and exists (select 1 from public.lucky_draw_winners w join public.lucky_draws x on x.id = w.draw_id
                                                                  where x.scope = d.scope and x.ref_id is not distinct from d.ref_id and w.user_id = e.user_id))) end)
$$;

create or replace function public.lucky_draws_for(p_scope text, p_ref uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_manage boolean := private.draw_can_manage(p_scope, p_ref);
begin
  if not private.draw_can_view(p_scope, p_ref) then raise exception 'FORBIDDEN'; end if;
  return coalesce((select jsonb_agg(private.draw_json(d, v_manage) order by d.created_at desc)
           from public.lucky_draws d where d.scope = p_scope and d.ref_id is not distinct from p_ref
            and (d.status <> 'CANCELLED' or v_manage)), '[]'::jsonb);
end $$;

create or replace function public.create_lucky_draw(p_scope text, p_ref uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_new_id uuid;
  v_uid uuid := private.require_uid();
  v_title text := trim(coalesce(p->>'title', ''));
  v_prizes jsonb;
  d public.lucky_draws;
begin
  if p_scope not in ('ORG_CAMPAIGN', 'CHALLENGE', 'CLUB', 'RACE', 'SYSTEM') then raise exception 'INVALID_SCOPE'; end if;
  if not private.draw_can_manage(p_scope, p_ref) then raise exception 'FORBIDDEN'; end if;
  if char_length(v_title) not between 3 and 120 then raise exception 'TITLE_REQUIRED'; end if;
  v_prizes := (select coalesce(jsonb_agg(jsonb_build_object('name', left(trim(x->>'name'), 80), 'qty', least(greatest(coalesce((x->>'qty')::int, 1), 1), 100))), '[]'::jsonb)
                 from jsonb_array_elements(case when jsonb_typeof(p->'prizes') = 'array' then p->'prizes' else '[]'::jsonb end) x
                where char_length(trim(coalesce(x->>'name', ''))) > 0);
  if jsonb_array_length(v_prizes) not between 1 and 10 then raise exception 'INVALID_PRIZES'; end if;
  if (select sum((x->>'qty')::int) from jsonb_array_elements(v_prizes) x) > 200 then raise exception 'INVALID_PRIZES'; end if;
  if (select count(*) from public.lucky_draws x where x.scope = p_scope and x.ref_id is not distinct from p_ref and x.status = 'READY') >= 5 then
    raise exception 'TOO_MANY_DRAWS';
  end if;
  v_new_id := gen_random_uuid();
  insert into public.lucky_draws (id, scope, ref_id, title, rule, prizes, exclude_winners, created_by)
  values (v_new_id, p_scope, case when p_scope = 'SYSTEM' then null else p_ref end, v_title,
          case when p->>'rule' in ('COMPLETED', 'ACTIVE', 'ALL') then p->>'rule' else 'COMPLETED' end, v_prizes,
          coalesce((p->>'exclude_winners')::boolean, true), v_uid);
  d := (select t from public.lucky_draws t where t.id = v_new_id);
  return private.draw_json(d, true);
end $$;

create or replace function public.cancel_lucky_draw(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare d public.lucky_draws := (select x from public.lucky_draws x where x.id = p_id);
begin
  if d.id is null or not private.draw_can_manage(d.scope, d.ref_id) then raise exception 'FORBIDDEN'; end if;
  if d.status <> 'READY' then raise exception 'DRAW_CLOSED'; end if;
  update public.lucky_draws set status = 'CANCELLED' where id = p_id;
end $$;

-- Quay: chỉ một lần. Thứ tự = md5(seed || user_id); công bố seed + mã băm danh sách để đối chiếu
create or replace function public.run_lucky_draw(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid uuid := private.require_uid();
  d public.lucky_draws := (select x from public.lucky_draws x where x.id = p_id for update);
  v_seed text := encode(extensions.gen_random_bytes(16), 'hex');
  v_slots text[];
  v_pool uuid[];
  v_count integer;
  v_hash text;
  v_org uuid;
  v_title text;
  w record;
begin
  if d.id is null or not private.draw_can_manage(d.scope, d.ref_id) then raise exception 'FORBIDDEN'; end if;
  if d.status <> 'READY' then raise exception 'DRAW_CLOSED'; end if;
  -- mỗi suất quà thành một ô: [Giải nhất, Giải nhì, Giải nhì, …]
  v_slots := (select array_agg(x.name order by x.ord, g.n)
                from (select e->>'name' as name, (e->>'qty')::int as qty, row_number() over () as ord
                        from jsonb_array_elements(d.prizes) e) x
                cross join lateral generate_series(1, x.qty) g(n));
  v_pool := (select array_agg(distinct e.user_id) from private.draw_entrants(d.scope, d.ref_id, d.rule) e
              where e.user_id is not null
                and not (d.exclude_winners and exists (select 1 from public.lucky_draw_winners lw join public.lucky_draws x on x.id = lw.draw_id
                                                        where x.scope = d.scope and x.ref_id is not distinct from d.ref_id and lw.user_id = e.user_id)));
  v_count := coalesce(cardinality(v_pool), 0);
  if v_count = 0 then raise exception 'NO_ENTRANTS'; end if;
  v_hash := (select md5(string_agg(u::text, ',' order by u)) from unnest(v_pool) u);
  insert into public.lucky_draw_winners (draw_id, user_id, prize, position)
  select d.id, t.u, v_slots[t.rn], t.rn
    from (select u, row_number() over (order by md5(v_seed || u::text)) as rn from unnest(v_pool) u) t
   where t.rn <= cardinality(v_slots);
  update public.lucky_draws set status = 'DONE', seed = v_seed, entrant_count = v_count, entrants_hash = v_hash, run_by = v_uid, run_at = now()
   where id = d.id;
  d := (select t from public.lucky_draws t where t.id = d.id);
  for w in select lw.user_id, lw.prize from public.lucky_draw_winners lw where lw.draw_id = d.id loop
    perform private.notify(w.user_id, case when d.scope = 'CLUB' then d.ref_id end, 'LUCKY_DRAW_WIN', 'Chúc mừng! Bạn trúng ' || w.prize,
      d.title, case d.scope when 'ORG_CAMPAIGN' then '/orgs/' || (select c.org_id from public.org_campaigns c where c.id = d.ref_id) || '/campaigns/' || d.ref_id
                             when 'CHALLENGE' then '/challenges/' || d.ref_id when 'CLUB' then '/clubs/' || d.ref_id || '/hall'
                             when 'RACE' then '/races/' || d.ref_id else '/notifications' end, v_uid, true);
  end loop;
  -- Đăng kết quả lên bảng tin
  v_title := 'Kết quả ' || d.title || ': ' || (select string_agg(private.display_name(lw.user_id) || ' (' || lw.prize || ')', ', ' order by lw.position)
                                                  from public.lucky_draw_winners lw where lw.draw_id = d.id);
  if d.scope = 'ORG_CAMPAIGN' then
    v_org := (select c.org_id from public.org_campaigns c where c.id = d.ref_id);
    insert into public.org_posts (org_id, author_id, kind, body, meta) values (v_org, v_uid, 'DRAW', left(v_title, 2000), jsonb_build_object('draw_id', d.id));
  elsif d.scope = 'CLUB' then
    insert into public.club_posts (club_id, author_id, kind, title, body, is_pinned)
    values (d.ref_id, v_uid, 'ANNOUNCEMENT', left('Quay thưởng: ' || d.title, 120), left(v_title, 2000), false);
  end if;
  return private.draw_json(d, true);
end $$;

-- ---------------------------------------------------------------------
-- 7. Quyền
-- ---------------------------------------------------------------------
revoke all on function private.org_subtree(uuid), private.org_unit_depth(uuid), private.org_my_units(uuid), private.org_can_manage(uuid),
  private.user_email(uuid), private.org_unit_path(uuid, text, boolean), private.org_day_stats(uuid, timestamptz, timestamptz, numeric, numeric, jsonb),
  private.org_clean_boost(jsonb, timestamptz, timestamptz), private.org_post_json(public.org_posts), private.draw_can_manage(text, uuid),
  private.draw_can_view(text, uuid), private.draw_entrants(text, uuid, text), private.draw_json(public.lucky_draws, boolean)
  from public, anon, authenticated;

revoke all on function public.save_org_unit(uuid, uuid, text, uuid), public.org_import_members(uuid, jsonb, jsonb), public.org_pending_invites_list(uuid),
  public.delete_org_pending_invite(uuid, text), public.lock_org_campaign(uuid), public.review_campaign_result(uuid, uuid, boolean, text),
  public.set_org_campaign_cert(uuid, jsonb), public.org_campaign_certificate(uuid), public.org_feed(uuid, timestamptz),
  public.create_org_post(uuid, text, text, boolean), public.delete_org_post(uuid), public.pin_org_post(uuid, boolean),
  public.toggle_org_post_like(uuid), public.org_post_comments(uuid), public.add_org_post_comment(uuid, text), public.delete_org_post_comment(uuid),
  public.lucky_draws_for(text, uuid), public.create_lucky_draw(text, uuid, jsonb), public.cancel_lucky_draw(uuid), public.run_lucky_draw(uuid)
  from public, anon;
grant execute on function public.save_org_unit(uuid, uuid, text, uuid), public.org_import_members(uuid, jsonb, jsonb), public.org_pending_invites_list(uuid),
  public.delete_org_pending_invite(uuid, text), public.lock_org_campaign(uuid), public.review_campaign_result(uuid, uuid, boolean, text),
  public.set_org_campaign_cert(uuid, jsonb), public.org_campaign_certificate(uuid), public.org_feed(uuid, timestamptz),
  public.create_org_post(uuid, text, text, boolean), public.delete_org_post(uuid), public.pin_org_post(uuid, boolean),
  public.toggle_org_post_like(uuid), public.org_post_comments(uuid), public.add_org_post_comment(uuid, text), public.delete_org_post_comment(uuid),
  public.lucky_draws_for(text, uuid), public.create_lucky_draw(text, uuid, jsonb), public.cancel_lucky_draw(uuid), public.run_lucky_draw(uuid)
  to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001008500_competition_review_plans_menu.sql
-- ===================================================================
-- 008500: Chống gian lận chỉ trong thi đấu + CLB Free tối đa 50 thành viên + bảng so sánh gói + admin sửa mọi trang menu.
-- • Chống gian lận CHỈ áp cho người đang thi đấu: bài có dấu hiệu bất thường chỉ CHỜ DUYỆT khi lúc chạy người đó đang tham gia
--   thử thách, giải chạy ảo hoặc chiến dịch doanh nghiệp. Ngoài thi đấu, bài GPS / Strava được TỰ DUYỆT (vẫn tính Xu, XP, BXH CLB),
--   mức nghi vấn vẫn được lưu và bài đánh dấu review_skipped → KHÔNG tính vào thử thách / giải / chiến dịch nếu sau đó mới tham gia.
--   Bài nhập tay (không có thiết bị ghi) vẫn chờ duyệt như cũ.
--   Các bài đang chờ duyệt của người không thi đấu được tự duyệt ngay khi chạy file này.
-- • CLB miễn phí nhận tối đa 50 thành viên (khoá clubChallenge.freeMaxMembers, 0 = không giới hạn; admin sửa ở Quản trị → Chính sách).
--   Chỉ chặn khi NHẬN THÊM, không đuổi ai; CLB Pro (kể cả được doanh nghiệp tài trợ) không giới hạn; admin hệ thống vẫn thêm được.
-- • public.plan_compare(): bảng so sánh Miễn phí / VIP / CLB Pro cho trang /goi — xem được khi chưa đăng nhập.
-- • Điều khoản và Quyền riêng tư chuyển vào help_pages → admin sửa được như mọi trang menu. Thêm trang "RaceHub cho doanh nghiệp".
--   Nội dung mẫu chỉ thêm khi chưa có; trang admin đã sửa (updated_by khác null) không bị ghi đè.
-- Cần 002400, 002700, 002800, 006600, 007000, 007300, 007700, 008200, 008300, 008400.
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT, không RETURNING INTO. Chạy lại an toàn.

-- ---------------------------------------------------------------------
-- 1. Chống gian lận chỉ trong thi đấu
-- ---------------------------------------------------------------------
alter table public.activities add column if not exists review_skipped boolean not null default false;

-- Lúc p_at người này có đang thi đấu không: thử thách đã tham gia, giải chạy ảo đã đăng ký, chiến dịch của tổ chức mình thuộc về
create or replace function private.in_competition(p_user uuid, p_at timestamptz) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.challenge_participants p join public.challenges c on c.id = p.challenge_id
                  where p.profile_id = p_user and p.status in ('JOINED', 'COMPLETED') and c.status = 'ACTIVE'
                    and p_at >= c.start_date and p_at < c.end_date)
      or exists (select 1 from public.race_registrations x join public.virtual_races r on r.id = x.race_id
                  where x.user_id = p_user and x.status <> 'WITHDRAWN' and r.status = 'PUBLISHED'
                    and p_at >= r.start_at and p_at < r.end_at)
      or exists (select 1 from public.org_campaigns c
                  where c.status = 'ACTIVE' and p_at >= c.starts_at and p_at < c.ends_at
                    and (exists (select 1 from public.org_members m
                                  where m.org_id = c.org_id and m.user_id = p_user and m.status = 'APPROVED')
                         or exists (select 1 from public.org_clubs oc
                                      join public.club_members cm on cm.club_id = oc.club_id and cm.status = 'APPROVED'
                                     where oc.org_id = c.org_id and oc.status = 'APPROVED' and cm.user_id = p_user)))
$$;

create or replace function private.review_skipped_reason(p_reason text) returns text
language sql immutable as $$
  select left('Tự duyệt: lúc chạy bạn không tham gia thử thách, giải chạy hay chiến dịch nào. Bài vẫn tính Xu, XP và bảng xếp hạng CLB, '
              || 'nhưng không tính vào thử thách / giải / chiến dịch. Dấu hiệu hệ thống ghi nhận: '
              || coalesce(replace(p_reason, ' Bài được tính sau khi ban quản trị CLB hoặc admin xác minh.', ''), 'không rõ'), 500)
$$;

-- Chạy TRƯỚC khi chèn bài (sau trg_aa_activity_shared): bài nghi vấn của người không thi đấu → tự duyệt
create or replace function private.activity_review_scope() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.validation_status = 'PENDING' and not coalesce(new.is_manual, false) and new.user_id is not null
     and new.started_at is not null and not private.in_competition(new.user_id, new.started_at) then
    new.validation_status := 'APPROVED';
    if new.status = 'PROCESSING' then new.status := 'READY'; end if;
    new.review_skipped := true;
    new.validation_reason := private.review_skipped_reason(new.validation_reason);
  end if;
  return new;
end $$;

drop trigger if exists trg_ab_activity_review_scope on public.activities;
create trigger trg_ab_activity_review_scope before insert on public.activities
  for each row execute function private.activity_review_scope();

-- (Bản đầu có bước tự duyệt bài đang chờ của người không thi đấu. Đã bỏ ở 009800: mọi bài chạy đều qua kiểm tra chống gian lận,
--  nên chạy lại file này không duyệt bài nào.)

-- Bài GPS trong app: trả về trạng thái sau khi trigger xử lý (bản 006600 + đọc lại trạng thái)
create or replace function public.submit_and_process_activity(
  p_title text, p_source text, p_started_at timestamptz, p_ended_at timestamptz,
  p_elapsed_s integer, p_moving_s integer, p_distance_m numeric, p_avg_pace_s integer, p_track_points jsonb
) returns json
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid uuid := private.require_uid();
  cfg jsonb := private.economy_config();
  v_points jsonb := coalesce(p_track_points, '[]'::jsonb);
  v_n integer;
  v_gps_m numeric := 0;
  -- Quãng đường theo app (đã kẹp) + từng km
  v_trk_m numeric := 0;
  v_cd numeric;
  v_cd_prev numeric;
  v_step numeric;
  v_seg_t numeric;
  v_sd numeric := 0;
  v_st numeric := 0;
  v_over numeric;
  v_over_t numeric;
  v_alt0 numeric;
  v_splits jsonb := '[]'::jsonb;
  v_spikes integer := 0;
  v_prev jsonb;
  v_p jsonb;
  v_seg numeric;
  v_dt numeric;
  v_distance numeric;
  v_moving integer;
  v_pace integer;
  v_status text := 'APPROVED';
  v_reason text := 'Hoạt động hợp lệ qua kiểm tra tự động.';
  v_activity uuid;
  v_seq integer := 0;
  v_reward jsonb;
  -- Tốc độ duy trì (quãng đường trong cửa sổ 30 s) — cùng luật với features/activity/model/fraud.ts
  v_t numeric[] := '{}';
  v_c numeric[] := '{}';
  v_t0 timestamptz;
  v_i integer; v_j integer := 1; v_w numeric; v_sp numeric;
  v_run_sev numeric; v_run_nor numeric; v_run_veh numeric;
  v_sev numeric := 0; v_nor numeric := 0; v_veh numeric := 0;
  v_flags jsonb := '[]'::jsonb;
  -- Mất tín hiệu GPS: đoạn > 60 giây và > 150 m giữa hai điểm liên tiếp (tắt màn hình, hầm…) = tuyến bị nối thẳng
  v_gaps integer := 0;
  v_gap_s numeric := 0;
  v_gap_m numeric := 0;
  v_score integer := 0;
begin
  -- Kiểm tra đầu vào cơ bản
  if p_started_at is null or p_ended_at is null or p_ended_at <= p_started_at then raise exception 'INVALID_TIME_RANGE'; end if;
  if p_started_at > now() + interval '5 minutes' then raise exception 'INVALID_TIME_RANGE'; end if;
  if p_ended_at - p_started_at > interval '24 hours' then raise exception 'ACTIVITY_TOO_LONG'; end if;
  if jsonb_typeof(v_points) <> 'array' then raise exception 'INVALID_TRACK_POINTS'; end if;
  v_n := jsonb_array_length(v_points);
  if v_n > 20000 then raise exception 'TOO_MANY_TRACK_POINTS'; end if;

  -- Chống gửi trùng / chồng thời gian với bài chạy khác
  if exists (select 1 from public.activities
              where user_id = v_uid and started_at < p_ended_at and ended_at > p_started_at) then
    raise exception 'ACTIVITY_DUPLICATE';
  end if;
  if (select count(*) from public.activities where user_id = v_uid and created_at > now() - interval '1 day') >= 20 then
    raise exception 'RATE_LIMITED';
  end if;

  -- Tính lại quãng đường từ GPS (không tin số client gửi)
  for v_p in select value from jsonb_array_elements(v_points) loop
    v_cd := case when jsonb_typeof(v_p->'distance_m') = 'number' then (v_p->>'distance_m')::numeric end;
    if v_prev is null then v_alt0 := case when jsonb_typeof(v_p->'altitude') = 'number' then (v_p->>'altitude')::numeric end; end if;
    if v_prev is not null then
      v_seg := private.haversine_m((v_prev->>'latitude')::numeric, (v_prev->>'longitude')::numeric,
                                   (v_p->>'latitude')::numeric, (v_p->>'longitude')::numeric);
      v_dt := extract(epoch from ((v_p->>'recorded_at')::timestamptz - (v_prev->>'recorded_at')::timestamptz));
      if v_dt > 0 and v_seg / v_dt > 12 then v_spikes := v_spikes + 1; end if;   -- > 43 km/h
      if v_dt > 60 and v_seg > 150 then v_gaps := v_gaps + 1; v_gap_s := v_gap_s + v_dt; v_gap_m := v_gap_m + v_seg; end if;
      v_gps_m := v_gps_m + coalesce(v_seg, 0);
      -- Đoạn theo app: có distance_m ở cả hai điểm → dùng, kẹp [0, 1,1 × đoạn thẳng + 3 m]; thiếu → đoạn thẳng
      v_step := case when v_cd is not null and v_cd_prev is not null
                     then least(greatest(v_cd - v_cd_prev, 0), 1.1 * coalesce(v_seg, 0) + 3)
                     else coalesce(v_seg, 0) end;
      v_trk_m := v_trk_m + v_step;
      -- Từng km: đoạn ≤ 30 s tính đủ giờ; dài hơn (đứng chờ / mất tín hiệu) chỉ tính phần di chuyển ước lượng ≥ 1,5 m/s
      if v_dt > 0 then
        v_seg_t := case when v_dt <= 30 then v_dt else least(v_dt, v_step / 1.5) end;
        v_sd := v_sd + v_step; v_st := v_st + v_seg_t;
        while v_sd >= 1000 loop
          v_over := v_sd - 1000;
          v_over_t := case when v_step > 0 then v_seg_t * v_over / v_step else 0 end;
          v_splits := v_splits || jsonb_build_object('distance_m', 1000, 'moving_s', greatest(0, round(v_st - v_over_t)),
            'elev_m', case when v_alt0 is not null and jsonb_typeof(v_p->'altitude') = 'number' then round(((v_p->>'altitude')::numeric - v_alt0) * 10) / 10 end,
            'hr', null);
          v_sd := v_over; v_st := v_over_t;
          v_alt0 := case when jsonb_typeof(v_p->'altitude') = 'number' then (v_p->>'altitude')::numeric end;
        end loop;
      end if;
    end if;
    v_cd_prev := v_cd;
    v_t0 := coalesce(v_t0, (v_p->>'recorded_at')::timestamptz, p_started_at);
    v_t := v_t || extract(epoch from (coalesce((v_p->>'recorded_at')::timestamptz, v_t0) - v_t0));
    v_c := v_c || v_trk_m;
    v_prev := v_p;
  end loop;

  -- Đoạn liên tục dài nhất có tốc độ ≥ 20 km/h, ≥ 17 km/h, ≥ 25 km/h
  for v_i in 2 .. coalesce(array_length(v_t, 1), 0) loop
    while v_j < v_i and v_t[v_i] - v_t[v_j] > 30 loop v_j := v_j + 1; end loop;
    v_w := v_t[v_i] - v_t[v_j];
    if v_w < 15 then continue; end if;
    v_sp := (v_c[v_i] - v_c[v_j]) / v_w;
    if v_sp >= 20 / 3.6 then v_run_sev := coalesce(v_run_sev, v_t[v_j]); v_sev := greatest(v_sev, v_t[v_i] - v_run_sev); else v_run_sev := null; end if;
    if v_sp >= 17 / 3.6 then v_run_nor := coalesce(v_run_nor, v_t[v_j]); v_nor := greatest(v_nor, v_t[v_i] - v_run_nor); else v_run_nor := null; end if;
    if v_sp >= 25 / 3.6 then v_run_veh := coalesce(v_run_veh, v_t[v_j]); v_veh := greatest(v_veh, v_t[v_i] - v_run_veh); else v_run_veh := null; end if;
  end loop;
  if v_veh >= 30 then
    v_flags := v_flags || jsonb_build_object('code', 'VEHICLE_BURST', 'severity', 'SEVERE', 'durationS', round(v_veh));
    v_score := v_score + 35;
  end if;
  if v_sev >= 120 then
    v_flags := v_flags || jsonb_build_object('code', 'SUSTAINED_SPEED', 'severity', 'SEVERE', 'durationS', round(v_sev));
    v_score := v_score + 35;
  elsif v_nor >= 180 then
    v_flags := v_flags || jsonb_build_object('code', 'SUSTAINED_SPEED', 'severity', 'HIGH', 'durationS', round(v_nor));
    v_score := v_score + 28;
  end if;
  if v_spikes > 3 then
    v_flags := v_flags || jsonb_build_object('code', 'GPS_TELEPORT', 'severity', 'HIGH', 'count', v_spikes);
    v_score := v_score + 20;
  end if;

  if v_gaps > 0 then
    v_flags := v_flags || jsonb_build_object('code', 'GPS_GAP', 'severity', case when v_gap_m > greatest(500, 0.25 * v_gps_m) then 'HIGH' else 'INFO' end,
      'count', v_gaps, 'durationS', round(v_gap_s), 'meters', round(v_gap_m));
  end if;
  v_moving := least(greatest(coalesce(p_moving_s, 0), 0), extract(epoch from (p_ended_at - p_started_at))::integer);
  v_distance := case when v_n >= 2 then round(least(v_trk_m, v_gps_m)) else greatest(coalesce(p_distance_m, 0), 0) end;
  v_pace := case when v_distance > 0 then round(v_moving / (v_distance / 1000.0)) else 0 end;

  -- Luật xác thực (xem ADR-007)
  if v_distance < 200 then
    v_status := 'REJECTED'; v_reason := 'Quá ngắn (< 200 m), không đủ điều kiện ghi nhận.';
  elsif v_n < 2 then
    v_status := 'PENDING'; v_score := greatest(v_score, 40);
    v_reason := 'Bài không có dữ liệu GPS — không đối chiếu được quãng đường.';
  elsif v_pace < (cfg->>'minValidPace')::numeric * 60 then
    v_status := 'PENDING'; v_score := greatest(v_score, 75);
    v_reason := 'Pace trung bình nhanh hơn 3:00/km — vượt khả năng chạy bộ.';
  elsif v_veh >= 30 then
    v_status := 'PENDING'; v_score := greatest(v_score, 85);
    v_reason := 'Di chuyển ≥ 25 km/h liên tục ' || round(v_veh) || ' giây — giống đi xe.';
  elsif v_sev >= 120 then
    v_status := 'PENDING'; v_score := greatest(v_score, 70);
    v_reason := 'Giữ tốc độ ≥ 20 km/h (pace 3:00) liên tục ' || round(v_sev) || ' giây.';
  elsif v_nor >= 180 then
    v_status := 'PENDING'; v_score := greatest(v_score, 65);
    v_reason := 'Giữ tốc độ ≥ 17 km/h (pace 3:32) liên tục ' || round(v_nor) || ' giây.';
  elsif v_spikes > 3 then
    v_status := 'PENDING'; v_score := greatest(v_score, 50);
    v_reason := 'Vị trí GPS nhảy xa bất thường ' || v_spikes || ' lần (> 43 km/h).';
  elsif v_gap_m > greatest(500, 0.25 * v_gps_m) then
    v_status := 'PENDING'; v_score := greatest(v_score, 40);
    v_reason := 'Mất tín hiệu GPS ' || greatest(1, round(v_gap_s / 60)) || ' phút — ' || round(v_gap_m / 1000.0, 2)
                || ' km được nối thẳng, không đối chiếu được tuyến (thường do tắt màn hình khi ghi bằng trình duyệt).';
  elsif p_distance_m > 0 and abs(p_distance_m - v_distance) > greatest(0.15 * v_distance, 100) then
    v_status := 'PENDING'; v_score := greatest(v_score, 45);
    v_reason := 'Quãng đường app gửi lên lệch nhiều so với tuyến GPS.';
  end if;
  if v_status = 'PENDING' then
    v_reason := left('Mức nghi vấn: ' || private.risk_label(private.risk_level(v_score)) || '. ' || v_reason
                     || ' Bài được tính sau khi ban quản trị CLB hoặc admin xác minh.', 500);
  end if;

  v_activity := gen_random_uuid();
  insert into public.activities (
    id, user_id, title, source, started_at, ended_at, elapsed_time_s, moving_time_s,
    distance_m, moving_distance_m, avg_pace_s, status, validation_status, validation_reason,
    risk_score, risk_level, risk_flags)
  values (
    v_activity, v_uid, left(coalesce(nullif(trim(p_title), ''), 'Buổi chạy'), 120),
    case when p_source in ('DIRECT_GPS', 'STRAVA', 'GARMIN') then p_source else 'DIRECT_GPS' end,
    p_started_at, p_ended_at, greatest(coalesce(p_elapsed_s, 0), v_moving), v_moving,
    v_distance, v_distance, v_pace,
    case v_status when 'APPROVED' then 'READY' when 'PENDING' then 'PROCESSING' else 'REJECTED' end,
    v_status, v_reason,
    least(v_score, 100), private.risk_level(v_score),
    case when jsonb_array_length(v_flags) > 0 then v_flags end);

  -- 008500: ngoài thử thách / giải / chiến dịch, trigger tự duyệt bài nghi vấn → trả về trạng thái thật
  v_status := (select x.validation_status from public.activities x where x.id = v_activity);
  v_reason := (select x.validation_reason from public.activities x where x.id = v_activity);

  for v_p in select value from jsonb_array_elements(v_points) loop
    v_seq := v_seq + 1;
    insert into public.activity_track_points (activity_id, sequence, latitude, longitude, accuracy, altitude, speed, recorded_at, distance_m)
    values (v_activity, v_seq, (v_p->>'latitude')::numeric, (v_p->>'longitude')::numeric,
            (v_p->>'accuracy')::numeric, (v_p->>'altitude')::numeric, (v_p->>'speed')::numeric,
            coalesce((v_p->>'recorded_at')::timestamptz, p_started_at), round(v_c[v_seq], 1));
  end loop;

  -- Từng km (km lẻ cuối ≥ 100 m) — màn chi tiết bài chạy đọc thẳng, khớp quãng đường đã lưu
  if v_n >= 2 then
    if v_sd >= 100 and v_st > 0 then
      v_splits := v_splits || jsonb_build_object('distance_m', round(v_sd), 'moving_s', round(v_st), 'elev_m', null, 'hr', null);
    end if;
    insert into public.activity_details (activity_id, splits, start_lat, start_lng, detailed)
    values (v_activity, v_splits, (v_points->0->>'latitude')::numeric, (v_points->0->>'longitude')::numeric, true)
    on conflict (activity_id) do update set splits = excluded.splits;
  end if;

  if v_status = 'APPROVED' then
    v_reward := (select jsonb_build_object('earned_xu', x.earned_xu, 'earned_xp', x.earned_xp)
                   from public.activities x where x.id = v_activity);         -- trigger trg_auto_reward đã thưởng
  end if;

  return json_build_object(
    'success', true, 'activity_id', v_activity,
    'validation_status', v_status, 'validation_reason', v_reason,
    'distance_m', v_distance,
    'earned_xp', coalesce((v_reward->>'earned_xp')::integer, 0),
    'earned_xu', coalesce((v_reward->>'earned_xu')::numeric, 0));
end $$;

-- Thử thách / giải chạy ảo / chiến dịch: không tính bài tự duyệt có dấu hiệu bất thường (bản cũ + điều kiện review_skipped)
create or replace function private.challenge_apply_activity(p_activity_id uuid, p_only_participant uuid default null) returns integer
language plpgsql security definer set search_path = public as $$
declare
  a public.activities := (select x from public.activities x where x.id = p_activity_id);
  r record;
  v_day date;
  v_km numeric;
  v_already numeric;
  v_counted numeric;
  v_boost numeric;
  n integer := 0;
begin
  if a.id is null or a.user_id is null or a.validation_status is distinct from 'APPROVED'
     or not public.activity_is_countable(a.status, a.validation_status) or not a.shared or a.review_skipped then
    return 0;
  end if;
  v_km := greatest(coalesce(nullif(a.moving_distance_m, 0), a.distance_m, 0), 0) / 1000.0;
  v_day := (a.started_at at time zone 'Asia/Ho_Chi_Minh')::date;

  for r in
    select p.id as pid, c.*
      from public.challenge_participants p join public.challenges c on c.id = p.challenge_id
     where p.profile_id = a.user_id and p.status in ('JOINED', 'COMPLETED')
       and (p_only_participant is null or p.id = p_only_participant)
       and c.status = 'ACTIVE'
       and a.started_at >= c.start_date and a.started_at < c.end_date
  loop
    -- Luật: cự ly tối thiểu mỗi bài (trừ chuỗi ngày — cộng dồn trong ngày), khoảng pace, bắt buộc nhịp tim
    if r.objective <> 'STREAK_DAYS' and v_km < coalesce(r.min_km, 0) then continue; end if;
    if coalesce(a.avg_pace_s, 0) > 0 and (a.avg_pace_s < coalesce(r.min_pace, 0) * 60
                                          or a.avg_pace_s > coalesce(r.max_pace, 99) * 60) then continue; end if;
    if r.require_hr and coalesce(a.avg_heartrate, 0) <= 0 then continue; end if;

    v_counted := v_km * 1000;
    if coalesce(r.daily_cap_km, 0) > 0 then
      -- trần mỗi ngày tính trên km thật (chia lại hệ số đã nhân)
      v_already := (select coalesce(sum(e.counted_m / e.boost), 0) from public.challenge_progress_events e
                     where e.participant_id = r.pid and e.day = v_day and e.activity_id <> a.id);
      v_counted := least(v_counted, greatest(r.daily_cap_km * 1000 - v_already, 0));
    end if;
    v_boost := case when r.target_club_id is not null and r.objective = 'DISTANCE' then private.club_boost(r.target_club_id, v_day) else 1 end;

    insert into public.challenge_progress_events (challenge_id, participant_id, activity_id, day, distance_m, counted_m, moving_s, boost)
    values (r.id, r.pid, a.id, v_day, v_km * 1000, v_counted * v_boost, coalesce(a.moving_time_s, 0), v_boost)
    on conflict (participant_id, activity_id) do nothing;
    if found then
      perform private.challenge_recompute_participant(r.pid);
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;

create or replace function private.race_evaluate(p_reg_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  g public.race_registrations := (select x from public.race_registrations x where x.id = p_reg_id);
  r public.virtual_races;
  best record;
  v_target numeric;
  v_was text;
begin
  if g.id is null or g.status = 'WITHDRAWN' then return; end if;
  r := (select x from public.virtual_races x where x.id = g.race_id);
  if r.status = 'CANCELLED' then return; end if;
  v_target := g.distance_km * 1000;
  v_was := g.status;
  for best in
    select a.id, a.distance_m, a.moving_time_s, a.started_at
      from public.activities a
     where a.user_id = g.user_id and a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED' and a.shared and not a.review_skipped
       and a.started_at >= r.start_at and a.started_at < r.end_at
       and a.distance_m >= v_target * 0.99 and coalesce(a.moving_time_s, 0) > 0
     order by a.moving_time_s / a.distance_m, a.started_at
  loop
    update public.race_registrations
       set status = 'FINISHED', finish_activity_id = best.id, finish_distance_m = best.distance_m,
           finish_moving_s = best.moving_time_s,
           finish_time_s = round(best.moving_time_s * v_target / best.distance_m),
           finished_at = best.started_at
     where id = g.id;
    if v_was <> 'FINISHED' then
      perform private.notify(g.user_id, r.club_id, 'RACE_FINISHED', 'Hoàn thành ' || r.title,
        'Cự ly ' || g.distance_km || ' km · BIB ' || g.bib || '. Xem thứ hạng và nhận giấy chứng nhận.', '/races/' || r.id, null, true);
    end if;
    return;                                  -- chỉ lấy bài tốt nhất
  end loop;
  update public.race_registrations
     set status = 'REGISTERED', finish_activity_id = null, finish_distance_m = null, finish_moving_s = null,
         finish_time_s = null, finished_at = null
   where id = g.id and status = 'FINISHED';
end $$;

create or replace function private.org_person_stats(p_user uuid, p_from timestamptz, p_to timestamptz, p_min_km numeric)
returns table (km numeric, runs integer, active_days integer)
language sql stable security definer set search_path = public as $$
  select coalesce(round(sum(x.distance_m) / 1000.0, 2), 0), count(*)::int,
         count(distinct (x.started_at at time zone 'Asia/Ho_Chi_Minh')::date)::int
    from public.activities x
   where x.user_id = p_user and x.validation_status = 'APPROVED' and x.shared and not x.review_skipped
     and public.activity_is_countable(x.status, x.validation_status)
     and x.started_at >= p_from and x.started_at < p_to and coalesce(x.distance_m, 0) >= coalesce(p_min_km, 0) * 1000
$$;

create or replace function private.org_day_stats(p_user uuid, p_from timestamptz, p_to timestamptz, p_min_km numeric, p_cap numeric, p_boost jsonb)
returns table (dist_value numeric, runs_value numeric, km numeric, runs integer, active_days integer)
language sql stable security definer set search_path = public as $$
  with d as (
    select (x.started_at at time zone 'Asia/Ho_Chi_Minh')::date as day, sum(x.distance_m) / 1000.0 as km, count(*)::int as runs
      from public.activities x
     where x.user_id = p_user and x.validation_status = 'APPROVED' and x.shared and not x.review_skipped
       and public.activity_is_countable(x.status, x.validation_status)
       and x.started_at >= p_from and x.started_at < p_to and coalesce(x.distance_m, 0) >= coalesce(p_min_km, 0) * 1000
     group by 1
  ), e as (
    select d.day, d.runs, least(d.km, coalesce(p_cap, d.km)) as ckm,
           coalesce((select max(least(greatest((b->>'mult')::numeric, 1), 3)) from jsonb_array_elements(coalesce(p_boost, '[]'::jsonb)) b
                      where (b->>'date') = to_char(d.day, 'YYYY-MM-DD')), 1) as mult
      from d
  )
  select coalesce(round(sum(e.ckm * e.mult), 2), 0), coalesce(sum(e.runs * e.mult), 0), coalesce(round(sum(e.ckm), 2), 0),
         coalesce(sum(e.runs), 0)::int, count(*)::int
    from e
$$;

-- ---------------------------------------------------------------------
-- 2. CLB miễn phí tối đa 50 thành viên (cấu hình được)
-- ---------------------------------------------------------------------
create or replace function private.club_challenge_policy() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('freeMinActiveMembers', 5, 'activeWindowDays', 30, 'freeMaxSlots', 50, 'freeMaxOpen', 2,
                            'proMaxSlots', 1000, 'proMaxOpen', 20, 'freeMaxMembers', 50)
         || coalesce(case when jsonb_typeof(private.economy_config()->'clubChallenge') = 'object'
                          then private.economy_config()->'clubChallenge' end, '{}'::jsonb)
$$;

create or replace function private.valid_economy_v2(c jsonb) returns boolean
language sql immutable as $$
  select jsonb_typeof(c) = 'object'
     and coalesce((c->>'xuVnd')::numeric, 100) between 1 and 1000000
     and coalesce((c->>'xpPerKm')::numeric, 10) between 0 and 1000
     and coalesce((c->'run'->>'freeKm')::numeric, 2) between 0 and 100
     and coalesce((c->'run'->>'dailyCap')::numeric, 20) between 0 and 100000
     and not exists (select 1 from jsonb_array_elements(coalesce(c->'run'->'tiers', '[]'::jsonb)) e
                      where (e->>'upToKm')::numeric not between 0 and 1000 or (e->>'rate')::numeric not between 0 and 1000)
     and coalesce((c->>'checkinXu')::numeric, 1) between 0 and 10000
     and coalesce((c->>'giftDailyCapXu')::numeric, 20000) between 0 and 100000000
     and not exists (select 1 from jsonb_array_elements(coalesce(c->'capacityTiers', '[]'::jsonb)) e
                      where (e->>'max')::int not between 1 and 1000000 or (e->>'xu')::numeric not between 0 and 10000000)
     and not exists (select 1 from jsonb_array_elements(coalesce(c->'streakRewards', '[]'::jsonb)) e
                      where (e->>'weeks')::int not between 1 and 520 or (e->>'xu')::numeric not between 0 and 100000)
     and coalesce((c->'referral'->>'inviterXu')::numeric, 0) between 0 and 100000
     and coalesce((c->'referral'->>'refereeXu')::numeric, 0) between 0 and 100000
     and coalesce((c->'referral'->>'monthlyCap')::numeric, 10) between 0 and 1000
     and coalesce((c->'comeback'->>'xu')::numeric, 10) between 0 and 10000
     and coalesce((c->'comeback'->>'minRestDays')::numeric, 28) between 7 and 365
     and coalesce((c->'comeback'->>'cooldownDays')::numeric, 90) between 0 and 3650
     and coalesce((c->'game'->>'shieldPrice')::numeric, 200) between 0 and 100000
     and coalesce((c->'clubChallenge'->>'freeMinActiveMembers')::numeric, 5) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'activeWindowDays')::numeric, 30) between 1 and 365
     and coalesce((c->'clubChallenge'->>'freeMaxSlots')::numeric, 50) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'freeMaxOpen')::numeric, 2) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'proMaxSlots')::numeric, 1000) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'proMaxOpen')::numeric, 20) between 0 and 10000
     and coalesce((c->'clubChallenge'->>'freeMaxMembers')::numeric, 50) between 0 and 1000000
$$;

create or replace function private.club_free_member_limit() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_max integer;
begin
  if new.status = 'APPROVED' and (tg_op = 'INSERT' or old.status is distinct from 'APPROVED')
     and not public.is_system_admin() and not private.club_is_pro(new.club_id) then
    v_max := coalesce((private.club_challenge_policy()->>'freeMaxMembers')::int, 50);
    if v_max > 0 and (select count(*) from public.club_members m
                       where m.club_id = new.club_id and m.status = 'APPROVED' and m.user_id <> new.user_id) >= v_max then
      raise exception 'CLUB_FREE_FULL';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_club_free_member_limit on public.club_members;
create trigger trg_club_free_member_limit before insert or update of status on public.club_members
  for each row execute function private.club_free_member_limit();

