-- 20261001011700_feedback_round3.sql
-- ===================================================================
-- 011700: GÓP Ý VÒNG 3
--   1. Thách đấu CLB: sau khi ban quản trị đăng ký CLB, THÀNH VIÊN tự đăng ký tham gia; chỉ người đã đăng ký mới được tính
--      (thách đấu tạo trước file này giữ cách tính cũ — mọi thành viên). BXH chi tiết từng CLB trong giải (ngày chạy, pace, km).
--   2. Tin nhắn 1-1: thả cảm xúc (emoji) cho từng tin.
--   3. Kiến thức: runner soạn bài / ebook chạy bộ → admin duyệt → đăng; bài được đăng tự cộng Xu (mặc định 30 Xu, admin đổi ở
--      Chính sách kinh tế, khóa contentRewardXu). Tác giả xem trước bài của mình khi chưa đăng.
--   4. Quản trị: tìm tài khoản theo email để cấp quyền admin.
-- Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT, không RETURNING INTO. Chạy lại an toàn.

-- ---------------------------------------------------------------------
-- 1. Thách đấu CLB — thành viên đăng ký
-- ---------------------------------------------------------------------
-- Cột mới để trống cho thách đấu cũ (= không cần đăng ký), mặc định bật cho thách đấu tạo từ nay
alter table public.club_cups add column if not exists require_signup boolean;
alter table public.club_cups alter column require_signup set default true;

create table if not exists public.club_cup_members (
  cup_id uuid not null references public.club_cups(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  club_id uuid not null references public.clubs(id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (cup_id, user_id)
);
create index if not exists club_cup_members_club_idx on public.club_cup_members (cup_id, club_id);
alter table public.club_cup_members enable row level security;
revoke all on public.club_cup_members from anon, authenticated;

-- Ai đăng ký CLB vào giải (kể cả người tạo giải cho CLB chủ nhà) tự có tên thi đấu cho CLB đó
create or replace function private.cup_entry_autosignup() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.registered_by is not null
     and coalesce((select u.require_signup from public.club_cups u where u.id = new.cup_id), false)
     and exists (select 1 from public.club_members m where m.club_id = new.club_id and m.user_id = new.registered_by and m.status = 'APPROVED') then
    insert into public.club_cup_members (cup_id, user_id, club_id) values (new.cup_id, new.registered_by, new.club_id)
    on conflict (cup_id, user_id) do nothing;
  end if;
  return new;
end $$;
drop trigger if exists trg_cup_entry_autosignup on public.club_cup_entries;
create trigger trg_cup_entry_autosignup after insert on public.club_cup_entries
  for each row execute function private.cup_entry_autosignup();

-- Người được tính cho từng CLB: thành viên đã duyệt (+ đã đăng ký nếu giải yêu cầu); người ở nhiều CLB chỉ tính cho CLB vào sớm nhất
create or replace function private.cup_counted(p_cup uuid)
returns table (club_id uuid, user_id uuid, joined_at timestamptz)
language sql stable security definer set search_path = public as $$
  select x.club_id, x.user_id, x.joined_at from (
    select m.club_id, m.user_id, m.joined_at,
           row_number() over (partition by m.user_id order by m.joined_at nulls first, m.club_id) as k
      from public.club_members m
      join public.club_cup_entries ce on ce.club_id = m.club_id and ce.cup_id = p_cup
     where m.status = 'APPROVED'
       and (not coalesce((select u.require_signup from public.club_cups u where u.id = p_cup), false)
            or exists (select 1 from public.club_cup_members cm where cm.cup_id = p_cup and cm.user_id = m.user_id and cm.club_id = m.club_id))) x
   where x.k = 1
$$;

create or replace function private.cup_standings(p_cup uuid, p_start timestamptz, p_end timestamptz, p_metric text) returns jsonb
language sql stable security definer set search_path = public as $$
  with e as (
    select ce.club_id from public.club_cup_entries ce where ce.cup_id = p_cup
  ), m1 as (
    select * from private.cup_counted(p_cup)
  ), runs as (
    select m1.club_id, a.user_id, sum(a.distance_m) as meters
      from public.activities a join m1 on m1.user_id = a.user_id
     where p_end > p_start
       and a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED'
       and a.started_at >= p_start and a.started_at < p_end
       and a.started_at >= coalesce(m1.joined_at, '-infinity'::timestamptz)
     group by m1.club_id, a.user_id
  ), agg as (
    select e.club_id,
           (select count(*) from m1 where m1.club_id = e.club_id) as members,
           (select count(*) from runs r where r.club_id = e.club_id) as runners,
           coalesce((select sum(r.meters) from runs r where r.club_id = e.club_id), 0) as meters
      from e
  ), scored as (
    select agg.*, round(agg.meters / 1000.0, 2) as km,
           round(agg.meters / 1000.0 / greatest(agg.members, 1), 2) as avg_km
      from agg
  ), ranked as (
    select s.*, rank() over (order by case when p_metric = 'TOTAL_KM' then s.km else s.avg_km end desc) as rnk from scored s
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'rank', r.rnk, 'club_id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
           'members', r.members, 'runners', r.runners, 'km', r.km, 'avg_km', r.avg_km,
           'score', case when p_metric = 'TOTAL_KM' then r.km else r.avg_km end)
         order by r.rnk, c.name), '[]'::jsonb)
    from ranked r join public.clubs c on c.id = r.club_id
$$;

create or replace function private.cup_json(u public.club_cups, p_full boolean) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', u.id, 'title', u.title, 'description', u.description, 'prize', u.prize, 'metric', u.metric,
    'start_at', u.start_at, 'end_at', u.end_at, 'reg_close_at', u.reg_close_at, 'max_clubs', u.max_clubs,
    'status', u.status, 'review_note', u.review_note, 'created_at', u.created_at, 'settled_at', u.settled_at,
    'require_signup', coalesce(u.require_signup, false),
    'host', (select jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color)
               from public.clubs c where c.id = u.host_club_id),
    'creator', (select jsonb_build_object('id', p.id, 'display_name', p.display_name, 'avatar_url', p.avatar_url)
                  from public.profiles p where p.id = u.created_by),
    'clubs', (select count(*) from public.club_cup_entries ce where ce.cup_id = u.id),
    'my_clubs', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
                         'staff', m.role in ('OWNER', 'CAPTAIN'),
                         'joined', exists (select 1 from public.club_cup_entries ce where ce.cup_id = u.id and ce.club_id = c.id),
                         'signed_up', exists (select 1 from public.club_cup_members cm where cm.cup_id = u.id and cm.club_id = c.id and cm.user_id = auth.uid()))
                       order by c.name), '[]'::jsonb)
                   from public.club_members m join public.clubs c on c.id = m.club_id
                  where m.user_id = auth.uid() and m.status = 'APPROVED'),
    'my_signup', (select cm.club_id from public.club_cup_members cm where cm.cup_id = u.id and cm.user_id = auth.uid()),
    'can_manage', u.created_by = auth.uid() or public.is_system_admin()
                  or (u.host_club_id is not null and public.club_is_staff(u.host_club_id)),
    'can_review', public.is_system_admin(),
    'standings', case when p_full then coalesce(u.result->'standings',
                   private.cup_standings(u.id, u.start_at, least(u.end_at, greatest(now(), u.start_at)), u.metric)) end)
$$;

-- Ban quản trị đăng ký CLB (như cũ) — thông báo nhắc thành viên tự đăng ký
create or replace function public.join_club_cup(p_cup_id uuid, p_club_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id for update);
  v_club text := (select c.name from public.clubs c where c.id = p_club_id);
begin
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  if v_club is null then raise exception 'CLUB_NOT_FOUND'; end if;
  if not public.club_is_staff(p_club_id) then raise exception 'CLUB_STAFF_REQUIRED'; end if;
  if u.status <> 'OPEN' then raise exception 'CUP_NOT_OPEN'; end if;
  if now() > u.reg_close_at then raise exception 'REGISTRATION_CLOSED'; end if;
  if exists (select 1 from public.club_cup_entries ce where ce.cup_id = u.id and ce.club_id = p_club_id) then raise exception 'ALREADY_JOINED'; end if;
  if (select count(*) from public.club_cup_entries ce where ce.cup_id = u.id) >= u.max_clubs then raise exception 'CUP_FULL'; end if;
  insert into public.club_cup_entries (cup_id, club_id, registered_by) values (u.id, p_club_id, v_uid);
  perform private.notify_club(p_club_id, false, 'CLUB_CUP', v_club || ' tham gia thách đấu "' || u.title || '"',
    case when coalesce(u.require_signup, false)
         then 'Bấm "Đăng ký thi đấu" trong trang thách đấu để km của bạn được tính cho CLB (từ ' || to_char(u.start_at at time zone 'Asia/Ho_Chi_Minh', 'DD/MM HH24:MI') || ').'
         else 'Mọi km hợp lệ từ ' || to_char(u.start_at at time zone 'Asia/Ho_Chi_Minh', 'DD/MM HH24:MI') || ' đều tính cho CLB. Chạy thôi!' end,
    '/cups/' || u.id, v_uid);
  if u.created_by is not null and u.created_by <> v_uid then
    perform private.notify(u.created_by, null, 'CLUB_CUP', v_club || ' đã đăng ký "' || u.title || '"', null, '/cups/' || u.id, v_uid, false);
  end if;
  return private.cup_json((select x from public.club_cups x where x.id = u.id), true);
end $$;

-- Thành viên đăng ký thi đấu cho CLB của mình (CLB đã vào giải); mỗi người một CLB trong một giải
create or replace function public.join_cup_as_member(p_cup_id uuid, p_club_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id);
  v_mine uuid;
begin
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  if u.status <> 'OPEN' or now() >= u.end_at then raise exception 'CUP_NOT_OPEN'; end if;
  if not exists (select 1 from public.club_cup_entries ce where ce.cup_id = u.id and ce.club_id = p_club_id) then raise exception 'CLUB_NOT_IN_CUP'; end if;
  if not exists (select 1 from public.club_members m where m.club_id = p_club_id and m.user_id = v_uid and m.status = 'APPROVED') then
    raise exception 'NOT_A_MEMBER';
  end if;
  v_mine := (select cm.club_id from public.club_cup_members cm where cm.cup_id = u.id and cm.user_id = v_uid);
  if v_mine = p_club_id then return private.cup_json(u, true); end if;
  if v_mine is not null then raise exception 'ALREADY_SIGNED_UP'; end if;
  insert into public.club_cup_members (cup_id, user_id, club_id) values (u.id, v_uid, p_club_id);
  return private.cup_json(u, true);
end $$;

-- Rút đăng ký (chỉ trước giờ bắt đầu)
create or replace function public.leave_cup_as_member(p_cup_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid(); u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id);
begin
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  if now() >= u.start_at then raise exception 'CUP_STARTED'; end if;
  delete from public.club_cup_members where cup_id = u.id and user_id = v_uid;
  return private.cup_json(u, true);
end $$;

-- BXH chi tiết một CLB trong giải: từng người được tính — km, số ngày chạy, số buổi, pace TB
create or replace function public.club_cup_club_board(p_cup_id uuid, p_club_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id);
  v_end timestamptz;
begin
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  if not exists (select 1 from public.club_cup_entries ce where ce.cup_id = u.id and ce.club_id = p_club_id) then raise exception 'CLUB_NOT_IN_CUP'; end if;
  v_end := least(u.end_at, greatest(now(), u.start_at));
  return (select jsonb_build_object(
    'club', (select jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color)
               from public.clubs c where c.id = p_club_id),
    'rows', coalesce(jsonb_agg(jsonb_build_object('rank', t.rnk, 'user_id', t.user_id, 'display_name', pr.display_name, 'avatar_url', pr.avatar_url,
              'km', round(t.meters / 1000.0, 2), 'runs', t.runs, 'days', t.days, 'moving_s', t.moving_s,
              'pace_s', case when t.meters > 0 then round(t.moving_s / (t.meters / 1000.0)) end)
            order by t.rnk, pr.display_name), '[]'::jsonb))
    from (select m.user_id,
                 coalesce(sum(a.distance_m), 0) as meters, count(a.id) as runs,
                 count(distinct (a.started_at at time zone 'Asia/Ho_Chi_Minh')::date) as days,
                 coalesce(sum(coalesce(nullif(a.moving_time_s, 0), a.elapsed_time_s)), 0) as moving_s,
                 rank() over (order by coalesce(sum(a.distance_m), 0) desc) as rnk
            from private.cup_counted(u.id) m
            left join public.activities a on a.user_id = m.user_id and a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED'
                  and a.started_at >= u.start_at and a.started_at < v_end and a.started_at >= coalesce(m.joined_at, '-infinity'::timestamptz)
           where m.club_id = p_club_id
           group by m.user_id) t
    join public.profiles pr on pr.id = t.user_id);
end $$;

-- ---------------------------------------------------------------------
-- 2. Tin nhắn 1-1: cảm xúc
-- ---------------------------------------------------------------------
create table if not exists public.direct_message_reactions (
  message_id uuid not null references public.direct_messages(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  emoji text not null check (char_length(emoji) between 1 and 16),
  created_at timestamptz not null default now(),
  primary key (message_id, user_id)
);
alter table public.direct_message_reactions enable row level security;
revoke all on public.direct_message_reactions from anon, authenticated;

create or replace function private.dm_json(m public.direct_messages, p_uid uuid) returns jsonb
language sql stable as $$
  select jsonb_build_object('id', m.id, 'sender_id', m.sender_id, 'mine', m.sender_id = p_uid, 'created_at', m.created_at,
    'deleted', m.deleted_at is not null, 'body', case when m.deleted_at is null then m.body else null end,
    'reactions', coalesce((select jsonb_agg(jsonb_build_object('emoji', r.emoji, 'count', r.n, 'mine', r.mine) order by r.first_at)
                             from (select x.emoji, count(*) as n, bool_or(x.user_id = p_uid) as mine, min(x.created_at) as first_at
                                     from public.direct_message_reactions x where x.message_id = m.id group by x.emoji) r), '[]'::jsonb))
$$;

-- Thả / đổi / bỏ cảm xúc (bấm lại đúng emoji đang chọn = bỏ)
create or replace function public.react_direct_message(p_id uuid, p_emoji text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  m public.direct_messages := (select x from public.direct_messages x where x.id = p_id);
  v_emoji text := nullif(trim(coalesce(p_emoji, '')), '');
begin
  if m.id is null or m.deleted_at is not null
     or not exists (select 1 from public.direct_threads t where t.id = m.thread_id and v_uid in (t.user_a, t.user_b)) then
    raise exception 'NOT_FOUND';
  end if;
  if v_emoji is null or char_length(v_emoji) > 16 then raise exception 'INVALID_EMOJI'; end if;
  if exists (select 1 from public.direct_message_reactions r where r.message_id = m.id and r.user_id = v_uid and r.emoji = v_emoji) then
    delete from public.direct_message_reactions where message_id = m.id and user_id = v_uid;
  else
    insert into public.direct_message_reactions (message_id, user_id, emoji) values (m.id, v_uid, v_emoji)
    on conflict (message_id, user_id) do update set emoji = excluded.emoji, created_at = now();
  end if;
  return private.dm_json(m, v_uid);
end $$;

-- ---------------------------------------------------------------------
-- 3. Kiến thức: runner soạn bài / ebook, admin duyệt, thưởng Xu khi đăng
-- ---------------------------------------------------------------------
alter table public.content_articles add column if not exists attachment_url text;
alter table public.content_articles drop constraint if exists content_articles_attachment_chk;
alter table public.content_articles add constraint content_articles_attachment_chk
  check (attachment_url is null or (attachment_url ~ '^https://' and char_length(attachment_url) <= 500));
alter table public.content_articles drop constraint if exists content_articles_content_type_check;
alter table public.content_articles add constraint content_articles_content_type_check check (content_type in ('ARTICLE', 'NEWS', 'EBOOK'));
alter table public.content_articles add column if not exists reward_xu numeric not null default 0;

-- Ảnh bìa + ebook PDF: mọi runner tải được vào thư mục của mình (≤ 10 MB)
update storage.buckets set file_size_limit = 10485760,
       allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'application/pdf']
 where id = 'content-media';
create or replace function public.can_upload_content_media(p_name text) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() is not null and (storage.foldername(p_name))[1] = auth.uid()::text
$$;

alter table public.game_events drop constraint if exists game_events_kind_check;
alter table public.game_events add constraint game_events_kind_check
  check (kind in ('RUN', 'QUEST', 'BADGE', 'STREAK', 'LEVEL_UP', 'LEAGUE', 'CHEER_IN', 'CHECKIN', 'REFERRAL', 'GIFT_IN', 'COMEBACK', 'CONTENT'));

-- Hồ sơ tác giả cộng đồng của runner (tạo khi soạn bài đầu tiên)
create or replace function private.community_author(p_uid uuid) returns uuid
language plpgsql security definer set search_path = public as $$
begin
  insert into public.content_authors (user_id, name, kind, avatar_url)
  select p.id, case when char_length(trim(coalesce(p.display_name, ''))) >= 2 then left(trim(p.display_name), 80) else 'Runner RaceHub' end, 'COMMUNITY', p.avatar_url
    from public.profiles p where p.id = p_uid
  on conflict (user_id) do nothing;
  return (select au.id from public.content_authors au where au.user_id = p_uid);
end $$;

-- Soạn / sửa bài của mình (nháp hoặc gửi duyệt). p: {id?, title, summary, body, cover_image_url, category_id,
-- content_type: ARTICLE | EBOOK, attachment_url, submit: boolean}. Bài đã đăng không sửa được (liên hệ ban biên tập).
create or replace function public.knowledge_submit(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  a public.content_articles := (select x from public.content_articles x where x.id::text = nullif(p->>'id', ''));
  v_title text := trim(coalesce(p->>'title', ''));
  v_body text := coalesce(p->>'body', '');
  v_cat text := coalesce(nullif(p->>'category_id', ''), 'BEGINNER');
  v_type text := case when upper(coalesce(p->>'content_type', '')) = 'EBOOK' then 'EBOOK' else 'ARTICLE' end;
  v_att text := nullif(trim(coalesce(p->>'attachment_url', '')), '');
  v_cover text := nullif(trim(coalesce(p->>'cover_image_url', '')), '');
  v_submit boolean := coalesce((p->>'submit')::boolean, false);
  v_status text;
  v_id uuid;
  v_slug text;
begin
  if nullif(p->>'id', '') is not null and (a.id is null or a.created_by is distinct from v_uid) then raise exception 'ARTICLE_NOT_FOUND'; end if;
  if a.id is not null and a.status not in ('DRAFT', 'REVIEW') then raise exception 'ALREADY_PUBLISHED'; end if;
  if char_length(v_title) not between 5 and 140 then raise exception 'TITLE_TOO_SHORT'; end if;
  if not exists (select 1 from public.content_categories c where c.id = v_cat) then raise exception 'INVALID_CATEGORY'; end if;
  if v_att is not null and v_att !~ '^https://' then raise exception 'INVALID_URL'; end if;
  if v_cover is not null and v_cover !~ '^https://' then raise exception 'INVALID_URL'; end if;
  if char_length(v_body) > 60000 then raise exception 'BODY_TOO_LONG'; end if;
  if v_submit and ((v_type = 'ARTICLE' and char_length(trim(v_body)) < 300) or (v_type = 'EBOOK' and (v_att is null or char_length(trim(v_body)) < 50))) then
    raise exception 'BODY_TOO_SHORT';
  end if;
  if a.id is null then
    if (select count(*) from public.content_articles x where x.created_by = v_uid and x.created_at > now() - interval '1 day') >= 10 then
      raise exception 'RATE_LIMITED';
    end if;
    v_id := gen_random_uuid();
    v_slug := trim(both '-' from left(trim(both '-' from regexp_replace(regexp_replace(coalesce(private.slugify(v_title), ''), '[^a-z0-9-]+', '', 'g'), '-{2,}', '-', 'g')), 80));
    insert into public.content_articles (id, slug, title, summary, body, cover_image_url, category_id, author_id, content_type,
      reading_time_minutes, needs_expert_review, attachment_url, created_by, status)
    values (v_id, coalesce(nullif(v_slug, ''), 'bai-viet') || '-' || substr(md5(v_id::text), 1, 5),
      v_title, nullif(left(trim(coalesce(p->>'summary', '')), 300), ''), v_body, v_cover, v_cat, private.community_author(v_uid), v_type,
      private.reading_minutes(v_body), (select c.needs_expert from public.content_categories c where c.id = v_cat), v_att, v_uid,
      case when v_submit then 'REVIEW' else 'DRAFT' end);
  else
    v_id := a.id;
    update public.content_articles set title = v_title, summary = nullif(left(trim(coalesce(p->>'summary', '')), 300), ''), body = v_body,
      cover_image_url = v_cover, category_id = v_cat, content_type = v_type, attachment_url = v_att,
      reading_time_minutes = private.reading_minutes(v_body),
      needs_expert_review = (select c.needs_expert from public.content_categories c where c.id = v_cat),
      status = case when v_submit then 'REVIEW' else 'DRAFT' end, updated_at = now()
     where id = v_id;
  end if;
  v_status := (select x.status from public.content_articles x where x.id = v_id);
  -- Báo admin khi có bài chờ duyệt (lần gửi đầu)
  if v_submit and (a.id is null or a.status <> 'REVIEW') then
    perform private.notify(pr.id, null, 'CONTENT', 'Bài viết cộng đồng chờ duyệt', '"' || v_title || '" — ' || private.display_name(v_uid), '/learn/studio', v_uid, false)
       from public.profiles pr where pr.role = 'SYSTEM_ADMIN' or pr.is_admin is true;
  end if;
  return jsonb_build_object('id', v_id, 'status', v_status);
end $$;

-- Bài tôi đã soạn (mọi trạng thái)
create or replace function public.knowledge_my_submissions() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'slug', a.slug, 'title', a.title, 'summary', a.summary, 'body', a.body,
            'category_id', a.category_id, 'content_type', a.content_type, 'cover_image_url', a.cover_image_url, 'attachment_url', a.attachment_url,
            'status', a.status, 'review_note', a.review_note, 'reward_xu', a.reward_xu, 'published_at', a.published_at, 'updated_at', a.updated_at)
          order by a.updated_at desc), '[]'::jsonb)
    from public.content_articles a where a.created_by = auth.uid()
$$;

-- Xóa bài nháp / đang chờ duyệt của mình
create or replace function public.knowledge_delete_submission(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from public.content_articles where id = p_id and created_by = private.require_uid() and status in ('DRAFT', 'REVIEW');
  if not found then raise exception 'ARTICLE_NOT_FOUND'; end if;
end $$;

-- Danh mục cho người soạn bài
create or replace function public.knowledge_categories() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'needs_expert', c.needs_expert) order by c.sort), '[]'::jsonb)
    from public.content_categories c
$$;

-- Bài của runner (không phải ban nội dung) được đăng lần đầu → cộng Xu cho tác giả
create or replace function private.content_reward_on_publish() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_xu numeric := coalesce((private.economy_config()->>'contentRewardXu')::numeric, 30);
begin
  if new.status = 'PUBLISHED' and old.status is distinct from 'PUBLISHED' and new.created_by is not null
     and private.content_role(new.created_by) is null and new.reward_xu = 0 and v_xu > 0 then
    if private.award(new.created_by, 'CONTENT', 'Bài viết được đăng', left(new.title, 160), v_xu, 0, 'content:' || new.id::text, null,
                     jsonb_build_object('article_id', new.id, 'slug', new.slug)) then
      update public.content_articles set reward_xu = v_xu where id = new.id;
      perform private.notify(new.created_by, null, 'CONTENT', 'Bài viết của bạn đã được đăng · +' || v_xu || ' Xu 🎉', new.title,
        '/learn/' || new.slug, null, true);
    end if;
  end if;
  return new;
end $$;
drop trigger if exists trg_content_reward on public.content_articles;
create trigger trg_content_reward after update of status on public.content_articles
  for each row execute function private.content_reward_on_publish();

-- Ban biên tập sửa bài ebook trong trình soạn CMS (chưa có lựa chọn Ebook) → giữ nguyên loại Ebook
create or replace function private.content_keep_ebook() returns trigger
language plpgsql as $$
begin
  if old.content_type = 'EBOOK' and new.content_type = 'ARTICLE' then new.content_type := 'EBOOK'; end if;
  return new;
end $$;
drop trigger if exists trg_content_keep_ebook on public.content_articles;
create trigger trg_content_keep_ebook before update of content_type on public.content_articles
  for each row execute function private.content_keep_ebook();

-- Người viết xem trước bài của mình khi chưa đăng; thêm tệp ebook + cờ bài cộng đồng
create or replace function public.knowledge_article(p_slug text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  a public.content_articles := (select x from public.content_articles x where x.slug = p_slug);
  v_live boolean;
  v_role text := private.content_role(v_uid);
begin
  if a.id is null then raise exception 'ARTICLE_NOT_FOUND'; end if;
  v_live := private.content_live(a);
  if not v_live and v_role is null and a.created_by is distinct from v_uid then raise exception 'ARTICLE_NOT_FOUND'; end if;
  if v_live then
    insert into public.content_read_history (user_id, article_id) values (v_uid, a.id)
    on conflict (user_id, article_id) do update set last_at = now();
    insert into public.content_user_events (user_id, article_id, kind, day)
    values (v_uid, a.id, 'VIEW', (now() at time zone 'Asia/Ho_Chi_Minh')::date) on conflict do nothing;
    if found then perform private.content_bump(a.id, 'VIEW'); end if;
  end if;
  return private.content_card(a, v_uid) || jsonb_build_object(
    'body', a.body, 'preview', not v_live, 'status', a.status, 'updated_at', a.updated_at, 'source_url', a.source_url,
    'attachment_url', a.attachment_url, 'community', a.created_by is not null and private.content_role(a.created_by) is null,
    'ctas', a.ctas, 'needs_expert_review', a.needs_expert_review, 'expert_reviewed_at', a.expert_reviewed_at,
    'expert_name', (select private.display_name(a.expert_reviewed_by)),
    'category', (select jsonb_build_object('id', c.id, 'name', c.name, 'icon', c.icon, 'market_kind', c.market_kind)
                   from public.content_categories c where c.id = a.category_id),
    'author', (select jsonb_build_object('id', au.id, 'name', au.name, 'title', au.title, 'bio', au.bio, 'avatar_url', au.avatar_url,
                 'kind', au.kind, 'verified', au.verified, 'partner_id', au.partner_id)
                 from public.content_authors au where au.id = a.author_id),
    'tags', (select coalesce(jsonb_agg(jsonb_build_object('slug', t.slug, 'name', t.name) order by t.name), '[]'::jsonb)
               from public.content_article_tags at join public.content_tags t on t.id = at.tag_id where at.article_id = a.id),
    'sources', (select coalesce(jsonb_agg(jsonb_build_object('title', s.title, 'url', s.url, 'publisher', s.publisher) order by s.sort), '[]'::jsonb)
                  from public.content_sources s where s.article_id = a.id),
    'my_feedback', (select jsonb_build_object('helpful', r.helpful, 'comment', r.comment) from public.content_reviews r
                     where r.article_id = a.id and r.user_id = v_uid),
    'series', case when a.series_id is not null then (
       select jsonb_build_object('id', s.id, 'title', s.title,
         'items', (select coalesce(jsonb_agg(jsonb_build_object('slug', x.slug, 'title', x.title,
                     'completed', exists (select 1 from public.content_read_history h where h.article_id = x.id and h.user_id = v_uid and h.completed_at is not null))
                     order by x.series_order, x.published_at), '[]'::jsonb)
                   from public.content_articles x where x.series_id = s.id and private.content_live(x)))
         from public.content_series s where s.id = a.series_id) end,
    'related', (select coalesce(jsonb_agg(private.content_card(y.x, v_uid) order by y.rn), '[]'::jsonb) from (
                  select x, row_number() over (order by
                           (select count(*) from public.content_article_tags t1 join public.content_article_tags t2 on t2.tag_id = t1.tag_id
                             where t1.article_id = a.id and t2.article_id = x.id) desc,
                           (x.category_id = a.category_id) desc, x.published_at desc) rn
                    from public.content_articles x where x.id <> a.id and private.content_live(x)) y where y.rn <= 4));
end $$;

-- ---------------------------------------------------------------------
-- 4. Quản trị: tìm tài khoản theo email (để cấp quyền admin)
-- ---------------------------------------------------------------------
create or replace function public.admin_find_user_by_email(p_email text) returns jsonb
language plpgsql stable security definer set search_path = public, auth as $$
begin
  perform private.require_admin();
  return (select jsonb_build_object('id', p.id, 'display_name', p.display_name, 'avatar_url', p.avatar_url, 'email', u.email,
            'role', p.role, 'last_sign_in_at', u.last_sign_in_at)
            from auth.users u join public.profiles p on p.id = u.id
           where lower(u.email) = lower(trim(coalesce(p_email, ''))));
end $$;

revoke all on function private.cup_counted(uuid), private.cup_entry_autosignup(), private.content_keep_ebook(), private.community_author(uuid), private.content_reward_on_publish() from public, anon, authenticated;
revoke all on function public.join_cup_as_member(uuid, uuid), public.leave_cup_as_member(uuid), public.club_cup_club_board(uuid, uuid),
  public.react_direct_message(uuid, text), public.knowledge_submit(jsonb), public.knowledge_my_submissions(),
  public.knowledge_delete_submission(uuid), public.knowledge_categories(), public.admin_find_user_by_email(text) from public, anon;
grant execute on function public.join_cup_as_member(uuid, uuid), public.leave_cup_as_member(uuid), public.club_cup_club_board(uuid, uuid),
  public.react_direct_message(uuid, text), public.knowledge_submit(jsonb), public.knowledge_my_submissions(),
  public.knowledge_delete_submission(uuid), public.knowledge_categories(), public.admin_find_user_by_email(text) to authenticated;

-- ===================================================================
-- 20261001011800_feedback_round4.sql
-- ===================================================================
-- 011800: Chỉnh sửa lần 4.
-- 1. Victory Studio lấy đúng "Mục tiêu đăng ký" (km runner tự đăng ký) ở thử thách tự đăng ký mục tiêu.
-- 2. Quản trị hệ thống 2 tầng:
--    - Quản trị chính (chủ hệ thống): CHỈ đặt được bằng key hệ thống (SQL Editor / service role), không đặt được từ app.
--      Chỉ Quản trị chính cấp / gỡ quyền admin và phân nhóm quyền; không ai trong app gỡ được Quản trị chính.
--    - Admin thường: chỉ làm được các nhóm quyền được giao (Người dùng, Kinh tế, Đơn hàng, CLB & doanh nghiệp, Thử thách,
--      Cửa hàng & khuyến mãi, Nội dung, Kiểm duyệt, Hệ thống, Nhật ký), có thể đặt hạn dùng; không tác động được admin khác.
--    Kiểm tra nhóm quyền đặt tập trung trong is_system_admin() / require_admin() theo tên hàm RPC đang gọi (request.path),
--    nên mọi hàm admin_* cũ đều được áp dụng mà không phải viết lại.
--    Đặt Quản trị chính (chạy trong SQL Editor):  select private.admin_set_owner('email-cua-ban@...');
-- 3. Victory Studio là tính năng trả phí: mở khi runner là VIP, thành viên CLB Pro, thành viên doanh nghiệp đang hoạt động,
--    hoặc thử thách do CLB Pro tổ chức. Gói Free vẫn dùng ảnh vinh danh thông thường (tab Vinh danh, ảnh chia sẻ bài chạy).
--    Admin mở cho mọi người bằng khóa victoryStudioFree = true trong chính sách kinh tế.
-- Chạy được trong SQL Editor: không DO $$, không SELECT … INTO, không LIMIT. Chạy lại nhiều lần vẫn an toàn.

-- ---------------------------------------------------------------------
-- 1. Victory: mục tiêu đăng ký
-- ---------------------------------------------------------------------
create or replace function private.victory_facts(p_uid uuid, p_kind text, p_ref text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.challenges;
  p public.challenge_participants;
  a public.activities;
  v_ended boolean;
  v_total integer;
  v_rank integer;
  v_state text;
  v_club text;
  v_dist numeric;
  v_km numeric;
  v_mile text;
  v_mile_km numeric;
  v_pace numeric;
  v_pr boolean;
  v_target numeric;
  v_runs integer;
  v_first timestamptz;
  v_reached timestamptz;
  v_level integer;
  v_xp integer;
  v_title text;
  v_desc text;
  v_icon text;
  v_tier text;
  v_at timestamptz;
begin
  if p_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_kind = 'CHALLENGE' then
    if p_ref !~ '^[0-9a-f-]{36}$' then raise exception 'NOT_FOUND'; end if;
    c := (select x from public.challenges x where x.id = p_ref::uuid);
    if c.id is null or c.status = 'CANCELLED' then raise exception 'NOT_FOUND'; end if;
    p := (select x from public.challenge_participants x where x.challenge_id = c.id and x.profile_id = p_uid and x.status <> 'LEFT');
    if p.id is null then raise exception 'NOT_PARTICIPANT'; end if;
    if coalesce(p.current_progress, 0) <= 0 and p.completed_at is null then raise exception 'NO_RESULT'; end if;
    v_ended := c.status = 'FINISHED' or c.end_date < now();
    v_total := (select count(*) from public.challenge_participants x where x.challenge_id = c.id and x.status <> 'LEFT');
    v_rank := coalesce(p.final_rank, 1 + (select count(*) from public.challenge_participants x
                                           where x.challenge_id = c.id and x.status <> 'LEFT' and x.current_progress > p.current_progress))::int;
    v_state := case when p.completed_at is not null then 'COMPLETED' when v_ended then 'FINISHED' else 'IN_PROGRESS' end;
    v_club := (select cl.name from public.clubs cl where cl.id = c.target_club_id);
    v_target := coalesce(nullif(c.target_value, 0), nullif(c.target_km, 0));
    -- Thử thách tự đăng ký mục tiêu: mục tiêu là số km runner đã đăng ký (chưa đăng ký → không hiện mục tiêu)
    if coalesce(c.pledge_enabled, false) then v_target := nullif(p.pledge_km, 0); end if;
    return jsonb_build_object(
      'kind', 'CHALLENGE', 'ref', c.id, 'state', v_state,
      'headline', case v_state when 'COMPLETED' then 'Hoàn thành thử thách' when 'FINISHED' then 'Về đích thử thách' else 'Đang chinh phục' end,
      'title', c.title,
      'subtitle', case when v_ended then 'Kết thúc ' || private.vic_date(c.end_date) else 'Đến ' || private.vic_date(c.end_date) end,
      'date', private.vic_date(coalesce(p.completed_at, case when v_ended then c.end_date end, now())),
      'club', v_club,
      'link', '/challenges/' || c.id,
      'stats', coalesce((select jsonb_agg(s order by o) from (values
          (1, private.vic_stat('score', 'Kết quả', private.vic_score(c.objective, p.current_progress))),
          (2, case when v_total > 1 then private.vic_stat('rank', case when v_ended then 'Thứ hạng' else 'Hạng tạm tính' end, v_rank || '/' || v_total) end),
          (3, case when coalesce(p.distance_m, 0) > 0 and coalesce(c.objective, 'DISTANCE') <> 'DISTANCE' then private.vic_stat('km', 'Quãng đường', private.vic_km(p.distance_m)) end),
          (4, case when coalesce(p.moving_s, 0) > 0 then private.vic_stat('time', 'Thời gian', private.vic_dur(p.moving_s)) end),
          (5, case when coalesce(p.run_count, 0) > 0 and coalesce(c.objective, 'DISTANCE') <> 'RUNS' then private.vic_stat('runs', 'Buổi chạy', p.run_count::text) end),
          (6, case when coalesce(p.streak_days, 0) > 0 and coalesce(c.objective, 'DISTANCE') <> 'STREAK_DAYS' then private.vic_stat('days', 'Ngày chạy', p.streak_days::text) end),
          (7, case when coalesce(p.distance_m, 0) >= 1000 and coalesce(p.moving_s, 0) > 0
                   then private.vic_stat('pace', 'Pace TB', private.pace_text(p.moving_s / (p.distance_m / 1000.0)) || '/km') end),
          (8, case when v_target is not null and coalesce(c.pledge_enabled, false)
                   then private.vic_stat('goal', 'Mục tiêu đăng ký', private.vic_score('DISTANCE', v_target))
                   when v_target is not null and coalesce(c.objective, 'DISTANCE') in ('DISTANCE', 'RUNS', 'DURATION', 'STREAK_DAYS')
                   then private.vic_stat('goal', 'Mục tiêu', private.vic_score(c.objective, v_target)) end),
          (9, case when p.completed_at is not null then private.vic_stat('done', 'Hoàn thành', private.vic_date(p.completed_at)) end)
        ) t(o, s) where s is not null), '[]'::jsonb),
      -- Hạng mục vinh danh BTC đã công bố
      'honors', coalesce((select jsonb_agg(coalesce((select cat->>'title' from jsonb_array_elements(h.categories) cat where cat->>'key' = ho.category),
                                                     ho.category) || case when ho.category like 'CUSTOM%' then '' else ' · Hạng ' || ho.rank end
                                            order by ho.category, ho.rank)
                           from public.challenge_honorees ho join public.challenge_honors h on h.challenge_id = ho.challenge_id and h.status = 'PUBLISHED'
                          where ho.challenge_id = c.id and ho.user_id = p_uid), '[]'::jsonb));

  elsif p_kind = 'RUN' then
    if p_ref !~ '^[0-9a-f-]{36}$' then raise exception 'NOT_FOUND'; end if;
    a := (select x from public.activities x where x.id = p_ref::uuid and x.user_id = p_uid);
    if a.id is null or not public.activity_is_countable(a.status, a.validation_status) then raise exception 'NOT_FOUND'; end if;
    v_dist := coalesce(nullif(a.moving_distance_m, 0), a.distance_m, 0);
    v_km := v_dist / 1000.0;
    if v_km < 1 or coalesce(a.moving_time_s, 0) <= 0 then raise exception 'NOT_ELIGIBLE'; end if;
    v_mile := case when v_km >= 42.195 then 'Marathon' when v_km >= 21.0975 then 'Half Marathon' when v_km >= 10 then '10K' when v_km >= 5 then '5K' end;
    v_mile_km := case when v_km >= 42.195 then 42.195 when v_km >= 21.0975 then 21.0975 when v_km >= 10 then 10 when v_km >= 5 then 5 end;
    v_pace := a.moving_time_s / v_km;
    -- Kỷ lục cá nhân: pace nhanh nhất trong các bài cùng mốc trở lên
    v_pr := v_mile is not null and not exists (
      select 1 from public.activities b
       where b.user_id = p_uid and b.id <> a.id and public.activity_is_countable(b.status, b.validation_status)
         and coalesce(nullif(b.moving_distance_m, 0), b.distance_m, 0) >= v_mile_km * 1000 and coalesce(b.moving_time_s, 0) > 0
         and b.moving_time_s / (coalesce(nullif(b.moving_distance_m, 0), b.distance_m) / 1000.0) < v_pace);
    return jsonb_build_object(
      'kind', 'RUN', 'ref', a.id, 'state', case when v_pr then 'PR' else 'DONE' end,
      'headline', case when v_pr then 'Kỷ lục cá nhân' when v_mile is not null then 'Chinh phục ' || v_mile else 'Hoàn thành bài chạy' end,
      'title', coalesce(v_mile, private.vic_km(v_dist)),
      'subtitle', coalesce(nullif(trim(a.title), ''), 'Chạy bộ'),
      'date', private.vic_date(a.started_at),
      'club', null, 'link', '/activities/' || a.id,
      'stats', coalesce((select jsonb_agg(s order by o) from (values
          (1, private.vic_stat('km', 'Quãng đường', private.vic_km(v_dist))),
          (2, private.vic_stat('time', 'Thời gian', private.vic_dur(a.moving_time_s))),
          (3, private.vic_stat('pace', 'Pace', private.pace_text(v_pace) || '/km')),
          (4, case when coalesce(a.elevation_gain_m, 0) >= 1 then private.vic_stat('elev', 'Leo cao', round(a.elevation_gain_m)::text || ' m') end)
        ) t(o, s) where s is not null), '[]'::jsonb),
      'honors', '[]'::jsonb);

  elsif p_kind = 'TOTAL_KM' then
    if p_ref not in ('50', '100', '200', '300', '500', '1000', '2000', '3000', '5000', '10000') then raise exception 'NOT_FOUND'; end if;
    v_dist := (select coalesce(sum(coalesce(nullif(x.moving_distance_m, 0), x.distance_m, 0)), 0) from public.activities x
                where x.user_id = p_uid and public.activity_is_countable(x.status, x.validation_status));
    if v_dist < p_ref::numeric * 1000 then raise exception 'NOT_ELIGIBLE'; end if;
    v_runs := (select count(*) from public.activities x where x.user_id = p_uid and public.activity_is_countable(x.status, x.validation_status));
    v_first := (select min(x.started_at) from public.activities x where x.user_id = p_uid and public.activity_is_countable(x.status, x.validation_status));
    v_reached := (select min(t.started_at) from (
                    select x.started_at, sum(coalesce(nullif(x.moving_distance_m, 0), x.distance_m, 0)) over (order by x.started_at, x.id) as cum
                      from public.activities x where x.user_id = p_uid and public.activity_is_countable(x.status, x.validation_status)) t
                   where t.cum >= p_ref::numeric * 1000);
    return jsonb_build_object(
      'kind', 'TOTAL_KM', 'ref', p_ref, 'state', 'DONE',
      'headline', 'Cột mốc hành trình', 'title', p_ref || ' KM', 'subtitle', 'Tổng quãng đường chạy trên RaceHub',
      'date', private.vic_date(coalesce(v_reached, now())), 'club', null, 'link', '/me',
      'stats', coalesce((select jsonb_agg(s order by o) from (values
          (1, private.vic_stat('km', 'Tổng quãng đường', private.vic_km(v_dist))),
          (2, private.vic_stat('runs', 'Buổi chạy', v_runs::text)),
          (3, private.vic_stat('since', 'Từ ngày', private.vic_date(v_first)))
        ) t(o, s) where s is not null), '[]'::jsonb),
      'honors', '[]'::jsonb);

  elsif p_kind = 'LEVEL' then
    if p_ref !~ '^[0-9]{1,2}$' then raise exception 'NOT_FOUND'; end if;
    v_level := (select coalesce(x.level, 1) from public.profiles x where x.id = p_uid);
    v_xp := (select coalesce(x.xp, 0) from public.profiles x where x.id = p_uid);
    if p_ref::int < 2 or p_ref::int > coalesce(v_level, 1) then raise exception 'NOT_ELIGIBLE'; end if;
    return jsonb_build_object(
      'kind', 'LEVEL', 'ref', p_ref, 'state', 'DONE',
      'headline', 'Lên cấp', 'title', 'Level ' || p_ref, 'subtitle', private.level_name(p_ref::int),
      'date', private.vic_date(now()), 'club', null, 'link', '/me',
      'stats', jsonb_build_array(
          private.vic_stat('level', 'Cấp độ', p_ref),
          private.vic_stat('title', 'Danh hiệu', private.level_name(p_ref::int)),
          private.vic_stat('xp', 'Tổng XP', v_xp::text)),
      'honors', '[]'::jsonb);

  elsif p_kind = 'BADGE' then
    v_title := (select x.title from public.achievements x join public.user_achievements u on u.achievement_id = x.id
                 where x.code = p_ref and u.user_id = p_uid);
    if v_title is null then raise exception 'NOT_FOUND'; end if;
    v_desc := (select x.description from public.achievements x where x.code = p_ref);
    v_icon := (select x.icon from public.achievements x where x.code = p_ref);
    v_tier := (select x.tier from public.achievements x where x.code = p_ref);
    v_at := (select min(u.unlocked_at) from public.achievements x join public.user_achievements u on u.achievement_id = x.id
              where x.code = p_ref and u.user_id = p_uid);
    return jsonb_build_object(
      'kind', 'BADGE', 'ref', p_ref, 'state', 'DONE', 'icon', v_icon,
      'headline', 'Huy hiệu mới', 'title', v_title, 'subtitle', v_desc,
      'date', private.vic_date(v_at), 'club', null, 'link', '/me?tab=badges',
      'stats', coalesce((select jsonb_agg(s order by o) from (values
          (1, private.vic_stat('badge', 'Huy hiệu', v_title)),
          (2, private.vic_stat('tier', 'Hạng', case lower(coalesce(v_tier, '')) when 'bronze' then 'Đồng' when 'silver' then 'Bạc'
                                                   when 'gold' then 'Vàng' when 'platinum' then 'Bạch kim' when 'diamond' then 'Kim cương' else v_tier end)),
          (3, private.vic_stat('at', 'Mở khóa', private.vic_date(v_at)))
        ) t(o, s) where s is not null), '[]'::jsonb),
      'honors', '[]'::jsonb);
  end if;
  raise exception 'NOT_FOUND';
end $$;

-- ---------------------------------------------------------------------
-- 2. Quản trị chính + nhóm quyền admin
-- ---------------------------------------------------------------------
create table if not exists public.admin_permissions (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  is_owner boolean not null default false,
  scopes text[] not null default '{}',
  expires_at timestamptz,
  note text check (note is null or char_length(note) <= 200),
  granted_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now()
);
alter table public.admin_permissions enable row level security;
revoke all on public.admin_permissions from anon, authenticated;

create or replace function private.admin_scope_list() returns text[]
language sql immutable as $$
  select array['USERS', 'ECONOMY', 'ORDERS', 'CLUBS', 'CHALLENGES', 'SHOP', 'CONTENT', 'MODERATION', 'SYSTEM', 'AUDIT']
$$;

-- Nhóm quyền của một hàm RPC quản trị (null = mọi admin đang hoạt động đều gọi được / hàm tự kiểm tra riêng)
create or replace function private.admin_scope_of(p_fn text) returns text
language sql immutable as $$
  select case
    when p_fn is null or (p_fn !~ '^admin_' and p_fn !~ '^cms_') then null
    when p_fn in ('admin_set_user_role', 'admin_set_permissions', 'admin_team', 'admin_list_admins', 'admin_inbox') then null
    when p_fn in ('admin_search_accounts', 'admin_user_detail', 'admin_set_user_ban', 'admin_account_risks', 'admin_find_user_by_email') then 'USERS'
    when p_fn ~ '^admin_(adjust_user_xu|grant_xu|economy_|publish_config|rollback_config|config_history|topup_club_fund|save_xu_package|set_payment_account|shine_overview|set_shine_config)' then 'ECONOMY'
    when p_fn ~ '^admin_(list_orders|confirm_order|grant_plan|save_plan)' then 'ORDERS'
    when p_fn ~ '^admin_(list_challenges|cancel_challenge|grant_challenge_pass|revoke_challenge_pass|list_passes|bib_listings|hide_bib|list_race_organizers|set_race_organizer)' then 'CHALLENGES'
    when p_fn ~ '^admin_(save_shine_item|preview_segment|run_grant|list_voucher_campaigns)'
      or p_fn ~ '^admin_.*(avatar|gift|promo|quest|uniform|partner)' then 'SHOP'
    when p_fn ~ '^admin_(help_|site_info_save|set_system_notice)' or p_fn ~ '^cms_' then 'CONTENT'
    when p_fn ~ '^admin_(list_reports|resolve_report|gps_qa_list)' then 'MODERATION'
    when p_fn = 'admin_audit_list' then 'AUDIT'
    when p_fn ~ '^admin_(list_clubs|set_club_plan)' or p_fn ~ '^admin_.*org' then 'CLUBS'
    else 'SYSTEM' end
$$;

-- Tên hàm RPC đang được gọi (PostgREST đặt request.path = /rpc/<tên>)
create or replace function private.rpc_fn() returns text
language sql stable as $$
  select nullif(substring(coalesce(current_setting('request.path', true), '') from '([a-z_0-9]+)$'), '')
$$;

create or replace function private.is_admin_owner(p_uid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admin_permissions a join public.profiles p on p.id = a.user_id
                  where a.user_id = p_uid and a.is_owner and (p.role = 'SYSTEM_ADMIN' or p.is_admin is true))
$$;

create or replace function private.admin_owner_exists() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admin_permissions a join public.profiles p on p.id = a.user_id
                  where a.is_owner and (p.role = 'SYSTEM_ADMIN' or p.is_admin is true))
$$;

-- Admin đang hoạt động: có vai trò admin và quyền chưa hết hạn (Quản trị chính không hết hạn)
create or replace function private.admin_active(p_uid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select p_uid is not null
     and exists (select 1 from public.profiles p where p.id = p_uid and (p.role = 'SYSTEM_ADMIN' or p.is_admin is true))
     and not exists (select 1 from public.admin_permissions a
                      where a.user_id = p_uid and not a.is_owner and a.expires_at is not null and a.expires_at <= now())
$$;

-- Có nhóm quyền? Quản trị chính: mọi nhóm. Admin cũ chưa được phân quyền (chưa có dòng): giữ toàn quyền như trước
-- cho tới khi Quản trị chính phân quyền lại.
create or replace function private.admin_has_scope(p_uid uuid, p_scope text) returns boolean
language sql stable security definer set search_path = public as $$
  select p_scope is null
      or not exists (select 1 from public.admin_permissions a where a.user_id = p_uid)
      or exists (select 1 from public.admin_permissions a where a.user_id = p_uid and (a.is_owner or p_scope = any(a.scopes)))
$$;

create or replace function public.is_system_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select private.admin_active(auth.uid()) and private.admin_has_scope(auth.uid(), private.admin_scope_of(private.rpc_fn()))
$$;

create or replace function private.require_admin() returns uuid
language plpgsql stable security definer set search_path = public as $$
begin
  perform private.require_uid();
  if not public.is_system_admin() then raise exception 'FORBIDDEN'; end if;
  return auth.uid();
end $$;

-- Admin toàn quyền trong CLB chỉ khi có nhóm quyền CLB & doanh nghiệp
create or replace function public.club_role(p_club uuid, p_user uuid default auth.uid()) returns text
language sql stable security definer set search_path = public as $$
  select case
    when private.admin_active(p_user) and private.admin_has_scope(p_user, 'CLUBS') then 'OWNER'
    else (select (array_agg(m.role))[1] from public.club_members m
           where m.club_id = p_club and m.user_id = p_user and m.status = 'APPROVED') end
$$;

create or replace function private.notify_admin_owners(p_actor uuid, p_title text, p_body text) returns void
language plpgsql security definer set search_path = public as $$
declare r record;
begin
  for r in select a.user_id from public.admin_permissions a where a.is_owner and a.user_id is distinct from p_actor loop
    perform private.notify(r.user_id, null, 'SYSTEM', p_title, p_body, '/admin', p_actor, true);
  end loop;
end $$;

-- Đặt / bỏ Quản trị chính: CHỈ chạy được trong SQL Editor (người giữ key hệ thống). App không gọi được.
create or replace function private.admin_set_owner(p_email text, p_on boolean default true) returns text
language plpgsql security definer set search_path = public, auth as $$
declare
  v_uid uuid := (select u.id from auth.users u where lower(u.email) = lower(trim(coalesce(p_email, ''))));
begin
  if v_uid is null then raise exception 'USER_NOT_FOUND'; end if;
  if p_on then
    if (select count(*) from public.admin_permissions a where a.is_owner and a.user_id <> v_uid) >= 3 then raise exception 'OWNER_LIMIT'; end if;
    update public.profiles set role = 'SYSTEM_ADMIN' where id = v_uid;
    insert into public.admin_permissions (user_id, is_owner, scopes, expires_at, updated_at)
    values (v_uid, true, private.admin_scope_list(), null, now())
    on conflict (user_id) do update set is_owner = true, scopes = private.admin_scope_list(), expires_at = null, updated_at = now();
  else
    update public.admin_permissions set is_owner = false, updated_at = now() where user_id = v_uid;
  end if;
  insert into public.admin_audit_log (actor_id, action, target, new_value, reason)
  values (v_uid, case when p_on then 'ADMIN_OWNER_SET' else 'ADMIN_OWNER_UNSET' end, 'user:' || v_uid,
          jsonb_build_object('owner', p_on), 'Đặt bằng key hệ thống (SQL Editor)');
  return case when p_on then 'OWNER_SET' else 'OWNER_UNSET' end;
end $$;

-- Cấp / gỡ quyền admin: chỉ Quản trị chính. Admin mới được cấp chưa có nhóm quyền nào (phân quyền ngay sau đó).
create or replace function public.admin_set_user_role(p_user uuid, p_role text, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_admin uuid := private.require_uid();
  v_role text := upper(coalesce(p_role, ''));
  v_old text := (select coalesce(p.role, 'MEMBER') from public.profiles p where p.id = p_user);
  v_was boolean := private.admin_active(p_user) or exists (select 1 from public.profiles p where p.id = p_user and p.is_admin is true);
begin
  if not private.admin_active(v_admin) then raise exception 'FORBIDDEN'; end if;
  if not private.admin_owner_exists() then raise exception 'OWNER_REQUIRED'; end if;
  if not private.is_admin_owner(v_admin) then raise exception 'OWNER_ONLY'; end if;
  if v_old is null then raise exception 'USER_NOT_FOUND'; end if;
  if v_role not in ('SYSTEM_ADMIN', 'MEMBER') then raise exception 'INVALID_ROLE'; end if;
  if p_user = v_admin then raise exception 'CANNOT_TARGET_SELF'; end if;
  if private.is_admin_owner(p_user) then raise exception 'CANNOT_TARGET_OWNER'; end if;
  if v_role = 'SYSTEM_ADMIN' and (select p.banned_at from public.profiles p where p.id = p_user) is not null then raise exception 'USER_BANNED'; end if;
  if v_role = 'SYSTEM_ADMIN' and not exists (select 1 from auth.users u where u.id = p_user and coalesce(u.email, '') <> '') then
    raise exception 'EMAIL_REQUIRED';
  end if;
  if v_old = v_role and (v_role = 'SYSTEM_ADMIN' or not v_was) then return jsonb_build_object('role', v_role); end if;
  update public.profiles set role = v_role, is_admin = case when v_role = 'SYSTEM_ADMIN' then is_admin else false end where id = p_user;
  if v_role = 'SYSTEM_ADMIN' then
    insert into public.admin_permissions (user_id, is_owner, scopes, granted_by, updated_at)
    values (p_user, false, '{}', v_admin, now())
    on conflict (user_id) do update set scopes = '{}', expires_at = null, granted_by = v_admin, updated_at = now();
  else
    delete from public.admin_permissions where user_id = p_user and not is_owner;
  end if;
  insert into public.admin_audit_log (actor_id, action, target, old_value, new_value, reason)
  values (v_admin, 'USER_ROLE', 'user:' || p_user, jsonb_build_object('role', v_old), jsonb_build_object('role', v_role), p_reason);
  perform private.notify(p_user, null, 'SYSTEM',
    case when v_role = 'SYSTEM_ADMIN' then 'Bạn được cấp quyền quản trị RaceHub' else 'Quyền quản trị RaceHub của bạn đã được gỡ' end,
    coalesce(p_reason, ''), case when v_role = 'SYSTEM_ADMIN' then '/admin' else '/me' end, v_admin, true);
  perform private.notify_admin_owners(v_admin,
    case when v_role = 'SYSTEM_ADMIN' then 'Đã cấp quyền admin cho ' else 'Đã gỡ quyền admin của ' end || coalesce(private.display_name(p_user), 'runner'),
    'Người thực hiện: ' || coalesce(private.display_name(v_admin), '') || coalesce(' · ' || p_reason, ''));
  return jsonb_build_object('role', v_role);
end $$;

-- Phân nhóm quyền cho một admin (chỉ Quản trị chính; không áp cho Quản trị chính khác)
create or replace function public.admin_set_permissions(p_user uuid, p_scopes text[], p_expires_at timestamptz default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_admin uuid := private.require_uid();
  v_scopes text[] := (select coalesce(array_agg(distinct upper(s) order by upper(s)), '{}') from unnest(coalesce(p_scopes, '{}')) s);
  v_old jsonb := (select to_jsonb(a) - 'updated_at' from public.admin_permissions a where a.user_id = p_user);
begin
  if not private.admin_active(v_admin) then raise exception 'FORBIDDEN'; end if;
  if not private.admin_owner_exists() then raise exception 'OWNER_REQUIRED'; end if;
  if not private.is_admin_owner(v_admin) then raise exception 'OWNER_ONLY'; end if;
  if p_user = v_admin then raise exception 'CANNOT_TARGET_SELF'; end if;
  if private.is_admin_owner(p_user) then raise exception 'CANNOT_TARGET_OWNER'; end if;
  if not exists (select 1 from public.profiles p where p.id = p_user and (p.role = 'SYSTEM_ADMIN' or p.is_admin is true)) then
    raise exception 'NOT_ADMIN';
  end if;
  if not v_scopes <@ private.admin_scope_list() then raise exception 'INVALID_SCOPE'; end if;
  if p_expires_at is not null and p_expires_at <= now() then raise exception 'INVALID_EXPIRY'; end if;
  insert into public.admin_permissions (user_id, is_owner, scopes, expires_at, note, granted_by, updated_at)
  values (p_user, false, v_scopes, p_expires_at, nullif(left(trim(coalesce(p_note, '')), 200), ''), v_admin, now())
  on conflict (user_id) do update set scopes = excluded.scopes, expires_at = excluded.expires_at, note = excluded.note,
                                      granted_by = v_admin, updated_at = now();
  insert into public.admin_audit_log (actor_id, action, target, old_value, new_value, reason)
  values (v_admin, 'ADMIN_SCOPES', 'user:' || p_user, v_old,
          jsonb_build_object('scopes', v_scopes, 'expires_at', p_expires_at), p_note);
  perform private.notify(p_user, null, 'SYSTEM', 'Quyền quản trị của bạn đã được cập nhật',
    case when cardinality(v_scopes) = 0 then 'Hiện chưa có nhóm quyền nào.' else 'Nhóm quyền: ' || array_to_string(v_scopes, ', ') end
      || coalesce(' · hết hạn ' || to_char(p_expires_at at time zone 'Asia/Ho_Chi_Minh', 'DD/MM/YYYY'), ''), '/admin', v_admin, true);
  return jsonb_build_object('user_id', p_user, 'scopes', v_scopes, 'expires_at', p_expires_at);
end $$;

-- Đội quản trị: mọi admin đang hoạt động xem được (minh bạch), chỉ Quản trị chính sửa được
create or replace function public.admin_team() returns jsonb
language plpgsql stable security definer set search_path = public, auth as $$
declare v_uid uuid := private.require_uid();
begin
  if not private.admin_active(v_uid) then raise exception 'FORBIDDEN'; end if;
  return jsonb_build_object(
    'owner_exists', private.admin_owner_exists(),
    'me', jsonb_build_object('id', v_uid, 'is_owner', private.is_admin_owner(v_uid),
            'legacy', not exists (select 1 from public.admin_permissions a where a.user_id = v_uid),
            'scopes', to_jsonb(case when private.is_admin_owner(v_uid) or not exists (select 1 from public.admin_permissions a where a.user_id = v_uid)
                                    then private.admin_scope_list()
                                    else (select a.scopes from public.admin_permissions a where a.user_id = v_uid) end),
            'expires_at', (select a.expires_at from public.admin_permissions a where a.user_id = v_uid and not a.is_owner)),
    'admins', (select coalesce(jsonb_agg(jsonb_build_object(
                  'id', p.id, 'display_name', p.display_name, 'avatar_url', p.avatar_url,
                  'email', u.email, 'last_sign_in_at', u.last_sign_in_at, 'is_me', p.id = v_uid,
                  'is_owner', coalesce(a.is_owner, false), 'legacy', a.user_id is null,
                  'scopes', to_jsonb(case when coalesce(a.is_owner, false) or a.user_id is null then private.admin_scope_list() else a.scopes end),
                  'expires_at', case when not coalesce(a.is_owner, false) then a.expires_at end,
                  'expired', not coalesce(a.is_owner, false) and a.expires_at is not null and a.expires_at <= now(),
                  'note', a.note,
                  'granted_at', (select max(l.created_at) from public.admin_audit_log l
                                  where l.action = 'USER_ROLE' and l.target = 'user:' || p.id and l.new_value->>'role' = 'SYSTEM_ADMIN'))
                order by coalesce(a.is_owner, false) desc, p.display_name), '[]'::jsonb)
                 from public.profiles p left join auth.users u on u.id = p.id left join public.admin_permissions a on a.user_id = p.id
                where p.role = 'SYSTEM_ADMIN' or p.is_admin is true));
end $$;


-- ---------------------------------------------------------------------
-- 3. Victory Studio theo gói
-- ---------------------------------------------------------------------
-- Lý do được mở (null = gói Free, chưa mở)
create or replace function private.victory_via(p_uid uuid, p_challenge text default null) returns text
language sql stable security definer set search_path = public as $$
  select case
    when coalesce(private.economy_config()->>'victoryStudioFree', 'false') = 'true' then 'FREE'
    when private.admin_active(p_uid) then 'ADMIN'
    when private.user_vip_tier(p_uid) > 0 then 'VIP'
    when exists (select 1 from public.club_members m
                  where m.user_id = p_uid and m.status = 'APPROVED' and private.club_is_pro(m.club_id)) then 'CLUB_PRO'
    when exists (select 1 from public.org_members m
                  where m.user_id = p_uid and m.status = 'APPROVED' and private.org_active(m.org_id)) then 'ORG'
    when coalesce(p_challenge, '') ~ '^[0-9a-f-]{36}$' and exists (
           select 1 from public.challenges c
            where c.id::text = lower(p_challenge) and c.target_club_id is not null and private.club_is_pro(c.target_club_id)) then 'EVENT'
  end
$$;

create or replace function public.victory_access(p_challenge text default null) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('unlocked', v is not null, 'via', v)
    from (select private.victory_via(auth.uid(), p_challenge) as v) t
$$;

-- Cấp mã xác thực mới (xuất ảnh Victory Studio) chỉ khi đã mở; ảnh đã cấp trước đó vẫn làm mới / xác thực được
create or replace function private.victory_gate() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if private.victory_via(coalesce(new.issued_by, new.user_id), case when new.kind = 'CHALLENGE' then new.ref end) is null then
    raise exception 'VICTORY_LOCKED';
  end if;
  return new;
end $$;
drop trigger if exists trg_victory_gate on public.victory_certificates;
create trigger trg_victory_gate before insert on public.victory_certificates for each row execute function private.victory_gate();

revoke all on function private.admin_scope_list(), private.admin_scope_of(text), private.rpc_fn(), private.is_admin_owner(uuid),
  private.admin_owner_exists(), private.admin_active(uuid), private.admin_has_scope(uuid, text), private.notify_admin_owners(uuid, text, text),
  private.admin_set_owner(text, boolean), private.victory_via(uuid, text), private.victory_gate() from public, anon, authenticated;
revoke all on function public.admin_set_permissions(uuid, text[], timestamptz, text), public.admin_team(),
  public.victory_access(text), public.admin_set_user_role(uuid, text, text) from public, anon;
grant execute on function public.admin_set_permissions(uuid, text[], timestamptz, text), public.admin_team(),
  public.victory_access(text), public.admin_set_user_role(uuid, text, text) to authenticated;

-- ===================================================================
-- 20261001011900_profiles_privacy.sql
-- ===================================================================
-- 011900: Vá lộ dữ liệu (kết quả quét bằng anon key, không đăng nhập).
--   profiles: còn 2 policy cũ "Allow public select profile" / "Public profiles are viewable by everyone" (USING true, cho cả anon)
--   → ai có anon key (nằm sẵn trong app web) đọc được MỌI cột của MỌI người: role, xu, strava_athlete_id, referral_code,
--   banned_reason… Token Strava đã được dọn từ 000100 (cột luôn null) nên không lộ token.
-- Sửa:
--   1. Khách chưa đăng nhập: không đọc được profiles.
--   2. Người đã đăng nhập: chỉ đọc CỘT CÔNG KHAI của người khác (id, tên, ảnh, level, giới tính, giới thiệu, ngày tham gia) — đủ cho các
--      chỗ app ghép tên / ảnh (bảng tin, bình luận, thành viên CLB, quỹ, thông báo).
--   3. Hồ sơ đầy đủ của CHÍNH MÌNH (Xu, XP, vai trò, Strava, mã giới thiệu…) đọc qua RPC my_account().
--   4. club_members, club_treasury_log, profile_settings, sổ cái: khách chưa đăng nhập bị từ chối hẳn (trước đây trả
--      200 + rỗng nhờ RLS; nay chặn thêm một lớp ở quyền bảng).
-- RPC SECURITY DEFINER (mọi màn hình khác) không bị ảnh hưởng. Chạy được trong SQL Editor, chạy lại an toàn.

-- 1 + 2. profiles
drop policy if exists "Allow public select profile" on public.profiles;
drop policy if exists "Public profiles are viewable by everyone" on public.profiles;
drop policy if exists "profiles_select_signed_in" on public.profiles;
create policy "profiles_select_signed_in" on public.profiles for select to authenticated using (true);

revoke select on public.profiles from anon, authenticated;
grant select (id, display_name, avatar_url, level, gender, bio, created_at) on public.profiles to authenticated;

-- 3. Hồ sơ đầy đủ của chính mình (bỏ các cột token cũ)
create or replace function public.my_account() returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(p) - 'strava_access_token' - 'strava_refresh_token' - 'strava_token_expires_at'
    from public.profiles p where p.id = auth.uid()
$$;
revoke all on function public.my_account() from public, anon;
grant execute on function public.my_account() to authenticated;

-- 4. Khách chưa đăng nhập không đọc các bảng riêng tư (RLS vẫn là lớp chính cho người đã đăng nhập)
revoke select on public.club_members, public.club_treasury_log, public.profile_settings,
  public.ledger_entries, public.ledger_transactions, public.wallet_transactions from anon;

-- ===================================================================
-- 20261001012000_pledge_required.sql
-- ===================================================================
-- 012000: Thử thách theo mục tiêu (pledge): tham gia BẮT BUỘC kèm mục tiêu.
--   join_challenge_pledge(id, km, code): vào thử thách + đặt mục tiêu trong CÙNG một giao dịch — mục tiêu không hợp lệ / đã khóa
--   thì không vào (không còn người "tham gia nhưng chưa đăng ký mục tiêu").
--   Người đã vào từ trước mà chưa có mục tiêu: app nhắc đăng ký (set_my_pledge vẫn dùng như cũ).
-- Chạy được trong SQL Editor, chạy lại an toàn.

create or replace function public.join_challenge_pledge(p_challenge_id uuid, p_km numeric, p_code text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_join jsonb;
begin
  perform private.require_uid();
  if not exists (select 1 from public.challenges where id = p_challenge_id) then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not exists (select 1 from public.challenges where id = p_challenge_id and pledge_enabled) then raise exception 'PLEDGE_NOT_SUPPORTED'; end if;
  if p_km is null or p_km <= 0 then raise exception 'PLEDGE_REQUIRED'; end if;
  v_join := public.join_challenge(p_challenge_id, p_code, null);
  perform public.set_my_pledge(p_challenge_id, p_km);
  return coalesce(v_join, '{}'::jsonb) || jsonb_build_object('pledge_km', round(p_km, 1));
end $$;

revoke all on function public.join_challenge_pledge(uuid, numeric, text) from public, anon;
grant execute on function public.join_challenge_pledge(uuid, numeric, text) to authenticated;

-- ===================================================================
-- 20261001012100_perf_clubs_inbox.sql
-- ===================================================================
-- Tăng tốc danh sách CLB (tab CLB): đếm tin chưa đọc tối đa 100 (giao diện chỉ hiện "99+"),
-- không phải quét toàn bộ lịch sử chat của CLB chưa từng mở. Kết quả trả về giữ nguyên các cột.
create or replace function public.my_clubs_inbox()
returns table (
  club_id uuid, name text, avatar_url text, accent_color text, role text, member_status text,
  member_count integer, unread_count integer, last_message_body text, last_message_author text,
  last_message_at timestamptz, pinned_title text
)
language sql stable security definer set search_path = public as $$
  select c.id, c.name, c.avatar_url, c.accent_color, m.role, m.status, c.member_count,
         case when m.status <> 'APPROVED' then 0 else (
           select count(*)::int from (
             select 1 from public.club_messages x
              where x.club_id = c.id and x.deleted_at is null and x.author_id <> (select auth.uid())
                and x.created_at > coalesce((select r.last_read_at from public.club_message_reads r
                                              where r.club_id = c.id and r.user_id = (select auth.uid())), m.joined_at, '-infinity')
              order by x.created_at desc
              limit 100) u)
         end,
         lm.body, private.display_name(lm.author_id), lm.created_at,
         (select coalesce(p.title, left(p.body, 80)) from public.club_posts p
           where p.club_id = c.id and p.is_pinned and p.deleted_at is null
           order by p.created_at desc limit 1)
    from public.club_members m
    join public.clubs c on c.id = m.club_id
    left join lateral (
      select x.body, x.author_id, x.created_at from public.club_messages x
       where x.club_id = c.id and x.deleted_at is null and m.status = 'APPROVED'
       order by x.created_at desc limit 1) lm on true
   where m.user_id = (select auth.uid()) and m.status in ('APPROVED', 'PENDING')
   order by coalesce(lm.created_at, m.joined_at) desc nulls last
$$;

-- ===================================================================
-- 20261001012200_perf_game_state.sql
-- ===================================================================
-- Trang chủ nhẹ hơn: my_game_state chỉ "bắt kịp" huy hiệu tối đa 1 lần / 10 phút cho mỗi người
-- (quét toàn bộ bài chạy). Huy hiệu từ bài chạy mới vẫn được chấm ngay khi bài được trả thưởng (game_after_run).
-- Không đổi cách tính XP, Xu, huy hiệu hay thử thách — chỉ đổi tần suất kiểm tra.
create table if not exists private.achievement_catchup (
  user_id uuid primary key references auth.users(id) on delete cascade,
  checked_at timestamptz not null default now()
);

create or replace function private.catch_up_achievements(p_uid uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare v_n integer;
begin
  insert into private.achievement_catchup as c (user_id, checked_at) values (p_uid, now())
  on conflict (user_id) do update set checked_at = excluded.checked_at
   where c.checked_at < excluded.checked_at - interval '10 minutes';
  get diagnostics v_n = row_count;
  if v_n = 0 then return false; end if;
  perform private.evaluate_achievements(p_uid, null);
  return true;
end $$;

revoke all on function private.catch_up_achievements(uuid) from public, anon, authenticated;
revoke all on private.achievement_catchup from public, anon, authenticated;

create or replace function public.my_game_state() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_now timestamptz := now();
  v_today date := private.vn_day(v_now);
  v_week date := private.vn_week(v_now);
  cfg jsonb := private.game_config();
  s public.user_streaks;
  w_km numeric;
  w_runs integer;
  w_days integer;
  v_gap integer;
  v_alive boolean;
  v_daily integer := 0;
  v_prev date;
  d date;
  v_quests jsonb;
  v_league jsonb := null;
  v_group uuid;
  v_tier integer;
  v_events jsonb;
begin
  perform private.settle_leagues_due();
  perform private.catch_up_achievements(v_uid);                  -- bắt kịp huy hiệu (tối đa 1 lần / 10 phút)
  s := private.ensure_streak(v_uid);
  w_km := (select ws.km from private.week_run_stats(v_uid, v_week) as ws);
  w_runs := (select ws.runs from private.week_run_stats(v_uid, v_week) as ws);
  w_days := (select ws.days from private.week_run_stats(v_uid, v_week) as ws);

  v_gap := case when s.last_week is null then null else (v_week - s.last_week) / 7 - 1 end;
  -- Còn chuỗi: tuần này đã đạt, hoặc tuần trước đạt, hoặc số tuần hụt ≤ số khiên
  v_alive := s.last_week is not null and (s.last_week = v_week or v_gap <= s.shields);

  -- Chuỗi ngày liên tiếp (hôm nay hoặc hôm qua còn chạy)
  for d in select distinct private.vn_day(a.started_at) as day from public.activities a
            where a.user_id = v_uid and a.rewarded_at is not null and a.validation_status = 'APPROVED'
              and coalesce(a.status, '') <> 'DELETED' and a.started_at > v_now - interval '400 days'
            order by 1 desc loop
    if v_prev is null then
      exit when d < v_today - 1;
    else
      exit when d <> v_prev - 1;
    end if;
    v_daily := v_daily + 1;
    v_prev := d;
  end loop;

  v_quests := (select coalesce(jsonb_agg(jsonb_build_object(
           'id', q.id, 'code', q.code, 'period', q.period, 'metric', q.metric, 'title', q.title, 'description', q.description,
           'icon', q.icon, 'target', q.target, 'reward_xu', q.reward_xu, 'reward_xp', q.reward_xp,
           'progress', least(coalesce(p.progress, 0), q.target), 'completed', p.completed_at is not null)
           order by q.period, q.sort), '[]'::jsonb)
    from public.quests q
    left join public.user_quest_progress p on p.quest_id = q.id and p.user_id = v_uid
         and p.period_start = case q.period when 'DAILY' then v_today else v_week end
   where q.is_active);

  v_group := (select group_id from public.league_members where user_id = v_uid and week_start = v_week);
  v_tier := coalesce((select tier from public.user_league where user_id = v_uid), 1);
  if v_group is not null then
    v_league := (with lb as (
      select lm.user_id, private.league_points(lm.user_id, v_week) as pts, lm.joined_at
        from public.league_members lm where lm.group_id = v_group),
    rk as (select user_id, pts, row_number() over (order by pts desc, joined_at) as rank from lb)
    select jsonb_build_object(
             'group_id', v_group, 'tier', v_tier, 'tier_name', private.league_name(v_tier),
             'size', (select count(*) from rk),
             'rank', (select rank from rk where user_id = v_uid),
             'points', (select pts from rk where user_id = v_uid),
             'promote', (select promote from private.league_zones((select count(*)::int from rk), v_tier)),
             'demote', (select demote from private.league_zones((select count(*)::int from rk), v_tier)),
             'ends_at', private.vn_start(v_week + 7)));
  end if;

  v_events := (select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at), '[]'::jsonb)
    from (select id, kind, title, subtitle, xu, xp, activity_id, payload, created_at from public.game_events
           where user_id = v_uid and seen_at is null and created_at > v_now - interval '7 days'
           order by created_at desc limit 12) e);

  return jsonb_build_object(
    'today', v_today, 'week_start', v_week,
    'checked_in', exists (select 1 from public.user_quest_progress p join public.quests q on q.id = p.quest_id
                           where p.user_id = v_uid and q.metric = 'CHECKIN' and p.period_start = v_today and p.progress >= 1),
    'week', jsonb_build_object('km', round(coalesce(w_km, 0), 2), 'runs', coalesce(w_runs, 0), 'days', coalesce(w_days, 0)),
    'streak', jsonb_build_object(
      'goal', s.weekly_goal, 'week_days', coalesce(w_days, 0), 'done_this_week', s.last_week = v_week,
      'current', case when v_alive then s.current_weeks else 0 end, 'best', s.best_weeks, 'alive', v_alive,
      'at_risk_weeks', greatest(coalesce(v_gap, 0), 0), 'shields', s.shields,
      'max_shields', (cfg->>'maxShields')::int, 'shield_price', (cfg->>'shieldPrice')::numeric, 'daily', v_daily),
    'quests', v_quests,
    'league', coalesce(v_league, jsonb_build_object('group_id', null, 'tier', v_tier, 'tier_name', private.league_name(v_tier))),
    'unseen', v_events);
end $$;

-- ===================================================================
-- 20261001012300_perf_rls_admin_check.sql
-- ===================================================================
-- Tăng tốc đọc dữ liệu: các chính sách RLS gọi is_system_admin() cho TỪNG DÒNG. Bọc thành (select public.is_system_admin())
-- để Postgres tính 1 lần cho cả câu truy vấn (khuyến nghị của Supabase). Quyền truy cập giữ nguyên tuyệt đối:
-- chỉ đổi cách viết biểu thức, không thêm/bớt điều kiện. Chạy lại nhiều lần an toàn (đã bọc thì bỏ qua).
do $$
declare
  r record;
  v_qual text;
  v_check text;
  pat constant text := '(?<!SELECT )(public\.)?is_system_admin\(\)';
begin
  for r in
    select schemaname, tablename, policyname, qual, with_check
      from pg_policies
     where schemaname = 'public'
       and (coalesce(qual, '') ~ pat or coalesce(with_check, '') ~ pat)
  loop
    v_qual := case when r.qual is null then null else regexp_replace(r.qual, pat, '( SELECT public.is_system_admin())', 'g') end;
    v_check := case when r.with_check is null then null else regexp_replace(r.with_check, pat, '( SELECT public.is_system_admin())', 'g') end;
    if v_qual is not null and v_check is not null then
      execute format('alter policy %I on %I.%I using (%s) with check (%s)', r.policyname, r.schemaname, r.tablename, v_qual, v_check);
    elsif v_qual is not null then
      execute format('alter policy %I on %I.%I using (%s)', r.policyname, r.schemaname, r.tablename, v_qual);
    else
      execute format('alter policy %I on %I.%I with check (%s)', r.policyname, r.schemaname, r.tablename, v_check);
    end if;
  end loop;
end $$;

-- club_is_member / club_is_staff được RLS gọi cho từng dòng. Kiểm tra thành viên (1 lần tra chỉ mục) TRƯỚC,
-- chỉ khi không phải thành viên mới kiểm tra quyền admin hệ thống (nhiều lượt tra cứu). Kết quả y hệt bản cũ.
create or replace function public.club_is_member(p_club uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when exists (select 1 from public.club_members
                  where club_id = p_club and user_id = auth.uid() and status = 'APPROVED') then true
    else public.is_system_admin()
  end
$$;

create or replace function public.club_is_staff(p_club uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when exists (select 1 from public.club_members
                  where club_id = p_club and user_id = auth.uid() and status = 'APPROVED'
                    and role in ('OWNER', 'CAPTAIN')) then true
    else public.is_system_admin()
  end
$$;

-- ===================================================================
-- 20261001012400_strava_max_speed_spike.sql
-- ===================================================================
-- 012400: Chống gian lận bài Strava — bỏ báo nhầm do một điểm GPS nhảy.
-- Trước đây bài có "vận tốc tối đa" > 43 km/h (một điểm) bị chặn chờ duyệt, kể cả khi phân tích theo cửa sổ thời gian
-- thấy bình thường. Giờ chỉ dùng quy tắc này khi không có kết quả phân tích chi tiết.
create or replace function public.ingest_provider_activity(
  p_user_id uuid, p_source text, p_external_id text, p_activity jsonb
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  cfg jsonb := private.economy_config();
  v_sport text := coalesce(p_activity->>'sport_type', 'Run');
  v_started timestamptz := (p_activity->>'started_at')::timestamptz;
  v_elapsed integer := greatest(coalesce((p_activity->>'elapsed_s')::numeric, 0), 0)::integer;
  v_moving integer := greatest(coalesce((p_activity->>'moving_s')::numeric, 0), 0)::integer;
  v_distance numeric := greatest(coalesce((p_activity->>'distance_m')::numeric, 0), 0);
  v_max_speed numeric := (p_activity->>'max_speed_mps')::numeric;
  v_manual boolean := coalesce((p_activity->>'manual')::boolean, false);
  v_has_gps boolean := coalesce((p_activity->>'has_gps')::boolean, true);
  v_ended timestamptz;
  v_pace integer;
  v_connected_at timestamptz;
  v_status text := 'APPROVED';
  v_reason text := 'Hợp lệ (đồng bộ tự động).';
  v_history_only boolean := false;
  v_existing public.activities%rowtype;
  v_id uuid;
  a public.activities%rowtype;
  v_level text;
  v_score integer := 0;
  v_risk jsonb := case when jsonb_typeof(p_activity->'risk') = 'object' then p_activity->'risk' end;
begin
  if p_source not in ('STRAVA', 'GARMIN', 'COROS') then raise exception 'INVALID_SOURCE'; end if;
  if p_external_id is null or v_started is null then raise exception 'INVALID_ACTIVITY'; end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then raise exception 'USER_NOT_FOUND'; end if;

  -- Đã có → chỉ cập nhật tiêu đề (Strava gửi aspect "update" khi đổi tên)
  v_existing := (select x from public.activities x where x.source = p_source and x.source_activity_id = p_external_id);
  if v_existing.id is not null then
    if v_existing.user_id <> p_user_id then raise exception 'ACTIVITY_OWNER_MISMATCH'; end if;
    update public.activities
       set title = left(coalesce(nullif(trim(p_activity->>'title'), ''), title), 120), updated_at = now()
     where id = v_existing.id and title is distinct from left(coalesce(nullif(trim(p_activity->>'title'), ''), title), 120);
    return jsonb_build_object('result', case when found then 'UPDATED' else 'DUPLICATE' end,
                              'activity_id', v_existing.id, 'validation_status', v_existing.validation_status);
  end if;

  -- Không phải chạy bộ / quá ngắn → bỏ qua, không lưu
  if v_sport not in ('Run', 'TrailRun', 'VirtualRun') then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'NOT_RUN');
  end if;
  if v_distance < 200 or v_moving <= 0 then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'TOO_SHORT');
  end if;
  if v_started > now() + interval '10 minutes' then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'FUTURE_START');
  end if;

  v_ended := v_started + make_interval(secs => greatest(v_elapsed, v_moving));
  v_pace := round(v_moving / (v_distance / 1000.0));

  -- Cùng một buổi chạy đã được ghi từ nguồn khác (vd GPS trong app) → không tính 2 lần.
  -- 009900: trừ khi bài này dài hơn hẳn các bài trùng giờ đang được tính (vd đồng hồ ghi đủ 2 giờ, điện thoại chỉ ghi một đoạn)
  if exists (select 1 from public.activities
              where user_id = p_user_id and coalesce(status, '') <> 'DELETED'
                and started_at < v_ended and coalesce(ended_at, started_at) > v_started)
     and v_distance <= 1.1 * private.overlap_meters(private.overlap_ids(p_user_id, v_started, v_ended)) then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'OVERLAPS_EXISTING_ACTIVITY');
  end if;

  -- Luật hợp lệ
  -- Chỉ bài NGHI GIAN LẬN mới chờ duyệt; bài chạy chậm / đi bộ vẫn được ghi nhận ngay (thử thách tự lọc theo pace riêng)
  if v_manual then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 70;
    v_reason := 'Bài nhập tay — không có dữ liệu thiết bị (GPS, thời gian thực) để xác minh.';
  elsif v_sport = 'VirtualRun' then
    v_status := 'PENDING'; v_level := 'MEDIUM'; v_score := 40;
    v_reason := 'Chạy máy / chạy ảo — không có tuyến GPS để đối chiếu quãng đường.';
  elsif not v_has_gps then
    v_status := 'PENDING'; v_level := 'MEDIUM'; v_score := 40;
    v_reason := 'Bài không có tuyến GPS — không đối chiếu được quãng đường.';
  elsif v_pace < (cfg->>'minValidPace')::numeric * 60 then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 75;
    v_reason := 'Pace trung bình ' || (v_pace / 60) || ':' || lpad((v_pace % 60)::text, 2, '0') || '/km — nhanh hơn kỷ lục thế giới.';
  -- 012400: "vận tốc tối đa" của Strava là MỘT điểm (hay do GPS nhảy). Chỉ dùng khi bài KHÔNG được phân tích chi tiết
  -- (không có risk); có risk thì bộ phân tích (cửa sổ trượt + đường cong pace theo thời gian, fraud.ts) quyết định.
  elsif v_risk is null and v_max_speed is not null and v_max_speed > 12 then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 70;
    v_reason := 'Vận tốc tối đa ' || round(v_max_speed * 3.6) || ' km/h — vượt khả năng chạy bộ (> 43 km/h).';
  end if;
  -- Bộ phân tích gian lận (máy chủ ứng dụng, xem features/activity/model/fraud.ts) → chờ ban quản trị xác minh
  if v_status = 'APPROVED' and v_risk->>'verdict' = 'REVIEW' then
    v_status := 'PENDING';
    v_level := coalesce(v_risk->>'level', 'HIGH');
    v_score := coalesce((v_risk->>'score')::int, 65);
    v_reason := coalesce(nullif(v_risk->>'reason', ''), 'Dữ liệu bài chạy bất thường') || '.';
  end if;
  if v_status = 'PENDING' then
    v_reason := left('Mức nghi vấn: ' || private.risk_label(v_level) || '. ' || v_reason
                     || ' Bài được tính sau khi ban quản trị CLB hoặc admin xác minh.', 500);
  end if;

  -- Bài chạy trước khi kết nối: lưu lịch sử, không thưởng (tránh "đổ" hàng tháng dữ liệu cũ lấy Xu)
  v_connected_at := (select max(ca.created_at) from public.connected_accounts ca
                      where ca.user_id = p_user_id and ca.provider = p_source);
  v_history_only := v_connected_at is not null and v_started < v_connected_at;

  v_id := gen_random_uuid();
  insert into public.activities (
    id, user_id, title, source, source_activity_id, sport_type, started_at, ended_at,
    elapsed_time_s, moving_time_s, distance_m, moving_distance_m, avg_pace_s,
    avg_speed_mps, max_speed_mps, avg_heartrate, elevation_gain_m, is_manual, device_name,
    status, validation_status, validation_reason, rewarded_at, earned_xu, earned_xp,
    risk_score, risk_level, risk_flags)
  values (
    v_id, p_user_id, left(coalesce(nullif(trim(p_activity->>'title'), ''), 'Buổi chạy'), 120), p_source, p_external_id, v_sport,
    v_started, v_ended, v_elapsed, v_moving, v_distance, v_distance, v_pace,
    (p_activity->>'avg_speed_mps')::numeric, v_max_speed, (p_activity->>'avg_heartrate')::numeric,
    coalesce((p_activity->>'elevation_gain_m')::numeric, 0), v_manual, left(p_activity->>'device_name', 80),
    case v_status when 'APPROVED' then 'READY' else 'PROCESSING' end, v_status,
    case when v_history_only then v_reason || ' Bài chạy trước khi kết nối — chỉ lưu lịch sử.' else v_reason end,
    case when v_history_only then now() end,
    case when v_history_only then 0 end,
    case when v_history_only then 0 end,
    case when v_status = 'PENDING' then v_score else (v_risk->>'score')::int end,
    case when v_status = 'PENDING' then v_level else v_risk->>'level' end, v_risk->'flags')
  on conflict (source, source_activity_id) where source_activity_id is not null do nothing;

  if not exists (select 1 from public.activities x where x.id = v_id) then  -- request song song đã chèn trước
    v_id := (select x.id from public.activities x where x.source = p_source and x.source_activity_id = p_external_id);
    return jsonb_build_object('result', 'DUPLICATE', 'activity_id', v_id);
  end if;

  a := (select x from public.activities x where x.id = v_id);   -- trigger đã trả thưởng nếu APPROVED
  return jsonb_build_object('result', 'IMPORTED', 'activity_id', v_id,
    'validation_status', a.validation_status, 'reason', a.validation_reason,
    'history_only', v_history_only,
    'earned_xu', coalesce(a.earned_xu, 0), 'earned_xp', coalesce(a.earned_xp, 0));
end $$;

-- ===================================================================
-- 20261001012500_fraud_audit_restore.sql
-- ===================================================================
-- 012500: Chống gian lận — lưu vết, dữ liệu gốc, lịch sử quyết định, khôi phục bài loại nhầm.
--  1. activity_analyses: kết quả phân tích của mọi bài (phiên bản luật, mức, bằng chứng, dữ liệu gốc rút gọn khi bài có dấu hiệu)
--  2. activity_decisions: mọi lần đổi trạng thái hợp lệ (hệ thống / người duyệt / khôi phục) + lý do
--  3. restore_activity(): khôi phục bài bị loại nhầm (trả lại Xu, XP, thử thách như bài hợp lệ)
--  4. Strava: km tính theo quãng đường đã bỏ cú nhảy GPS (không loại bài vì GPS nhảy)
--  (GPS trong app: mất tín hiệu đơn thuần đã không bị coi là gian lận từ 009700/010000 — chỉ "chưa xác minh km",
--   người chạy tự chọn "chỉ tính phần có GPS"; giữ nguyên)
--  6. fraud_review_stats(): tỷ lệ báo nhầm thật (bài bị giữ rồi được duyệt hợp lệ / khôi phục)

-- ---------------------------------------------------------------------
-- 1–2. Bảng lưu vết (chỉ đọc qua RPC; người chạy không đọc trực tiếp)
-- ---------------------------------------------------------------------
create table if not exists public.activity_analyses (
  id uuid primary key default gen_random_uuid(),
  activity_id uuid not null references public.activities(id) on delete cascade,
  created_at timestamptz not null default now(),
  engine text not null,
  verdict text,
  basis text,
  score integer,
  level text,
  independent integer,
  reported_distance_m numeric,
  clean_distance_m numeric,
  flags jsonb,
  inputs jsonb,
  streams jsonb
);
create index if not exists activity_analyses_activity_idx on public.activity_analyses (activity_id, created_at desc);
alter table public.activity_analyses enable row level security;
revoke all on public.activity_analyses from anon, authenticated;

create table if not exists public.activity_decisions (
  id bigint generated always as identity primary key,
  activity_id uuid not null references public.activities(id) on delete cascade,
  at timestamptz not null default now(),
  actor_id uuid,
  actor_kind text not null check (actor_kind in ('SYSTEM', 'REVIEWER', 'RESTORE')),
  from_status text,
  to_status text not null,
  reason text,
  detail text
);
create index if not exists activity_decisions_activity_idx on public.activity_decisions (activity_id, at desc);
create index if not exists activity_decisions_at_idx on public.activity_decisions (at desc);
alter table public.activity_decisions enable row level security;
revoke all on public.activity_decisions from anon, authenticated;

create or replace function private.activity_trace() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_an text;
  a jsonb;
  v_kind text;
begin
  if tg_op = 'INSERT' then
    v_an := nullif(current_setting('racehub.analysis', true), '');
    if v_an is not null then
      a := v_an::jsonb;
      perform set_config('racehub.analysis', '', true);
      insert into public.activity_analyses (activity_id, engine, verdict, basis, score, level, independent,
                                            reported_distance_m, clean_distance_m, flags, inputs, streams)
      values (new.id, coalesce(a->>'engine', 'unknown'), a->>'verdict', a->>'basis', (a->>'score')::int, a->>'level',
              (a->>'independent')::int, nullif(current_setting('racehub.reported_distance', true), '')::numeric,
              (a->>'clean_distance_m')::numeric, a->'flags', a->'inputs', a->'streams');
    elsif new.risk_flags is not null or new.validation_status = 'PENDING' then
      -- Bài ghi bằng GPS trong app (luật phía máy chủ): lưu kết quả; dữ liệu gốc đã nằm ở bảng điểm GPS
      insert into public.activity_analyses (activity_id, engine, verdict, score, level, flags, inputs)
      values (new.id, 'sql-' || lower(coalesce(new.source, 'unknown')),
              case when new.validation_status = 'PENDING' then 'REVIEW' else 'OK' end,
              new.risk_score, new.risk_level, new.risk_flags,
              jsonb_build_object('distance_m', new.distance_m, 'moving_time_s', new.moving_time_s));
    end if;
  elsif new.validation_status is not distinct from old.validation_status then
    return null;
  end if;

  v_kind := coalesce(nullif(current_setting('racehub.decision_kind', true), ''),
                     case when auth.uid() is null or auth.uid() = new.user_id then 'SYSTEM' else 'REVIEWER' end);
  insert into public.activity_decisions (activity_id, actor_id, actor_kind, from_status, to_status, reason, detail)
  values (new.id, auth.uid(), v_kind, case when tg_op = 'UPDATE' then old.validation_status end, new.validation_status,
          left(new.validation_reason, 500), left(new.review_detail, 500));
  return null;
end $$;

drop trigger if exists trg_zz_activity_trace on public.activities;
create trigger trg_zz_activity_trace after insert or update of validation_status on public.activities
  for each row execute function private.activity_trace();

-- ---------------------------------------------------------------------
-- 3. Khôi phục bài bị loại nhầm
-- ---------------------------------------------------------------------
create or replace function public.restore_activity(p_activity_id uuid, p_note text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  a public.activities := (select x from public.activities x where x.id = p_activity_id);
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if a.id is null or coalesce(a.status, '') = 'DELETED' then raise exception 'ACTIVITY_NOT_FOUND'; end if;
  if a.validation_status <> 'REJECTED' then raise exception 'ACTIVITY_NOT_REJECTED'; end if;
  if a.user_id = v_uid or not private.can_review_activity(a.user_id) then raise exception 'FORBIDDEN'; end if;
  if v_note is null or length(v_note) < 5 then raise exception 'NOTE_REQUIRED'; end if;
  -- Bài bị loại vì trùng giờ với bài khác đang được tính → khôi phục sẽ tính 2 lần
  if exists (select 1 from public.activities x
              where x.user_id = a.user_id and x.id <> a.id and x.validation_status = 'APPROVED'
                and coalesce(x.status, '') <> 'DELETED'
                and x.started_at < coalesce(a.ended_at, a.started_at) and coalesce(x.ended_at, x.started_at) > a.started_at) then
    raise exception 'OVERLAPS_COUNTED_RUN';
  end if;

  perform set_config('racehub.decision_kind', 'RESTORE', true);
  update public.activities
     set validation_status = 'APPROVED', status = 'READY',
         validation_reason = 'Đã khôi phục sau khi xem xét lại.',
         review_detail = left('Khôi phục: ' || v_note || coalesce(' · Trước đó: ' || coalesce(review_detail, validation_reason), ''), 500),
         reviewed_by = v_uid, reviewed_at = now(), updated_at = now()
   where id = a.id;                      -- APPROVED → trigger trả thưởng + cộng vào thử thách
  perform set_config('racehub.decision_kind', '', true);

  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_uid, 'RESTORE_ACTIVITY', a.id::text, jsonb_build_object('note', v_note));

  perform private.notify(a.user_id, null, 'RUN_REVIEW', 'Bài chạy đã được khôi phục',
    round(coalesce(a.distance_m, 0) / 1000.0, 2) || ' km — đã xem xét lại và ghi nhận, cộng Xu, XP và thử thách.',
    '/activities/' || a.id, v_uid, true);
end $$;

/** Bài bị loại trong N ngày gần đây mà người gọi được quyền xem lại (BQT CLB của người chạy hoặc admin) */
create or replace function public.rejected_activities(p_club_id uuid default null, p_days integer default 30) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if p_club_id is not null and not public.club_is_staff(p_club_id) then raise exception 'FORBIDDEN'; end if;
  if p_club_id is null and not public.is_system_admin() then raise exception 'FORBIDDEN'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'title', a.title, 'distance_m', a.distance_m, 'moving_time_s', a.moving_time_s,
      'started_at', a.started_at, 'created_at', a.created_at, 'source', a.source,
      'validation_reason', coalesce(a.review_detail, a.validation_reason), 'risk_score', a.risk_score, 'risk_level', a.risk_level,
      'risk_flags', a.risk_flags, 'user_id', a.user_id, 'can_review', a.user_id <> auth.uid(), 'reviewed_at', a.reviewed_at,
      'overlap', coalesce(a.validation_reason, '') like 'Trùng giờ%',
      'profiles', jsonb_build_object('display_name', pr.display_name, 'avatar_url', pr.avatar_url))
      order by coalesce(a.reviewed_at, a.updated_at, a.created_at) desc), '[]'::jsonb)
    from public.activities a
    join public.profiles pr on pr.id = a.user_id
   where a.validation_status = 'REJECTED' and coalesce(a.status, '') <> 'DELETED'
     and coalesce(a.reviewed_at, a.updated_at, a.created_at) > now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 180))
     and (p_club_id is null or exists (select 1 from public.club_members m
                                        where m.club_id = p_club_id and m.user_id = a.user_id and m.status = 'APPROVED')));
end $$;

/** Hồ sơ kiểm tra một bài: các lần phân tích + lịch sử quyết định (cho người duyệt / admin) */
create or replace function public.activity_audit(p_activity_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  a public.activities := (select x from public.activities x where x.id = p_activity_id);
begin
  if a.id is null then raise exception 'ACTIVITY_NOT_FOUND'; end if;
  if a.user_id <> auth.uid() and not private.can_review_activity(a.user_id) then raise exception 'FORBIDDEN'; end if;
  return jsonb_build_object(
    'analyses', (select coalesce(jsonb_agg(jsonb_build_object('at', x.created_at, 'engine', x.engine, 'verdict', x.verdict,
                   'basis', x.basis, 'score', x.score, 'level', x.level, 'independent', x.independent,
                   'reported_distance_m', x.reported_distance_m, 'clean_distance_m', x.clean_distance_m,
                   'flags', x.flags, 'inputs', x.inputs, 'has_streams', x.streams is not null) order by x.created_at desc), '[]'::jsonb)
                   from public.activity_analyses x where x.activity_id = a.id),
    'decisions', (select coalesce(jsonb_agg(jsonb_build_object('at', d.at, 'actor_kind', d.actor_kind,
                   'actor', private.display_name(d.actor_id), 'from', d.from_status, 'to', d.to_status,
                   'reason', d.reason, 'detail', case when a.user_id = auth.uid() then null else d.detail end) order by d.at), '[]'::jsonb)
                   from public.activity_decisions d where d.activity_id = a.id));
end $$;

/** Tỷ lệ báo nhầm thật: trong các bài hệ thống giữ lại (PENDING), bao nhiêu được người duyệt xác nhận hợp lệ / khôi phục */
create or replace function public.fraud_review_stats(p_days integer default 90) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_from timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 90), 1), 365));
begin
  perform private.require_admin();
  return (
    with held as (
      select distinct d.activity_id from public.activity_decisions d
       where d.at >= v_from and d.actor_kind = 'SYSTEM' and d.to_status = 'PENDING'),
    final as (
      select h.activity_id,
             (select d.to_status from public.activity_decisions d where d.activity_id = h.activity_id order by d.at desc, d.id desc limit 1) as last,
             exists (select 1 from public.activity_decisions d where d.activity_id = h.activity_id and d.actor_kind = 'RESTORE') as restored,
             (select a.risk_flags from public.activities a where a.id = h.activity_id) as flags
        from held h),
    codes as (
      select f->>'code' as code, count(*) as n, count(*) filter (where final.last = 'APPROVED') as approved
        from final, jsonb_array_elements(case when jsonb_typeof(final.flags) = 'array' then final.flags else '[]'::jsonb end) f
       group by 1)
    select jsonb_build_object(
      'days', p_days,
      'held', (select count(*) from final),
      'still_pending', (select count(*) from final where last = 'PENDING'),
      'approved_after_review', (select count(*) from final where last = 'APPROVED'),
      'rejected', (select count(*) from final where last = 'REJECTED'),
      'restored', (select count(*) from final where restored),
      'false_positive_rate', (select round(count(*) filter (where last = 'APPROVED')::numeric
                                       / nullif(count(*) filter (where last in ('APPROVED', 'REJECTED')), 0), 3) from final),
      'by_rule', (select coalesce(jsonb_agg(jsonb_build_object('code', code, 'held', n, 'approved', approved) order by n desc), '[]'::jsonb) from codes)));
end $$;

-- ---------------------------------------------------------------------
-- 4. Strava: km theo quãng đường đã bỏ cú nhảy GPS + lưu kết quả phân tích
-- ---------------------------------------------------------------------
create or replace function public.ingest_provider_activity(
  p_user_id uuid, p_source text, p_external_id text, p_activity jsonb
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  cfg jsonb := private.economy_config();
  v_sport text := coalesce(p_activity->>'sport_type', 'Run');
  v_started timestamptz := (p_activity->>'started_at')::timestamptz;
  v_elapsed integer := greatest(coalesce((p_activity->>'elapsed_s')::numeric, 0), 0)::integer;
  v_moving integer := greatest(coalesce((p_activity->>'moving_s')::numeric, 0), 0)::integer;
  v_distance numeric := greatest(coalesce((p_activity->>'distance_m')::numeric, 0), 0);
  v_max_speed numeric := (p_activity->>'max_speed_mps')::numeric;
  v_manual boolean := coalesce((p_activity->>'manual')::boolean, false);
  v_has_gps boolean := coalesce((p_activity->>'has_gps')::boolean, true);
  v_ended timestamptz;
  v_pace integer;
  v_connected_at timestamptz;
  v_status text := 'APPROVED';
  v_reason text := 'Hợp lệ (đồng bộ tự động).';
  v_history_only boolean := false;
  v_existing public.activities%rowtype;
  v_id uuid;
  a public.activities%rowtype;
  v_level text;
  v_score integer := 0;
  v_risk jsonb := case when jsonb_typeof(p_activity->'risk') = 'object' then p_activity->'risk' end;
  v_clean numeric := nullif(p_activity->'risk'->>'clean_distance_m', '')::numeric;
  v_reported numeric;
  v_note text;
begin
  if p_source not in ('STRAVA', 'GARMIN', 'COROS') then raise exception 'INVALID_SOURCE'; end if;
  if p_external_id is null or v_started is null then raise exception 'INVALID_ACTIVITY'; end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then raise exception 'USER_NOT_FOUND'; end if;

  -- Đã có → chỉ cập nhật tiêu đề (Strava gửi aspect "update" khi đổi tên)
  v_existing := (select x from public.activities x where x.source = p_source and x.source_activity_id = p_external_id);
  if v_existing.id is not null then
    if v_existing.user_id <> p_user_id then raise exception 'ACTIVITY_OWNER_MISMATCH'; end if;
    update public.activities
       set title = left(coalesce(nullif(trim(p_activity->>'title'), ''), title), 120), updated_at = now()
     where id = v_existing.id and title is distinct from left(coalesce(nullif(trim(p_activity->>'title'), ''), title), 120);
    return jsonb_build_object('result', case when found then 'UPDATED' else 'DUPLICATE' end,
                              'activity_id', v_existing.id, 'validation_status', v_existing.validation_status);
  end if;

  -- Không phải chạy bộ / quá ngắn → bỏ qua, không lưu
  if v_sport not in ('Run', 'TrailRun', 'VirtualRun') then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'NOT_RUN');
  end if;
  if v_distance < 200 or v_moving <= 0 then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'TOO_SHORT');
  end if;
  if v_started > now() + interval '10 minutes' then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'FUTURE_START');
  end if;

  v_ended := v_started + make_interval(secs => greatest(v_elapsed, v_moving));
  -- 012500: cú nhảy GPS cộng thêm km không có thật → tính theo quãng đường đã bỏ cú nhảy (không loại bài)
  if v_clean is not null and v_clean > 0 and v_distance - v_clean >= greatest(200, 0.03 * v_distance) then
    v_reported := v_distance;
    v_note := 'Bỏ ' || round(v_distance - v_clean) || ' m do GPS nhảy (Strava ' || round(v_distance / 1000.0, 2)
              || ' km → tính ' || round(v_clean / 1000.0, 2) || ' km).';
    v_distance := v_clean;
  end if;
  v_pace := round(v_moving / (v_distance / 1000.0));

  -- Cùng một buổi chạy đã được ghi từ nguồn khác (vd GPS trong app) → không tính 2 lần.
  -- 009900: trừ khi bài này dài hơn hẳn các bài trùng giờ đang được tính (vd đồng hồ ghi đủ 2 giờ, điện thoại chỉ ghi một đoạn)
  if exists (select 1 from public.activities
              where user_id = p_user_id and coalesce(status, '') <> 'DELETED'
                and started_at < v_ended and coalesce(ended_at, started_at) > v_started)
     and v_distance <= 1.1 * private.overlap_meters(private.overlap_ids(p_user_id, v_started, v_ended)) then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'OVERLAPS_EXISTING_ACTIVITY');
  end if;

  -- Luật hợp lệ
  -- Chỉ bài NGHI GIAN LẬN mới chờ duyệt; bài chạy chậm / đi bộ vẫn được ghi nhận ngay (thử thách tự lọc theo pace riêng)
  if v_manual then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 70;
    v_reason := 'Bài nhập tay — không có dữ liệu thiết bị (GPS, thời gian thực) để xác minh.';
  elsif v_sport = 'VirtualRun' then
    v_status := 'PENDING'; v_level := 'MEDIUM'; v_score := 40;
    v_reason := 'Chạy máy / chạy ảo — không có tuyến GPS để đối chiếu quãng đường.';
  elsif not v_has_gps then
    v_status := 'PENDING'; v_level := 'MEDIUM'; v_score := 40;
    v_reason := 'Bài không có tuyến GPS — không đối chiếu được quãng đường.';
  elsif v_pace < (cfg->>'minValidPace')::numeric * 60 then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 75;
    v_reason := 'Pace trung bình ' || (v_pace / 60) || ':' || lpad((v_pace % 60)::text, 2, '0') || '/km — nhanh hơn kỷ lục thế giới.';
  -- 012400: "vận tốc tối đa" của Strava là MỘT điểm (hay do GPS nhảy). Chỉ dùng khi bài KHÔNG được phân tích chi tiết
  -- (không có risk); có risk thì bộ phân tích (cửa sổ trượt + đường cong pace theo thời gian, fraud.ts) quyết định.
  elsif v_risk is null and v_max_speed is not null and v_max_speed > 12 then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 70;
    v_reason := 'Vận tốc tối đa ' || round(v_max_speed * 3.6) || ' km/h — vượt khả năng chạy bộ (> 43 km/h).';
  end if;
  -- Bộ phân tích gian lận (máy chủ ứng dụng, xem features/activity/model/fraud.ts) → chờ ban quản trị xác minh
  if v_status = 'APPROVED' and v_risk->>'verdict' = 'REVIEW' then
    v_status := 'PENDING';
    v_level := coalesce(v_risk->>'level', 'HIGH');
    v_score := coalesce((v_risk->>'score')::int, 65);
    v_reason := coalesce(nullif(v_risk->>'reason', ''), 'Dữ liệu bài chạy bất thường') || '.';
  end if;
  if v_status = 'PENDING' then
    v_reason := left('Mức nghi vấn: ' || private.risk_label(v_level) || '. ' || v_reason
                     || ' Bài được tính sau khi ban quản trị CLB hoặc admin xác minh.', 500);
  end if;

  -- Bài chạy trước khi kết nối: lưu lịch sử, không thưởng (tránh "đổ" hàng tháng dữ liệu cũ lấy Xu)
  v_connected_at := (select max(ca.created_at) from public.connected_accounts ca
                      where ca.user_id = p_user_id and ca.provider = p_source);
  v_history_only := v_connected_at is not null and v_started < v_connected_at;

  v_id := gen_random_uuid();
  -- Kết quả phân tích chi tiết (dữ liệu gốc rút gọn + bằng chứng) → trigger lưu vào activity_analyses cùng lúc với bài
  perform set_config('racehub.analysis', coalesce((p_activity->'analysis')::text, ''), true);
  perform set_config('racehub.reported_distance', coalesce(v_reported::text, ''), true);
  insert into public.activities (
    id, user_id, title, source, source_activity_id, sport_type, started_at, ended_at,
    elapsed_time_s, moving_time_s, distance_m, moving_distance_m, avg_pace_s,
    avg_speed_mps, max_speed_mps, avg_heartrate, elevation_gain_m, is_manual, device_name,
    status, validation_status, validation_reason, review_detail, rewarded_at, earned_xu, earned_xp,
    risk_score, risk_level, risk_flags)
  values (
    v_id, p_user_id, left(coalesce(nullif(trim(p_activity->>'title'), ''), 'Buổi chạy'), 120), p_source, p_external_id, v_sport,
    v_started, v_ended, v_elapsed, v_moving, v_distance, v_distance, v_pace,
    (p_activity->>'avg_speed_mps')::numeric, v_max_speed, (p_activity->>'avg_heartrate')::numeric,
    coalesce((p_activity->>'elevation_gain_m')::numeric, 0), v_manual, left(p_activity->>'device_name', 80),
    case v_status when 'APPROVED' then 'READY' else 'PROCESSING' end, v_status,
    case when v_history_only then v_reason || ' Bài chạy trước khi kết nối — chỉ lưu lịch sử.' else v_reason end,
    case when v_note is null then null when v_status = 'PENDING' then left(v_reason || ' · ' || v_note, 500) else v_note end,
    case when v_history_only then now() end,
    case when v_history_only then 0 end,
    case when v_history_only then 0 end,
    case when v_status = 'PENDING' then v_score else (v_risk->>'score')::int end,
    case when v_status = 'PENDING' then v_level else v_risk->>'level' end, v_risk->'flags')
  on conflict (source, source_activity_id) where source_activity_id is not null do nothing;

  if not exists (select 1 from public.activities x where x.id = v_id) then  -- request song song đã chèn trước
    v_id := (select x.id from public.activities x where x.source = p_source and x.source_activity_id = p_external_id);
    return jsonb_build_object('result', 'DUPLICATE', 'activity_id', v_id);
  end if;

  a := (select x from public.activities x where x.id = v_id);   -- trigger đã trả thưởng nếu APPROVED
  return jsonb_build_object('result', 'IMPORTED', 'activity_id', v_id,
    'validation_status', a.validation_status, 'reason', a.validation_reason,
    'history_only', v_history_only,
    'earned_xu', coalesce(a.earned_xu, 0), 'earned_xp', coalesce(a.earned_xp, 0));
end $$;

revoke all on function private.activity_trace() from public, anon, authenticated;
revoke all on function public.restore_activity(uuid, text), public.rejected_activities(uuid, integer),
  public.activity_audit(uuid), public.fraud_review_stats(integer) from public, anon;
grant execute on function public.restore_activity(uuid, text), public.rejected_activities(uuid, integer),
  public.activity_audit(uuid), public.fraud_review_stats(integer) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001012600_partner_distance_unchanged.sql
-- ===================================================================
-- 012600: KHÔNG sửa km của bài từ đối tác (Strava / Garmin / COROS).
-- RaceHub nhận dữ liệu từ đối tác nên chỉ phân loại: hợp lệ / nghi vấn (chờ duyệt) / bị loại (người duyệt quyết định).
-- GPS lạc rồi quay về là bình thường (chỉ ghi chú). Một cú "dịch chuyển" ≥ 1 km trong vài giây → bộ phân tích
-- (features/activity/model/fraud.ts, GPS_DISTANCE_GAIN) đánh dấu NGHI VẤN → bài chờ duyệt, km giữ nguyên.
-- Thay bản 012500: bỏ đoạn tính km theo clean_distance_m; activity_analyses.reported_distance_m = km đối tác.

create or replace function public.ingest_provider_activity(
  p_user_id uuid, p_source text, p_external_id text, p_activity jsonb
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  cfg jsonb := private.economy_config();
  v_sport text := coalesce(p_activity->>'sport_type', 'Run');
  v_started timestamptz := (p_activity->>'started_at')::timestamptz;
  v_elapsed integer := greatest(coalesce((p_activity->>'elapsed_s')::numeric, 0), 0)::integer;
  v_moving integer := greatest(coalesce((p_activity->>'moving_s')::numeric, 0), 0)::integer;
  v_distance numeric := greatest(coalesce((p_activity->>'distance_m')::numeric, 0), 0);
  v_max_speed numeric := (p_activity->>'max_speed_mps')::numeric;
  v_manual boolean := coalesce((p_activity->>'manual')::boolean, false);
  v_has_gps boolean := coalesce((p_activity->>'has_gps')::boolean, true);
  v_ended timestamptz;
  v_pace integer;
  v_connected_at timestamptz;
  v_status text := 'APPROVED';
  v_reason text := 'Hợp lệ (đồng bộ tự động).';
  v_history_only boolean := false;
  v_existing public.activities%rowtype;
  v_id uuid;
  a public.activities%rowtype;
  v_level text;
  v_score integer := 0;
  v_risk jsonb := case when jsonb_typeof(p_activity->'risk') = 'object' then p_activity->'risk' end;
begin
  if p_source not in ('STRAVA', 'GARMIN', 'COROS') then raise exception 'INVALID_SOURCE'; end if;
  if p_external_id is null or v_started is null then raise exception 'INVALID_ACTIVITY'; end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then raise exception 'USER_NOT_FOUND'; end if;

  -- Đã có → chỉ cập nhật tiêu đề (Strava gửi aspect "update" khi đổi tên)
  v_existing := (select x from public.activities x where x.source = p_source and x.source_activity_id = p_external_id);
  if v_existing.id is not null then
    if v_existing.user_id <> p_user_id then raise exception 'ACTIVITY_OWNER_MISMATCH'; end if;
    update public.activities
       set title = left(coalesce(nullif(trim(p_activity->>'title'), ''), title), 120), updated_at = now()
     where id = v_existing.id and title is distinct from left(coalesce(nullif(trim(p_activity->>'title'), ''), title), 120);
    return jsonb_build_object('result', case when found then 'UPDATED' else 'DUPLICATE' end,
                              'activity_id', v_existing.id, 'validation_status', v_existing.validation_status);
  end if;

  -- Không phải chạy bộ / quá ngắn → bỏ qua, không lưu
  if v_sport not in ('Run', 'TrailRun', 'VirtualRun') then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'NOT_RUN');
  end if;
  if v_distance < 200 or v_moving <= 0 then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'TOO_SHORT');
  end if;
  if v_started > now() + interval '10 minutes' then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'FUTURE_START');
  end if;

  v_ended := v_started + make_interval(secs => greatest(v_elapsed, v_moving));
  -- 012600: km của đối tác (Strava…) giữ nguyên — cú nhảy GPS chỉ dùng để phân loại hợp lệ / nghi vấn (fraud.ts)
  v_pace := round(v_moving / (v_distance / 1000.0));

  -- Cùng một buổi chạy đã được ghi từ nguồn khác (vd GPS trong app) → không tính 2 lần.
  -- 009900: trừ khi bài này dài hơn hẳn các bài trùng giờ đang được tính (vd đồng hồ ghi đủ 2 giờ, điện thoại chỉ ghi một đoạn)
  if exists (select 1 from public.activities
              where user_id = p_user_id and coalesce(status, '') <> 'DELETED'
                and started_at < v_ended and coalesce(ended_at, started_at) > v_started)
     and v_distance <= 1.1 * private.overlap_meters(private.overlap_ids(p_user_id, v_started, v_ended)) then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'OVERLAPS_EXISTING_ACTIVITY');
  end if;

  -- Luật hợp lệ
  -- Chỉ bài NGHI GIAN LẬN mới chờ duyệt; bài chạy chậm / đi bộ vẫn được ghi nhận ngay (thử thách tự lọc theo pace riêng)
  if v_manual then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 70;
    v_reason := 'Bài nhập tay — không có dữ liệu thiết bị (GPS, thời gian thực) để xác minh.';
  elsif v_sport = 'VirtualRun' then
    v_status := 'PENDING'; v_level := 'MEDIUM'; v_score := 40;
    v_reason := 'Chạy máy / chạy ảo — không có tuyến GPS để đối chiếu quãng đường.';
  elsif not v_has_gps then
    v_status := 'PENDING'; v_level := 'MEDIUM'; v_score := 40;
    v_reason := 'Bài không có tuyến GPS — không đối chiếu được quãng đường.';
  elsif v_pace < (cfg->>'minValidPace')::numeric * 60 then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 75;
    v_reason := 'Pace trung bình ' || (v_pace / 60) || ':' || lpad((v_pace % 60)::text, 2, '0') || '/km — nhanh hơn kỷ lục thế giới.';
  -- 012400: "vận tốc tối đa" của Strava là MỘT điểm (hay do GPS nhảy). Chỉ dùng khi bài KHÔNG được phân tích chi tiết
  -- (không có risk); có risk thì bộ phân tích (cửa sổ trượt + đường cong pace theo thời gian, fraud.ts) quyết định.
  elsif v_risk is null and v_max_speed is not null and v_max_speed > 12 then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 70;
    v_reason := 'Vận tốc tối đa ' || round(v_max_speed * 3.6) || ' km/h — vượt khả năng chạy bộ (> 43 km/h).';
  end if;
  -- Bộ phân tích gian lận (máy chủ ứng dụng, xem features/activity/model/fraud.ts) → chờ ban quản trị xác minh
  if v_status = 'APPROVED' and v_risk->>'verdict' = 'REVIEW' then
    v_status := 'PENDING';
    v_level := coalesce(v_risk->>'level', 'HIGH');
    v_score := coalesce((v_risk->>'score')::int, 65);
    v_reason := coalesce(nullif(v_risk->>'reason', ''), 'Dữ liệu bài chạy bất thường') || '.';
  end if;
  if v_status = 'PENDING' then
    v_reason := left('Mức nghi vấn: ' || private.risk_label(v_level) || '. ' || v_reason
                     || ' Bài được tính sau khi ban quản trị CLB hoặc admin xác minh.', 500);
  end if;

  -- Bài chạy trước khi kết nối: lưu lịch sử, không thưởng (tránh "đổ" hàng tháng dữ liệu cũ lấy Xu)
  v_connected_at := (select max(ca.created_at) from public.connected_accounts ca
                      where ca.user_id = p_user_id and ca.provider = p_source);
  v_history_only := v_connected_at is not null and v_started < v_connected_at;

  v_id := gen_random_uuid();
  -- Kết quả phân tích chi tiết (dữ liệu gốc rút gọn + bằng chứng) → trigger lưu vào activity_analyses cùng lúc với bài
  perform set_config('racehub.analysis', coalesce((p_activity->'analysis')::text, ''), true);
  perform set_config('racehub.reported_distance', v_distance::text, true);
  insert into public.activities (
    id, user_id, title, source, source_activity_id, sport_type, started_at, ended_at,
    elapsed_time_s, moving_time_s, distance_m, moving_distance_m, avg_pace_s,
    avg_speed_mps, max_speed_mps, avg_heartrate, elevation_gain_m, is_manual, device_name,
    status, validation_status, validation_reason, review_detail, rewarded_at, earned_xu, earned_xp,
    risk_score, risk_level, risk_flags)
  values (
    v_id, p_user_id, left(coalesce(nullif(trim(p_activity->>'title'), ''), 'Buổi chạy'), 120), p_source, p_external_id, v_sport,
    v_started, v_ended, v_elapsed, v_moving, v_distance, v_distance, v_pace,
    (p_activity->>'avg_speed_mps')::numeric, v_max_speed, (p_activity->>'avg_heartrate')::numeric,
    coalesce((p_activity->>'elevation_gain_m')::numeric, 0), v_manual, left(p_activity->>'device_name', 80),
    case v_status when 'APPROVED' then 'READY' else 'PROCESSING' end, v_status,
    case when v_history_only then v_reason || ' Bài chạy trước khi kết nối — chỉ lưu lịch sử.' else v_reason end,
    null,
    case when v_history_only then now() end,
    case when v_history_only then 0 end,
    case when v_history_only then 0 end,
    case when v_status = 'PENDING' then v_score else (v_risk->>'score')::int end,
    case when v_status = 'PENDING' then v_level else v_risk->>'level' end, v_risk->'flags')
  on conflict (source, source_activity_id) where source_activity_id is not null do nothing;

  if not exists (select 1 from public.activities x where x.id = v_id) then  -- request song song đã chèn trước
    v_id := (select x.id from public.activities x where x.source = p_source and x.source_activity_id = p_external_id);
    return jsonb_build_object('result', 'DUPLICATE', 'activity_id', v_id);
  end if;

  a := (select x from public.activities x where x.id = v_id);   -- trigger đã trả thưởng nếu APPROVED
  return jsonb_build_object('result', 'IMPORTED', 'activity_id', v_id,
    'validation_status', a.validation_status, 'reason', a.validation_reason,
    'history_only', v_history_only,
    'earned_xu', coalesce(a.earned_xu, 0), 'earned_xp', coalesce(a.earned_xp, 0));
end $$;

revoke all on function public.ingest_provider_activity(uuid, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.ingest_provider_activity(uuid, text, text, jsonb) to service_role;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001012700_club_match_v2.sql
-- ===================================================================
-- 012700: THI ĐẤU CLB v2 — một bộ luật cho cả "CLB đấu CLB" (1–1) và "Thách đấu nhiều CLB".
-- • Gộp: trận 1–1 là một thách đấu (club_cups) kind = 'DUEL' có đúng 2 CLB. Trận cũ trong club_battles được chuyển sang
--   (giữ id, giữ cách tính cũ: mọi thành viên, km). Hàm cũ create/respond/cancel_club_battle không dùng nữa.
-- • Luật mới (rules_version = 2), người tạo chọn:
--     - Hình thức: TOTAL (tổng) · AVG (trung bình mỗi VĐV đăng ký) · TOP (cộng top X VĐV giỏi nhất mỗi CLB)
--     - Đo bằng: KM · TIME (thời gian chạy) · PACE (pace đội = tổng thời gian / tổng km của VĐV chạy đủ km tối thiểu; thấp thắng)
--     - Số VĐV tối thiểu / tối đa mỗi bên; thiếu tối thiểu lúc chốt → xử thua (FORFEIT) hoặc hủy trận (CANCEL)
--     - Trần mỗi ngày (mặc định 42 km/người/ngày; thời gian tính theo tỉ lệ) và trần đóng góp (% tổng của đội, tùy chọn)
--     - Tiêu chí phụ khi hòa: nhiều người chạy hơn → nhiều ngày chạy hơn → hòa
--     - Chốt danh sách trước giờ G (mặc định 1 giờ): sau đó không đăng ký / rút được
-- • Đăng ký: chỉ thành viên vào CLB TRƯỚC khi trận được tạo (1–1) / trước khi CLB vào giải (nhiều CLB); mỗi người một CLB.
-- • Thương lượng (1–1): CLB được mời Nhận lời / Từ chối (kèm lý do) / Đề xuất lại điều khoản; mỗi lần đổi là một phiên bản,
--   nhận lời xong điều khoản bị khóa. Lời mời không trả lời trước giờ chốt danh sách → hết hạn.
-- • Kết quả 2 bước: hết giờ → KẾT QUẢ TẠM (báo ban quản trị số bài đang chờ duyệt) → sau 48 giờ → CHÍNH THỨC + trao thưởng.
-- • Thưởng (không cộng Xu): huy hiệu "Chiến thắng đấu CLB" cho VĐV đã chạy của CLB thắng, "MVP đấu CLB" cho người đóng góp
--   nhiều nhất trận; điểm uy tín CLB (Elo, chỉ trận 1–1) + chuỗi thắng; danh hiệu "Nhà vô địch" 7 ngày trên trang CLB.
-- • Chỉ tính bài chạy hợp lệ (APPROVED), được chia sẻ, không bị bỏ qua duyệt, bắt đầu trong khung giờ — như mọi BXH.
-- Cần 003600, 011700. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT, không RETURNING INTO. Chạy lại an toàn.

-- ---------------------------------------------------------------------
-- 1. Cột / bảng mới
-- ---------------------------------------------------------------------
alter table public.club_cups add column if not exists kind text not null default 'CUP';
alter table public.club_cups add column if not exists rules_version integer;
alter table public.club_cups add column if not exists opponent_club_id uuid references public.clubs(id) on delete cascade;
alter table public.club_cups add column if not exists format text not null default 'AVG';
alter table public.club_cups add column if not exists measure text not null default 'KM';
alter table public.club_cups add column if not exists top_n integer;
alter table public.club_cups add column if not exists min_roster integer not null default 1;
alter table public.club_cups add column if not exists max_roster integer;
alter table public.club_cups add column if not exists daily_cap_km numeric;
alter table public.club_cups add column if not exists share_cap_pct integer;
alter table public.club_cups add column if not exists pace_min_km numeric not null default 5;
alter table public.club_cups add column if not exists tiebreak text not null default 'PARTICIPANTS';
alter table public.club_cups add column if not exists lock_hours integer not null default 1;
alter table public.club_cups add column if not exists roster_close_at timestamptz;
alter table public.club_cups add column if not exists forfeit_rule text not null default 'FORFEIT';
alter table public.club_cups add column if not exists final_delay_hours integer not null default 48;
alter table public.club_cups add column if not exists terms_version integer not null default 1;
alter table public.club_cups add column if not exists awaiting_club_id uuid references public.clubs(id) on delete set null;
alter table public.club_cups add column if not exists negotiation jsonb not null default '[]'::jsonb;
alter table public.club_cups add column if not exists decline_reason text;
alter table public.club_cups add column if not exists cancel_reason text;
alter table public.club_cups add column if not exists accepted_at timestamptz;
alter table public.club_cups add column if not exists reminded_at timestamptz;
alter table public.club_cups add column if not exists locked_at timestamptz;
alter table public.club_cups add column if not exists provisional_at timestamptz;
alter table public.club_cups add column if not exists final_at timestamptz;
alter table public.club_cups add column if not exists legacy_battle_id uuid;
create unique index if not exists club_cups_legacy_battle_idx on public.club_cups (legacy_battle_id) where legacy_battle_id is not null;
create index if not exists club_cups_kind_idx on public.club_cups (kind, status, start_at desc);
create index if not exists club_cups_opponent_idx on public.club_cups (opponent_club_id) where opponent_club_id is not null;

-- Thách đấu cũ tính tổng km giữ đúng cách tính
update public.club_cups set format = 'TOTAL' where rules_version is null and metric = 'TOTAL_KM' and format <> 'TOTAL';
update public.club_cups set final_delay_hours = 2 where rules_version is null and final_delay_hours <> 2;

alter table public.club_cups drop constraint if exists club_cups_status_chk;
alter table public.club_cups add constraint club_cups_status_chk check (status in
  ('PENDING_REVIEW', 'INVITED', 'OPEN', 'PROVISIONAL', 'FINISHED', 'REJECTED', 'DECLINED', 'EXPIRED', 'CANCELLED'));
alter table public.club_cups drop constraint if exists club_cups_kind_chk;
alter table public.club_cups add constraint club_cups_kind_chk check (kind in ('CUP', 'DUEL'));
alter table public.club_cups drop constraint if exists club_cups_rules_chk;
alter table public.club_cups add constraint club_cups_rules_chk check (
  format in ('TOTAL', 'AVG', 'TOP') and measure in ('KM', 'TIME', 'PACE')
  and (format <> 'TOP' or top_n between 1 and 50)
  and min_roster between 1 and 100 and (max_roster is null or max_roster between min_roster and 500)
  and (daily_cap_km is null or daily_cap_km between 5 and 100)
  and (share_cap_pct is null or share_cap_pct between 20 and 60)
  and pace_min_km between 1 and 42.2
  and tiebreak in ('PARTICIPANTS', 'DAYS', 'NONE')
  and lock_hours between 0 and 72 and forfeit_rule in ('FORFEIT', 'CANCEL')
  and final_delay_hours between 0 and 168);

alter table public.club_cup_entries add column if not exists forfeited boolean not null default false;

-- Điểm uy tín CLB (Elo) — chỉ trận 1–1 có luật mới
create table if not exists public.club_match_ratings (
  club_id uuid primary key references public.clubs(id) on delete cascade,
  rating integer not null default 1000,
  played integer not null default 0,
  wins integer not null default 0,
  draws integer not null default 0,
  losses integer not null default 0,
  streak integer not null default 0,
  best_streak integer not null default 0,
  updated_at timestamptz not null default now()
);
alter table public.club_match_ratings enable row level security;
revoke all on public.club_match_ratings from anon, authenticated;

insert into public.achievements (code, title, description, category, tier, icon, rule, xp_reward, xu_reward, sort) values
  ('CLUB_MATCH_WIN', 'Chiến thắng đấu CLB', 'Thi đấu và góp km cho CLB thắng một trận đấu CLB', 'SOCIAL', 'GOLD', 'Trophy', null, 0, 0, 72),
  ('CLUB_MATCH_MVP', 'MVP đấu CLB', 'Người đóng góp nhiều nhất một trận đấu CLB', 'SOCIAL', 'LEGEND', 'Crown', null, 0, 0, 73)
on conflict (code) do nothing;

-- ---------------------------------------------------------------------
-- 2. Hàm phụ
-- ---------------------------------------------------------------------
create or replace function private.match_kind_note(u public.club_cups) returns text
language sql immutable as $$ select case u.kind when 'DUEL' then 'CLUB_BATTLE' else 'CLUB_CUP' end $$;

-- Thời điểm thành viên phải vào CLB trước đó mới được đăng ký (1–1: lúc tạo trận; nhiều CLB: lúc CLB vào giải)
create or replace function private.match_cutoff(u public.club_cups, p_club uuid) returns timestamptz
language sql stable security definer set search_path = public as $$
  select case when u.kind = 'DUEL' then u.created_at
              else coalesce((select ce.registered_at from public.club_cup_entries ce where ce.cup_id = u.id and ce.club_id = p_club), u.created_at) end
$$;

create or replace function private.fmt_pace(p_s numeric) returns text
language sql immutable as $$
  select case when p_s is null then '—' else (round(p_s)::int / 60) || ':' || lpad((round(p_s)::int % 60)::text, 2, '0') || '/km' end
$$;

-- Điểm của một CLB dạng chữ (thông báo)
create or replace function private.match_score_text(u public.club_cups, p_score numeric) returns text
language sql immutable as $$
  select case
    when p_score is null then 'chưa có điểm'
    when u.measure = 'PACE' then private.fmt_pace(p_score)
    when u.measure = 'TIME' then round(p_score / 3600.0, 1) || ' giờ' || case when u.format = 'AVG' then '/người' else '' end
    else round(p_score, 2) || ' km' || case when u.format = 'AVG' then '/người' else '' end end
$$;

-- Kiểm tra + chuẩn hóa điều khoản trận (tạo / đề xuất lại). Trả về jsonb đã chuẩn hóa hoặc báo lỗi.
create or replace function private.match_terms(p jsonb, p_kind text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_format text := upper(coalesce(nullif(p->>'format', ''), 'AVG'));
  v_measure text := upper(coalesce(nullif(p->>'measure', ''), 'KM'));
  v_top integer := nullif(p->>'top_n', '')::integer;
  v_min integer := coalesce(nullif(p->>'min_roster', '')::integer, 1);
  v_max integer := nullif(p->>'max_roster', '')::integer;
  v_cap numeric := case when p ? 'daily_cap_km' then nullif(p->>'daily_cap_km', '')::numeric else 42 end;
  v_share integer := nullif(p->>'share_cap_pct', '')::integer;
  v_pmin numeric := coalesce(nullif(p->>'pace_min_km', '')::numeric, 5);
  v_tb text := upper(coalesce(nullif(p->>'tiebreak', ''), 'PARTICIPANTS'));
  v_lock integer := coalesce(nullif(p->>'lock_hours', '')::integer, 1);
  v_forfeit text := upper(coalesce(nullif(p->>'forfeit_rule', ''), 'FORFEIT'));
  v_start timestamptz := nullif(p->>'start_at', '')::timestamptz;
  v_end timestamptz := nullif(p->>'end_at', '')::timestamptz;
  v_maxdur interval;
begin
  if v_format not in ('TOTAL', 'AVG', 'TOP') then raise exception 'INVALID_FORMAT'; end if;
  if v_measure not in ('KM', 'TIME', 'PACE') then raise exception 'INVALID_MEASURE'; end if;
  if v_measure = 'PACE' and v_format = 'TOTAL' then v_format := 'AVG'; end if;     -- "tổng pace" vô nghĩa → pace cả đội
  if v_format = 'TOP' and (v_top is null or v_top not between 1 and 50) then raise exception 'INVALID_TOP_N'; end if;
  if v_format <> 'TOP' then v_top := null; end if;
  if v_min not between 1 and 100 then raise exception 'INVALID_ROSTER'; end if;
  if v_max is not null and v_max not between v_min and 500 then raise exception 'INVALID_ROSTER'; end if;
  if v_format = 'TOP' and v_min < v_top then v_min := v_top; end if;               -- top X cần ít nhất X người
  if v_max is not null and v_max < v_min then raise exception 'INVALID_ROSTER'; end if;
  if v_cap is not null and v_cap not between 5 and 100 then raise exception 'INVALID_DAILY_CAP'; end if;
  if v_share is not null and v_share not between 20 and 60 then raise exception 'INVALID_SHARE_CAP'; end if;
  if v_pmin not between 1 and 42.2 then raise exception 'INVALID_PACE_MIN'; end if;
  if v_tb not in ('PARTICIPANTS', 'DAYS', 'NONE') then raise exception 'INVALID_TIEBREAK'; end if;
  if v_lock not between 0 and 72 then raise exception 'INVALID_LOCK'; end if;
  if v_forfeit not in ('FORFEIT', 'CANCEL') then raise exception 'INVALID_FORFEIT'; end if;
  if v_start is null or v_end is null or v_end <= v_start then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_start < now() - interval '10 minutes' then raise exception 'START_IN_PAST'; end if;
  v_maxdur := case when p_kind = 'DUEL' then interval '62 days' else interval '93 days' end;
  if v_end - v_start < interval '1 day' or v_end - v_start > v_maxdur then raise exception 'INVALID_DURATION'; end if;
  if v_start - make_interval(hours => v_lock) < now() + interval '30 minutes' then raise exception 'LOCK_TOO_SOON'; end if;
  return jsonb_build_object('format', v_format, 'measure', v_measure, 'top_n', v_top, 'min_roster', v_min, 'max_roster', v_max,
    'daily_cap_km', v_cap, 'share_cap_pct', v_share, 'pace_min_km', v_pmin, 'tiebreak', v_tb, 'lock_hours', v_lock,
    'forfeit_rule', v_forfeit, 'start_at', v_start, 'end_at', v_end, 'roster_close_at', v_start - make_interval(hours => v_lock));
end $$;

create or replace function private.match_terms_of(u public.club_cups) returns jsonb
language sql stable as $$
  select jsonb_build_object('format', u.format, 'measure', u.measure, 'top_n', u.top_n, 'min_roster', u.min_roster, 'max_roster', u.max_roster,
    'daily_cap_km', u.daily_cap_km, 'share_cap_pct', u.share_cap_pct, 'pace_min_km', u.pace_min_km, 'tiebreak', u.tiebreak,
    'lock_hours', u.lock_hours, 'forfeit_rule', u.forfeit_rule, 'start_at', u.start_at, 'end_at', u.end_at, 'roster_close_at', u.roster_close_at)
$$;

-- ---------------------------------------------------------------------
-- 3. Tính điểm
-- ---------------------------------------------------------------------
-- Mỗi VĐV được tính (danh sách thi đấu): km (đã áp trần ngày), km gốc, thời gian (tỉ lệ theo trần), số ngày, số buổi.
-- Người đã đăng ký mà chưa chạy vẫn có dòng (0) — để thấy danh sách và để chia trung bình.
create or replace function private.match_runner_rows(p_cup uuid, p_start timestamptz, p_end timestamptz, p_cap_km numeric)
returns table (club_id uuid, user_id uuid, km numeric, raw_km numeric, time_s numeric, days integer, runs integer)
language sql stable security definer set search_path = public as $$
  with r as (
    select * from private.cup_counted(p_cup)
  ), d as (
    select r.club_id, a.user_id, (a.started_at at time zone 'Asia/Ho_Chi_Minh')::date as day,
           sum(a.distance_m) as m, sum(coalesce(nullif(a.moving_time_s, 0), a.elapsed_time_s, 0)) as t, count(*) as n
      from public.activities a join r on r.user_id = a.user_id
     where p_end > p_start
       and a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED'
       and a.shared and not coalesce(a.review_skipped, false)
       and a.started_at >= p_start and a.started_at < p_end
       and a.started_at >= coalesce(r.joined_at, '-infinity'::timestamptz)
     group by r.club_id, a.user_id, (a.started_at at time zone 'Asia/Ho_Chi_Minh')::date
  ), c as (
    select d.*, case when p_cap_km is null or d.m <= p_cap_km * 1000 then d.m else p_cap_km * 1000 end as cm from d
  )
  select r.club_id, r.user_id,
         coalesce(round(sum(c.cm) / 1000.0, 3), 0),
         coalesce(round(sum(c.m) / 1000.0, 3), 0),
         coalesce(round(sum(case when c.m > 0 then c.t * c.cm / c.m else 0 end)), 0),
         count(c.day)::integer,
         coalesce(sum(c.n), 0)::integer
    from r left join c on c.user_id = r.user_id and c.club_id = r.club_id
   group by r.club_id, r.user_id
$$;

-- Giá trị đóng góp từng VĐV sau trần đóng góp (% tổng đội); pace: "pace_s" + đủ km tối thiểu mới được xét
create or replace function private.match_values(u public.club_cups, p_end timestamptz)
returns table (club_id uuid, user_id uuid, km numeric, raw_km numeric, time_s numeric, days integer, runs integer,
               val numeric, pace_s numeric, qualified boolean, rn_val bigint, rn_pace bigint)
language sql stable security definer set search_path = public as $$
  with x as (
    select * from private.match_runner_rows(u.id, u.start_at, p_end, u.daily_cap_km)
  ), v as (
    select x.*, case u.measure when 'TIME' then x.time_s else x.km end as v0,
           sum(case u.measure when 'TIME' then x.time_s else x.km end) over (partition by x.club_id) as team_raw
      from x
  ), w as (
    select v.club_id, v.user_id, v.km, v.raw_km, v.time_s, v.days, v.runs,
           case when u.share_cap_pct is not null and u.measure <> 'PACE' then least(v.v0, v.team_raw * u.share_cap_pct / 100.0) else v.v0 end as val,
           case when v.km > 0 then round(v.time_s / v.km) end as pace_s,
           (v.km >= u.pace_min_km and v.km > 0 and v.time_s > 0) as qualified
      from v
  )
  select w.*,
         row_number() over (partition by w.club_id order by w.val desc, w.user_id),
         row_number() over (partition by w.club_id order by case when w.qualified then w.pace_s end asc nulls last, w.user_id)
    from w
$$;

create or replace function private.match_standings(u public.club_cups, p_end timestamptz) returns jsonb
language sql stable security definer set search_path = public as $$
  with w as (
    select * from private.match_values(u, p_end)
  ), e as (
    select ce.club_id, ce.forfeited from public.club_cup_entries ce where ce.cup_id = u.id
  ), agg as (
    select e.club_id, e.forfeited,
           count(w.user_id) as roster,
           count(w.user_id) filter (where w.runs > 0) as runners,
           coalesce(sum(w.km), 0) as km, coalesce(sum(w.time_s), 0) as time_s, coalesce(sum(w.days), 0) as days,
           coalesce(sum(w.val), 0) as total_val,
           coalesce(sum(w.val) filter (where w.rn_val <= coalesce(u.top_n, 1000000)), 0) as top_val,
           sum(w.time_s) filter (where w.qualified and (u.format <> 'TOP' or w.rn_pace <= u.top_n)) as p_t,
           sum(w.km) filter (where w.qualified and (u.format <> 'TOP' or w.rn_pace <= u.top_n)) as p_km
      from e left join w on w.club_id = e.club_id
     group by e.club_id, e.forfeited
  ), s as (
    select agg.*,
           case when u.measure = 'PACE' then case when agg.p_km > 0 then round(agg.p_t / agg.p_km) end
                when u.format = 'TOTAL' then agg.total_val
                when u.format = 'TOP' then agg.top_val
                else agg.total_val / greatest(agg.roster, 1) end as score,
           case u.tiebreak when 'PARTICIPANTS' then agg.runners when 'DAYS' then agg.days else 0 end as tb
      from agg
  ), ranked as (
    select s.*, rank() over (order by s.forfeited, (s.score is null and u.measure = 'PACE'),
                                      case when u.measure = 'PACE' then s.score end asc,
                                      case when u.measure <> 'PACE' then s.score end desc,
                                      s.tb desc) as rnk
      from s
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'rank', r.rnk, 'club_id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
           'members', r.roster, 'runners', r.runners, 'km', round(r.km, 2), 'avg_km', round(r.km / greatest(r.roster, 1), 2),
           'time_s', round(r.time_s), 'days', r.days, 'forfeited', r.forfeited,
           'score', case when u.measure = 'KM' then round(r.score, 2) else round(r.score) end,
           'top', (select coalesce(jsonb_agg(jsonb_build_object('user_id', w.user_id, 'display_name', private.display_name(w.user_id),
                                                                  'avatar_url', p.avatar_url, 'km', round(w.km, 2), 'time_s', w.time_s,
                                                                  'pace_s', w.pace_s, 'value', round(w.val, 2))
                                             order by w.rn_val), '[]'::jsonb)
                     from w join public.profiles p on p.id = w.user_id
                    where w.club_id = r.club_id and w.rn_val <= 3 and w.runs > 0))
         order by r.rnk, c.name), '[]'::jsonb)
    from ranked r join public.clubs c on c.id = r.club_id
$$;

-- Người đóng góp nhiều nhất trận (pace: nhanh nhất trong những người chạy đủ km tối thiểu)
create or replace function private.match_mvp(u public.club_cups, p_end timestamptz) returns jsonb
language sql stable security definer set search_path = public as $$
  with v as (
    select v.* from private.match_values(u, p_end) v
      join public.club_cup_entries ce on ce.cup_id = u.id and ce.club_id = v.club_id and not ce.forfeited
     where v.runs > 0 and (u.measure <> 'PACE' or v.qualified)
  ), w as (
    select v.*, row_number() over (order by case when u.measure = 'PACE' then null else v.val end desc nulls last,
                                            case when u.measure = 'PACE' then v.pace_s end asc nulls last,
                                            v.km desc, v.user_id) as rk
      from v
  )
  select (select jsonb_build_object('user_id', w.user_id, 'club_id', w.club_id, 'display_name', private.display_name(w.user_id),
                                    'avatar_url', p.avatar_url, 'km', round(w.km, 2), 'time_s', w.time_s, 'pace_s', w.pace_s, 'value', round(w.val, 2))
            from w join public.profiles p on p.id = w.user_id where w.rk = 1)
$$;

-- Giai đoạn để hiển thị
create or replace function private.match_phase(u public.club_cups) returns text
language sql stable as $$
  select case
    when u.status in ('PENDING_REVIEW', 'INVITED', 'REJECTED', 'DECLINED', 'EXPIRED', 'CANCELLED', 'PROVISIONAL', 'FINISHED') then u.status
    when now() < coalesce(u.roster_close_at, u.start_at) then 'REGISTRATION'
    when now() < u.start_at then 'LOCKED'
    when now() < u.end_at then 'LIVE'
    else 'SETTLING' end
$$;

-- ---------------------------------------------------------------------
-- 4. Chốt kết quả, thưởng, điểm uy tín
-- ---------------------------------------------------------------------
create or replace function private.match_badge(p_user uuid, p_code text, p_link text) returns void
language plpgsql security definer set search_path = public as $$
declare v_id uuid := (select a.id from public.achievements a where a.code = p_code); v_title text; v_n integer;
begin
  if v_id is null or p_user is null then return; end if;
  insert into public.user_achievements (user_id, achievement_id) values (p_user, v_id) on conflict do nothing;
  get diagnostics v_n = row_count;
  if v_n > 0 then
    v_title := (select a.title from public.achievements a where a.id = v_id);
    perform private.notify(p_user, null, 'BADGE', 'Huy hiệu mới: ' || v_title, null, p_link, null, true);
  end if;
end $$;

-- Elo K=32: thắng CLB mạnh hơn được nhiều điểm hơn; p_sa = 1 (A thắng) / 0.5 (hòa) / 0 (A thua)
create or replace function private.match_elo(p_a uuid, p_b uuid, p_sa numeric) returns void
language plpgsql security definer set search_path = public as $$
declare ra numeric; rb numeric; ea numeric;
begin
  insert into public.club_match_ratings (club_id) values (p_a), (p_b) on conflict (club_id) do nothing;
  ra := (select rating from public.club_match_ratings where club_id = p_a);
  rb := (select rating from public.club_match_ratings where club_id = p_b);
  ea := 1 / (1 + power(10::numeric, (rb - ra) / 400.0));
  update public.club_match_ratings set rating = greatest(100, round(ra + 32 * (p_sa - ea))), played = played + 1,
         wins = wins + (p_sa = 1)::int, draws = draws + (p_sa = 0.5)::int, losses = losses + (p_sa = 0)::int,
         streak = case when p_sa = 1 then greatest(streak, 0) + 1 when p_sa = 0 then least(streak, 0) - 1 else 0 end,
         best_streak = greatest(best_streak, case when p_sa = 1 then greatest(streak, 0) + 1 else 0 end), updated_at = now()
   where club_id = p_a;
  update public.club_match_ratings set rating = greatest(100, round(rb + 32 * ((1 - p_sa) - (1 - ea)))), played = played + 1,
         wins = wins + (p_sa = 0)::int, draws = draws + (p_sa = 0.5)::int, losses = losses + (p_sa = 1)::int,
         streak = case when p_sa = 0 then greatest(streak, 0) + 1 when p_sa = 1 then least(streak, 0) - 1 else 0 end,
         best_streak = greatest(best_streak, case when p_sa = 0 then greatest(streak, 0) + 1 else 0 end), updated_at = now()
   where club_id = p_b;
end $$;

create or replace function private.match_finalize(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  u public.club_cups := (select x from public.club_cups x where x.id = p_id);
  s jsonb; v_win uuid; v_mvp jsonb; v_n integer; r jsonb; m record; v_total integer; v_link text; v_kind text; v_msg text;
begin
  if u.id is null or u.status not in ('OPEN', 'PROVISIONAL') then return; end if;
  s := private.match_standings(u, u.end_at);
  -- Thắng: đúng một CLB hạng 1, không bị xử thua; hòa (cùng hạng 1) → không ai thắng
  v_win := case when (select count(*) from jsonb_array_elements(s) e where (e->>'rank')::int = 1) = 1
                then (select (e->>'club_id')::uuid from jsonb_array_elements(s) e
                       where (e->>'rank')::int = 1 and not coalesce((e->>'forfeited')::boolean, false)
                         and (e->>'score') is not null) end;
  v_mvp := private.match_mvp(u, u.end_at);
  update public.club_cups set status = 'FINISHED', settled_at = now(), final_at = now(),
         result = jsonb_build_object('standings', s, 'winner_id', v_win, 'mvp', v_mvp, 'final', true)
   where id = u.id and status in ('OPEN', 'PROVISIONAL');
  get diagnostics v_n = row_count;
  if v_n = 0 then return; end if;

  v_link := '/cups/' || u.id;
  v_kind := private.match_kind_note(u);
  if u.rules_version is not null then
    if v_win is not null then
      for m in select w.user_id from private.match_runner_rows(u.id, u.start_at, u.end_at, u.daily_cap_km) w
                where w.club_id = v_win and w.runs > 0 loop
        perform private.match_badge(m.user_id, 'CLUB_MATCH_WIN', v_link);
      end loop;
    end if;
    if v_mvp is not null then perform private.match_badge((v_mvp->>'user_id')::uuid, 'CLUB_MATCH_MVP', v_link); end if;
    if u.kind = 'DUEL' and u.host_club_id is not null and u.opponent_club_id is not null then
      perform private.match_elo(u.host_club_id, u.opponent_club_id,
        case when v_win = u.host_club_id then 1 when v_win = u.opponent_club_id then 0 else 0.5 end);
    end if;
  end if;

  v_total := jsonb_array_length(s);
  for r in select value from jsonb_array_elements(s) loop
    v_msg := case
      when coalesce((r->>'forfeited')::boolean, false) then 'CLB bị xử thua (không đủ VĐV) tại "' || u.title || '"'
      when v_win = (r->>'club_id')::uuid then 'CLB thắng "' || u.title || '"! 🏆'
      when v_win is null and (r->>'rank')::int = 1 then 'Hòa tại "' || u.title || '"'
      when u.kind = 'DUEL' then 'CLB thua "' || u.title || '" — hẹn trận sau!'
      else 'CLB xếp hạng ' || (r->>'rank') || '/' || v_total || ' tại "' || u.title || '"' end;
    perform private.notify_club((r->>'club_id')::uuid, false, v_kind, 'Kết quả chính thức: ' || v_msg,
      private.match_score_text(u, nullif(r->>'score', '')::numeric) || ' · ' || (r->>'runners') || '/' || (r->>'members') || ' VĐV đã chạy'
        || case when v_mvp is not null and (v_mvp->>'club_id') = (r->>'club_id') then ' · MVP: ' || (v_mvp->>'display_name') else '' end,
      v_link, null);
  end loop;
end $$;

-- Chuyển trạng thái một trận theo thời gian (idempotent; gọi khi mở trang + cron hằng ngày)
create or replace function private.match_tick(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  u public.club_cups := (select x from public.club_cups x where x.id = p_id);
  v_n integer; v_short integer; m record; e record; v_pending integer; v_kind text; v_link text; s jsonb; v_close text;
begin
  if u.id is null then return; end if;
  v_kind := private.match_kind_note(u);
  v_link := '/cups/' || u.id;

  -- 1. Lời mời 1–1 không được trả lời trước giờ chốt danh sách → hết hạn
  if u.status = 'INVITED' then
    if now() >= coalesce(u.roster_close_at, u.start_at) then
      update public.club_cups set status = 'EXPIRED' where id = u.id and status = 'INVITED';
      get diagnostics v_n = row_count;
      if v_n > 0 then
        perform private.notify_club(u.host_club_id, true, v_kind, 'Lời thách đấu "' || u.title || '" đã hết hạn', 'Đối thủ chưa trả lời trước giờ chốt danh sách.', v_link, null);
        perform private.notify_club(u.opponent_club_id, true, v_kind, 'Lời thách đấu "' || u.title || '" đã hết hạn', null, v_link, null);
      end if;
    end if;
    return;
  end if;

  if u.status = 'OPEN' and u.rules_version is not null then
    v_close := to_char(u.roster_close_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM');
    -- 2. Nhắc thành viên đủ điều kiện mà chưa đăng ký (một lần, khoảng 1 ngày trước giờ chốt)
    if u.reminded_at is null and now() >= u.roster_close_at - interval '26 hours' and now() < u.roster_close_at then
      update public.club_cups set reminded_at = now() where id = u.id and reminded_at is null;
      get diagnostics v_n = row_count;
      if v_n > 0 then
        for m in select cm.user_id, cm.club_id from public.club_members cm
                   join public.club_cup_entries ce on ce.cup_id = u.id and ce.club_id = cm.club_id
                  where cm.status = 'APPROVED' and cm.joined_at <= private.match_cutoff(u, cm.club_id)
                    and not exists (select 1 from public.club_cup_members x where x.cup_id = u.id and x.user_id = cm.user_id) loop
          perform private.notify(m.user_id, m.club_id, v_kind, 'Sắp chốt danh sách: ' || u.title,
            'Bấm để đăng ký thi đấu trước ' || v_close || ' — chỉ người đã đăng ký mới được tính cho CLB.', v_link, null, true);
        end loop;
      end if;
    end if;
    -- 3. Chốt danh sách: CLB thiếu VĐV tối thiểu → xử thua / hủy trận (theo luật đã chọn)
    if u.locked_at is null and now() >= u.roster_close_at then
      update public.club_cups set locked_at = now() where id = u.id and locked_at is null;
      get diagnostics v_n = row_count;
      if v_n > 0 then
        update public.club_cup_entries ce set forfeited = true
         where ce.cup_id = u.id
           and (select count(*) from public.club_cup_members x where x.cup_id = u.id and x.club_id = ce.club_id) < u.min_roster;
        v_short := (select count(*) from public.club_cup_entries ce where ce.cup_id = u.id and ce.forfeited);
        if u.kind = 'DUEL' and (v_short = 2 or (v_short = 1 and u.forfeit_rule = 'CANCEL')) then
          update public.club_cups set status = 'CANCELLED', cancel_reason = 'Không đủ ' || u.min_roster || ' VĐV đăng ký lúc chốt danh sách'
           where id = u.id;
          for e in select ce.club_id from public.club_cup_entries ce where ce.cup_id = u.id loop
            perform private.notify_club(e.club_id, false, v_kind, 'Trận "' || u.title || '" đã hủy',
              'Không đủ ' || u.min_roster || ' VĐV đăng ký lúc chốt danh sách.', v_link, null);
          end loop;
          return;
        end if;
        for m in select x.user_id, x.club_id from public.club_cup_members x where x.cup_id = u.id loop
          perform private.notify(m.user_id, m.club_id, v_kind, 'Đã chốt danh sách: ' || u.title,
            'Bắt đầu ' || to_char(u.start_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM') || '. Mọi bài chạy hợp lệ trong giờ thi đấu đều tính cho CLB!',
            v_link, null, false);
        end loop;
        for e in select ce.club_id from public.club_cup_entries ce where ce.cup_id = u.id and ce.forfeited loop
          perform private.notify_club(e.club_id, true, v_kind, 'CLB bị xử thua "' || u.title || '"',
            'Chưa đủ ' || u.min_roster || ' VĐV đăng ký lúc chốt danh sách.', v_link, null);
        end loop;
      end if;
    end if;
  end if;

  u := (select x from public.club_cups x where x.id = p_id);
  -- 4. Hết giờ → kết quả tạm (luật mới) / chốt luôn sau 2 giờ (trận cũ)
  if u.status = 'OPEN' and now() >= u.end_at then
    if u.rules_version is null then
      if now() >= u.end_at + make_interval(hours => u.final_delay_hours) then perform private.match_finalize(u.id); end if;
      return;
    end if;
    update public.club_cups set status = 'PROVISIONAL', provisional_at = now() where id = u.id and status = 'OPEN';
    get diagnostics v_n = row_count;
    if v_n > 0 then
      s := private.match_standings(u, u.end_at);
      for e in select (x->>'club_id')::uuid as club_id, x->>'score' as score, (x->>'rank')::int as rk from jsonb_array_elements(s) x loop
        perform private.notify_club(e.club_id, false, v_kind, 'Kết quả tạm: ' || u.title,
          'Hạng ' || e.rk || ' · ' || private.match_score_text(u, nullif(e.score, '')::numeric)
            || '. Kết quả chính thức sau ' || u.final_delay_hours || ' giờ (chờ bài đồng bộ muộn và bài đang duyệt).', v_link, null);
        -- Báo ban quản trị số bài của VĐV đang chờ duyệt — duyệt trước giờ chốt chính thức
        v_pending := (select count(*) from public.activities a
                        join public.club_cup_members x on x.cup_id = u.id and x.user_id = a.user_id and x.club_id = e.club_id
                       where a.validation_status = 'PENDING' and coalesce(a.status, '') <> 'DELETED'
                         and a.started_at >= u.start_at and a.started_at < u.end_at);
        if v_pending > 0 then
          perform private.notify_club(e.club_id, true, v_kind, v_pending || ' bài chạy thi đấu đang chờ duyệt',
            'Duyệt trước ' || to_char((u.end_at + make_interval(hours => u.final_delay_hours)) at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM')
              || ' để được tính vào kết quả "' || u.title || '".', '/clubs/' || e.club_id || '/members', null);
        end if;
      end loop;
    end if;
    u := (select x from public.club_cups x where x.id = p_id);
  end if;
  -- 5. Hết thời gian chờ → kết quả chính thức + thưởng
  if u.status = 'PROVISIONAL' and now() >= u.end_at + make_interval(hours => u.final_delay_hours) then
    perform private.match_finalize(u.id);
  end if;
end $$;

-- Cron hằng ngày (service role): mọi trận cần chuyển trạng thái
create or replace function public.settle_due_club_cups() returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in select x.id from public.club_cups x
            where (x.status = 'INVITED' and now() >= coalesce(x.roster_close_at, x.start_at))
               or (x.status = 'OPEN' and (now() >= x.end_at
                    or (x.rules_version is not null and x.locked_at is null and now() >= x.roster_close_at)
                    or (x.rules_version is not null and x.reminded_at is null and now() >= x.roster_close_at - interval '26 hours')))
               or (x.status = 'PROVISIONAL' and now() >= x.end_at + make_interval(hours => x.final_delay_hours)) loop
    perform private.match_tick(r.id);
    n := n + 1;
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------------
-- 5. Xem
-- ---------------------------------------------------------------------
create or replace function private.club_brief(p_club uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color)
    from public.clubs c where c.id = p_club
$$;

create or replace function private.cup_visible(u public.club_cups) returns boolean
language sql stable security definer set search_path = public as $$
  select u.status in ('OPEN', 'PROVISIONAL', 'FINISHED', 'CANCELLED') or u.created_by = auth.uid() or public.is_system_admin()
      or (u.host_club_id is not null and public.club_is_staff(u.host_club_id))
      or (u.opponent_club_id is not null and public.club_is_staff(u.opponent_club_id))
      -- 1–1 đã từ chối / hết hạn: thành viên hai CLB vẫn xem lại được
      or (u.kind = 'DUEL' and (public.club_is_member(u.host_club_id) or public.club_is_member(u.opponent_club_id)))
$$;

create or replace function private.cup_json(u public.club_cups, p_full boolean) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', u.id, 'title', u.title, 'description', u.description, 'prize', u.prize, 'metric', u.metric,
    'start_at', u.start_at, 'end_at', u.end_at, 'reg_close_at', u.reg_close_at, 'max_clubs', u.max_clubs,
    'status', u.status, 'review_note', u.review_note, 'created_at', u.created_at, 'settled_at', u.settled_at,
    'require_signup', coalesce(u.require_signup, false),
    'host', private.club_brief(u.host_club_id),
    'creator', (select jsonb_build_object('id', p.id, 'display_name', p.display_name, 'avatar_url', p.avatar_url)
                  from public.profiles p where p.id = u.created_by),
    'clubs', (select count(*) from public.club_cup_entries ce where ce.cup_id = u.id),
    'my_clubs', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
                         'staff', m.role in ('OWNER', 'CAPTAIN') or public.is_system_admin(),
                         'joined', ce.club_id is not null,
                         'forfeited', coalesce(ce.forfeited, false),
                         'eligible', m.joined_at is null or u.rules_version is null or m.joined_at <= private.match_cutoff(u, c.id),
                         'roster', (select count(*) from public.club_cup_members x where x.cup_id = u.id and x.club_id = c.id),
                         'signed_up', exists (select 1 from public.club_cup_members cm where cm.cup_id = u.id and cm.club_id = c.id and cm.user_id = auth.uid()))
                       order by (ce.club_id is null), c.name), '[]'::jsonb)
                   from public.club_members m join public.clubs c on c.id = m.club_id
                   left join public.club_cup_entries ce on ce.cup_id = u.id and ce.club_id = c.id
                  where m.user_id = auth.uid() and m.status = 'APPROVED'
                    and (u.kind = 'CUP' or c.id in (u.host_club_id, u.opponent_club_id))),
    'my_signup', (select cm.club_id from public.club_cup_members cm where cm.cup_id = u.id and cm.user_id = auth.uid()),
    'can_manage', u.created_by = auth.uid() or public.is_system_admin()
                  or (u.host_club_id is not null and public.club_is_staff(u.host_club_id)),
    'can_review', public.is_system_admin(),
    'standings', case when p_full and u.status in ('OPEN', 'PROVISIONAL', 'FINISHED') then coalesce(u.result->'standings',
                   private.match_standings(u, least(u.end_at, greatest(now(), u.start_at)))) end)
  || jsonb_build_object(
    'kind', u.kind, 'rules_version', u.rules_version, 'opponent', private.club_brief(u.opponent_club_id),
    'format', u.format, 'measure', u.measure, 'top_n', u.top_n, 'min_roster', u.min_roster, 'max_roster', u.max_roster,
    'daily_cap_km', u.daily_cap_km, 'share_cap_pct', u.share_cap_pct, 'pace_min_km', u.pace_min_km, 'tiebreak', u.tiebreak,
    'lock_hours', u.lock_hours, 'roster_close_at', coalesce(u.roster_close_at, case when coalesce(u.require_signup, false) then u.end_at else u.start_at end),
    'forfeit_rule', u.forfeit_rule,
    'final_after', u.end_at + make_interval(hours => u.final_delay_hours), 'final_delay_hours', u.final_delay_hours,
    'accepted_at', u.accepted_at, 'locked_at', u.locked_at, 'provisional_at', u.provisional_at, 'final_at', u.final_at,
    'phase', private.match_phase(u), 'terms_version', u.terms_version, 'awaiting_club_id', u.awaiting_club_id,
    'decline_reason', u.decline_reason, 'cancel_reason', u.cancel_reason,
    'negotiation', case when public.is_system_admin()
                          or (u.host_club_id is not null and public.club_is_staff(u.host_club_id))
                          or (u.opponent_club_id is not null and public.club_is_staff(u.opponent_club_id)) then u.negotiation end,
    'can_respond', u.status = 'INVITED' and u.awaiting_club_id is not null and public.club_is_staff(u.awaiting_club_id),
    'can_cancel', case
       when u.status in ('FINISHED', 'CANCELLED', 'DECLINED', 'EXPIRED', 'REJECTED') then false
       when public.is_system_admin() then u.status <> 'PROVISIONAL'
       when u.kind = 'DUEL' then (u.status = 'INVITED' and public.club_is_staff(u.host_club_id))
                               or (u.status = 'OPEN' and now() < u.start_at
                                   and (public.club_is_staff(u.host_club_id) or public.club_is_staff(u.opponent_club_id)))
       else (u.created_by = auth.uid() or (u.host_club_id is not null and public.club_is_staff(u.host_club_id)))
            and (u.status = 'PENDING_REVIEW' or (u.status = 'OPEN' and now() < u.start_at)) end,
    'winner_id', u.result->'winner_id', 'mvp', u.result->'mvp',
    -- Ban quản trị: số bài của VĐV thi đấu đang chờ duyệt trong khung giờ
    'pending_runs', case when u.status in ('OPEN', 'PROVISIONAL') and exists (
          select 1 from public.club_cup_entries ce where ce.cup_id = u.id and public.club_is_staff(ce.club_id))
        then (select count(*) from public.activities a join public.club_cup_members x on x.cup_id = u.id and x.user_id = a.user_id
               where a.validation_status = 'PENDING' and coalesce(a.status, '') <> 'DELETED'
                 and a.started_at >= u.start_at and a.started_at < u.end_at and public.club_is_staff(x.club_id)) end,
    -- Bài Strava của tôi đang ẩn → không được tính: nhắc bật "Hiện bài Strava"
    'my_strava_hidden', exists (select 1 from public.connected_accounts ca where ca.user_id = auth.uid() and ca.provider = 'STRAVA')
                        and not private.activity_shared(auth.uid(), 'STRAVA'))
$$;

create or replace function public.club_cup(p_cup_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare u public.club_cups;
begin
  perform private.match_tick(p_cup_id);
  u := (select x from public.club_cups x where x.id = p_cup_id);
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  return private.cup_json(u, true);
end $$;

-- Trang Thách đấu: chỉ giải nhiều CLB (trận 1–1 xem ở tab Đấu CLB của mỗi CLB)
create or replace function public.list_club_cups(p_scope text default 'ACTIVE') returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  if p_scope = 'REVIEW' and not public.is_system_admin() then raise exception 'FORBIDDEN'; end if;
  return (select coalesce(jsonb_agg(private.cup_json(x.cup, false) order by x.rn), '[]'::jsonb) from (
    select u as cup, row_number() over (order by
             case when p_scope = 'DONE' then extract(epoch from u.end_at) * -1 else extract(epoch from u.start_at) end) as rn
      from public.club_cups u
     where u.kind = 'CUP' and private.cup_visible(u)
       and case p_scope
             when 'ACTIVE' then u.status in ('OPEN', 'PROVISIONAL')
             when 'DONE' then u.status in ('FINISHED', 'CANCELLED')
             when 'REVIEW' then u.status = 'PENDING_REVIEW'
             else u.created_by = v_uid
               or exists (select 1 from public.club_cup_entries ce join public.club_members m on m.club_id = ce.club_id
                           where ce.cup_id = u.id and m.user_id = v_uid and m.status = 'APPROVED')
           end) x
   where x.rn <= 60);
end $$;

-- BXH VĐV của một CLB trong trận: người đã đăng ký (kể cả chưa chạy), km tính / km gốc, ngày, pace, giá trị đóng góp
create or replace function public.club_cup_club_board(p_cup_id uuid, p_club_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id);
  v_end timestamptz;
begin
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  if not exists (select 1 from public.club_cup_entries ce where ce.cup_id = u.id and ce.club_id = p_club_id) then raise exception 'CLUB_NOT_IN_CUP'; end if;
  v_end := least(u.end_at, greatest(now(), u.start_at));
  return jsonb_build_object(
    'club', private.club_brief(p_club_id),
    'measure', u.measure, 'format', u.format, 'top_n', u.top_n, 'pace_min_km', u.pace_min_km, 'daily_cap_km', u.daily_cap_km,
    'rows', (select coalesce(jsonb_agg(jsonb_build_object(
               'rank', t.rk, 'user_id', t.user_id, 'display_name', p.display_name, 'avatar_url', p.avatar_url,
               'km', round(t.km, 2), 'raw_km', round(t.raw_km, 2), 'runs', t.runs, 'days', t.days, 'moving_s', t.time_s,
               'pace_s', t.pace_s, 'qualified', t.qualified, 'value', round(t.val, 2),
               'counted', case when u.measure = 'PACE' then t.qualified and (u.format <> 'TOP' or t.rn_pace <= u.top_n)
                               when u.format = 'TOP' then t.rn_val <= u.top_n and t.runs > 0 else t.runs > 0 end)
             order by t.rk, p.display_name), '[]'::jsonb)
               from (select v.*, case when u.measure = 'PACE' then v.rn_pace else v.rn_val end as rk
                       from private.match_values(u, v_end) v where v.club_id = p_club_id) t
               join public.profiles p on p.id = t.user_id));
end $$;

-- Tổng quan đấu CLB của một CLB: điểm uy tín, thành tích, danh hiệu vô địch 7 ngày, trận đang diễn ra / chờ, trận gần đây
create or replace function public.club_match_summary(p_club_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare r record;
begin
  perform private.require_uid();
  if not exists (select 1 from public.clubs c where c.id = p_club_id) then raise exception 'CLUB_NOT_FOUND'; end if;
  for r in select x.id from public.club_cups x
            where (x.host_club_id = p_club_id or x.opponent_club_id = p_club_id
                   or exists (select 1 from public.club_cup_entries ce where ce.cup_id = x.id and ce.club_id = p_club_id))
              and x.status in ('INVITED', 'OPEN', 'PROVISIONAL') loop
    perform private.match_tick(r.id);
  end loop;
  return jsonb_build_object(
    'can_challenge', public.club_is_staff(p_club_id),
    'rating', (select jsonb_build_object('rating', g.rating, 'played', g.played, 'wins', g.wins, 'draws', g.draws, 'losses', g.losses,
                                         'streak', g.streak, 'best_streak', g.best_streak)
                 from public.club_match_ratings g where g.club_id = p_club_id),
    'rank', (select count(*) + 1 from public.club_match_ratings g
              where g.played > 0 and g.rating > coalesce((select h.rating from public.club_match_ratings h where h.club_id = p_club_id), 1000)),
    'champion', (select jsonb_build_object('cup_id', t.id, 'title', t.title, 'kind', t.kind, 'final_at', t.final_at,
                                           'until', t.final_at + interval '7 days')
                   from (select x.id, x.title, x.kind, x.final_at, row_number() over (order by x.final_at desc) as rn
                           from public.club_cups x
                          where x.status = 'FINISHED' and x.final_at > now() - interval '7 days'
                            and (x.result->>'winner_id') = p_club_id::text) t
                  where t.rn = 1),
    'active', (select coalesce(jsonb_agg(private.cup_json(x, true) order by x.start_at), '[]'::jsonb)
                 from public.club_cups x
                where (x.host_club_id = p_club_id or x.opponent_club_id = p_club_id
                       or exists (select 1 from public.club_cup_entries ce where ce.cup_id = x.id and ce.club_id = p_club_id))
                  and (x.status in ('OPEN', 'PROVISIONAL') or (x.status = 'INVITED' and private.cup_visible(x)))),
    'recent', (select coalesce(jsonb_agg(private.cup_json(t.x, false) order by t.ord desc), '[]'::jsonb)
                 from (select x, coalesce(x.final_at, x.settled_at, x.end_at) as ord,
                              row_number() over (order by coalesce(x.final_at, x.settled_at, x.end_at) desc) as rn
                         from public.club_cups x
                        where (x.host_club_id = p_club_id or x.opponent_club_id = p_club_id
                               or exists (select 1 from public.club_cup_entries ce where ce.cup_id = x.id and ce.club_id = p_club_id))
                          and x.status in ('FINISHED', 'DECLINED', 'EXPIRED', 'CANCELLED') and private.cup_visible(x)) t
                where t.rn <= 15));
end $$;

-- Trang chủ: các trận của các CLB tôi đang ở — cần đăng ký / đang đấu / kết quả tạm; lời mời chờ tôi (ban quản trị) trả lời
create or replace function public.my_club_matches() returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid(); r record;
begin
  for r in select x.id from public.club_cups x
            where x.status in ('INVITED', 'OPEN', 'PROVISIONAL')
              and (exists (select 1 from public.club_cup_entries ce join public.club_members m on m.club_id = ce.club_id
                            where ce.cup_id = x.id and m.user_id = v_uid and m.status = 'APPROVED')
                   or (x.status = 'INVITED' and public.club_is_staff(x.awaiting_club_id))) loop
    perform private.match_tick(r.id);
  end loop;
  return (select coalesce(jsonb_agg(private.cup_json(x, true) order by x.start_at), '[]'::jsonb)
            from public.club_cups x
           where (x.status in ('OPEN', 'PROVISIONAL')
                  and exists (select 1 from public.club_cup_entries ce join public.club_members m on m.club_id = ce.club_id
                               where ce.cup_id = x.id and m.user_id = v_uid and m.status = 'APPROVED'))
              or (x.status = 'INVITED' and x.awaiting_club_id is not null
                  and exists (select 1 from public.club_members m where m.club_id = x.awaiting_club_id and m.user_id = v_uid
                               and m.status = 'APPROVED' and m.role in ('OWNER', 'CAPTAIN'))));
end $$;

-- Bảng điểm uy tín đấu CLB (1–1) toàn hệ thống
create or replace function public.club_duel_ladder() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('rank', t.rk, 'club_id', c.id, 'name', c.name, 'avatar_url', c.avatar_url,
           'accent_color', c.accent_color, 'rating', t.rating, 'played', t.played, 'wins', t.wins, 'draws', t.draws,
           'losses', t.losses, 'streak', t.streak,
           'is_mine', exists (select 1 from public.club_members m where m.club_id = c.id and m.user_id = auth.uid() and m.status = 'APPROVED'))
         order by t.rk, c.name), '[]'::jsonb)
    from (select g.*, rank() over (order by g.rating desc) as rk from public.club_match_ratings g where g.played > 0) t
    join public.clubs c on c.id = t.club_id
   where t.rk <= 50
$$;

-- ---------------------------------------------------------------------
-- 6. Trận 1–1: tạo · nhận lời / từ chối / đề xuất lại · hủy
-- ---------------------------------------------------------------------
create or replace function public.create_club_duel(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_club uuid := nullif(p->>'club_id', '')::uuid;
  v_opp uuid := nullif(p->>'opponent_id', '')::uuid;
  v_id uuid := gen_random_uuid();
  t jsonb;
  v_a text; v_b text; v_msg text := nullif(left(trim(coalesce(p->>'message', '')), 200), '');
begin
  if v_club is null or not public.club_is_staff(v_club) then raise exception 'FORBIDDEN'; end if;
  v_a := (select c.name from public.clubs c where c.id = v_club);
  v_b := (select c.name from public.clubs c where c.id = v_opp);
  if v_opp is null or v_opp = v_club or v_b is null then raise exception 'INVALID_OPPONENT'; end if;
  t := private.match_terms(p, 'DUEL');
  if exists (select 1 from public.club_cups x
              where x.kind = 'DUEL' and x.status in ('INVITED', 'OPEN', 'PROVISIONAL')
                and ((x.host_club_id = v_club and x.opponent_club_id = v_opp) or (x.host_club_id = v_opp and x.opponent_club_id = v_club))) then
    raise exception 'BATTLE_EXISTS';
  end if;
  if (select count(*) from public.club_cups x where x.kind = 'DUEL' and x.host_club_id = v_club and x.created_at > now() - interval '1 day') >= 5 then
    raise exception 'RATE_LIMITED';
  end if;
  insert into public.club_cups (id, kind, rules_version, title, description, metric, start_at, end_at, reg_close_at, max_clubs,
                                host_club_id, opponent_club_id, created_by, status, require_signup, awaiting_club_id,
                                format, measure, top_n, min_roster, max_roster, daily_cap_km, share_cap_pct, pace_min_km, tiebreak,
                                lock_hours, roster_close_at, forfeit_rule, final_delay_hours, negotiation)
  values (v_id, 'DUEL', 2, left(v_a || ' vs ' || v_b, 120), v_msg,
          case when t->>'format' = 'TOTAL' then 'TOTAL_KM' else 'AVG_KM' end,
          (t->>'start_at')::timestamptz, (t->>'end_at')::timestamptz, (t->>'start_at')::timestamptz, 2,
          v_club, v_opp, v_uid, 'INVITED', true, v_opp,
          t->>'format', t->>'measure', (t->>'top_n')::int, (t->>'min_roster')::int, (t->>'max_roster')::int,
          (t->>'daily_cap_km')::numeric, (t->>'share_cap_pct')::int, (t->>'pace_min_km')::numeric, t->>'tiebreak',
          (t->>'lock_hours')::int, (t->>'roster_close_at')::timestamptz, t->>'forfeit_rule', 48,
          jsonb_build_array(jsonb_build_object('v', 1, 'club_id', v_club, 'by', v_uid, 'at', now(), 'action', 'PROPOSE', 'note', v_msg, 'terms', t)));
  perform private.notify_club(v_opp, true, 'CLUB_BATTLE', v_a || ' thách đấu CLB của bạn',
    coalesce(v_msg, 'Xem luật thi đấu rồi Nhận lời, Từ chối hoặc Đề xuất lại.'), '/cups/' || v_id, v_uid);
  return private.cup_json((select x from public.club_cups x where x.id = v_id), false);
end $$;

-- p_action: ACCEPT | DECLINE (p->>'note' = lý do, không bắt buộc) | COUNTER (p = điều khoản mới + note)
create or replace function public.respond_club_duel(p_cup_id uuid, p_action text, p jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id for update);
  v_act text := upper(coalesce(p_action, ''));
  v_note text := nullif(left(trim(coalesce(p->>'note', '')), 200), '');
  v_other uuid; t jsonb; v_me text; v_close text;
begin
  if u.id is null or u.kind <> 'DUEL' then raise exception 'CUP_NOT_FOUND'; end if;
  perform private.match_tick(u.id);
  u := (select x from public.club_cups x where x.id = p_cup_id);
  if u.status <> 'INVITED' then raise exception 'BATTLE_NOT_PENDING'; end if;
  if u.awaiting_club_id is null or not public.club_is_staff(u.awaiting_club_id) then raise exception 'FORBIDDEN'; end if;
  v_other := case when u.awaiting_club_id = u.host_club_id then u.opponent_club_id else u.host_club_id end;
  v_me := (select c.name from public.clubs c where c.id = u.awaiting_club_id);

  if v_act = 'ACCEPT' then
    update public.club_cups set status = 'OPEN', accepted_at = now(), awaiting_club_id = null,
           negotiation = negotiation || jsonb_build_array(jsonb_build_object('v', terms_version, 'club_id', u.awaiting_club_id, 'by', v_uid,
                                                                              'at', now(), 'action', 'ACCEPT', 'note', v_note))
     where id = u.id;
    -- Hai CLB vào trận; người đăng ký tính từ lúc tạo trận (chống "chiêu mộ" sau khi đã biết đối thủ)
    insert into public.club_cup_entries (cup_id, club_id, registered_by, registered_at)
    values (u.id, u.host_club_id, u.created_by, u.created_at), (u.id, u.opponent_club_id, v_uid, u.created_at)
    on conflict (cup_id, club_id) do nothing;
    v_close := to_char(u.roster_close_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM');
    perform private.notify_club(u.host_club_id, false, 'CLUB_BATTLE', '⚔ ' || u.title || ': đăng ký thi đấu!',
      'Đối thủ đã nhận lời. Bấm "Đăng ký thi đấu" trước ' || v_close || ' — chỉ người đăng ký mới được tính cho CLB.', '/cups/' || u.id, null);
    perform private.notify_club(u.opponent_club_id, false, 'CLUB_BATTLE', '⚔ ' || u.title || ': đăng ký thi đấu!',
      'CLB đã nhận lời. Bấm "Đăng ký thi đấu" trước ' || v_close || ' — chỉ người đăng ký mới được tính cho CLB.', '/cups/' || u.id, null);
  elsif v_act = 'DECLINE' then
    update public.club_cups set status = 'DECLINED', awaiting_club_id = null, decline_reason = v_note,
           negotiation = negotiation || jsonb_build_array(jsonb_build_object('v', terms_version, 'club_id', u.awaiting_club_id, 'by', v_uid,
                                                                              'at', now(), 'action', 'DECLINE', 'note', v_note))
     where id = u.id;
    perform private.notify_club(v_other, true, 'CLUB_BATTLE', v_me || ' đã từ chối lời thách đấu', coalesce('Lý do: ' || v_note, null), '/cups/' || u.id, v_uid);
  elsif v_act = 'COUNTER' then
    if u.terms_version >= 6 then raise exception 'TOO_MANY_COUNTERS'; end if;
    t := private.match_terms(p, 'DUEL');
    update public.club_cups set
           format = t->>'format', measure = t->>'measure', top_n = (t->>'top_n')::int, min_roster = (t->>'min_roster')::int,
           max_roster = (t->>'max_roster')::int, daily_cap_km = (t->>'daily_cap_km')::numeric, share_cap_pct = (t->>'share_cap_pct')::int,
           pace_min_km = (t->>'pace_min_km')::numeric, tiebreak = t->>'tiebreak', lock_hours = (t->>'lock_hours')::int,
           forfeit_rule = t->>'forfeit_rule', start_at = (t->>'start_at')::timestamptz, end_at = (t->>'end_at')::timestamptz,
           reg_close_at = (t->>'start_at')::timestamptz, roster_close_at = (t->>'roster_close_at')::timestamptz,
           metric = case when t->>'format' = 'TOTAL' then 'TOTAL_KM' else 'AVG_KM' end,
           terms_version = terms_version + 1, awaiting_club_id = v_other,
           negotiation = negotiation || jsonb_build_array(jsonb_build_object('v', terms_version + 1, 'club_id', u.awaiting_club_id, 'by', v_uid,
                                                                              'at', now(), 'action', 'COUNTER', 'note', v_note, 'terms', t))
     where id = u.id;
    perform private.notify_club(v_other, true, 'CLUB_BATTLE', v_me || ' đề xuất lại điều khoản "' || u.title || '"',
      coalesce(v_note, 'Xem điều khoản mới rồi Nhận lời, Từ chối hoặc Đề xuất lại.'), '/cups/' || u.id, v_uid);
  else
    raise exception 'INVALID_ACTION';
  end if;
  return private.cup_json((select x from public.club_cups x where x.id = u.id), true);
end $$;

-- Hủy: 1–1 → CLB thách đấu khi đang chờ trả lời; ban quản trị một trong hai CLB trước giờ bắt đầu. Nhiều CLB: như cũ. Admin: luôn (trừ khi đã có kết quả).
create or replace function public.cancel_club_cup(p_cup_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id);
  e record;
begin
  if u.id is null then raise exception 'CUP_NOT_FOUND'; end if;
  if not coalesce((private.cup_json(u, false)->>'can_cancel')::boolean, false) then
    if u.status in ('OPEN', 'PROVISIONAL') and now() >= u.start_at then raise exception 'CUP_STARTED'; end if;
    if u.status not in ('PENDING_REVIEW', 'INVITED', 'OPEN') then raise exception 'CUP_NOT_OPEN'; end if;
    raise exception 'FORBIDDEN';
  end if;
  update public.club_cups set status = 'CANCELLED', awaiting_club_id = null,
         cancel_reason = coalesce(cancel_reason, 'Hủy bởi ' || private.display_name(v_uid)) where id = u.id;
  for e in select x.club_id from (select ce.club_id from public.club_cup_entries ce where ce.cup_id = u.id
                                  union select u.host_club_id union select u.opponent_club_id) x where x.club_id is not null loop
    perform private.notify_club(e.club_id, u.status = 'INVITED', private.match_kind_note(u), '"' || u.title || '" đã hủy', null, '/cups/' || u.id, v_uid);
  end loop;
  return private.cup_json((select x from public.club_cups x where x.id = u.id), false);
end $$;

-- ---------------------------------------------------------------------
-- 7. Thách đấu nhiều CLB: tạo với luật mới (vẫn cần admin duyệt nếu người thường tạo)
-- ---------------------------------------------------------------------
create or replace function public.create_club_cup(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_id uuid := gen_random_uuid();
  v_host uuid := nullif(p->>'host_club_id', '')::uuid;
  v_admin boolean := public.is_system_admin();
  v_title text := trim(coalesce(p->>'title', ''));
  v_max integer := coalesce((p->>'max_clubs')::integer, 20);
  v_status text;
  v_name text := private.display_name(v_uid);
  t jsonb;
  v_close timestamptz;
  a record;
begin
  if char_length(v_title) < 3 or char_length(v_title) > 120 then raise exception 'INVALID_TITLE'; end if;
  -- Biểu mẫu cũ gửi "metric" → đổi sang hình thức mới
  t := private.match_terms(p || jsonb_build_object('format', coalesce(nullif(p->>'format', ''),
                                                   case when p->>'metric' = 'TOTAL_KM' then 'TOTAL' else 'AVG' end)), 'CUP');
  v_close := coalesce(nullif(p->>'reg_close_at', '')::timestamptz, (t->>'roster_close_at')::timestamptz);
  if v_close > (t->>'roster_close_at')::timestamptz then v_close := (t->>'roster_close_at')::timestamptz; end if;
  if v_close < now() then raise exception 'INVALID_REG_CLOSE'; end if;
  if v_max < 2 or v_max > 200 then raise exception 'INVALID_MAX'; end if;
  if v_host is not null and not public.club_is_staff(v_host) and not v_admin then raise exception 'FORBIDDEN'; end if;
  if (select count(*) from public.club_cups u where u.created_by = v_uid and u.created_at > now() - interval '1 day') >= 5 then
    raise exception 'RATE_LIMITED';
  end if;

  v_status := case when v_admin or v_host is not null then 'OPEN' else 'PENDING_REVIEW' end;
  insert into public.club_cups (id, kind, rules_version, title, description, prize, metric, start_at, end_at, reg_close_at, max_clubs,
                                host_club_id, created_by, status, reviewed_by, reviewed_at, require_signup,
                                format, measure, top_n, min_roster, max_roster, daily_cap_km, share_cap_pct, pace_min_km, tiebreak,
                                lock_hours, roster_close_at, forfeit_rule, final_delay_hours)
  values (v_id, 'CUP', 2, v_title, nullif(left(trim(coalesce(p->>'description', '')), 1000), ''), nullif(left(trim(coalesce(p->>'prize', '')), 200), ''),
          case when t->>'format' = 'TOTAL' then 'TOTAL_KM' else 'AVG_KM' end,
          (t->>'start_at')::timestamptz, (t->>'end_at')::timestamptz, v_close, v_max, v_host, v_uid, v_status,
          case when v_status = 'OPEN' then v_uid end, case when v_status = 'OPEN' then now() end, true,
          t->>'format', t->>'measure', (t->>'top_n')::int, (t->>'min_roster')::int, (t->>'max_roster')::int,
          (t->>'daily_cap_km')::numeric, (t->>'share_cap_pct')::int, (t->>'pace_min_km')::numeric, t->>'tiebreak',
          (t->>'lock_hours')::int, (t->>'roster_close_at')::timestamptz, 'FORFEIT', 48);

  if v_host is not null then
    insert into public.club_cup_entries (cup_id, club_id, registered_by) values (v_id, v_host, v_uid);
  end if;
  if v_status = 'PENDING_REVIEW' then
    for a in select pr.id from public.profiles pr where pr.role = 'SYSTEM_ADMIN' loop
      perform private.notify(a.id, null, 'CLUB_CUP', 'Thách đấu CLB chờ duyệt: ' || v_title,
        v_name || ' vừa tạo. Vào Quản trị → Thách đấu để duyệt.', '/cups/' || v_id, v_uid, true);
    end loop;
  end if;
  return private.cup_json((select u from public.club_cups u where u.id = v_id), false);
end $$;

-- Ban quản trị đăng ký CLB vào giải nhiều CLB (trận 1–1 có sẵn hai CLB)
create or replace function public.join_club_cup(p_cup_id uuid, p_club_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id for update);
  v_club text := (select c.name from public.clubs c where c.id = p_club_id);
begin
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  if u.kind <> 'CUP' then raise exception 'NOT_A_CUP'; end if;
  if v_club is null then raise exception 'CLUB_NOT_FOUND'; end if;
  if not public.club_is_staff(p_club_id) then raise exception 'CLUB_STAFF_REQUIRED'; end if;
  if u.status <> 'OPEN' then raise exception 'CUP_NOT_OPEN'; end if;
  if now() > u.reg_close_at then raise exception 'REGISTRATION_CLOSED'; end if;
  if exists (select 1 from public.club_cup_entries ce where ce.cup_id = u.id and ce.club_id = p_club_id) then raise exception 'ALREADY_JOINED'; end if;
  if (select count(*) from public.club_cup_entries ce where ce.cup_id = u.id) >= u.max_clubs then raise exception 'CUP_FULL'; end if;
  insert into public.club_cup_entries (cup_id, club_id, registered_by) values (u.id, p_club_id, v_uid);
  perform private.notify_club(p_club_id, false, 'CLUB_CUP', v_club || ' tham gia "' || u.title || '": đăng ký thi đấu!',
    case when coalesce(u.require_signup, false)
         then 'Bấm "Đăng ký thi đấu" trước ' || to_char(coalesce(u.roster_close_at, u.end_at) at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM')
              || ' — chỉ người đăng ký mới được tính cho CLB.'
         else 'Mọi km hợp lệ từ ' || to_char(u.start_at at time zone 'Asia/Ho_Chi_Minh', 'DD/MM HH24:MI') || ' đều tính cho CLB. Chạy thôi!' end,
    '/cups/' || u.id, v_uid);
  if u.created_by is not null and u.created_by <> v_uid then
    perform private.notify(u.created_by, null, 'CLUB_CUP', v_club || ' đã đăng ký "' || u.title || '"', null, '/cups/' || u.id, v_uid, false);
  end if;
  return private.cup_json((select x from public.club_cups x where x.id = u.id), true);
end $$;

create or replace function public.leave_club_cup(p_cup_id uuid, p_club_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id);
begin
  perform private.require_uid();
  if u.id is null then raise exception 'CUP_NOT_FOUND'; end if;
  if u.kind <> 'CUP' then raise exception 'NOT_A_CUP'; end if;
  if not public.club_is_staff(p_club_id) then raise exception 'CLUB_STAFF_REQUIRED'; end if;
  if now() >= coalesce(u.roster_close_at, u.start_at) then raise exception 'CUP_STARTED'; end if;
  delete from public.club_cup_members where cup_id = u.id and club_id = p_club_id;
  delete from public.club_cup_entries where cup_id = u.id and club_id = p_club_id;
  return private.cup_json((select x from public.club_cups x where x.id = u.id), true);
end $$;

-- ---------------------------------------------------------------------
-- 8. Thành viên đăng ký thi đấu
-- ---------------------------------------------------------------------
create or replace function public.join_cup_as_member(p_cup_id uuid, p_club_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id);
  v_mine uuid;
  v_joined timestamptz;
begin
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  if u.status <> 'OPEN' or now() >= u.end_at then raise exception 'CUP_NOT_OPEN'; end if;
  if u.rules_version is not null and now() >= u.roster_close_at then raise exception 'ROSTER_LOCKED'; end if;
  if not exists (select 1 from public.club_cup_entries ce where ce.cup_id = u.id and ce.club_id = p_club_id) then raise exception 'CLUB_NOT_IN_CUP'; end if;
  v_joined := (select m.joined_at from public.club_members m where m.club_id = p_club_id and m.user_id = v_uid and m.status = 'APPROVED');
  if not exists (select 1 from public.club_members m where m.club_id = p_club_id and m.user_id = v_uid and m.status = 'APPROVED') then
    raise exception 'NOT_A_MEMBER';
  end if;
  if u.rules_version is not null and v_joined is not null and v_joined > private.match_cutoff(u, p_club_id) then
    raise exception 'JOINED_CLUB_TOO_LATE';
  end if;
  v_mine := (select cm.club_id from public.club_cup_members cm where cm.cup_id = u.id and cm.user_id = v_uid);
  if v_mine = p_club_id then return private.cup_json(u, true); end if;
  if v_mine is not null then raise exception 'ALREADY_SIGNED_UP'; end if;
  if u.max_roster is not null and (select count(*) from public.club_cup_members x where x.cup_id = u.id and x.club_id = p_club_id) >= u.max_roster then
    raise exception 'ROSTER_FULL';
  end if;
  insert into public.club_cup_members (cup_id, user_id, club_id) values (u.id, v_uid, p_club_id);
  return private.cup_json(u, true);
end $$;

create or replace function public.leave_cup_as_member(p_cup_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid(); u public.club_cups := (select x from public.club_cups x where x.id = p_cup_id);
begin
  if u.id is null or not private.cup_visible(u) then raise exception 'CUP_NOT_FOUND'; end if;
  if u.rules_version is not null and now() >= u.roster_close_at then raise exception 'ROSTER_LOCKED'; end if;
  if now() >= u.start_at then raise exception 'CUP_STARTED'; end if;
  delete from public.club_cup_members where cup_id = u.id and user_id = v_uid;
  return private.cup_json(u, true);
end $$;

-- ---------------------------------------------------------------------
-- 9. Chuyển trận "CLB đấu CLB" cũ (club_battles) sang thách đấu 1–1 — giữ id, giữ cách tính cũ (mọi thành viên, km)
-- ---------------------------------------------------------------------
insert into public.club_cups (id, kind, legacy_battle_id, rules_version, title, description, metric, format, measure,
                              start_at, end_at, reg_close_at, max_clubs, host_club_id, opponent_club_id, created_by, status,
                              require_signup, awaiting_club_id, final_delay_hours, accepted_at, settled_at, final_at, created_at, daily_cap_km)
select b.id, 'DUEL', b.id, null, left(ca.name || ' vs ' || co.name, 120), b.message, b.metric,
       case when b.metric = 'TOTAL_KM' then 'TOTAL' else 'AVG' end, 'KM',
       b.start_at, b.end_at, b.start_at, 2, b.challenger_id, b.opponent_id, b.created_by,
       case b.status when 'PENDING' then 'INVITED' when 'ACCEPTED' then 'OPEN' else b.status end,
       false, case when b.status = 'PENDING' then b.opponent_id end, 2, b.responded_at, b.settled_at, b.settled_at, b.created_at, null
  from public.club_battles b
  join public.clubs ca on ca.id = b.challenger_id
  join public.clubs co on co.id = b.opponent_id
on conflict (id) do nothing;

insert into public.club_cup_entries (cup_id, club_id, registered_by, registered_at)
select b.id, x.club_id, b.created_by, b.created_at
  from public.club_battles b
  cross join lateral (values (b.challenger_id), (b.opponent_id)) as x(club_id)
 where b.status in ('ACCEPTED', 'FINISHED') and exists (select 1 from public.club_cups u where u.id = b.id)
on conflict (cup_id, club_id) do nothing;

-- Kết quả trận cũ đã xong: bảng điểm theo engine mới (cùng cách tính cũ) + người thắng đã công bố
update public.club_cups u set result = jsonb_build_object('standings', private.match_standings(u, u.end_at),
                                                          'winner_id', b.winner_id, 'mvp', null, 'final', true, 'legacy', true)
  from public.club_battles b
 where b.id = u.id and u.legacy_battle_id is not null and u.status = 'FINISHED' and u.result is null;

-- Hàm cũ: không tạo trận kiểu cũ nữa (app mới dùng create_club_duel); danh sách cũ trả rỗng; cron cũ không làm gì
create or replace function public.create_club_battle(p_club_id uuid, p_opponent_id uuid, p_metric text,
                                                     p_start timestamptz, p_end timestamptz, p_message text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
begin raise exception 'FEATURE_MOVED'; end $$;
create or replace function public.respond_club_battle(p_battle_id uuid, p_accept boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
begin raise exception 'FEATURE_MOVED'; end $$;
create or replace function public.cancel_club_battle(p_battle_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
begin raise exception 'FEATURE_MOVED'; end $$;
create or replace function public.club_battles_of(p_club_id uuid) returns jsonb
language sql stable security definer set search_path = public as $$ select '[]'::jsonb $$;
create or replace function public.settle_due_club_battles() returns integer
language sql security definer set search_path = public as $$ select 0 $$;

-- ---------------------------------------------------------------------
-- 10. Quyền
-- ---------------------------------------------------------------------
revoke all on function private.match_kind_note(public.club_cups), private.match_cutoff(public.club_cups, uuid), private.fmt_pace(numeric),
  private.match_score_text(public.club_cups, numeric), private.match_terms(jsonb, text), private.match_terms_of(public.club_cups),
  private.match_runner_rows(uuid, timestamptz, timestamptz, numeric), private.match_values(public.club_cups, timestamptz),
  private.match_standings(public.club_cups, timestamptz), private.match_mvp(public.club_cups, timestamptz),
  private.match_phase(public.club_cups), private.match_badge(uuid, text, text), private.match_elo(uuid, uuid, numeric),
  private.match_finalize(uuid), private.match_tick(uuid), private.club_brief(uuid) from public, anon, authenticated;
revoke all on function public.create_club_duel(jsonb), public.respond_club_duel(uuid, text, jsonb), public.club_match_summary(uuid),
  public.my_club_matches(), public.club_duel_ladder(), public.club_cup_club_board(uuid, uuid) from public, anon;
grant execute on function public.create_club_duel(jsonb), public.respond_club_duel(uuid, text, jsonb), public.club_match_summary(uuid),
  public.my_club_matches(), public.club_duel_ladder(), public.club_cup_club_board(uuid, uuid) to authenticated;
revoke all on function public.settle_due_club_cups(), public.settle_due_club_battles() from public, anon, authenticated;
grant execute on function public.settle_due_club_cups(), public.settle_due_club_battles() to service_role;

notify pgrst, 'reload schema';

