  check (context in ('NEARBY', 'CONNECTION', 'CLUB', 'BIB', 'MARKET', 'OTHER', 'DM', 'COMMENT', 'PROFILE', 'HUB'));

-- ---------------------------------------------------------------------
-- 2. Hàm phụ
-- ---------------------------------------------------------------------
-- 34 tỉnh / thành (giữ đồng bộ với shared/lib/provinces.ts)
create or replace function private.vn_provinces() returns text[]
language sql immutable as $$
  select array['Hà Nội', 'TP. Hồ Chí Minh', 'Hải Phòng', 'Đà Nẵng', 'Huế', 'Cần Thơ',
    'An Giang', 'Bắc Ninh', 'Cà Mau', 'Cao Bằng', 'Đắk Lắk', 'Điện Biên', 'Đồng Nai', 'Đồng Tháp', 'Gia Lai', 'Hà Tĩnh',
    'Hưng Yên', 'Khánh Hòa', 'Lai Châu', 'Lâm Đồng', 'Lạng Sơn', 'Lào Cai', 'Nghệ An', 'Ninh Bình', 'Phú Thọ', 'Quảng Ngãi',
    'Quảng Ninh', 'Quảng Trị', 'Sơn La', 'Tây Ninh', 'Thái Nguyên', 'Thanh Hóa', 'Tuyên Quang', 'Vĩnh Long']
$$;

-- Ô ~2 km (0,02°) — thô hơn ô vị trí tạm (0,01°) vì suy ra từ nơi xuất phát, thường là gần nhà
create or replace function private.home_cell(v numeric) returns numeric
language sql immutable as $$ select (round(v / 0.02) * 0.02)::numeric(6, 2) $$;

-- Không chèn link / số điện thoại / Zalo vào bài đăng, lời mời (chống lừa đảo, kéo ra ngoài)
create or replace function private.has_contact_or_link(p text) returns boolean
language sql immutable as $$
  select coalesce(p, '') ~* '(https?://|www\.|\.com|\.vn|\.net|zalo|telegram|t\.me|fb\.com|facebook)'
      or regexp_replace(coalesce(p, ''), '[\s\.\-]', '', 'g') ~ '(\+?84|0)\d{9}'
$$;

-- Tính lại khu hay chạy: ô có nhiều bài xuất phát nhất trong 60 ngày (≥ 2 bài), bài hợp lệ
create or replace function private.refresh_home_area(p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_on boolean := coalesce((select s.auto_area and s.enabled and s.suspended_at is null from public.runner_discovery_settings s where s.user_id = p_user), false);
  v_best jsonb;
begin
  if not v_on then
    delete from public.runner_home_area where user_id = p_user;
    return;
  end if;
  v_best := (select to_jsonb(x) from (
      select private.home_cell(d.start_lat) as la, private.home_cell(d.start_lng) as ln, count(*)::int as n, max(a.started_at) as last_at,
             row_number() over (order by count(*) desc, max(a.started_at) desc) as rn
        from public.activities a join public.activity_details d on d.activity_id = a.id
       where a.user_id = p_user and a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED'
         and a.started_at > now() - interval '60 days' and d.start_lat is not null and d.start_lng is not null
         and d.start_lat between -90 and 90 and d.start_lng between -180 and 180
       group by 1, 2) x where x.rn = 1);
  if v_best is null or (v_best->>'n')::int < 2 then
    delete from public.runner_home_area where user_id = p_user;
    return;
  end if;
  insert into public.runner_home_area as h (user_id, cell_lat, cell_lng, runs, last_run_at, updated_at)
  values (p_user, (v_best->>'la')::numeric, (v_best->>'ln')::numeric, (v_best->>'n')::int, (v_best->>'last_at')::timestamptz, now())
  on conflict (user_id) do update set cell_lat = excluded.cell_lat, cell_lng = excluded.cell_lng, runs = excluded.runs,
    last_run_at = excluded.last_run_at, updated_at = now();
end $$;

-- Bài mới / bài được duyệt / có toạ độ xuất phát → cập nhật khu hay chạy (không bao giờ chặn việc lưu bài)
create or replace function private.home_area_on_activity() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_user uuid;
begin
  -- Tách nhánh: mỗi bảng có cột khác nhau (new.user_id / new.activity_id)
  if tg_table_name = 'activities' then
    v_user := new.user_id;
  else
    v_user := (select a.user_id from public.activities a where a.id = new.activity_id);
  end if;
  if v_user is not null and exists (select 1 from public.runner_discovery_settings s where s.user_id = v_user and s.auto_area) then
    begin
      perform private.refresh_home_area(v_user);
    exception when others then null;
    end;
  end if;
  return null;
end $$;

drop trigger if exists home_area_activity_trg on public.activities;
create trigger home_area_activity_trg after update of validation_status on public.activities
  for each row when (new.validation_status is distinct from old.validation_status) execute function private.home_area_on_activity();
drop trigger if exists home_area_detail_trg on public.activity_details;
create trigger home_area_detail_trg after insert or update of start_lat, start_lng on public.activity_details
  for each row execute function private.home_area_on_activity();

-- Vị trí dùng cho Quanh đây của mọi người: vị trí tạm còn hạn (LIVE), không có thì khu hay chạy (HOME)
create or replace function private.nearby_locations() returns table (user_id uuid, cell_lat numeric, cell_lng numeric, area_label text, kind text)
language sql stable security definer set search_path = public as $$
  select p.user_id, p.cell_lat, p.cell_lng, p.area_label, 'LIVE' from public.runner_location_presence p where p.expires_at > now()
  union all
  select h.user_id, h.cell_lat, h.cell_lng, null, 'HOME'
    from public.runner_home_area h join public.runner_discovery_settings s on s.user_id = h.user_id
   where s.auto_area and s.enabled and s.suspended_at is null
     and not exists (select 1 from public.runner_location_presence p where p.user_id = h.user_id and p.expires_at > now())
$$;

-- Vị trí của một người: {lat, lng, kind, area} hoặc null
create or replace function private.nearby_cell(p_user uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('lat', l.cell_lat, 'lng', l.cell_lng, 'kind', l.kind, 'area', l.area_label)
    from private.nearby_locations() l where l.user_id = p_user
$$;

-- Số liệu công khai của runner (chỉ bài hợp lệ, ĐÃ CHIA SẺ)
create or replace function private.runner_stats(p_user uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'km_30d', round(coalesce(sum(a.distance_m) filter (where a.started_at > now() - interval '30 days'), 0) / 1000.0, 1),
    'runs_30d', count(*) filter (where a.started_at > now() - interval '30 days'),
    'km_year', round(coalesce(sum(a.distance_m) filter (where a.started_at > now() - interval '365 days'), 0) / 1000.0),
    'longest_km', round(coalesce(max(a.distance_m) filter (where a.started_at > now() - interval '365 days'), 0) / 1000.0, 1),
    'last_run_at', max(a.started_at))
    from public.activities a
   where a.user_id = p_user and a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED' and a.shared
$$;

-- Thành tích ước tính 12 tháng: bài dài ≥ cự ly, quy pace trung bình về cự ly đó (luôn ≥ thực tế → không "nổ" thành tích)
create or replace function private.runner_prs(p_user uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  with r as (
    select a.distance_m::numeric as d, a.moving_time_s::numeric as t from public.activities a
     where a.user_id = p_user and a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED' and a.shared
       and a.started_at > now() - interval '365 days' and a.distance_m > 0 and a.moving_time_s > 0
       and a.moving_time_s / (a.distance_m / 1000.0) >= 150)
  select jsonb_strip_nulls(jsonb_build_object(
    '5K', (select round(min(t * 5000 / d))::int from r where d >= 5000),
    '10K', (select round(min(t * 10000 / d))::int from r where d >= 10000),
    'HM', (select round(min(t * 21097 / d))::int from r where d >= 21097),
    'FM', (select round(min(t * 42195 / d))::int from r where d >= 42195)))
$$;

-- Điểm hợp nhau (0–100): pace 30 · tỉnh 15 · mục tiêu 15 · khung giờ 15 · mục đích 10 · còn chạy đều 10 · ngẫu nhiên theo ngày ≤ 5
create or replace function private.match_score(p_my_pace integer, p_pace integer, me public.runner_discovery_settings, o public.runner_discovery_settings,
  p_last_run timestamptz) returns integer
language sql stable as $$
  select round(
      (case when p_pace is null or p_my_pace is null then 12 else greatest(0, 30 - greatest(0, abs(p_pace - p_my_pace) - 20) * 30 / 70.0) end)
    + (case when me.province is not null and me.province = o.province then 15 else 0 end)
    + least(15, 8 * cardinality(array(select unnest(o.goals) intersect select unnest(coalesce(me.goals, '{}'::text[])))))
    + least(15, 8 * cardinality(array(select unnest(o.time_slots) intersect select unnest(coalesce(me.time_slots, '{}'::text[])))))
    + (case when o.purposes && coalesce(me.purposes, array['BUDDY']) then 10 else 3 end)
    + (case when p_last_run > now() - interval '7 days' then 10 when p_last_run > now() - interval '30 days' then 5 else 0 end)
    + (abs(hashtext(o.user_id::text || current_date::text)) % 5))::int
$$;

-- Người dùng có trong Hội quán không (tự tham gia, đủ điều kiện, không bị khoá)
create or replace function private.hub_member(p_user uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.runner_discovery_settings s where s.user_id = p_user and s.hub_listed and s.suspended_at is null)
     and private.nearby_eligible(p_user)
$$;

-- ---------------------------------------------------------------------
-- 3. Cài đặt (mở rộng 006100)
-- ---------------------------------------------------------------------
create or replace function public.my_discovery() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  s public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = v_uid);
  p public.runner_location_presence := (select x from public.runner_location_presence x where x.user_id = v_uid);
  h public.runner_home_area := (select x from public.runner_home_area x where x.user_id = v_uid);
begin
  return jsonb_build_object(
    'enabled', coalesce(s.enabled, false) and s.suspended_at is null,
    'suspended', s.suspended_at is not null,
    'visible_to', coalesce(s.visible_to, 'VERIFIED'), 'purposes', coalesce(to_jsonb(s.purposes), '["BUDDY"]'::jsonb),
    'goals', coalesce(to_jsonb(s.goals), '[]'::jsonb), 'time_slots', coalesce(to_jsonb(s.time_slots), '[]'::jsonb),
    'share_pace', coalesce(s.share_pace, true), 'radius_km', coalesce(s.radius_km, 10), 'bio', s.bio,
    'consented', s.consent_version = private.nearby_consent_version(),
    'valid_runs', private.valid_runs(v_uid), 'eligible', private.nearby_eligible(v_uid),
    'pace_s', private.typical_pace(v_uid),
    'presence', case when p.user_id is not null and p.expires_at > now() then jsonb_build_object(
      'source', p.source, 'area_label', p.area_label, 'updated_at', p.updated_at, 'expires_at', p.expires_at,
      'moves_left', greatest(0, 3 - case when p.moves_since > now() - interval '24 hours' then p.moves else 0 end)) end,
    'auto_area', coalesce(s.auto_area, false),
    'home', case when h.user_id is not null then jsonb_build_object('runs', h.runs, 'last_run_at', h.last_run_at, 'updated_at', h.updated_at) end,
    'located', private.nearby_cell(v_uid) is not null,
    'hub_listed', coalesce(s.hub_listed, false), 'province', s.province, 'headline', s.headline,
    'incoming', (select count(*) from public.runner_connection_requests r where r.to_id = v_uid and r.status = 'PENDING'),
    'connections', (select count(*) from public.runner_connections c where c.user_a = v_uid or c.user_b = v_uid));
end $$;

-- p: như 006100 + {auto_area, auto_consent, hub_listed, hub_consent, province, headline}
create or replace function public.set_discovery(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  s public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = v_uid);
  v_enabled boolean := coalesce((p->>'enabled')::boolean, s.enabled, false);
  v_vis text := coalesce(p->>'visible_to', s.visible_to, 'VERIFIED');
  v_radius integer := coalesce((p->>'radius_km')::int, s.radius_km, 10);
  v_purposes text[] := coalesce((select array_agg(x) from jsonb_array_elements_text(case when jsonb_typeof(p->'purposes') = 'array' then p->'purposes' end) x), s.purposes, array['BUDDY']);
  v_goals text[] := coalesce((select array_agg(x) from jsonb_array_elements_text(case when jsonb_typeof(p->'goals') = 'array' then p->'goals' end) x), s.goals, '{}');
  v_slots text[] := coalesce((select array_agg(x) from jsonb_array_elements_text(case when jsonb_typeof(p->'time_slots') = 'array' then p->'time_slots' end) x), s.time_slots, '{}');
  v_consent text := case when coalesce((p->>'consent')::boolean, false) then private.nearby_consent_version() else s.consent_version end;
  v_auto boolean := coalesce((p->>'auto_area')::boolean, s.auto_area, false);
  v_hub boolean := coalesce((p->>'hub_listed')::boolean, s.hub_listed, false);
  v_province text := case when p ? 'province' then nullif(trim(coalesce(p->>'province', '')), '') else s.province end;
  v_headline text := case when p ? 'headline' then nullif(left(trim(coalesce(p->>'headline', '')), 80), '') else s.headline end;
  v_auto_at timestamptz := s.auto_area_at;
  v_hub_at timestamptz := s.hub_consent_at;
begin
  if v_vis not in ('VERIFIED', 'SAME_GENDER', 'CLUBS') then raise exception 'INVALID_SETTINGS'; end if;
  if v_radius not in (2, 5, 10, 20) then raise exception 'INVALID_SETTINGS'; end if;
  if not (v_purposes <@ array['BUDDY', 'CLUB', 'COACH']) or not (v_goals <@ array['5K', '10K', 'HM', 'FM', 'TRAIL'])
     or not (v_slots <@ array['EARLY', 'MORNING', 'NOON', 'EVENING', 'WEEKEND']) then raise exception 'INVALID_SETTINGS'; end if;
  if v_province is not null and not (v_province = any (private.vn_provinces())) then raise exception 'INVALID_SETTINGS'; end if;
  if private.has_contact_or_link(v_headline) or private.has_contact_or_link(case when p ? 'bio' then p->>'bio' end) then raise exception 'NO_LINKS'; end if;
  if v_enabled then
    if coalesce(v_consent, '') <> private.nearby_consent_version() then raise exception 'CONSENT_REQUIRED'; end if;
    if not private.nearby_eligible(v_uid) then raise exception 'NOT_ELIGIBLE'; end if;
    if s.suspended_at is not null then raise exception 'NEARBY_SUSPENDED'; end if;
  end if;
  -- Khu hay chạy tự động: phải đồng ý riêng lần bật đầu tiên; chỉ có tác dụng khi Quanh đây đang bật
  if v_auto and not coalesce(s.auto_area, false) then
    if not coalesce((p->>'auto_consent')::boolean, false) then raise exception 'CONSENT_REQUIRED'; end if;
    v_auto_at := now();
  end if;
  -- Hội quán: đồng ý riêng (hồ sơ hiện toàn quốc) + đủ điều kiện
  if v_hub and not coalesce(s.hub_listed, false) then
    if not coalesce((p->>'hub_consent')::boolean, false) then raise exception 'CONSENT_REQUIRED'; end if;
    if not private.nearby_eligible(v_uid) then raise exception 'NOT_ELIGIBLE'; end if;
    if s.suspended_at is not null then raise exception 'NEARBY_SUSPENDED'; end if;
    v_hub_at := now();
  end if;
  insert into public.runner_discovery_settings as t (user_id, enabled, visible_to, purposes, goals, time_slots, share_pace, radius_km, bio,
                                                     consent_version, consent_at, auto_area, auto_area_at, hub_listed, hub_consent_at,
                                                     province, headline, updated_at)
  values (v_uid, v_enabled, v_vis, v_purposes, v_goals, v_slots, coalesce((p->>'share_pace')::boolean, s.share_pace, true), v_radius,
          case when p ? 'bio' then nullif(left(trim(coalesce(p->>'bio', '')), 140), '') else s.bio end,
          v_consent, case when v_consent is distinct from s.consent_version then now() else s.consent_at end,
          v_auto, v_auto_at, v_hub, v_hub_at, v_province, v_headline, now())
  on conflict (user_id) do update set enabled = excluded.enabled, visible_to = excluded.visible_to, purposes = excluded.purposes,
    goals = excluded.goals, time_slots = excluded.time_slots, share_pace = excluded.share_pace, radius_km = excluded.radius_km,
    bio = excluded.bio, consent_version = excluded.consent_version, consent_at = excluded.consent_at,
    auto_area = excluded.auto_area, auto_area_at = excluded.auto_area_at, hub_listed = excluded.hub_listed,
    hub_consent_at = excluded.hub_consent_at, province = excluded.province, headline = excluded.headline, updated_at = now();
  -- Tắt = xoá vị trí ngay; bật / tắt khu hay chạy = tính lại / xoá ngay
  if not v_enabled then delete from public.runner_location_presence where user_id = v_uid; end if;
  perform private.refresh_home_area(v_uid);
  -- Rời Hội quán = đóng các bài đang mở
  if not v_hub then update public.hub_posts set status = 'CLOSED' where author_id = v_uid and status = 'ACTIVE'; end if;
  return public.my_discovery();
end $$;

-- ---------------------------------------------------------------------
-- 4. Tìm runner quanh đây — dùng vị trí tạm HOẶC khu hay chạy (của cả mình và người khác)
-- ---------------------------------------------------------------------
create or replace function public.nearby_runners(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  s public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = v_uid);
  me jsonb := private.nearby_cell(v_uid);
  v_lat numeric := (me->>'lat')::numeric;
  v_lng numeric := (me->>'lng')::numeric;
  v_radius integer := coalesce((p->>'radius_km')::int, s.radius_km, 10);
  v_pace text := upper(coalesce(p->>'pace', 'ALL'));
  v_purpose text := nullif(nullif(upper(coalesce(p->>'purpose', '')), ''), 'ALL');
  v_goal text := nullif(nullif(upper(coalesce(p->>'goal', '')), ''), 'ALL');
  v_slot text := nullif(nullif(upper(coalesce(p->>'slot', '')), ''), 'ALL');
  v_offset integer := greatest(0, coalesce((p->>'offset')::int, 0));
  v_my_pace integer := private.typical_pace(v_uid);
  v_dlat numeric;
  v_dlng numeric;
begin
  if not coalesce(s.enabled, false) or s.suspended_at is not null then raise exception 'NEARBY_DISABLED'; end if;
  if me is null then raise exception 'NO_PRESENCE'; end if;
  if v_radius not in (2, 5, 10, 20) then v_radius := 10; end if;
  if (select count(*) from public.runner_nearby_searches x where x.user_id = v_uid and x.created_at > now() - interval '1 hour') >= 60 then
    raise exception 'TOO_MANY_SEARCHES';
  end if;
  insert into public.runner_nearby_searches (user_id) values (v_uid);
  delete from public.runner_nearby_searches where created_at < now() - interval '7 days';
  delete from public.runner_location_presence where expires_at < now() - interval '1 day';
  v_dlat := v_radius / 111.0 + 0.02;
  v_dlng := v_radius / (111.0 * greatest(cos(radians(v_lat::float8)), 0.2)) + 0.02;

  return (
    with cand as (
      select o.user_id as id, ds, o.area_label, o.kind, private.cell_km(v_lat, v_lng, o.cell_lat, o.cell_lng) as km,
             case when ds.share_pace then private.typical_pace(o.user_id) end as pace,
             (select max(a.started_at) from public.activities a where a.user_id = o.user_id and a.validation_status = 'APPROVED'
                 and coalesce(a.status, '') <> 'DELETED' and a.shared) as last_run
        from private.nearby_locations() o
        join public.runner_discovery_settings ds on ds.user_id = o.user_id
       where o.user_id <> v_uid and ds.enabled and ds.suspended_at is null
         and o.cell_lat between v_lat - v_dlat and v_lat + v_dlat
         and o.cell_lng between v_lng - v_dlng and v_lng + v_dlng
         and not private.is_blocked(v_uid, o.user_id)
         and private.nearby_visible(v_uid, o.user_id, ds.visible_to)      -- họ cho mình thấy
         and private.nearby_visible(o.user_id, v_uid, s.visible_to)       -- mình cho họ thấy (công bằng 2 chiều)
         and private.nearby_eligible(o.user_id)
    ), f as (
      select c.*,
        private.share_club(v_uid, c.id) as clubs,
        (select count(*) from public.runner_connections a join public.runner_connections b
            on (b.user_a = case when a.user_a = v_uid then a.user_b else a.user_a end or b.user_b = case when a.user_a = v_uid then a.user_b else a.user_a end)
           where (a.user_a = v_uid or a.user_b = v_uid) and (b.user_a = c.id or b.user_b = c.id)) as mutual
        from cand c
       where c.km <= v_radius
         and (v_pace = 'ALL' or (v_pace = 'UNKNOWN' and c.pace is null)
              or (v_pace = 'FAST' and c.pace < 330) or (v_pace = 'MID' and c.pace between 330 and 420) or (v_pace = 'EASY' and c.pace > 420))
         and (v_purpose is null or v_purpose = any((c.ds).purposes))
         and (v_goal is null or v_goal = any((c.ds).goals))
         and (v_slot is null or v_slot = any((c.ds).time_slots))
    ), sc as (
      select f.*,
        -- pace 30 · khung giờ 20 · mục tiêu 15 · mục đích 10 · cộng đồng 15 · khoảng cách 10 · còn chạy đều 5
        (case when f.pace is null or v_my_pace is null then 12 else greatest(0, 30 - greatest(0, abs(f.pace - v_my_pace) - 20) * 30 / 70.0) end
         + least(20, 10 * cardinality(array(select unnest((f.ds).time_slots) intersect select unnest(s.time_slots))))
         + least(15, 8 * cardinality(array(select unnest((f.ds).goals) intersect select unnest(s.goals))))
         + case when 'BUDDY' = any((f.ds).purposes) and 'BUDDY' = any(s.purposes) then 10 else 3 end
         + least(15, 10 * least(f.clubs, 1) + 3 * f.mutual)
         + case when f.km < 2 then 10 when f.km < 5 then 8 when f.km < 10 then 5 else 2 end
         + case when f.last_run > now() - interval '7 days' then 5 else 0 end
         + (abs(hashtext(f.id::text || current_date::text)) % 5)) as score
        from f
    )
    select jsonb_build_object('items', coalesce(jsonb_agg(y.x order by y.rn), '[]'::jsonb),
      'total', (select count(*) from sc), 'nearby_total', (select count(*) from cand), 'my_kind', me->>'kind')
      from (
        select row_number() over (order by sc.score desc, sc.id) as rn, jsonb_build_object(
          'id', sc.id, 'name', private.first_name(sc.id),
          'avatar_url', (select avatar_url from public.profiles where id = sc.id),
          'level', (select level from public.profiles where id = sc.id),
          'km', private.shown_km(sc.km, v_uid, sc.id), 'area_label', sc.area_label, 'where', sc.kind,
          'last_run_days', case when sc.last_run is not null then greatest(0, (current_date - (sc.last_run at time zone 'Asia/Ho_Chi_Minh')::date)) end,
          'pace_s', sc.pace, 'goals', to_jsonb((sc.ds).goals), 'time_slots', to_jsonb((sc.ds).time_slots),
          'purposes', to_jsonb((sc.ds).purposes), 'bio', (sc.ds).bio, 'clubs', sc.clubs, 'mutual', sc.mutual,
          'hub', (sc.ds).hub_listed,
          'score', round(sc.score), 'connection',
            case when private.are_connected(v_uid, sc.id) then 'CONNECTED'
                 when exists (select 1 from public.runner_connection_requests r where r.from_id = v_uid and r.to_id = sc.id and r.status = 'PENDING') then 'PENDING_OUT'
                 when exists (select 1 from public.runner_connection_requests r where r.from_id = sc.id and r.to_id = v_uid and r.status = 'PENDING') then 'PENDING_IN'
                 else 'NONE' end,
          'reasons', to_jsonb(array_remove(array[
            case when sc.pace is not null and v_my_pace is not null and abs(sc.pace - v_my_pace) <= 30 then 'PACE' end,
            case when (sc.ds).time_slots && s.time_slots then 'SLOT' end,
            case when (sc.ds).goals && s.goals then 'GOAL' end,
            case when sc.clubs > 0 then 'CLUB' end,
            case when sc.mutual > 0 then 'MUTUAL' end,
            case when sc.last_run > now() - interval '7 days' then 'ACTIVE' end], null))) as x
          from sc
      ) y(rn, x)
     where y.rn > v_offset and y.rn <= v_offset + 30
  );
end $$;

create or replace function public.nearby_events(p_radius_km integer default 20) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  me jsonb := private.nearby_cell(v_uid);
  v_lat numeric := (me->>'lat')::numeric;
  v_lng numeric := (me->>'lng')::numeric;
begin
  if me is null then raise exception 'NO_PRESENCE'; end if;
  return (select coalesce(jsonb_agg(private.event_json(e, v_uid) || jsonb_build_object(
            'club_name', c.name, 'club_avatar', c.avatar_url,
            'km', round(private.cell_km(v_lat, v_lng, e.lat::numeric, e.lng::numeric), 1),
            'is_member', exists (select 1 from public.club_members m where m.club_id = e.club_id and m.user_id = v_uid and m.status = 'APPROVED'))
          order by e.starts_at), '[]'::jsonb)
            from public.club_events e join public.clubs c on c.id = e.club_id
           where e.visibility = 'PUBLIC' and e.status = 'SCHEDULED' and e.lat is not null
             and e.starts_at > now() - interval '1 hour' and e.starts_at < now() + interval '14 days'
             and private.cell_km(v_lat, v_lng, e.lat::numeric, e.lng::numeric) <= least(greatest(p_radius_km, 2), 50));
end $$;

create or replace function public.nearby_clubs(p_radius_km integer default 20) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  me jsonb := private.nearby_cell(v_uid);
  v_lat numeric := (me->>'lat')::numeric;
  v_lng numeric := (me->>'lng')::numeric;
begin
  if me is null then raise exception 'NO_PRESENCE'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'avatar_url', c.avatar_url, 'accent_color', c.accent_color,
            'member_count', c.member_count, 'area_label', c.area_label, 'join_policy', c.join_policy,
            'km', round(private.cell_km(v_lat, v_lng, c.cell_lat, c.cell_lng)),
            'is_member', exists (select 1 from public.club_members m where m.club_id = c.id and m.user_id = v_uid and m.status = 'APPROVED'),
            'upcoming', (select count(*) from public.club_events e where e.club_id = c.id and e.visibility = 'PUBLIC' and e.status = 'SCHEDULED' and e.starts_at > now()))
          order by private.cell_km(v_lat, v_lng, c.cell_lat, c.cell_lng)), '[]'::jsonb)
            from public.clubs c
           where c.cell_lat is not null
             and private.cell_km(v_lat, v_lng, c.cell_lat, c.cell_lng) <= least(greatest(p_radius_km, 2), 50));
end $$;

-- ---------------------------------------------------------------------
-- 5. Bài đăng Hội quán
-- ---------------------------------------------------------------------
create or replace function private.hub_post_json(h public.hub_posts, p_viewer uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', h.id, 'kind', h.kind, 'body', h.body, 'province', h.province, 'area_label', h.area_label, 'near', h.cell_lat is not null,
    'goal', h.goal, 'pace_s', h.pace_s, 'meet_at', h.meet_at, 'race_name', h.race_name, 'status', h.status,
    'expires_at', h.expires_at, 'created_at', h.created_at, 'interest_count', h.interest_count,
    'interested', exists (select 1 from public.hub_post_interests i where i.post_id = h.id and i.user_id = p_viewer),
    'is_mine', h.author_id = p_viewer,
    'author', jsonb_build_object('id', p.id, 'name', p.display_name, 'avatar_url', p.avatar_url, 'level', p.level,
      'province', (select s.province from public.runner_discovery_settings s where s.user_id = p.id)),
    'activity', (select jsonb_build_object('distance_m', a.distance_m, 'moving_time_s', a.moving_time_s,
                   'day', (a.started_at at time zone 'Asia/Ho_Chi_Minh')::date)
                   from public.activities a where a.id = h.activity_id and a.shared and a.validation_status = 'APPROVED'))
    from public.profiles p where p.id = h.author_id
$$;

-- p: {kind, body, near (bool), province, goal, pace_s, meet_at, race_name, activity_id}
create or replace function public.create_hub_post(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  s public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = v_uid);
  v_kind text := upper(coalesce(p->>'kind', ''));
  v_body text := trim(coalesce(p->>'body', ''));
  v_near boolean := coalesce((p->>'near')::boolean, false);
  v_cell jsonb := case when v_near then private.nearby_cell(v_uid) end;
  v_province text := coalesce(nullif(trim(coalesce(p->>'province', '')), ''), s.province);
  v_goal text := nullif(upper(coalesce(p->>'goal', '')), '');
  v_pace integer := nullif(p->>'pace_s', '')::int;
  v_meet timestamptz := nullif(p->>'meet_at', '')::timestamptz;
  v_race text := nullif(left(trim(coalesce(p->>'race_name', '')), 80), '');
  v_act uuid := nullif(p->>'activity_id', '')::uuid;
  v_expires timestamptz;
  v_id uuid := gen_random_uuid();
  h public.hub_posts;
begin
  if not private.hub_member(v_uid) then raise exception 'HUB_NOT_JOINED'; end if;
  if v_kind not in ('BUDDY', 'RACE', 'PACER', 'SHARE', 'ASK') then raise exception 'INVALID_POST'; end if;
  if char_length(v_body) < 5 or char_length(v_body) > 500 then raise exception 'INVALID_POST'; end if;
  if private.has_contact_or_link(v_body) or private.has_contact_or_link(v_race) then raise exception 'NO_LINKS'; end if;
  if v_province is not null and not (v_province = any (private.vn_provinces())) then raise exception 'INVALID_POST'; end if;
  if v_goal is not null and v_goal not in ('5K', '10K', 'HM', 'FM', 'TRAIL') then raise exception 'INVALID_POST'; end if;
  if v_pace is not null and v_pace not between 150 and 1200 then raise exception 'INVALID_POST'; end if;
  if v_meet is not null and (v_meet < now() or v_meet > now() + interval '120 days') then raise exception 'INVALID_POST'; end if;
  if v_kind = 'RACE' and v_race is null then raise exception 'RACE_NAME_REQUIRED'; end if;
  if v_near and v_cell is null then raise exception 'NO_PRESENCE'; end if;
  if v_act is not null and not exists (select 1 from public.activities a where a.id = v_act and a.user_id = v_uid
                                          and a.validation_status = 'APPROVED' and a.shared) then raise exception 'ACTIVITY_NOT_FOUND'; end if;
  if (select count(*) from public.hub_posts x where x.author_id = v_uid and x.created_at > now() - interval '24 hours') >= 5 then
    raise exception 'TOO_MANY_POSTS';
  end if;
  v_expires := least(now() + interval '120 days', coalesce(v_meet + interval '1 day', now() + interval '14 days'));
  insert into public.hub_posts (id, author_id, kind, body, province, cell_lat, cell_lng, area_label, goal, pace_s, meet_at, race_name, activity_id, expires_at)
  values (v_id, v_uid, v_kind, v_body, v_province, (v_cell->>'lat')::numeric, (v_cell->>'lng')::numeric, v_cell->>'area', v_goal, v_pace, v_meet, v_race,
          v_act, v_expires);
  h := (select x from public.hub_posts x where x.id = v_id);
  -- Bài "gần tôi" rủ chạy / cần pacer: báo cho tối đa 30 runner gần nhất (≤ 10 km) đang bật Quanh đây; mỗi người ≤ 3 lần / ngày
  if v_cell is not null and v_kind in ('BUDDY', 'PACER') then
    perform private.notify(x.user_id, null, 'HUB_NEARBY', private.first_name(v_uid) || ' rủ chạy gần bạn',
              left(v_body, 120), '/hub?post=' || h.id, v_uid, false)
       from (select l.user_id, row_number() over (order by private.cell_km((v_cell->>'lat')::numeric, (v_cell->>'lng')::numeric, l.cell_lat, l.cell_lng)) as rn
               from private.nearby_locations() l join public.runner_discovery_settings ds on ds.user_id = l.user_id
              where l.user_id <> v_uid and ds.enabled and ds.suspended_at is null
                and private.cell_km((v_cell->>'lat')::numeric, (v_cell->>'lng')::numeric, l.cell_lat, l.cell_lng) <= 10
                and not private.is_blocked(v_uid, l.user_id)
                and private.nearby_visible(l.user_id, v_uid, s.visible_to)
                and private.nearby_visible(v_uid, l.user_id, ds.visible_to)
                and (select count(*) from public.notifications n where n.user_id = l.user_id and n.kind = 'HUB_NEARBY'
                       and n.created_at > now() - interval '24 hours') < 3) x
      where x.rn <= 30;
  end if;
  return private.hub_post_json(h, v_uid);
end $$;

create or replace function public.close_hub_post(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  update public.hub_posts set status = 'CLOSED' where id = p_id and author_id = v_uid and status = 'ACTIVE';
  if not found and not exists (select 1 from public.hub_posts where id = p_id and author_id = v_uid) then raise exception 'POST_NOT_FOUND'; end if;
end $$;

-- p: {kind, province, scope: ALL | NEAR | MINE, id (mở từ thông báo), offset}
create or replace function public.hub_feed(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_kind text := nullif(nullif(upper(coalesce(p->>'kind', '')), ''), 'ALL');
  v_province text := nullif(trim(coalesce(p->>'province', '')), '');
  v_scope text := upper(coalesce(p->>'scope', 'ALL'));
  v_offset integer := greatest(0, coalesce((p->>'offset')::int, 0));
  v_id uuid := nullif(p->>'id', '')::uuid;
  me jsonb := private.nearby_cell(v_uid);
begin
  if v_scope = 'NEAR' and me is null then raise exception 'NO_PRESENCE'; end if;
  return (
    with f as (
      select h, row_number() over (order by h.created_at desc, h.id) as rn,
             case when me is not null and h.cell_lat is not null
                  then private.shown_km(private.cell_km((me->>'lat')::numeric, (me->>'lng')::numeric, h.cell_lat, h.cell_lng), v_uid, h.author_id) end as km
        from public.hub_posts h
       where (v_kind is null or h.kind = v_kind)
         and (v_id is null or h.id = v_id)
         and (v_province is null or h.province = v_province)
         and (case when v_scope = 'MINE' then h.author_id = v_uid
                   else h.status = 'ACTIVE' and h.expires_at > now() and not private.is_blocked(v_uid, h.author_id) end)
         and (v_scope <> 'NEAR' or (h.cell_lat is not null
              and private.cell_km((me->>'lat')::numeric, (me->>'lng')::numeric, h.cell_lat, h.cell_lng) <= 20))
    )
    select jsonb_build_object('items', coalesce(jsonb_agg(private.hub_post_json(f.h, v_uid) || jsonb_build_object('km', f.km) order by f.rn)
                                          filter (where f.rn > v_offset and f.rn <= v_offset + 30), '[]'::jsonb),
                              'total', count(*))
      from f
  );
end $$;

-- "Quan tâm" (bấm lần nữa = bỏ): báo cho người đăng; hai bên nhắn tin được cho nhau
create or replace function public.toggle_hub_interest(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  h public.hub_posts := (select x from public.hub_posts x where x.id = p_id);
  v_on boolean;
begin
  if h.id is null or h.status <> 'ACTIVE' or h.expires_at < now() or private.is_blocked(v_uid, h.author_id) then raise exception 'POST_NOT_FOUND'; end if;
  if h.author_id = v_uid then raise exception 'INVALID_TARGET'; end if;
  v_on := not exists (select 1 from public.hub_post_interests i where i.post_id = h.id and i.user_id = v_uid);
  if v_on then
    if (select count(*) from public.hub_post_interests i where i.user_id = v_uid and i.created_at > now() - interval '24 hours') >= 30 then
      raise exception 'RATE_LIMITED';
    end if;
    insert into public.hub_post_interests (post_id, user_id) values (h.id, v_uid) on conflict do nothing;
    perform private.notify(h.author_id, null, 'HUB_INTEREST', private.display_name(v_uid) || ' quan tâm bài của bạn',
      left(h.body, 120), '/hub?post=' || h.id, v_uid, true);
  else
    delete from public.hub_post_interests where post_id = h.id and user_id = v_uid;
  end if;
  update public.hub_posts set interest_count = (select count(*) from public.hub_post_interests i where i.post_id = h.id) where id = h.id;
  return private.hub_post_json((select x from public.hub_posts x where x.id = h.id), v_uid);
end $$;

-- Người đăng xem ai quan tâm
create or replace function public.hub_interested(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  if not exists (select 1 from public.hub_posts h where h.id = p_id and h.author_id = v_uid) then raise exception 'POST_NOT_FOUND'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.display_name, 'avatar_url', p.avatar_url, 'level', p.level,
            'pace_s', case when coalesce(s.share_pace, false) then private.typical_pace(p.id) end, 'province', s.province, 'at', i.created_at)
          order by i.created_at desc), '[]'::jsonb)
            from public.hub_post_interests i join public.profiles p on p.id = i.user_id
            left join public.runner_discovery_settings s on s.user_id = p.id
           where i.post_id = p_id and not private.is_blocked(v_uid, i.user_id));
end $$;

create or replace function public.report_hub_post(p_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  h public.hub_posts := (select x from public.hub_posts x where x.id = p_id);
begin
  if h.id is null then raise exception 'POST_NOT_FOUND'; end if;
  if h.author_id = v_uid then raise exception 'INVALID_TARGET'; end if;
  if upper(coalesce(p_reason, '')) not in ('SPAM', 'HARASSMENT', 'FAKE', 'UNSAFE', 'OTHER') then raise exception 'INVALID_REASON'; end if;
  insert into public.hub_post_reports (post_id, user_id, reason) values (h.id, v_uid, upper(p_reason)) on conflict do nothing;
  if not exists (select 1 from public.user_reports r where r.reporter = v_uid and r.target = h.author_id and r.status = 'OPEN') then
    insert into public.user_reports (reporter, target, context, reason, note)
    values (v_uid, h.author_id, 'HUB', upper(p_reason), 'Bài Hội quán: ' || left(h.body, 300));
  end if;
  -- 3 người khác nhau báo cáo → bài tự ẩn chờ admin
  if (select count(*) from public.hub_post_reports r where r.post_id = h.id) >= 3 then
    update public.hub_posts set status = 'HIDDEN' where id = h.id;
  end if;
end $$;

-- Admin: ẩn / hiện lại bài
create or replace function public.admin_set_hub_post(p_id uuid, p_hidden boolean) returns void
language plpgsql security definer set search_path = public as $$
declare v_admin uuid := private.require_admin();
begin
  update public.hub_posts set status = case when p_hidden then 'HIDDEN' else 'ACTIVE' end where id = p_id;
  if not found then raise exception 'POST_NOT_FOUND'; end if;
  if not p_hidden then delete from public.hub_post_reports where post_id = p_id; end if;
  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_admin, 'HUB_POST_' || case when p_hidden then 'HIDE' else 'SHOW' end, 'hub_post:' || p_id, '{}'::jsonb);
end $$;

-- ---------------------------------------------------------------------
-- 6. Danh bạ runner Hội quán
-- ---------------------------------------------------------------------
-- p: {province, goal, purpose, slot, pace: ALL|FAST|MID|EASY, q, sort: MATCH|ACTIVE|NEW, offset}
create or replace function public.hub_runners(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  s public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = v_uid);
  v_province text := nullif(trim(coalesce(p->>'province', '')), '');
  v_goal text := nullif(nullif(upper(coalesce(p->>'goal', '')), ''), 'ALL');
  v_purpose text := nullif(nullif(upper(coalesce(p->>'purpose', '')), ''), 'ALL');
  v_slot text := nullif(nullif(upper(coalesce(p->>'slot', '')), ''), 'ALL');
  v_pace text := upper(coalesce(p->>'pace', 'ALL'));
  v_q text := nullif(private.search_key(coalesce(p->>'q', '')), '');
  v_sort text := upper(coalesce(p->>'sort', 'MATCH'));
  v_offset integer := greatest(0, coalesce((p->>'offset')::int, 0));
  v_my_pace integer := private.typical_pace(v_uid);
begin
  return (
    with c as (
      select ds, ds.user_id as id, pr.display_name, pr.avatar_url, pr.level,
             case when ds.share_pace then private.typical_pace(ds.user_id) end as pace,
             (select max(a.started_at) from public.activities a where a.user_id = ds.user_id and a.validation_status = 'APPROVED'
                 and coalesce(a.status, '') <> 'DELETED' and a.shared) as last_run
        from public.runner_discovery_settings ds join public.profiles pr on pr.id = ds.user_id
       where ds.hub_listed and ds.suspended_at is null and pr.banned_at is null and ds.user_id <> v_uid
         and not private.is_blocked(v_uid, ds.user_id) and private.nearby_eligible(ds.user_id)
         and (v_province is null or ds.province = v_province)
         and (v_goal is null or v_goal = any(ds.goals))
         and (v_purpose is null or v_purpose = any(ds.purposes))
         and (v_slot is null or v_slot = any(ds.time_slots))
         and (v_q is null or private.search_key(pr.display_name || ' ' || coalesce(ds.headline, '')) like '%' || v_q || '%')
    ), f as (
      select c.*, private.match_score(v_my_pace, c.pace, s, c.ds, c.last_run) as score
        from c
       where v_pace = 'ALL' or (v_pace = 'FAST' and c.pace < 330) or (v_pace = 'MID' and c.pace between 330 and 420) or (v_pace = 'EASY' and c.pace > 420)
    ), r as (
      select f.*, row_number() over (order by
          case when v_sort = 'ACTIVE' then extract(epoch from coalesce(f.last_run, 'epoch'::timestamptz)) end desc nulls last,
          case when v_sort = 'NEW' then extract(epoch from (f.ds).hub_consent_at) end desc nulls last,
          f.score desc, f.id) as rn
        from f
    )
    select jsonb_build_object('total', (select count(*) from r), 'items', coalesce(jsonb_agg(jsonb_build_object(
        'id', r.id, 'name', r.display_name, 'avatar_url', r.avatar_url, 'level', r.level,
        'province', (r.ds).province, 'headline', (r.ds).headline, 'bio', (r.ds).bio,
        'goals', to_jsonb((r.ds).goals), 'time_slots', to_jsonb((r.ds).time_slots), 'purposes', to_jsonb((r.ds).purposes),
        'pace_s', r.pace, 'score', r.score,
        'last_run_days', case when r.last_run is not null then greatest(0, (current_date - (r.last_run at time zone 'Asia/Ho_Chi_Minh')::date)) end,
        'stats', private.runner_stats(r.id), 'prs', private.runner_prs(r.id),
        'connection', case when private.are_connected(v_uid, r.id) then 'CONNECTED'
                           when exists (select 1 from public.runner_connection_requests q where q.from_id = v_uid and q.to_id = r.id and q.status = 'PENDING') then 'PENDING_OUT'
                           when exists (select 1 from public.runner_connection_requests q where q.from_id = r.id and q.to_id = v_uid and q.status = 'PENDING') then 'PENDING_IN'
                           else 'NONE' end,
        'following', private.is_following(v_uid, r.id),
        'reasons', to_jsonb(array_remove(array[
            case when r.pace is not null and v_my_pace is not null and abs(r.pace - v_my_pace) <= 30 then 'PACE' end,
            case when s.province is not null and (r.ds).province = s.province then 'PROVINCE' end,
            case when (r.ds).goals && coalesce(s.goals, '{}'::text[]) then 'GOAL' end,
            case when (r.ds).time_slots && coalesce(s.time_slots, '{}'::text[]) then 'SLOT' end,
            case when r.last_run > now() - interval '7 days' then 'ACTIVE' end], null)))
        order by r.rn) filter (where r.rn > v_offset and r.rn <= v_offset + 30), '[]'::jsonb))
      from r
  );
end $$;

-- Hồ sơ Hội quán của tôi: cài đặt + số liệu + thành tích + bài đăng gần đây
create or replace function public.my_hub() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  s public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = v_uid);
begin
  return jsonb_build_object(
    'listed', coalesce(s.hub_listed, false) and s.suspended_at is null,
    'eligible', private.nearby_eligible(v_uid), 'valid_runs', private.valid_runs(v_uid), 'suspended', s.suspended_at is not null,
    'province', s.province, 'headline', s.headline, 'bio', s.bio,
    'goals', coalesce(to_jsonb(s.goals), '[]'::jsonb), 'time_slots', coalesce(to_jsonb(s.time_slots), '[]'::jsonb),
    'purposes', coalesce(to_jsonb(s.purposes), '["BUDDY"]'::jsonb), 'share_pace', coalesce(s.share_pace, true),
    'pace_s', private.typical_pace(v_uid), 'stats', private.runner_stats(v_uid), 'prs', private.runner_prs(v_uid),
    'located', private.nearby_cell(v_uid) is not null,
    'interests_in', (select count(*) from public.hub_post_interests i join public.hub_posts h on h.id = i.post_id
                      where h.author_id = v_uid and h.status = 'ACTIVE'),
    'posts', (select coalesce(jsonb_agg(private.hub_post_json(h, v_uid) order by h.created_at desc), '[]'::jsonb)
                from public.hub_posts h where h.author_id = v_uid and h.created_at > now() - interval '60 days'));
end $$;

-- ---------------------------------------------------------------------
-- 7. Bảng tin quanh đây: bài chạy gần đây của runner quanh mình + bài Hội quán gần mình
-- ---------------------------------------------------------------------
create or replace function public.nearby_feed(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  s public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = v_uid);
  me jsonb := private.nearby_cell(v_uid);
  v_lat numeric := (me->>'lat')::numeric;
  v_lng numeric := (me->>'lng')::numeric;
  v_radius integer := coalesce((p->>'radius_km')::int, s.radius_km, 10);
begin
  if not coalesce(s.enabled, false) or s.suspended_at is not null then raise exception 'NEARBY_DISABLED'; end if;
  if me is null then raise exception 'NO_PRESENCE'; end if;
  if v_radius not in (2, 5, 10, 20) then v_radius := 10; end if;
  return (
    with ppl as (
      select l.user_id, l.kind, private.cell_km(v_lat, v_lng, l.cell_lat, l.cell_lng) as km
        from private.nearby_locations() l join public.runner_discovery_settings ds on ds.user_id = l.user_id
       where l.user_id <> v_uid and ds.enabled and ds.suspended_at is null
         and private.cell_km(v_lat, v_lng, l.cell_lat, l.cell_lng) <= v_radius
         and not private.is_blocked(v_uid, l.user_id)
         and private.nearby_visible(v_uid, l.user_id, ds.visible_to)
         and private.nearby_visible(l.user_id, v_uid, s.visible_to)
         and private.nearby_eligible(l.user_id)
    ), runs as (
      -- Chỉ ngày (không giờ), quãng đường, pace — không tuyến, không điểm xuất phát
      select jsonb_build_object('type', 'RUN', 'at', a.started_at, 'day', (a.started_at at time zone 'Asia/Ho_Chi_Minh')::date,
               'user', jsonb_build_object('id', a.user_id, 'name', private.first_name(a.user_id),
                         'avatar_url', (select avatar_url from public.profiles where id = a.user_id),
                         'level', (select level from public.profiles where id = a.user_id)),
               'km', private.shown_km(ppl.km, v_uid, a.user_id), 'where', ppl.kind,
               'distance_m', a.distance_m, 'moving_time_s', a.moving_time_s,
               'connection', case when private.are_connected(v_uid, a.user_id) then 'CONNECTED' else 'NONE' end) as x,
             row_number() over (partition by a.user_id order by a.started_at desc) as k, a.started_at as t
        from public.activities a join ppl on ppl.user_id = a.user_id
       where a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED' and a.shared
         and a.started_at > now() - interval '7 days' and a.distance_m >= 1000
    ), posts as (
      select private.hub_post_json(h, v_uid) || jsonb_build_object('type', 'POST', 'at', h.created_at,
               'km', private.shown_km(private.cell_km(v_lat, v_lng, h.cell_lat, h.cell_lng), v_uid, h.author_id)) as x, h.created_at as t
        from public.hub_posts h
       where h.status = 'ACTIVE' and h.expires_at > now() and h.cell_lat is not null and h.author_id <> v_uid
         and private.cell_km(v_lat, v_lng, h.cell_lat, h.cell_lng) <= greatest(v_radius, 10)
         and not private.is_blocked(v_uid, h.author_id)
    ), allx as (
      select x, t from runs where k <= 2           -- mỗi người tối đa 2 bài để bảng tin không bị một người chiếm
      union all select x, t from posts
    )
    select jsonb_build_object('items', coalesce(jsonb_agg(z.x order by z.t desc), '[]'::jsonb), 'my_kind', me->>'kind', 'people', (select count(*) from ppl))
      from (select x, t, row_number() over (order by t desc) as rn from allx) z where z.rn <= 40
  );
end $$;

-- ---------------------------------------------------------------------
-- 8. Kết nối từ Hội quán + nhắn tin sau khi "Quan tâm"
-- ---------------------------------------------------------------------
create or replace function public.send_connection(p_to uuid, p_message text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  s public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = v_uid);
  t public.runner_discovery_settings := (select x from public.runner_discovery_settings x where x.user_id = p_to);
  v_msg text := nullif(left(trim(coalesce(p_message, '')), 140), '');
  v_in public.runner_connection_requests := (select r from public.runner_connection_requests r where r.from_id = p_to and r.to_id = v_uid and r.status = 'PENDING');
  v_id uuid := gen_random_uuid();
begin
  if p_to = v_uid then raise exception 'INVALID_TARGET'; end if;
  -- Người gửi: đang bật Quanh đây HOẶC đã vào Hội quán
  if s.user_id is null or s.suspended_at is not null or not (s.enabled or s.hub_listed) then raise exception 'NEARBY_DISABLED'; end if;
  -- Người nhận: vào Hội quán (ai cũng thấy) HOẶC bật Quanh đây và cho mình thấy
  if t.user_id is null or t.suspended_at is not null
     or not (t.hub_listed or (t.enabled and private.nearby_visible(v_uid, p_to, t.visible_to))) then
    raise exception 'TARGET_UNAVAILABLE';
  end if;
  if private.is_blocked(v_uid, p_to) then raise exception 'TARGET_UNAVAILABLE'; end if;
  if private.are_connected(v_uid, p_to) then raise exception 'ALREADY_CONNECTED'; end if;
  if v_msg is not null and private.has_contact_or_link(v_msg) then raise exception 'NO_LINKS'; end if;
  -- Họ đã mời mình → chấp nhận luôn
  if v_in.id is not null then return public.respond_connection(v_in.id, 'ACCEPT'); end if;
  if exists (select 1 from public.runner_connection_requests x where x.from_id = v_uid and x.to_id = p_to and x.status = 'PENDING') then
    raise exception 'ALREADY_REQUESTED';
  end if;
  if exists (select 1 from public.runner_connection_requests x where x.from_id = v_uid and x.to_id = p_to and x.status = 'DECLINED'
              and x.responded_at > now() - interval '30 days') then raise exception 'REQUEST_COOLDOWN'; end if;
  if (select count(*) from public.runner_connection_requests x where x.from_id = v_uid and x.created_at > now() - interval '24 hours') >= 15 then
    raise exception 'TOO_MANY_REQUESTS';
  end if;
  insert into public.runner_connection_requests (id, from_id, to_id, message) values (v_id, v_uid, p_to, v_msg);
  perform private.notify(p_to, null, 'RUNNER_CONNECT', private.first_name(v_uid) || ' muốn kết nối chạy cùng bạn',
    coalesce(v_msg, 'Xem lời mời trong Quanh đây.'), '/nearby/connections', v_uid, true);
  return jsonb_build_object('id', v_id, 'status', 'PENDING');
end $$;

-- Nhắn tin: như 011500 + hai người đã "gặp nhau" qua bài Hội quán (một người quan tâm bài của người kia)
create or replace function private.can_dm(p_from uuid, p_to uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select p_from is not null and p_to is not null and p_from <> p_to
     and not private.is_blocked(p_from, p_to)
     and (private.is_following(p_to, p_from)
          or private.are_connected(p_from, p_to)
          or public.shares_club(p_from, p_to)
          or exists (select 1 from public.direct_messages m join public.direct_threads t on t.id = m.thread_id
                      where t.user_a = least(p_from, p_to) and t.user_b = greatest(p_from, p_to) and m.sender_id = p_to)
          or exists (select 1 from public.hub_post_interests i join public.hub_posts h on h.id = i.post_id
                      where (h.author_id = p_from and i.user_id = p_to) or (h.author_id = p_to and i.user_id = p_from)))
$$;

-- ---------------------------------------------------------------------
-- 9. Quyền
-- ---------------------------------------------------------------------
revoke all on function private.vn_provinces(), private.home_cell(numeric), private.has_contact_or_link(text), private.refresh_home_area(uuid),
  private.home_area_on_activity(), private.nearby_locations(), private.nearby_cell(uuid), private.runner_stats(uuid), private.runner_prs(uuid),
  private.match_score(integer, integer, public.runner_discovery_settings, public.runner_discovery_settings, timestamptz), private.hub_member(uuid),
  private.hub_post_json(public.hub_posts, uuid), private.can_dm(uuid, uuid)
  from public, anon, authenticated;
revoke all on function public.create_hub_post(jsonb), public.close_hub_post(uuid), public.hub_feed(jsonb), public.toggle_hub_interest(uuid),
  public.hub_interested(uuid), public.report_hub_post(uuid, text), public.admin_set_hub_post(uuid, boolean), public.hub_runners(jsonb),
  public.my_hub(), public.nearby_feed(jsonb), public.my_discovery(), public.set_discovery(jsonb), public.nearby_runners(jsonb),
  public.nearby_events(integer), public.nearby_clubs(integer), public.send_connection(uuid, text) from public, anon;
grant execute on function public.create_hub_post(jsonb), public.close_hub_post(uuid), public.hub_feed(jsonb), public.toggle_hub_interest(uuid),
  public.hub_interested(uuid), public.report_hub_post(uuid, text), public.admin_set_hub_post(uuid, boolean), public.hub_runners(jsonb),
  public.my_hub(), public.nearby_feed(jsonb), public.my_discovery(), public.set_discovery(jsonb), public.nearby_runners(jsonb),
  public.nearby_events(integer), public.nearby_clubs(integer), public.send_connection(uuid, text) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001012900_cms_ebook.sql
-- ===================================================================
-- Trình soạn của ban nội dung (CMS) đăng được Ebook PDF như trang Viết bài của runner (011700).
-- Trước đây cms_save ép content_type về ARTICLE / NEWS và bỏ qua attachment_url:
-- admin không đăng được ebook, và sửa ebook của runner trong CMS làm mất loại Ebook.
-- p thêm: content_type 'EBOOK', attachment_url (https, ≤ 500 ký tự; bắt buộc với Ebook; vắng khóa = giữ tệp cũ).

create or replace function public.cms_save(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_role text := private.require_content_staff();
  a public.content_articles := (select x from public.content_articles x where x.id = nullif(p->>'id', '')::uuid);
  v_id uuid;
  v_title text := trim(coalesce(p->>'title', ''));
  v_slug text := nullif(private.slugify(coalesce(nullif(p->>'slug', ''), p->>'title')), '');
  v_body text := coalesce(p->>'body', '');
  v_cat text := coalesce(nullif(p->>'category_id', ''), a.category_id);
  v_expert boolean;
  v_editor boolean := v_role in ('ADMIN', 'EDITOR');
  v_type text := case upper(coalesce(p->>'content_type', '')) when 'NEWS' then 'NEWS' when 'EBOOK' then 'EBOOK' else 'ARTICLE' end;
  -- Không gửi khóa attachment_url thì giữ tệp cũ (bản app cũ không biết khóa này)
  v_att text := case when p ? 'attachment_url' then nullif(trim(coalesce(p->>'attachment_url', '')), '') else a.attachment_url end;
begin
  if nullif(p->>'id', '') is not null and a.id is null then raise exception 'ARTICLE_NOT_FOUND'; end if;
  if a.id is not null and not v_editor and (a.created_by is distinct from v_uid or a.status not in ('DRAFT', 'REVIEW')) then
    raise exception 'FORBIDDEN';
  end if;
  if char_length(v_title) < 5 then raise exception 'TITLE_TOO_SHORT'; end if;
  if v_slug is null then raise exception 'INVALID_SLUG'; end if;
  if not exists (select 1 from public.content_categories c where c.id = v_cat) then raise exception 'INVALID_CATEGORY'; end if;
  if exists (select 1 from public.content_articles x where x.slug = v_slug and x.id is distinct from a.id) then raise exception 'SLUG_TAKEN'; end if;
  if nullif(p->>'cover_image_url', '') is not null and p->>'cover_image_url' !~ '^https://' then raise exception 'INVALID_URL'; end if;
  if nullif(p->>'source_url', '') is not null and p->>'source_url' !~ '^https?://' then raise exception 'INVALID_URL'; end if;
  if v_att is not null and (v_att !~ '^https://' or char_length(v_att) > 500) then raise exception 'INVALID_URL'; end if;
  if v_type = 'EBOOK' and v_att is null then raise exception 'EBOOK_PDF_REQUIRED'; end if;
  -- Chuyên mục sức khoẻ / giáo án luôn cần duyệt chuyên môn; chỉ admin tắt được
  v_expert := (select c.needs_expert from public.content_categories c where c.id = v_cat)
              or coalesce((p->>'needs_expert_review')::boolean, a.needs_expert_review, false);
  if v_role = 'ADMIN' and (p ? 'needs_expert_review') then v_expert := (p->>'needs_expert_review')::boolean; end if;

  if a.id is null then
    insert into public.content_articles (slug, title, summary, body, cover_image_url, category_id, author_id, content_type, reading_time_minutes,
      source_url, source_name, is_featured, series_id, series_order, ctas, needs_expert_review, attachment_url, created_by)
    values (v_slug, v_title, nullif(left(trim(coalesce(p->>'summary', '')), 300), ''), v_body, nullif(p->>'cover_image_url', ''), v_cat,
      coalesce(nullif(p->>'author_id', '')::uuid, (select au.id from public.content_authors au where au.user_id = v_uid)),
      v_type, private.reading_minutes(v_body),
      nullif(p->>'source_url', ''), nullif(left(trim(coalesce(p->>'source_name', '')), 80), ''),
      v_editor and coalesce((p->>'is_featured')::boolean, false), nullif(p->>'series_id', ''), nullif(p->>'series_order', '')::int,
      private.clean_ctas(p->'ctas'), v_expert, v_att, v_uid)
    returning id into v_id;
  else
    v_id := a.id;
    update public.content_articles set slug = v_slug, title = v_title, summary = nullif(left(trim(coalesce(p->>'summary', '')), 300), ''),
      body = v_body, cover_image_url = nullif(p->>'cover_image_url', ''), category_id = v_cat,
      author_id = case when p ? 'author_id' then nullif(p->>'author_id', '')::uuid else author_id end,
      content_type = v_type, attachment_url = v_att,
      reading_time_minutes = private.reading_minutes(v_body),
      source_url = nullif(p->>'source_url', ''), source_name = nullif(left(trim(coalesce(p->>'source_name', '')), 80), ''),
      is_featured = case when v_editor then coalesce((p->>'is_featured')::boolean, is_featured) else is_featured end,
      series_id = nullif(p->>'series_id', ''), series_order = nullif(p->>'series_order', '')::int,
      ctas = private.clean_ctas(p->'ctas'), needs_expert_review = v_expert,
      -- nội dung chuyên môn đổi mà người sửa không phải chuyên gia → duyệt lại
      expert_reviewed_at = case when body is distinct from v_body and v_role not in ('ADMIN', 'EXPERT') then null else expert_reviewed_at end,
      expert_reviewed_by = case when body is distinct from v_body and v_role not in ('ADMIN', 'EXPERT') then null else expert_reviewed_by end,
      updated_at = now()
     where id = v_id;
    -- bài đang đăng mất duyệt chuyên môn → gỡ về chờ duyệt
    update public.content_articles set status = 'REVIEW', review_note = 'Nội dung đã đổi — cần duyệt chuyên môn lại'
     where id = v_id and needs_expert_review and expert_reviewed_at is null and status in ('SCHEDULED', 'PUBLISHED');
  end if;

  -- Tag: tạo mới nếu chưa có
  delete from public.content_article_tags where article_id = v_id;
  insert into public.content_tags (slug, name)
  select distinct private.slugify(t), left(trim(t), 40) from jsonb_array_elements_text(coalesce(p->'tags', '[]'::jsonb)) t
   where private.slugify(t) <> '' on conflict (slug) do nothing;
  insert into public.content_article_tags (article_id, tag_id)
  select distinct v_id, ct.id from jsonb_array_elements_text(coalesce(p->'tags', '[]'::jsonb)) t
    join public.content_tags ct on ct.slug = private.slugify(t)
  on conflict do nothing;
  -- Nguồn tham khảo
  delete from public.content_sources where article_id = v_id;
  insert into public.content_sources (article_id, title, url, publisher, sort)
  select v_id, left(trim(s->>'title'), 200), case when s->>'url' ~ '^https?://' then left(s->>'url', 500) end,
         nullif(left(trim(coalesce(s->>'publisher', '')), 80), ''), n::int
    from jsonb_array_elements(coalesce(p->'sources', '[]'::jsonb)) with ordinality x(s, n)
   where char_length(trim(coalesce(s->>'title', ''))) > 0 and n <= 20;
  return v_id;
end $$;

-- ===================================================================
-- 20261001013000_ops_readonly.sql
-- ===================================================================
-- Trợ lý vận hành (ADR-018): schema `ops` chỉ gồm view tổng hợp + role `ops_reader` chỉ đọc được schema này.
-- Routine Claude kết nối bằng ops_reader để soạn báo cáo; không đọc được public / private / auth, không ghi được gì.
--
-- Sau khi chạy migration, Quản trị chính tự đặt mật khẩu (KHÔNG ghi vào repo, không gửi qua chat):
--   alter role ops_reader with login password '<mật khẩu mạnh>';
-- Chuỗi kết nối (Supabase → Connect → Session pooler), thay user thành ops_reader.<project-ref>,
-- rồi lưu làm biến môi trường RACEHUB_OPS_DB_URL trong cài đặt môi trường của project Claude.
-- Nghi lộ: alter role ops_reader with password '<mới>';  hoặc  alter role ops_reader nologin;
--
-- Danh sách tester kiểm thử kín (email trùng danh sách trong Play Console):
--   insert into ops.testers (email) values ('a@gmail.com'), ('b@gmail.com') on conflict do nothing;

create schema if not exists ops;
revoke all on schema ops from public;
do $$ begin
  -- Supabase có anon / authenticated; schema ops không mở cho app (không có trong API schemas)
  if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on schema ops from anon, authenticated'; end if;
end $$;

create table if not exists ops.testers (
  email text primary key check (email = lower(trim(email)) and email like '%@%' and char_length(email) <= 200),
  joined_on date not null default (now() at time zone 'Asia/Ho_Chi_Minh')::date,
  note text check (note is null or char_length(note) <= 200),
  active boolean not null default true
);

-- Mỗi tester: có tài khoản chưa, lần đăng nhập / chạy / nhận thông báo gần nhất, số ngày im lặng.
-- App chưa ghi "lần mở app", nên dùng lần có dấu hiệu sống gần nhất trong 3 nguồn trên.
create or replace view ops.tester_activity as
select t.email, t.joined_on, t.note,
       u.id is not null as has_account,
       p.display_name,
       u.last_sign_in_at,
       r.last_run_at,
       coalesce(r.runs_7d, 0) as runs_7d,
       coalesce(r.km_7d, 0) as km_7d,
       s.last_push_seen_at,
       greatest(u.last_sign_in_at, r.last_run_at, s.last_push_seen_at) as last_signal_at,
       (now()::date - greatest(u.last_sign_in_at, r.last_run_at, s.last_push_seen_at)::date) as days_silent
  from ops.testers t
  left join auth.users u on lower(u.email) = t.email
  left join public.profiles p on p.id = u.id
  left join lateral (
    select max(a.started_at) as last_run_at,
           count(*) filter (where a.started_at >= now() - interval '7 days') as runs_7d,
           round(coalesce(sum(a.distance_m) filter (where a.started_at >= now() - interval '7 days'), 0) / 1000.0, 1) as km_7d
      from public.activities a where a.user_id = u.id) r on true
  left join lateral (select max(ps.last_seen_at) as last_push_seen_at from public.push_subscriptions ps where ps.user_id = u.id) s on true
 where t.active;

-- Số liệu theo tuần (thứ Hai → Chủ nhật, giờ VN), 8 tuần gần nhất.
create or replace view ops.weekly_metrics as
with w as (
  select generate_series(date_trunc('week', (now() at time zone 'Asia/Ho_Chi_Minh')) - interval '7 weeks',
                         date_trunc('week', (now() at time zone 'Asia/Ho_Chi_Minh')), interval '1 week') as week_start
)
select w.week_start::date as week_start,
       (select count(*) from public.profiles p
         where (p.created_at at time zone 'Asia/Ho_Chi_Minh') >= w.week_start
           and (p.created_at at time zone 'Asia/Ho_Chi_Minh') < w.week_start + interval '1 week') as new_users,
       (select count(distinct a.user_id) from public.activities a
         where (a.started_at at time zone 'Asia/Ho_Chi_Minh') >= w.week_start
           and (a.started_at at time zone 'Asia/Ho_Chi_Minh') < w.week_start + interval '1 week') as active_runners,
       (select count(*) from public.activities a
         where (a.started_at at time zone 'Asia/Ho_Chi_Minh') >= w.week_start
           and (a.started_at at time zone 'Asia/Ho_Chi_Minh') < w.week_start + interval '1 week') as runs,
       (select round(coalesce(sum(a.distance_m), 0) / 1000.0, 1) from public.activities a
         where (a.started_at at time zone 'Asia/Ho_Chi_Minh') >= w.week_start
           and (a.started_at at time zone 'Asia/Ho_Chi_Minh') < w.week_start + interval '1 week') as km,
       (select count(*) from public.challenges c
         where (c.created_at at time zone 'Asia/Ho_Chi_Minh') >= w.week_start
           and (c.created_at at time zone 'Asia/Ho_Chi_Minh') < w.week_start + interval '1 week') as new_challenges,
       (select count(*) from public.clubs c
         where (c.created_at at time zone 'Asia/Ho_Chi_Minh') >= w.week_start
           and (c.created_at at time zone 'Asia/Ho_Chi_Minh') < w.week_start + interval '1 week') as new_clubs
  from w;

-- Việc cần chủ dự án để ý. kind: CHALLENGE_ENDING | CHALLENGE_LOW_SIGNUP | CLUB_QUIET | USER_REPORT_OPEN
create or replace view ops.attention as
select 'CHALLENGE_ENDING'::text as kind, c.id as ref_id, c.title,
       format('Kết thúc %s, %s người tham gia', to_char(c.end_date at time zone 'Asia/Ho_Chi_Minh', 'DD/MM HH24:MI'),
              (select count(*) from public.challenge_participants cp where cp.challenge_id = c.id)) as detail,
       c.end_date as due_at
  from public.challenges c
 where c.status = 'ACTIVE' and c.end_date between now() and now() + interval '3 days'
union all
select 'CHALLENGE_LOW_SIGNUP', c.id, c.title,
       format('Hạn đăng ký %s, mới %s/%s người tối thiểu', to_char(c.reg_deadline at time zone 'Asia/Ho_Chi_Minh', 'DD/MM HH24:MI'),
              n.joined, coalesce(c.min_members, 1)),
       c.reg_deadline
  from public.challenges c
  cross join lateral (select count(*) as joined from public.challenge_participants cp where cp.challenge_id = c.id) n
 where c.status = 'ACTIVE' and c.reg_deadline between now() and now() + interval '2 days'
   and n.joined < greatest(coalesce(c.min_members, 1), 2)
union all
select 'CLUB_QUIET', c.id, c.name,
       format('%s thành viên, không ai chạy trong 14 ngày', c.member_count),
       null::timestamptz
  from public.clubs c
 where c.created_at < now() - interval '14 days'
   and not exists (select 1 from public.club_members m join public.activities a on a.user_id = m.user_id
                    where m.club_id = c.id and coalesce(m.status, 'APPROVED') = 'APPROVED' and a.started_at >= now() - interval '14 days')
union all
select 'USER_REPORT_OPEN', r.id, r.reason,
       format('Báo cáo %s (%s) chưa xử lý từ %s', r.reason, r.context, to_char(r.created_at at time zone 'Asia/Ho_Chi_Minh', 'DD/MM')),
       r.created_at
  from public.user_reports r
 where r.status = 'OPEN';

-- Role chỉ đọc. Tạo ở trạng thái nologin; Quản trị chính tự bật đăng nhập + đặt mật khẩu (xem đầu file).
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'ops_reader') then
    create role ops_reader nologin noinherit;
  end if;
end $$;
alter role ops_reader set default_transaction_read_only = on;
alter role ops_reader set statement_timeout = '15s';
grant usage on schema ops to ops_reader;
grant select on ops.testers, ops.tester_activity, ops.weekly_metrics, ops.attention to ops_reader;

-- ===================================================================
-- 20261001013100_feedback_round6.sql
-- ===================================================================
-- 013100: Chỉnh sửa lần 6.
-- 1. Bảng tin "Đang theo dõi" thích / bình luận / tặng quà ngay tại chỗ như "Cộng đồng":
--    following_feed trả kèm bài AUTO_RUN của buổi chạy (ưu tiên bài ở CLB mình tham gia). Người theo dõi runner được tương tác
--    với bài chạy (AUTO_RUN) của runner đó dù khác CLB — private.can_engage_post thay cho kiểm tra thành viên CLB trong các hàm
--    thích / bình luận / thích bình luận / xem lượt tương tác / tặng quà (bài viết thường của CLB vẫn chỉ thành viên CLB).
-- 2. Bài chạy chờ duyệt (từ Strava / Garmin / COROS): báo ngay cho người chạy kèm lý do; người chạy gửi được giải trình
--    (activities.owner_note) để ban quản trị CLB / admin đọc khi duyệt.
-- 3. Vinh danh thử thách theo cự ly: hạng mục DIST<mét> (VD DIST21097 = Top Half Marathon) — bài tốt nhất có cự ly ≥ hạng mục
--    trong thời gian thử thách, thời gian quy đổi theo pace trung bình.
-- 4. Người tạo / ban tổ chức sửa được thử thách TRƯỚC khi bắt đầu: tên, mô tả, mục tiêu, luật km / pace, thời gian.
--    Không đổi thể thức, số người, đối tượng, giải thưởng (liên quan phí và ký quỹ); thời lượng mới không dài hơn thời lượng đã trả phí.
-- Cần 013000. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT, không RETURNING INTO. Chạy lại an toàn.

-- ---------------------------------------------------------------------
-- 1. Bảng tin "Đang theo dõi"
-- ---------------------------------------------------------------------
/** Được thích / bình luận / tặng quà trên bài này: thành viên CLB, hoặc người theo dõi chủ bài (chỉ bài chạy AUTO_RUN, bài đang chia sẻ) */
create or replace function private.can_engage_post(p public.club_posts) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() is not null and p.id is not null and (public.club_is_member(p.club_id)
    or (p.kind = 'AUTO_RUN' and p.author_id is not null and p.activity_id is not null
        and (p.author_id = auth.uid()
             or (private.is_following(auth.uid(), p.author_id) and not private.is_blocked(auth.uid(), p.author_id)
                 and exists (select 1 from public.activities a where a.id = p.activity_id and a.shared and public.can_view_activities(a.user_id))))))
$$;

create or replace function public.following_feed(p_before timestamptz default null, p_limit integer default 20) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 40);
begin
  return (select coalesce(jsonb_agg(jsonb_build_object(
            'id', t.id, 'title', t.title, 'source', t.source, 'started_at', t.started_at,
            'distance_m', t.dist, 'moving_time_s', t.mt, 'avg_pace_s', t.avg_pace_s, 'elevation_gain_m', t.elevation_gain_m,
            'is_me', t.user_id = v_uid,
            'user', jsonb_build_object('id', pr.id, 'display_name', pr.display_name, 'avatar_url', pr.avatar_url, 'level', coalesce(pr.level, 1)),
            -- 013100: bài AUTO_RUN của buổi chạy (cùng dạng community_feed) để thích / bình luận / tặng quà tại chỗ
            'post', case when cp.id is null then null else jsonb_build_object(
              'id', cp.id, 'club_id', cp.club_id, 'author_id', cp.author_id, 'kind', cp.kind, 'title', cp.title, 'body', cp.body,
              'image_paths', coalesce(to_jsonb(cp.image_paths), '[]'::jsonb), 'activity_id', cp.activity_id, 'meta', coalesce(cp.meta, '{}'::jsonb),
              'is_pinned', false, 'reaction_count', cp.reaction_count, 'comment_count', cp.comment_count, 'cheer_xu', cp.cheer_xu,
              'gift_count', cp.gift_count, 'created_at', cp.created_at,
              'reacted', exists (select 1 from public.club_post_reactions r where r.post_id = cp.id and r.user_id = v_uid),
              'author', jsonb_build_object('id', pr.id, 'display_name', pr.display_name, 'level', coalesce(pr.level, 1), 'avatar_url', pr.avatar_url),
              'club', jsonb_build_object('id', cl.id, 'name', cl.name, 'avatar_url', cl.avatar_url, 'accent_color', cl.accent_color)) end)
          order by t.started_at desc), '[]'::jsonb)
    from (select a.id, a.user_id, a.title, a.source, a.started_at, a.avg_pace_s, a.elevation_gain_m,
                 coalesce(nullif(a.moving_distance_m, 0), a.distance_m, 0) as dist, coalesce(a.moving_time_s, a.elapsed_time_s, 0) as mt,
                 row_number() over (order by a.started_at desc, a.id) as rn
            from public.activities a
           where (a.user_id = v_uid or a.user_id in (select f.followee_id from public.runner_follows f where f.follower_id = v_uid))
             and a.started_at is not null and a.started_at < coalesce(p_before, now() + interval '1 day')
             and a.started_at > now() - interval '90 days'
             and public.activity_is_countable(a.status, a.validation_status)
             and (a.user_id = v_uid or (a.shared and public.can_view_activities(a.user_id) and not private.is_blocked(v_uid, a.user_id)))) t
    join public.profiles pr on pr.id = t.user_id
    left join lateral (
      select x.* from (select p.*, row_number() over (order by public.club_is_member(p.club_id) desc, p.created_at, p.id) as prn
                         from public.club_posts p
                        where p.activity_id = t.id and p.kind = 'AUTO_RUN' and p.deleted_at is null) x
       where x.prn = 1) cp on true
    left join public.clubs cl on cl.id = cp.club_id
   where t.rn <= v_limit);
end $$;

-- Các hàm tương tác: thay "thành viên CLB" bằng private.can_engage_post (giữ nguyên phần còn lại của bản gần nhất)
create or replace function public.post_engagement(p_post_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  p public.club_posts := (select x from public.club_posts x where x.id = p_post_id and x.deleted_at is null);
begin
  if p.id is null then raise exception 'POST_NOT_FOUND'; end if;
  if not private.can_engage_post(p) then raise exception 'NOT_A_MEMBER'; end if;
  return jsonb_build_object(
    'like_count', p.reaction_count,
    'gift_count', p.gift_count,
    'likes', (select coalesce(jsonb_agg(jsonb_build_object(
                'user_id', t.user_id, 'display_name', pr.display_name, 'avatar_url', pr.avatar_url, 'level', coalesce(pr.level, 1),
                'at', t.created_at, 'me', t.user_id = v_uid) order by t.created_at desc), '[]'::jsonb)
                from (select r.user_id, r.created_at, row_number() over (order by r.created_at desc) as rn
                        from public.club_post_reactions r where r.post_id = p.id) t
                join public.profiles pr on pr.id = t.user_id
               where t.rn <= 500),
    'gifts', (select coalesce(jsonb_agg(jsonb_build_object(
                'id', t.id, 'user_id', t.from_user, 'display_name', pr.display_name, 'avatar_url', pr.avatar_url, 'level', coalesce(pr.level, 1),
                'emoji', g.emoji, 'name', g.name, 'tier', g.tier, 'qty', t.qty, 'at', t.created_at, 'me', t.from_user = v_uid,
                -- lời nhắn là chuyện riêng của người tặng và người nhận
                'message', case when v_uid in (t.from_user, t.to_user) then t.message end) order by t.created_at desc), '[]'::jsonb)
                from (select c.id, c.from_user, c.to_user, c.gift_code, greatest(coalesce(c.qty, 1), 1) as qty, c.message, c.created_at,
                             row_number() over (order by c.created_at desc) as rn
                        from public.cheers c where c.post_id = p.id and c.gift_code is not null) t
                join public.profiles pr on pr.id = t.from_user
                join public.gift_catalog g on g.code = t.gift_code
               where t.rn <= 500),
    'gift_summary', (select coalesce(jsonb_agg(jsonb_build_object('emoji', s.emoji, 'name', s.name, 'qty', s.n) order by s.n desc, s.price desc), '[]'::jsonb)
                       from (select g.emoji, g.name, g.price_xu as price, sum(greatest(coalesce(c.qty, 1), 1)) as n
                               from public.cheers c join public.gift_catalog g on g.code = c.gift_code
                              where c.post_id = p.id group by g.emoji, g.name, g.price_xu) s),
    'gift_senders', (select count(distinct c.from_user) from public.cheers c where c.post_id = p.id and c.gift_code is not null)
  );
end $$;

create or replace function public.toggle_post_reaction(p_post_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid(); p public.club_posts; v_on boolean;
begin
  perform 1 from public.club_posts where id = p_post_id and deleted_at is null for update;
  p := (select x from public.club_posts x where x.id = p_post_id and x.deleted_at is null);
  if p.id is null then raise exception 'POST_NOT_FOUND'; end if;
  if not private.can_engage_post(p) then raise exception 'NOT_A_MEMBER'; end if;

  delete from public.club_post_reactions where post_id = p_post_id and user_id = v_uid;
  if found then
    v_on := false;
  else
    insert into public.club_post_reactions (post_id, user_id) values (p_post_id, v_uid);
    v_on := true;
    -- Chỉ báo một lần cho mỗi người thích mỗi bài
    if not exists (select 1 from public.notifications
                    where user_id = p.author_id and actor_id = v_uid and kind = 'POST_CHEER'
                      and link = '/clubs/' || p.club_id || '?post=' || p.id) then
      perform private.notify(p.author_id, p.club_id, 'POST_CHEER',
        private.display_name(v_uid) || case when p.kind = 'AUTO_RUN' then ' đã thích buổi chạy của bạn'
                                            when p.kind = 'AUTO_JOIN' then ' chào mừng bạn vào CLB'
                                            else ' đã thích bài đăng của bạn' end,
        null, '/clubs/' || p.club_id || '?post=' || p.id, v_uid, false);
    end if;
  end if;

  update public.club_posts
     set reaction_count = (select count(*) from public.club_post_reactions where post_id = p_post_id)
   where id = p_post_id;
  return jsonb_build_object('reacted', v_on, 'count', (select x.reaction_count from public.club_posts x where x.id = p_post_id));
end $$;

create or replace function public.club_post_comment_thread(p_post_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := private.require_uid(); p public.club_posts := (select x from public.club_posts x where x.id = p_post_id and x.deleted_at is null);
begin
  if p.id is null then raise exception 'POST_NOT_FOUND'; end if;
  if not private.can_engage_post(p) and not public.is_system_admin() then raise exception 'NOT_A_MEMBER'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', c.id, 'parent_id', c.parent_id, 'author_id', c.author_id, 'body', c.body, 'created_at', c.created_at, 'edited_at', c.edited_at,
      'author_name', pr.display_name, 'author_avatar', pr.avatar_url, 'author_level', pr.level,
      'like_count', c.like_count,
      'liked', exists (select 1 from public.club_comment_likes l where l.comment_id = c.id and l.user_id = v_uid),
      'can_edit', c.author_id = v_uid,
      'can_delete', c.author_id = v_uid or public.club_is_staff(p.club_id)) order by c.created_at)
    from public.club_post_comments c left join public.profiles pr on pr.id = c.author_id
   where c.post_id = p_post_id and c.deleted_at is null), '[]'::jsonb);
end $$;

create or replace function public.add_post_comment(p_post_id uuid, p_body text, p_parent_id uuid) returns public.club_post_comments
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  p public.club_posts := (select x from public.club_posts x where x.id = p_post_id and x.deleted_at is null);
  v_body text := trim(coalesce(p_body, ''));
  v_parent public.club_post_comments;
  v_to uuid;                            -- người được trả lời trực tiếp (nhận thông báo)
  c public.club_post_comments;
  v_id uuid := gen_random_uuid();
  v_link text;
begin
  if p.id is null then raise exception 'POST_NOT_FOUND'; end if;
  if not private.can_engage_post(p) then raise exception 'NOT_A_MEMBER'; end if;
  if char_length(v_body) = 0 then raise exception 'EMPTY_COMMENT'; end if;
  if char_length(v_body) > 1000 then raise exception 'POST_TOO_LONG'; end if;
  if (select count(*) from public.club_post_comments where author_id = v_uid and created_at > now() - interval '1 minute') >= 10 then
    raise exception 'RATE_LIMITED';
  end if;
  if p_parent_id is not null then
    v_parent := (select x from public.club_post_comments x where x.id = p_parent_id and x.post_id = p_post_id and x.deleted_at is null);
    if v_parent.id is null then raise exception 'COMMENT_NOT_FOUND'; end if;
    v_to := v_parent.author_id;
    -- một tầng: trả lời một câu trả lời thì gắn vào bình luận gốc (thông báo vẫn gửi người mình trả lời)
    if v_parent.parent_id is not null then
      v_parent := coalesce((select x from public.club_post_comments x where x.id = v_parent.parent_id and x.deleted_at is null), v_parent);
    end if;
  end if;

  insert into public.club_post_comments (id, post_id, author_id, body, parent_id) values (v_id, p_post_id, v_uid, v_body, v_parent.id);
  c := (select x from public.club_post_comments x where x.id = v_id);
  update public.club_posts
     set comment_count = (select count(*) from public.club_post_comments where post_id = p_post_id and deleted_at is null)
   where id = p_post_id;

  v_link := '/clubs/' || p.club_id || '?post=' || p.id;
  if v_to is not null then
    perform private.notify(v_to, p.club_id, 'COMMENT_REPLY',
      private.display_name(v_uid) || ' đã trả lời bình luận của bạn', left(v_body, 140), v_link, v_uid, false);
  end if;
  if p.author_id is distinct from v_to then
    perform private.notify(p.author_id, p.club_id, 'POST_COMMENT',
      private.display_name(v_uid) || ' đã bình luận bài của bạn', left(v_body, 140), v_link, v_uid, false);
  end if;
  return c;
end $$;

create or replace function public.toggle_post_comment_like(p_comment_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.club_post_comments := (select x from public.club_post_comments x where x.id = p_comment_id and x.deleted_at is null);
  p public.club_posts := (select x from public.club_posts x where x.id = c.post_id);
  v_liked boolean;
  v_count integer;
begin
  if c.id is null or p.id is null or p.deleted_at is not null then raise exception 'COMMENT_NOT_FOUND'; end if;
  if not private.can_engage_post(p) then raise exception 'NOT_A_MEMBER'; end if;
  if exists (select 1 from public.club_comment_likes l where l.comment_id = c.id and l.user_id = v_uid) then
    delete from public.club_comment_likes where comment_id = c.id and user_id = v_uid;
    v_liked := false;
  else
    insert into public.club_comment_likes (comment_id, user_id) values (c.id, v_uid) on conflict do nothing;
    v_liked := true;
    if not exists (select 1 from public.notifications n where n.user_id = c.author_id and n.actor_id = v_uid and n.kind = 'COMMENT_LIKE'
                     and n.link = '/clubs/' || p.club_id || '?post=' || p.id and n.created_at > now() - interval '1 day') then
      perform private.notify(c.author_id, p.club_id, 'COMMENT_LIKE', private.display_name(v_uid) || ' đã thích bình luận của bạn',
        left(c.body, 140), '/clubs/' || p.club_id || '?post=' || p.id, v_uid, false);
    end if;
  end if;
  v_count := (select count(*) from public.club_comment_likes l where l.comment_id = c.id);
  update public.club_post_comments set like_count = v_count where id = c.id;
  return jsonb_build_object('liked', v_liked, 'count', v_count);
end $$;

create or replace function public.send_gift(
  p_to_user uuid, p_gift_code text, p_qty integer default 1, p_message text default null, p_post_id uuid default null,
  p_activity_id uuid default null, p_idempotency_key text default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  g public.gift_catalog := (select x from public.gift_catalog x where x.code = p_gift_code);
  v_qty integer := coalesce(p_qty, 1);
  v_total integer;
  v_list integer;
  v_msg text := nullif(trim(coalesce(p_message, '')), '');
  v_club uuid;
  v_author uuid;
  v_act uuid;
  v_id uuid := (select c.id from public.cheers c where c.idempotency_key = p_idempotency_key);
  v_sent numeric;
  v_name text;
  o jsonb;
  v_promo uuid;
begin
  if p_idempotency_key is null or length(p_idempotency_key) < 8 then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
  if v_id is not null then return jsonb_build_object('gift_id', v_id, 'duplicate', true); end if;
  if g.code is null or not g.is_active or not private.gift_in_season(g, private.vn_day(now())) then raise exception 'GIFT_NOT_AVAILABLE'; end if;
  if g.vip_tier > private.user_vip_tier(v_uid) then raise exception 'VIP_REQUIRED'; end if;
  if v_qty not in (1, 5, 10, 99) then raise exception 'INVALID_QTY'; end if;
  if p_to_user is null or p_to_user = v_uid then raise exception 'CANNOT_GIFT_SELF'; end if;
  if not exists (select 1 from public.profiles where id = p_to_user) then raise exception 'USER_NOT_FOUND'; end if;
  if v_msg is not null and char_length(v_msg) > 140 then raise exception 'MESSAGE_TOO_LONG'; end if;
  if p_post_id is not null then
    v_club := (select cp.club_id from public.club_posts cp where cp.id = p_post_id and cp.deleted_at is null);
    v_author := (select cp.author_id from public.club_posts cp where cp.id = p_post_id and cp.deleted_at is null);
    if v_club is null or not private.can_engage_post((select cp from public.club_posts cp where cp.id = p_post_id)) or v_author is distinct from p_to_user then raise exception 'FORBIDDEN'; end if;
  end if;
  if p_activity_id is not null and not exists (select 1 from public.activities where id = p_activity_id and user_id = p_to_user) then
    raise exception 'FORBIDDEN';
  end if;
  -- Quà theo mốc: chỉ tặng trên bài chạy của người nhận đạt đúng mốc
  if g.context is not null then
    v_act := coalesce(p_activity_id, (select cp.activity_id from public.club_posts cp where cp.id = p_post_id));
    if v_act is null or not exists (select 1 from public.activities where id = v_act and user_id = p_to_user)
       or not private.gift_context_ok(v_act, g.context) then
      raise exception 'GIFT_CONTEXT_REQUIRED';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('gift:' || v_uid, 0));
  v_list := g.price_xu * v_qty;
  o := private.item_offer(v_uid, 'GIFT', g.code, g.price_xu, v_qty);
  if o is not null and (o->>'eligible')::boolean and o->>'kind' <> 'TRIAL'
     and (o->>'left' is null or (o->>'left')::int >= v_qty) then
    v_total := (o->>'price')::int * v_qty;
    v_promo := (o->>'promo_id')::uuid;
  else
    v_total := v_list;
  end if;
  v_sent := coalesce((select sum(c.amount) from public.cheers c where c.from_user = v_uid and c.gift_code is not null
                       and c.created_at >= private.vn_start(private.vn_day(now()))), 0);
  if v_sent + v_total > coalesce((private.economy_config()->>'giftDailyCapXu')::int, 20000) then raise exception 'GIFT_DAILY_LIMIT'; end if;
  if private.balance(v_uid) < v_total then raise exception 'INSUFFICIENT_BALANCE'; end if;

  -- Đốt Xu: người tặng → hệ thống. Người nhận KHÔNG nhận Xu.
  if v_total > 0 then
    perform private.ledger_post('GIFT', 'gift:' || p_idempotency_key, 'Tặng ' || v_qty || ' × ' || g.name || ' cho ' || private.display_name(p_to_user), v_uid,
      private.debit_entries(v_uid, v_total, private.system_account()));
  end if;
  v_id := gen_random_uuid();
  insert into public.cheers (id, from_user, to_user, amount, list_amount, promo_id, message, activity_id, post_id, club_id, idempotency_key, gift_code, qty)
  values (v_id, v_uid, p_to_user, v_total, v_list, v_promo, v_msg, p_activity_id, p_post_id, v_club, p_idempotency_key, g.code, v_qty);
  if v_promo is not null then
    insert into public.item_promo_redemptions (promo_id, user_id, qty, xu_paid, ref) values (v_promo, v_uid, v_qty, v_total, 'gift:' || p_idempotency_key);
  end if;
  if p_post_id is not null then update public.club_posts set cheer_xu = cheer_xu + v_total where id = p_post_id; end if;

  v_name := private.display_name(v_uid);
  perform private.award(p_to_user, 'GIFT_IN', v_name || ' tặng bạn ' || case when v_qty > 1 then v_qty || ' × ' else '' end || g.emoji || ' ' || g.name,
    v_msg, 0, 0, 'gift_in:' || v_id, p_activity_id, jsonb_build_object('from', v_uid, 'gift', g.code, 'emoji', g.emoji, 'qty', v_qty, 'tier', g.tier,
      'kind', g.kind, 'art_url', g.art_url));
  perform private.notify(p_to_user, v_club, 'GIFT', v_name || ' tặng bạn ' || case when v_qty > 1 then v_qty || ' × ' else '' end || g.emoji || ' ' || g.name,
    coalesce(v_msg, g.description), case when p_activity_id is not null then '/activities/' || p_activity_id
                                         when v_club is not null then '/clubs/' || v_club else '/me' end, v_uid, g.kind = 'ANIMATED');
  return jsonb_build_object('gift_id', v_id, 'total_xu', v_total, 'list_xu', v_list, 'emoji', g.emoji, 'tier', g.tier, 'kind', g.kind,
    'art_url', g.art_url, 'price_xu', g.price_xu, 'qty', v_qty, 'balance', private.balance(v_uid));
end $$;
-- ---------------------------------------------------------------------
-- 2. Bài chạy chờ duyệt: báo người chạy kèm lý do + giải trình
-- ---------------------------------------------------------------------
alter table public.activities add column if not exists owner_note text;
alter table public.activities add column if not exists owner_note_at timestamptz;

/** Lý do chờ duyệt viết cho người chạy: bỏ phần "Mức nghi vấn: …." đầu câu và câu "Bài được tính sau khi…" cuối câu */
create or replace function private.pending_reason_text(p_reason text) returns text
language sql immutable as $$
  select nullif(trim(regexp_replace(regexp_replace(coalesce(p_reason, ''), '^Mức nghi vấn: [^.]*\.\s*', ''), '\s*Bài được tính sau khi.*$', '')), '')
$$;

create or replace function private.run_pending_notify() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_reason text;
begin
  if new.validation_status is distinct from 'PENDING' or new.user_id is null then return new; end if;
  if tg_op = 'UPDATE' and old.validation_status is not distinct from 'PENDING' then return new; end if;
  -- Bài ghi trong app: người chạy thấy ngay trên màn hình kết quả. Bài cũ / bài trước khi kết nối: không báo.
  if new.source = 'DIRECT_GPS' or new.rewarded_at is not null or coalesce(new.started_at, now()) < now() - interval '2 days' then return new; end if;
  begin
    -- validation_reason là lời báo ngắn cho người chạy (friendly_review, 009700); không có thì dùng lý do chi tiết của hệ thống
    v_reason := coalesce(private.pending_reason_text(new.validation_reason), private.pending_reason_text(new.review_detail),
                         'Dữ liệu bài chạy cần được xác minh.');
    perform private.notify(new.user_id, null, 'RUN_PENDING',
      'Bài chạy "' || left(coalesce(nullif(new.title, ''), 'Buổi chạy'), 60) || '" đang chờ xác minh',
      left(v_reason, 200) || ' Bạn có thể gửi giải trình ngay trong bài chạy.', '/activities/' || new.id, null, true);
  exception when others then
    raise warning 'run_pending_notify % lỗi: % %', new.id, sqlstate, sqlerrm;
  end;
  return new;
end $$;

drop trigger if exists trg_zz_run_pending on public.activities;
create trigger trg_zz_run_pending after insert or update of validation_status on public.activities
  for each row execute function private.run_pending_notify();

/** Người chạy giải trình cho bài đang chờ xác minh (5–500 ký tự; gửi lại thì thay bản cũ) */
create or replace function public.explain_pending_run(p_activity_id uuid, p_note text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  a public.activities := (select x from public.activities x where x.id = p_activity_id for update);
  v_note text := trim(coalesce(p_note, ''));
begin
  if a.id is null or a.user_id <> v_uid then raise exception 'FORBIDDEN'; end if;
  if a.validation_status <> 'PENDING' then raise exception 'ACTIVITY_NOT_PENDING'; end if;
  if char_length(v_note) not between 5 and 500 then raise exception 'INVALID_NOTE'; end if;
  if a.owner_note_at is not null and a.owner_note_at > now() - interval '10 seconds' then raise exception 'RATE_LIMITED'; end if;
  update public.activities set owner_note = v_note, owner_note_at = now() where id = a.id;
  return jsonb_build_object('owner_note', v_note, 'owner_note_at', now());
end $$;

create or replace function public.activity_review_info(p_activity uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare a public.activities := (select x from public.activities x where x.id = p_activity);
begin
  if a.id is null or a.user_id is distinct from auth.uid() then raise exception 'FORBIDDEN'; end if;
  return jsonb_build_object('status', a.validation_status, 'reason', a.validation_reason,
    'can_accept_verified', private.can_accept_verified(a),
    'gap_distance_m', round(private.gap_meters(a.risk_flags)),
    'verified_distance_m', greatest(round(coalesce(a.distance_m, 0) - private.gap_meters(a.risk_flags)), 0),
    'owner_note', a.owner_note, 'owner_note_at', a.owner_note_at);
end $$;

create or replace function public.club_pending_activities(p_club_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.club_is_staff(p_club_id) and not public.is_system_admin() then raise exception 'FORBIDDEN'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'title', a.title, 'distance_m', a.distance_m, 'moving_time_s', a.moving_time_s,
      'started_at', a.started_at, 'created_at', a.created_at, 'source', a.source,
      'validation_reason', coalesce(a.review_detail, a.validation_reason), 'risk_score', a.risk_score, 'risk_level', a.risk_level, 'risk_flags', a.risk_flags,
      'user_id', a.user_id, 'can_review', a.user_id <> auth.uid(), 'owner_note', a.owner_note,
      'profiles', jsonb_build_object('display_name', pr.display_name, 'avatar_url', pr.avatar_url))
      order by a.created_at desc), '[]'::jsonb)
    from public.activities a
    join public.club_members m on m.user_id = a.user_id and m.club_id = p_club_id and m.status = 'APPROVED'
    join public.profiles pr on pr.id = a.user_id
   where a.validation_status = 'PENDING' and coalesce(a.status, '') <> 'DELETED'
     and (a.shared or public.is_system_admin()));
end $$;

-- ---------------------------------------------------------------------
-- 3. Vinh danh theo cự ly (bản 004900 + hạng mục DIST<mét>)
-- ---------------------------------------------------------------------
create or replace function private.honor_compute(c public.challenges, p_cats jsonb)
returns table (category text, rank integer, user_id uuid, value numeric)
language plpgsql stable security definer set search_path = public as $$
declare
  cat jsonb;
  k text;
  n int;
  v_len interval := c.end_date - c.start_date;
begin
  for cat in select * from jsonb_array_elements(coalesce(p_cats, '[]'::jsonb)) loop
    k := cat->>'key';
    n := least(10, greatest(1, coalesce((cat->>'count')::int, 3)));
    if k = 'TOP' then
      return query select k, x.rn::int, x.pid, x.v from (
        select p.profile_id as pid, p.current_progress as v,
               row_number() over (order by p.current_progress desc, p.completed_at asc nulls last, p.joined_at) as rn
          from public.challenge_participants p
         where p.challenge_id = c.id and p.status <> 'LEFT' and p.current_progress > 0) x where x.rn <= n;
    elsif k = 'KM' then
      return query select k, x.rn::int, x.pid, x.v from (
        select p.profile_id as pid, round(p.distance_m / 1000.0, 2) as v,
               row_number() over (order by p.distance_m desc, p.joined_at) as rn
          from public.challenge_participants p
         where p.challenge_id = c.id and p.status <> 'LEFT' and p.distance_m > 0) x where x.rn <= n;
    elsif k = 'DAYS' then
      return query select k, x.rn::int, x.pid, x.v from (
        select p.profile_id as pid, p.streak_days::numeric as v,
               row_number() over (order by p.streak_days desc, p.distance_m desc) as rn
          from public.challenge_participants p
         where p.challenge_id = c.id and p.status <> 'LEFT' and p.streak_days > 0) x where x.rn <= n;
    elsif k = 'STREAK' then
      -- chuỗi ngày chạy liên tiếp dài nhất (khoảng trống & đảo)
      return query select k, x.rn::int, x.pid, x.v from (
        select s.pid, s.best::numeric as v, row_number() over (order by s.best desc, s.km desc) as rn
          from (select g.pid, max(g.len) as best, max(g.km) as km
                  from (select d.pid, d.km, count(*) over (partition by d.pid, d.grp) as len
                          from (select p.profile_id as pid, p.distance_m as km, e.day,
                                       e.day - (row_number() over (partition by p.id order by e.day))::int as grp
                                  from public.challenge_participants p
                                  join (select distinct participant_id, day from public.challenge_progress_events where challenge_id = c.id) e
                                    on e.participant_id = p.id
                                 where p.challenge_id = c.id and p.status <> 'LEFT') d) g
                 group by g.pid) s
         where s.best >= 2) x where x.rn <= n;
    elsif k = 'BREAKTHROUGH' then
      -- km trong thử thách trừ km cùng độ dài trước khi bắt đầu; cần ≥ 5 km trong thử thách
      return query select k, x.rn::int, x.pid, x.v from (
        select b.pid, round(b.gain, 2) as v, row_number() over (order by b.gain desc) as rn
          from (select p.profile_id as pid,
                       p.distance_m / 1000.0 - coalesce((select sum(coalesce(a.moving_distance_m, a.distance_m)) / 1000.0 from public.activities a
                                                           where a.user_id = p.profile_id and a.validation_status = 'APPROVED'
                                                             and a.started_at >= c.start_date - v_len and a.started_at < c.start_date), 0) as gain
                  from public.challenge_participants p
                 where p.challenge_id = c.id and p.status <> 'LEFT' and p.distance_m >= 5000) b
         where b.gain > 0) x where x.rn <= n;
    elsif k = 'SUPPORTED' then
      return query select k, x.rn::int, x.pid, x.v from (
        select t.pid, t.s as v, row_number() over (order by t.s desc) as rn
          from (select cp.profile_id as pid, sum(ch.amount) as s
                  from public.challenge_participants cp
                  join public.cheers ch on ch.to_user = cp.profile_id and ch.gift_code is not null
                                       and ch.created_at >= c.start_date and ch.created_at < c.end_date
                 where cp.challenge_id = c.id and cp.status <> 'LEFT'
                 group by cp.profile_id) t) x where x.rn <= n;
    elsif k ~ '^DIST[0-9]{3,6}$' then
      -- 013100: vinh danh theo cự ly — bài tốt nhất có cự ly ≥ D trong thời gian thử thách, thời gian quy đổi theo pace trung bình
      -- (cách tính như Chinh phục thời gian / Giải chạy). VD bài 21,3 km trong 1:52:00 tính cho 21,097 km là 1:50:56.
      return query select k, x.rn::int, x.pid, x.v from (
        select b.pid, b.best as v, row_number() over (order by b.best, b.at) as rn
          from (select p.profile_id as pid,
                       min(round(a.mt * substr(k, 5)::numeric / a.dist)) as best, min(a.started_at) as at
                  from public.challenge_participants p
                  join (select x.user_id, x.started_at, coalesce(nullif(x.moving_distance_m, 0), x.distance_m) as dist,
                               coalesce(nullif(x.moving_time_s, 0), x.elapsed_time_s) as mt
                          from public.activities x
                         where x.started_at >= c.start_date and x.started_at < c.end_date
                           and x.validation_status = 'APPROVED' and public.activity_is_countable(x.status, x.validation_status)) a
                    on a.user_id = p.profile_id and a.dist >= substr(k, 5)::numeric and a.mt > 0
                 where p.challenge_id = c.id and p.status <> 'LEFT'
                 group by p.profile_id) b) x where x.rn <= n;
    elsif k like 'CUSTOM%' then
      return query select k, x.ord::int, x.pid, null::numeric from (
        select u.v::uuid as pid, u.ord
          from jsonb_array_elements_text(coalesce(cat->'users', '[]'::jsonb)) with ordinality as u(v, ord)
         where exists (select 1 from public.challenge_participants p where p.challenge_id = c.id and p.profile_id = u.v::uuid and p.status <> 'LEFT')) x
       where x.ord <= 10;
    end if;
  end loop;
end $$;

create or replace function private.honor_categories(p jsonb) returns jsonb
language plpgsql immutable as $$
declare v_out jsonb := '[]'::jsonb; cat jsonb; k text; seen text[] := '{}';
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 8 then raise exception 'INVALID_HONOR_CATEGORIES'; end if;
  for cat in select * from jsonb_array_elements(p) loop
    k := cat->>'key';
    if k is null or not (k = any (array['TOP', 'KM', 'DAYS', 'STREAK', 'BREAKTHROUGH', 'SUPPORTED']) or k ~ '^CUSTOM[1-5]$'
                         or (k ~ '^DIST[0-9]{3,6}$' and substr(k, 5)::int between 400 and 250000)) or k = any (seen) then
      raise exception 'INVALID_HONOR_CATEGORIES';
    end if;
    if k like 'CUSTOM%' and (jsonb_typeof(coalesce(cat->'users', '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(cat->'users', '[]'::jsonb)) > 10
        or exists (select 1 from jsonb_array_elements_text(coalesce(cat->'users', '[]'::jsonb)) u where u !~ '^[0-9a-fA-F-]{36}$')) then
      raise exception 'INVALID_HONOR_CATEGORIES';
    end if;
    seen := seen || k;
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'key', k,
      'title', coalesce(nullif(left(trim(coalesce(cat->>'title', '')), 60), ''), k),
      'count', least(10, greatest(1, coalesce(private.bib_num(cat->'count', 1, 10, 3), 3)))::int,
      'users', case when k like 'CUSTOM%' then coalesce(cat->'users', '[]'::jsonb) else null end));
  end loop;
  return v_out;
end $$;
-- ---------------------------------------------------------------------
-- 4. Sửa thử thách trước khi bắt đầu
-- ---------------------------------------------------------------------
create or replace function public.update_challenge(p_challenge_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.challenges;
  v_title text;
  v_desc text;
  v_target numeric;
  v_min_km numeric;
  v_min_pace numeric;
  v_max_pace numeric;
  v_cap numeric;
  v_start timestamptz;
  v_end timestamptz;
  m record;
begin
  perform 1 from public.challenges where id = p_challenge_id for update;
  c := (select x from public.challenges x where x.id = p_challenge_id);
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not private.challenge_is_manager(c) then raise exception 'FORBIDDEN'; end if;
  if c.status <> 'ACTIVE' then raise exception 'CHALLENGE_CLOSED'; end if;
  if now() >= c.start_date then raise exception 'CHALLENGE_STARTED'; end if;

  v_title := trim(coalesce(p->>'title', c.title));
  v_desc := case when p ? 'description' then nullif(trim(coalesce(p->>'description', '')), '') else c.description end;
  v_target := coalesce((p->>'target_value')::numeric, c.target_value);
  v_min_km := coalesce((p->>'min_km')::numeric, c.min_km);
  v_min_pace := coalesce((p->>'min_pace')::numeric, c.min_pace);
  v_max_pace := coalesce((p->>'max_pace')::numeric, c.max_pace);
  v_cap := case when p ? 'daily_cap_km' then nullif((p->>'daily_cap_km')::numeric, 0) else c.daily_cap_km end;
  v_start := coalesce((p->>'start_date')::timestamptz, c.start_date);
  v_end := coalesce((p->>'end_date')::timestamptz, c.end_date);

  -- Kiểm tra như lúc tạo (create_challenge_v2)
  if char_length(v_title) not between 3 and 120 then raise exception 'INVALID_TITLE'; end if;
  if v_desc is not null and char_length(v_desc) > 2000 then raise exception 'DESC_TOO_LONG'; end if;
  if v_end <= v_start or v_end - v_start < interval '1 hour' then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_start < now() then raise exception 'INVALID_TIME_RANGE'; end if;
  if c.format = 'TEAM' and v_start < now() + interval '10 minutes' then raise exception 'TEAM_START_TOO_SOON'; end if;
  -- Phí khởi tạo đã trả theo thời lượng: không cho kéo dài hơn
  if v_end - v_start > c.end_date - c.start_date then raise exception 'DURATION_TOO_LONG'; end if;
  if v_target < 0 or v_min_km < 0 or v_min_km > 100 or coalesce(v_cap, 0) < 0 then raise exception 'INVALID_DISTANCE'; end if;
  if v_min_pace <= 0 or v_max_pace < v_min_pace or v_max_pace > 30 then raise exception 'INVALID_PACE'; end if;
  if c.format in ('SOLO_GOAL', 'COLLECTIVE') and c.objective not in ('BEST_TIME', 'BEST_PACE') and v_target <= 0 then raise exception 'TARGET_REQUIRED'; end if;
  if c.objective = 'STREAK_DAYS' and (v_min_km <= 0 or v_target > ceil(extract(epoch from v_end - v_start) / 86400)) then
    raise exception 'INVALID_STREAK';
  end if;

  update public.challenges
     set title = v_title, description = v_desc, target_value = v_target,
         target_km = case when objective = 'DISTANCE' then v_target else target_km end,
         min_km = v_min_km, min_pace = v_min_pace, max_pace = v_max_pace, daily_cap_km = v_cap,
         start_date = v_start, end_date = v_end,
         reg_deadline = case when format = 'TEAM' then least(coalesce(reg_deadline, v_start), v_start)
                             when reg_deadline is null or reg_deadline = c.end_date or reg_deadline > v_end then v_end
                             else reg_deadline end
   where id = c.id;

  -- Bài giới thiệu thử thách trên bảng tin CLB
  update public.club_posts
     set title = v_title, body = coalesce(v_desc, ''),
         meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('target_value', v_target, 'start_date', v_start, 'end_date', v_end)
   where kind = 'CHALLENGE' and deleted_at is null and meta->>'challenge_id' = c.id::text;

  for m in select profile_id from public.challenge_participants
            where challenge_id = c.id and profile_id is not null and coalesce(status, 'JOINED') <> 'LEFT' loop
    perform private.notify(m.profile_id, null, 'CHALLENGE_UPDATED', 'Thử thách "' || left(v_title, 80) || '" vừa được cập nhật',
      'Xem lại thời gian và luật trước khi bắt đầu.', '/challenges/' || c.id, v_uid, true);
  end loop;

  return jsonb_build_object('id', c.id, 'title', v_title, 'start_date', v_start, 'end_date', v_end);
end $$;

-- ---------------------------------------------------------------------
-- 5. Quyền
-- ---------------------------------------------------------------------
revoke all on function private.can_engage_post(public.club_posts), private.pending_reason_text(text), private.run_pending_notify()
  from public, anon, authenticated;
revoke all on function public.explain_pending_run(uuid, text), public.update_challenge(uuid, jsonb) from public, anon;
grant execute on function public.explain_pending_run(uuid, text), public.update_challenge(uuid, jsonb) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001013200_club_avatar_storage_fix.sql
-- ===================================================================
-- 013200: Chỉnh sửa lần 7 — quản trị CLB không đổi được ảnh đại diện CLB.
-- Nguyên nhân: update_club (008900) tự dọn file ảnh cũ bằng "delete from storage.objects". Supabase nay CHẶN xoá thẳng bảng
-- storage ("Direct deletion from storage tables is not allowed. Use the Storage API instead.") → cả giao dịch đổi ảnh bị huỷ,
-- ảnh mới đã tải lên cũng bị app xoá lại. Lỗi chỉ xảy ra khi CLB đã có ảnh cũ (avatar_path khác null) — đúng lúc "đổi" ảnh.
-- Sửa: bỏ việc xoá file trong SQL; app tự xoá file cũ qua Storage API (supabase.storage.remove) sau khi đổi thành công —
-- chính sách club_avatars_staff_delete (008900) vẫn chỉ cho Ban quản trị CLB xoá file trong thư mục của CLB mình.
-- Giữ nguyên chữ ký, kiểu trả về, kiểm tra quyền (chủ / đội trưởng / admin hệ thống) và quyền gọi của update_club.
-- Cần 008900. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT, không RETURNING INTO. Chạy lại an toàn.

create or replace function public.update_club(p_club_id uuid, p_name text default null, p_description text default null,
                                              p_avatar_url text default null, p_avatar_path text default null) returns public.clubs
language plpgsql security definer set search_path = public as $$
declare
  v_club public.clubs;
begin
  if coalesce(public.club_role(p_club_id), '') not in ('OWNER', 'CAPTAIN') then raise exception 'FORBIDDEN'; end if;
  if p_name is not null then
    if trim(p_name) = '' then raise exception 'NAME_REQUIRED'; end if;
    if char_length(trim(p_name)) > 60 then raise exception 'NAME_TOO_LONG'; end if;
  end if;
  if p_description is not null and char_length(p_description) > 300 then raise exception 'DESC_TOO_LONG'; end if;
  begin
    update public.clubs
       set name        = coalesce(nullif(trim(coalesce(p_name, '')), ''), name),
           description = case when p_description is null then description else nullif(trim(p_description), '') end,
           avatar_url  = case when p_avatar_url is null then avatar_url else nullif(trim(p_avatar_url), '') end,
           avatar_path = case when p_avatar_url is null then avatar_path else nullif(trim(coalesce(p_avatar_path, '')), '') end
     where id = p_club_id;
  exception when unique_violation then
    raise exception 'NAME_TAKEN';
  end;
  v_club := (select c from public.clubs c where c.id = p_club_id);
  if v_club.id is null then raise exception 'CLUB_NOT_FOUND'; end if;
  -- 013200: KHÔNG xoá file ảnh cũ ở đây (Supabase cấm xoá thẳng bảng kho ảnh) — app xoá qua Storage API
  return v_club;
end $$;

revoke execute on function public.update_club(uuid, text, text, text, text) from public, anon;
grant execute on function public.update_club(uuid, text, text, text, text) to authenticated;

-- ===================================================================
-- 20261001013300_challenge_round7.sql
-- ===================================================================
-- 013300: Chỉnh sửa lần 7 — THỬ THÁCH.
-- 1. Danh sách thử thách: thử thách theo mục tiêu tự đăng ký trả target_value = mục tiêu CỦA NGƯỜI XEM (đã đăng ký),
--    thay cho mốc thấp nhất (VD đăng ký 21 km nhưng thẻ thử thách vẫn hiện 11 km).
-- 2. Sửa thử thách TRƯỚC giờ bắt đầu — người tạo / BTC được sửa mọi hạng mục (sau giờ bắt đầu giữ luật cũ: CHALLENGE_STARTED):
--    tên, mô tả, thời gian (bỏ giới hạn thời lượng: phí khởi tạo chỉ tính theo quy mô), mục tiêu, luật km / pace, cách tính điểm,
--    cách tính đội + tên đội, số người tối đa, đối tượng (Công khai ↔ Có mã mời), thưởng Xu quỹ CLB, bắt buộc nhịp tim,
--    mục tiêu tự đăng ký (bật / tắt / đổi mốc), hạng mục chinh phục (kể cả khi đã có người đăng ký).
--    • Số người tối đa không nhỏ hơn số người đã tham gia. Tăng quy mô sang mức phí cao hơn: thu phần chênh qua sổ cái
--      (CHALLENGE_CREATION_FEE, như lúc tạo; hạn mức CLB / lượt miễn phí còn bao được thì không thu). Giảm quy mô không hoàn phí
--      (phí khởi tạo không hoàn, như khi huỷ).
--    • Đổi thưởng: phần chênh đi qua sổ cái — tăng thì ký quỹ thêm (CHALLENGE_ESCROW), giảm thì hoàn quỹ CLB (CHALLENGE_REFUND),
--      kèm nhật ký quỹ CLB. Tổng ký quỹ luôn bằng reward_xu nên tất toán / huỷ (challenge_refund_escrow) vẫn đúng.
--    • Mọi người đã tham gia nhận thông báo CHALLENGE_UPDATED; ai mất mục tiêu / hạng mục đã đăng ký được nhắc chọn lại.
-- 3. Thử thách lặp hằng tuần: tên kỳ mới lấy số tuần ISO của kỳ mới ("Thử thách tuần 41" → "Thử thách tuần 42"),
--    không thêm "· Kỳ 2". Kỳ mới của thử thách chinh phục chép luôn các hạng mục.
-- 4. Vinh danh theo mục tiêu BTC đặt: GOAL<mét> (người chọn mục tiêu đó và đã hoàn thành) và CAT<thứ tự> (hạng mục chinh phục,
--    người đạt, kết quả nhanh nhất trước).
-- 5. Chinh phục cá nhân: đã đăng ký rồi mà có kết quả cho một cự ly (bài ≥ cự ly trong thời gian thử thách) thì không sửa đăng ký
--    cự ly đó nữa — không thêm, không đổi mục tiêu, không bỏ (CONQUEST_RESULT_LOCKED). Lần đăng ký đầu (tham gia trễ) vẫn như cũ:
--    mọi bài từ ngày bắt đầu đều được tính.
-- Cần 013100. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT, không RETURNING INTO. Chạy lại an toàn.

-- ---------------------------------------------------------------------
-- 1. Danh sách: mục tiêu của chính người xem (bản 005400)
-- ---------------------------------------------------------------------
create or replace function public.list_challenges(p_tab text default 'MINE', p_club_id uuid default null)
returns table (
  id uuid, title text, description text, format text, objective text, game_mode text, target_value numeric,
  start_date timestamptz, end_date timestamptz, status text, target_audience text, target_club_id uuid,
  club_name text, club_accent text, reward_xu numeric, participant_count integer, max_slots integer,
  my_status text, my_score numeric, my_rank integer, total_score numeric, created_by uuid
)
language sql stable security definer set search_path = public as $$
  with base as (
    select c.*,
           (select count(*)::int from public.challenge_participants p where p.challenge_id = c.id and p.status <> 'LEFT') as n,
           (select coalesce(sum(p.current_progress), 0) from public.challenge_participants p where p.challenge_id = c.id and p.status <> 'LEFT') as total,
           me.status as my_status, me.current_progress as my_score,
           case when me.status <> 'LEFT' then me.pledge_km end as my_pledge,
           case when me.id is not null then (select count(*)::int + 1 from public.challenge_participants o
                  where o.challenge_id = c.id and o.status <> 'LEFT' and o.current_progress > me.current_progress) end as my_rank
      from public.challenges c
      left join public.challenge_participants me on me.challenge_id = c.id and me.profile_id = auth.uid()
     where c.status in ('ACTIVE', 'FINISHED', 'CANCELLED')
       and case upper(coalesce(p_tab, 'MINE'))
         when 'MINE' then c.status <> 'CANCELLED'
                          and ((me.id is not null and me.status <> 'LEFT') or c.created_by = auth.uid())
                          and (c.status = 'ACTIVE' or c.end_date > now() - interval '30 days')
         when 'DISCOVER' then c.target_audience = 'PUBLIC' and c.status = 'ACTIVE' and c.end_date > now()
                          and (c.format <> 'TEAM' or c.start_date > now())
                          and (me.id is null or me.status = 'LEFT')
         when 'CLUB' then c.status <> 'CANCELLED'
                          and c.target_audience = 'CLUB_ONLY' and public.club_is_member(c.target_club_id)
                          and (p_club_id is null or c.target_club_id = p_club_id)
                          and (c.status = 'ACTIVE' or c.end_date > now() - interval '60 days')
         when 'ENDED' then me.id is not null and (c.status <> 'ACTIVE' or c.end_date <= now())
         else false end
  ), ranked as (
    select b.*, row_number() over (
             order by (b.status = 'ACTIVE' and b.end_date > now()) desc,
                      case when upper(coalesce(p_tab, 'MINE')) = 'DISCOVER' then -b.n else 0 end,
                      b.end_date) as rn
      from base b
  )
  select b.id, b.title, b.description, b.format, b.objective, b.game_mode,
         -- 013300: thử thách tự đăng ký mục tiêu → mục tiêu người xem đã chọn (chưa chọn: mốc thấp nhất như cũ)
         case when coalesce(b.pledge_enabled, false) and b.my_pledge is not null then b.my_pledge else b.target_value end,
         b.start_date, b.end_date,
         b.status, b.target_audience, b.target_club_id, cl.name, cl.accent_color, b.reward_xu, b.n, b.max_slots,
         b.my_status, b.my_score, b.my_rank, round(b.total, 2), b.created_by
    from ranked b left join public.clubs cl on cl.id = b.target_club_id
   where b.rn <= 60
   order by b.rn
$$;

-- ---------------------------------------------------------------------
-- 2. Sửa thử thách trước giờ bắt đầu: toàn quyền (bản 013100 mở rộng)
-- ---------------------------------------------------------------------
-- Mục tiêu tự đăng ký (bản 002200): trước giờ bắt đầu, ai có mục tiêu không còn hợp lệ với mốc mới thì bỏ mục tiêu + nhắc chọn lại
create or replace function public.set_challenge_pledge(p_challenge_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.challenges := (select x from public.challenges x where x.id = p_challenge_id);
  v_opts numeric[];
  v_min numeric := nullif((p->>'min_km')::numeric, 0);
  v_max numeric := nullif((p->>'max_km')::numeric, 0);
  v_cap numeric := (p->>'cap_pct')::numeric;
  v_size integer := nullif((p->>'team_size')::int, 0);
  m record;
begin
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not private.challenge_is_manager(c) then raise exception 'FORBIDDEN'; end if;
  if c.status <> 'ACTIVE' or now() >= c.end_date then raise exception 'CHALLENGE_CLOSED'; end if;
  if c.objective <> 'DISTANCE' or c.format not in ('SOLO_GOAL', 'TEAM') then raise exception 'PLEDGE_NOT_SUPPORTED'; end if;
  -- Đã có người đăng ký mục tiêu và đã xuất phát → không đổi luật giữa chừng
  if now() >= c.start_date and exists (select 1 from public.challenge_participants x
                                         where x.challenge_id = c.id and x.pledge_km is not null) then
    raise exception 'PLEDGE_RULES_LOCKED';
  end if;

  v_opts := (select array_agg(v order by v) from (
               select distinct round((e)::numeric, 1) as v from jsonb_array_elements_text(coalesce(p->'options', '[]'::jsonb)) as t(e)) s);
  if v_opts is not null and (array_length(v_opts, 1) > 8 or v_opts[1] <= 0 or v_opts[array_length(v_opts, 1)] > 5000) then
    raise exception 'INVALID_PLEDGE_OPTIONS';
  end if;
  if v_opts is null and (v_min is null or v_max is null or v_min > v_max or v_max > 5000) then
    raise exception 'INVALID_PLEDGE_OPTIONS';
  end if;
  if v_cap is not null and (v_cap < 0 or v_cap > 500) then raise exception 'INVALID_PLEDGE_CAP'; end if;
  if v_size is not null and (c.format <> 'TEAM' or v_size < 2 or v_size > 50) then raise exception 'INVALID_TEAM_SIZE'; end if;

  update public.challenges
     set pledge_enabled = true, pledge_options = v_opts,
         pledge_min_km = case when v_opts is null then v_min end, pledge_max_km = case when v_opts is null then v_max end,
         pledge_cap_pct = v_cap, pledge_team_size = v_size,
         game_mode = case when format = 'TEAM' then 'TEAM_SUM' else game_mode end,
         reward_split = case when format = 'SOLO_GOAL' then 'FINISHERS' else reward_split end
   where id = c.id;

  -- 013300: mục tiêu cũ không còn trong mốc mới → bỏ, nhắc người đó chọn lại (chỉ xảy ra trước giờ bắt đầu)
  for m in select x.id, x.profile_id from public.challenge_participants x
            where x.challenge_id = c.id and x.status <> 'LEFT' and x.pledge_km is not null
              and case when v_opts is not null then not (x.pledge_km = any (v_opts)) else x.pledge_km < v_min or x.pledge_km > v_max end loop
    update public.challenge_participants set pledge_km = null, pledged_at = null, updated_at = now() where id = m.id;
    perform private.notify(m.profile_id, c.target_club_id, 'CHALLENGE_UPDATED', 'Chọn lại mục tiêu: ' || left(c.title, 80),
      'Ban tổ chức đã đổi các mục tiêu, mục tiêu cũ của bạn không còn. Vào chọn mục tiêu mới trước giờ bắt đầu.',
      '/challenges/' || c.id, v_uid, true);
  end loop;
  perform private.challenge_recompute_all(c.id);
  return jsonb_build_object('options', v_opts, 'min_km', v_min, 'max_km', v_max, 'cap_pct', v_cap, 'team_size', v_size);
end $$;

-- Hạng mục chinh phục (bản 010700): trước giờ bắt đầu sửa được cả khi đã có người đăng ký.
-- Hạng mục giữ nguyên cự ly thì giữ đăng ký; đổi cự ly / bỏ hạng mục / đổi kiểu (thời gian ↔ pace, BTC đặt ↔ tự đặt) thì
-- đăng ký liên quan bị xoá và người đó được nhắc chọn lại. Sau giờ bắt đầu: đã có người đăng ký thì khoá như cũ.
create or replace function public.set_challenge_conquest(p_challenge_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.challenges := (select x from public.challenges x where x.id = p_challenge_id);
  v_obj text := upper(coalesce(p->>'objective', ''));
  v_mode text := upper(coalesce(p->>'mode', 'FIXED'));
  v_cats jsonb := case when jsonb_typeof(p->'categories') = 'array' then p->'categories' else '[]'::jsonb end;
  v_n integer := jsonb_array_length(case when jsonb_typeof(p->'categories') = 'array' then p->'categories' else '[]'::jsonb end);
  v_min_m numeric;
  v_before uuid[];
  m record;
begin
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not private.challenge_is_manager(c) then raise exception 'FORBIDDEN'; end if;
  if c.status <> 'ACTIVE' or now() >= c.end_date then raise exception 'CHALLENGE_CLOSED'; end if;
  if c.format <> 'SOLO_GOAL' then raise exception 'CONQUEST_NOT_SUPPORTED'; end if;
  if v_obj not in ('BEST_TIME', 'BEST_PACE') or v_mode not in ('FIXED', 'SELF') then raise exception 'INVALID_CONQUEST'; end if;
  if v_n not between 1 and 8 then raise exception 'INVALID_CONQUEST'; end if;
  if now() >= c.start_date and exists (select 1 from public.challenge_category_entries e where e.challenge_id = c.id) then
    raise exception 'CONQUEST_LOCKED';
  end if;
  begin
    if exists (select 1 from jsonb_array_elements(v_cats) x
                where char_length(trim(coalesce(x->>'label', ''))) not between 1 and 40
                   or (x->>'distance_km')::numeric not between 0.4 and 250
                   or (v_mode = 'FIXED' and coalesce((x->>'target_s')::int, 0) <= 0)
                   or (v_mode = 'FIXED' and v_obj = 'BEST_PACE' and (x->>'target_s')::int not between 120 and 1500)
                   or (v_mode = 'FIXED' and v_obj = 'BEST_TIME' and (x->>'target_s')::int not between 60 and 172800)) then
      raise exception 'INVALID_CONQUEST';
    end if;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'INVALID_CONQUEST';
  end;

  -- Ai đang có đăng ký (để nhắc nếu mất)
  v_before := (select coalesce(array_agg(distinct e.user_id), '{}') from public.challenge_category_entries e where e.challenge_id = c.id);
  -- Đổi kiểu tính / ai đặt mục tiêu: mục tiêu tự đặt cũ không còn ý nghĩa
  if c.objective is distinct from v_obj or c.conquest_mode is distinct from v_mode then
    delete from public.challenge_category_entries where challenge_id = c.id;
  end if;
  -- Hạng mục bị bỏ (vị trí > số hạng mục mới) — xoá kèm đăng ký
  delete from public.challenge_categories where challenge_id = c.id and position > v_n;
  -- Hạng mục đổi cự ly: bỏ đăng ký của hạng mục đó
  delete from public.challenge_category_entries e
   using public.challenge_categories cat, jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where e.category_id = cat.id and cat.challenge_id = c.id and cat.position = t.ord
     and cat.distance_m <> round((t.x->>'distance_km')::numeric * 1000);
  update public.challenge_categories cat
     set label = trim(t.x->>'label'), distance_m = round((t.x->>'distance_km')::numeric * 1000),
         target_s = case when v_mode = 'FIXED' then (t.x->>'target_s')::int end
    from jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where cat.challenge_id = c.id and cat.position = t.ord;
  insert into public.challenge_categories (challenge_id, position, label, distance_m, target_s)
  select c.id, t.ord, trim(t.x->>'label'), round((t.x->>'distance_km')::numeric * 1000),
         case when v_mode = 'FIXED' then (t.x->>'target_s')::int end
    from jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where not exists (select 1 from public.challenge_categories x where x.challenge_id = c.id and x.position = t.ord);

  v_min_m := (select min(distance_m) from public.challenge_categories where challenge_id = c.id);
  update public.challenges
     set objective = v_obj, conquest_mode = v_mode, target_value = 1, target_type = v_obj, target_km = 0,
         pledge_enabled = false, reward_split = 'FINISHERS', game_mode = 'ACCUMULATE',
         -- bài ngắn hơn hạng mục nhỏ nhất không thể cho kết quả → không cần ghi nhận
         min_km = round(v_min_m * 0.99 / 1000.0, 2)
   where id = c.id;
  update public.challenge_participants set pledge_km = null where challenge_id = c.id and pledge_km is not null;

  for m in select u.uid from unnest(v_before) as u(uid)
            where not exists (select 1 from public.challenge_category_entries e where e.challenge_id = c.id and e.user_id = u.uid) loop
    perform private.notify(m.uid, c.target_club_id, 'CHALLENGE_UPDATED', 'Chọn lại hạng mục: ' || left(c.title, 80),
      'Ban tổ chức đã đổi các hạng mục chinh phục, đăng ký cũ của bạn không còn. Vào chọn lại trước giờ bắt đầu.',
      '/challenges/' || c.id, v_uid, true);
  end loop;
  perform private.challenge_recompute_all(c.id);
  return public.challenge_conquest_board(c.id);
end $$;

create or replace function public.update_challenge(p_challenge_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid uuid := private.require_uid();
  c public.challenges;
  v_title text;
  v_desc text;
  v_target numeric;
  v_min_km numeric;
  v_min_pace numeric;
  v_max_pace numeric;
  v_cap numeric;
  v_start timestamptz;
  v_end timestamptz;
  v_objective text;
  v_conquest boolean;
  v_pledge boolean;
  v_mode text;
  v_slots integer;
  v_joined integer;
  v_audience text;
  v_reward numeric;
  v_diff numeric;
  v_require_hr boolean;
  v_fee integer;
  v_extra integer := 0;
  v_free boolean := false;
  v_quota jsonb;
  v_payer uuid;
  v_names text[];
  v_code text;
  m record;
begin
  perform 1 from public.challenges where id = p_challenge_id for update;
  c := (select x from public.challenges x where x.id = p_challenge_id);
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not private.challenge_is_manager(c) then raise exception 'FORBIDDEN'; end if;
  if c.status <> 'ACTIVE' then raise exception 'CHALLENGE_CLOSED'; end if;
  -- Sau giờ bắt đầu: giữ luật cũ, không sửa được nữa
  if now() >= c.start_date then raise exception 'CHALLENGE_STARTED'; end if;

  v_title := trim(coalesce(p->>'title', c.title));
  v_desc := case when p ? 'description' then nullif(trim(coalesce(p->>'description', '')), '') else c.description end;
  v_target := coalesce((p->>'target_value')::numeric, c.target_value);
  v_min_km := coalesce((p->>'min_km')::numeric, c.min_km);
  v_min_pace := coalesce((p->>'min_pace')::numeric, c.min_pace);
  v_max_pace := coalesce((p->>'max_pace')::numeric, c.max_pace);
  v_cap := case when p ? 'daily_cap_km' then nullif((p->>'daily_cap_km')::numeric, 0) else c.daily_cap_km end;
  v_start := coalesce((p->>'start_date')::timestamptz, c.start_date);
  v_end := coalesce((p->>'end_date')::timestamptz, c.end_date);
  v_conquest := case when jsonb_typeof(p->'conquest') = 'object' then true
                     when p ? 'objective' then upper(p->>'objective') in ('BEST_TIME', 'BEST_PACE')
                     else c.objective in ('BEST_TIME', 'BEST_PACE') end;
  v_objective := case when jsonb_typeof(p->'conquest') = 'object' then upper(coalesce(p->'conquest'->>'objective', ''))
                      else upper(coalesce(nullif(p->>'objective', ''), c.objective)) end;
  v_pledge := case when p ? 'pledge' then jsonb_typeof(p->'pledge') = 'object' else coalesce(c.pledge_enabled, false) end;
  v_require_hr := coalesce((p->>'require_hr')::boolean, c.require_hr);
  v_reward := round(coalesce((p->>'reward_xu')::numeric, c.reward_xu, 0), 1);
  v_audience := upper(coalesce(nullif(p->>'audience', ''), c.target_audience));

  -- Kiểm tra như lúc tạo (create_challenge_v2)
  if char_length(v_title) not between 3 and 120 then raise exception 'INVALID_TITLE'; end if;
  if v_desc is not null and char_length(v_desc) > 2000 then raise exception 'DESC_TOO_LONG'; end if;
  if v_end <= v_start or v_end - v_start < interval '1 hour' or v_end - v_start > interval '366 days' then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_start < now() then raise exception 'INVALID_TIME_RANGE'; end if;
  if c.format = 'TEAM' and v_start < now() + interval '10 minutes' then raise exception 'TEAM_START_TOO_SOON'; end if;
  if v_target < 0 or v_min_km < 0 or v_min_km > 100 or coalesce(v_cap, 0) < 0 then raise exception 'INVALID_DISTANCE'; end if;
  if v_min_pace <= 0 or v_max_pace < v_min_pace or v_max_pace > 30 then raise exception 'INVALID_PACE'; end if;

  -- Cách tính điểm: mỗi thể thức có lựa chọn riêng (như trình tạo)
  if v_objective is distinct from c.objective and not (
       (c.format = 'SOLO_GOAL' and v_objective in ('DISTANCE', 'BEST_TIME', 'BEST_PACE', 'STREAK_DAYS'))
    or (c.format in ('RANKED', 'COLLECTIVE') and v_objective = 'DISTANCE')
    or (c.format = 'TEAM' and v_objective in ('DISTANCE', 'RUNS', 'DURATION'))
    or (c.format = 'DUEL' and v_objective in ('DISTANCE', 'RUNS', 'DURATION', 'STREAK_DAYS'))) then
    raise exception 'INVALID_OBJECTIVE';
  end if;
  -- Chuyển sang chinh phục phải kèm các hạng mục
  if v_conquest and c.objective not in ('BEST_TIME', 'BEST_PACE') and jsonb_typeof(p->'conquest') is distinct from 'object' then
    raise exception 'INVALID_CONQUEST';
  end if;
  if v_pledge and (v_conquest or v_objective <> 'DISTANCE' or c.format not in ('SOLO_GOAL', 'TEAM')) then raise exception 'PLEDGE_NOT_SUPPORTED'; end if;
  -- Đua đội theo mục tiêu ↔ đua đội thường: cách chia đội khác hẳn → tạo thử thách mới
  if c.format = 'TEAM' and v_pledge is distinct from coalesce(c.pledge_enabled, false) then raise exception 'TEAM_MODE_LOCKED'; end if;
  if c.format in ('SOLO_GOAL', 'COLLECTIVE') and not v_conquest and not v_pledge and v_target <= 0 then raise exception 'TARGET_REQUIRED'; end if;
  if v_objective = 'STREAK_DAYS' and (v_min_km <= 0 or v_target > ceil(extract(epoch from v_end - v_start) / 86400)) then
    raise exception 'INVALID_STREAK';
  end if;
  v_mode := case when c.format = 'TEAM' then case when v_pledge then 'TEAM_SUM' else coalesce(nullif(p->>'game_mode', ''), c.game_mode) end
                 when v_objective = 'STREAK_DAYS' then 'STREAK' else 'ACCUMULATE' end;
  if c.format = 'TEAM' and v_mode not in ('TEAM_SUM', 'TEAM_AVG', 'TEAM_GAP', 'LAST_MEMBER') then raise exception 'INVALID_GAME_MODE'; end if;

  -- Tên đội (đua đội thường): đổi tên đúng số đội hiện có
  if c.format = 'TEAM' and not v_pledge and jsonb_typeof(p->'team_names') = 'array' then
    v_names := array(select trim(t.v) from jsonb_array_elements_text(p->'team_names') with ordinality as t(v, ord) order by t.ord);
    if cardinality(v_names) <> (select count(*) from public.challenge_teams where challenge_id = c.id)
       or exists (select 1 from unnest(v_names) as t(v) where char_length(t.v) not between 1 and 40)
       or (select count(distinct lower(t.v)) from unnest(v_names) as t(v)) <> cardinality(v_names) then
      raise exception 'INVALID_TEAMS';
    end if;
  end if;

  -- Số người tối đa: không nhỏ hơn số người đã tham gia
  v_slots := case when c.format = 'DUEL' then 2 else coalesce((p->>'max_slots')::int, c.max_slots) end;
  if v_slots not between 1 and 10000 then raise exception 'INVALID_MAX_SLOTS'; end if;
  if c.format = 'TEAM' and coalesce(c.fixed_team_size, 0) > 0 then
    v_slots := least(v_slots, c.fixed_team_size * greatest((select count(*)::int from public.challenge_teams where challenge_id = c.id), 1));
  end if;
  v_joined := (select count(*)::int from public.challenge_participants where challenge_id = c.id and status <> 'LEFT');
  if v_slots < v_joined then raise exception 'SLOTS_BELOW_JOINED'; end if;

  -- Đối tượng: chỉ đổi Công khai ↔ Có mã mời (thử thách CLB / 1-1 giữ nguyên vì liên quan quỹ CLB và lời mời)
  if v_audience is distinct from c.target_audience
     and (c.target_club_id is not null or c.format = 'DUEL' or v_audience not in ('PUBLIC', 'INVITE_ONLY')) then
    raise exception 'AUDIENCE_LOCKED';
  end if;

  -- Phí quy mô: chỉ thu thêm khi lên mức phí cao hơn mức đã trả (hạn mức CLB / lượt miễn phí còn bao được thì miễn)
  v_payer := coalesce(c.target_club_id, c.created_by);
  if v_slots > c.max_slots then
    v_fee := private.challenge_creation_fee(c.format = 'TEAM', v_slots, v_start, v_end);
    if v_fee > coalesce(c.fee_charged, 0) then
      if c.target_club_id is not null then
        perform pg_advisory_xact_lock(hashtext('club_challenge:' || c.target_club_id));
        v_quota := private.club_challenge_quota_json(c.target_club_id, v_slots);
        -- Thử thách này đã nằm trong số đang mở → không tính chính nó khi xét số thử thách đồng thời
        v_free := (v_quota->>'reason') is null
               or ((v_quota->>'reason') = 'OPEN_LIMIT' and (v_quota->>'open')::int - 1 < (v_quota->>'max_open')::int
                   and v_slots <= (v_quota->>'max_slots')::int);
      end if;
      if not v_free and c.pass_id is not null then
        v_free := coalesce((select x.max_slots from public.challenge_passes x where x.id = c.pass_id), 0) >= v_slots;
      end if;
      if not v_free then v_extra := v_fee - coalesce(c.fee_charged, 0); end if;
    end if;
  end if;

  -- Thưởng: chỉ quỹ CLB treo thưởng; tối đa 50% (quỹ hiện có + phần đang ký quỹ) như lúc tạo
  v_diff := v_reward - coalesce(c.reward_xu, 0);
  if v_reward < 0 or v_reward > 100000 then raise exception 'INVALID_AMOUNT'; end if;
  if v_diff <> 0 and (c.target_club_id is null or c.reward_source = 'CREATOR') then raise exception 'REWARD_NOT_ALLOWED'; end if;
  if v_diff > 0 and v_reward > (private.balance(c.target_club_id) + coalesce(c.reward_xu, 0)) * 0.5 then raise exception 'REWARD_TOO_LARGE'; end if;
  if c.target_club_id is not null and (case when v_payer = c.target_club_id then v_extra else 0 end) + greatest(v_diff, 0) > private.balance(c.target_club_id) then
    raise exception 'INSUFFICIENT_TREASURY';
  end if;
  if c.target_club_id is null and v_extra > private.balance(v_payer) then raise exception 'INSUFFICIENT_BALANCE'; end if;

  -- Sổ cái: phí chênh + ký quỹ chênh (mỗi lần sửa một mã giao dịch riêng, không đụng mã của lúc tạo / huỷ)
  if v_extra > 0 then
    perform private.ledger_post('CHALLENGE_CREATION_FEE', 'challenge_edit_fee:' || c.id || ':' || gen_random_uuid(),
      case when c.target_club_id is not null then 'Phí tăng quy mô thử thách (quỹ CLB)' else 'Phí tăng quy mô thử thách' end, v_uid,
      private.debit_entries(v_payer, v_extra, private.system_account()), c.id);
    if c.target_club_id is not null then
      insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
      values (c.target_club_id, v_uid, -v_extra, 'SPEND', left('Phí tăng quy mô thử thách: ' || v_title, 200));
    end if;
  end if;
  if v_diff > 0 then
    perform private.ledger_post('CHALLENGE_ESCROW', 'challenge_escrow_adj:' || c.id || ':' || gen_random_uuid(), 'Tăng treo thưởng thử thách (quỹ CLB)', v_uid,
      private.debit_entries(c.target_club_id, v_diff, private.system_account()), c.id);
    insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
    values (c.target_club_id, v_uid, -v_diff, 'REWARD', left('Tăng treo thưởng: ' || v_title, 200));
  elsif v_diff < 0 then
    perform private.ledger_post('CHALLENGE_REFUND', 'challenge_refund_adj:' || c.id || ':' || gen_random_uuid(), 'Giảm treo thưởng thử thách — hoàn quỹ CLB', v_uid,
      jsonb_build_array(
        jsonb_build_object('account_id', c.target_club_id, 'coin_kind', 'BONUS', 'amount', -v_diff),
        jsonb_build_object('account_id', private.system_account(), 'coin_kind', 'BONUS', 'amount', v_diff)), c.id);
    insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
    values (c.target_club_id, v_uid, -v_diff, 'CONTRIBUTE', left('Hoàn bớt treo thưởng: ' || v_title, 200));
  end if;

  update public.challenges
     set title = v_title, description = v_desc, target_value = v_target,
         objective = case when v_conquest then objective else v_objective end,
         target_type = case when v_conquest then target_type else v_objective end,
         target_km = case when not v_conquest and v_objective = 'DISTANCE' then v_target else 0 end,
         game_mode = v_mode,
         min_km = v_min_km, min_pace = v_min_pace, max_pace = v_max_pace, daily_cap_km = v_cap,
         start_date = v_start, end_date = v_end,
         reg_deadline = case when format = 'TEAM' then least(coalesce(reg_deadline, v_start), v_start)
                             when reg_deadline is null or reg_deadline = c.end_date or reg_deadline > v_end then v_end
                             else reg_deadline end,
         max_slots = v_slots,
         calculated_fee = case when v_slots > c.max_slots then greatest(coalesce(calculated_fee, 0), coalesce(v_fee, 0)) else calculated_fee end,
         fee_charged = coalesce(fee_charged, 0) + v_extra,
         reward_xu = v_reward,
         reward_source = case when v_diff = 0 then reward_source when v_reward > 0 then 'CLUB' else 'NONE' end,
         target_audience = v_audience,
         require_hr = v_require_hr
   where id = c.id;

  -- Bỏ chinh phục → bỏ các hạng mục (kèm đăng ký)
  if not v_conquest and c.objective in ('BEST_TIME', 'BEST_PACE') then
    delete from public.challenge_categories where challenge_id = c.id;
    update public.challenges set conquest_mode = null where id = c.id;
  end if;
  if jsonb_typeof(p->'conquest') = 'object' then
    perform public.set_challenge_conquest(c.id, p->'conquest');
  end if;
  -- Mục tiêu tự đăng ký: bật / đổi mốc (set_challenge_pledge) hoặc tắt (bỏ mục tiêu đã chọn)
  if jsonb_typeof(p->'pledge') = 'object' then
    perform public.set_challenge_pledge(c.id, p->'pledge');
  elsif p ? 'pledge' and coalesce(c.pledge_enabled, false) then
    update public.challenges
       set pledge_enabled = false, pledge_options = null, pledge_min_km = null, pledge_max_km = null, pledge_cap_pct = null
     where id = c.id;
    update public.challenge_participants set pledge_km = null, pledged_at = null where challenge_id = c.id;
  end if;
  -- Chinh phục cá nhân theo mục tiêu: mục tiêu chung = mốc thấp nhất (như lúc tạo)
  update public.challenges x
     set target_value = coalesce((select min(o) from unnest(x.pledge_options) as o), x.pledge_min_km, x.target_value),
         target_km = coalesce((select min(o) from unnest(x.pledge_options) as o), x.pledge_min_km, x.target_value)
   where x.id = c.id and x.pledge_enabled and x.format = 'SOLO_GOAL';

  -- Tên đội
  if v_names is not null then
    update public.challenge_teams t set name = v_names[t.position]
     where t.challenge_id = c.id and t.position between 1 and cardinality(v_names);
  end if;
  -- Có mã mời: tạo mã nếu chưa có
  if v_audience <> 'PUBLIC' and not exists (select 1 from public.challenge_invites where challenge_id = c.id) then
    loop
      v_code := substr(md5(gen_random_uuid()::text), 1, 8);
      exit when not exists (select 1 from public.challenge_invites where code = v_code);
    end loop;
    insert into public.challenge_invites (challenge_id, code) values (c.id, v_code);
  end if;

  perform private.challenge_recompute_all(c.id);

  -- Bài giới thiệu thử thách trên bảng tin CLB
  update public.club_posts
     set title = v_title, body = coalesce(v_desc, ''),
         meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('target_value', v_target, 'start_date', v_start, 'end_date', v_end,
                                                                 'reward_xu', v_reward, 'objective', (select x.objective from public.challenges x where x.id = c.id))
   where kind = 'CHALLENGE' and deleted_at is null and meta->>'challenge_id' = c.id::text;

  for m in select profile_id from public.challenge_participants
            where challenge_id = c.id and profile_id is not null and coalesce(status, 'JOINED') <> 'LEFT' and profile_id <> v_uid loop
    perform private.notify(m.profile_id, c.target_club_id, 'CHALLENGE_UPDATED', 'Thử thách "' || left(v_title, 80) || '" vừa được cập nhật',
      'Xem lại thời gian, luật và giải thưởng trước khi bắt đầu.', '/challenges/' || c.id, v_uid, true);
  end loop;

  return jsonb_build_object('id', c.id, 'title', v_title, 'start_date', v_start, 'end_date', v_end,
                            'fee_extra', v_extra, 'reward_diff', v_diff, 'invite_code', (select code from public.challenge_invites where challenge_id = c.id));
end $$;

-- ---------------------------------------------------------------------
-- 3. Thử thách lặp lại: tên kỳ mới
-- ---------------------------------------------------------------------
-- Hằng tuần + tên có "tuần <số>" → số tuần ISO (giờ VN) của kỳ mới; còn lại: "<tên> · Kỳ <n>" như cũ
create or replace function private.recur_title(p_title text, p_recurrence text, p_occurrence integer, p_start timestamptz) returns text
language sql stable set search_path = public as $$
  select case
    when p_recurrence = 'WEEKLY' and s.base ~ '([Tt]uần|TUẦN)\s*\d{1,2}(?!\d)' then
      left(regexp_replace(s.base, '([Tt]uần|TUẦN)(\s*)\d{1,2}(?!\d)', '\1\2' || extract(week from (p_start at time zone 'Asia/Ho_Chi_Minh'))::int), 120)
    else left(s.base, 108) || ' · Kỳ ' || (coalesce(p_occurrence, 1) + 1) end
    from (select regexp_replace(regexp_replace(coalesce(p_title, ''), '\s*·\s*Kỳ \d+$', ''), '\s*[-–]\s*[Ll]ần\s*\d+$', '') as base) s
$$;

-- Bản 007600 + tên kỳ mới (private.recur_title) + chép hạng mục chinh phục
create or replace function private.spawn_next_occurrence(p_id uuid) returns uuid
language plpgsql security definer set search_path = public, extensions as $$
declare
  c public.challenges := (select x from public.challenges x where x.id = p_id for update);
  v_step interval;
  v_start timestamptz;
  v_end timestamptz;
  v_payload jsonb;
  v_old_claims text := current_setting('request.jwt.claims', true);
  v_old_sub text := current_setting('request.jwt.claim.sub', true);
  v_new uuid;
  v_n integer := 0;
  v_conquest boolean;
begin
  if c.id is null or c.recurrence = 'NONE' or c.recur_next_id is not null or c.status = 'CANCELLED' or c.created_by is null then return null; end if;
  v_step := private.recurrence_step(c.recurrence);
  v_start := c.start_date + v_step;
  v_end := c.end_date + v_step;
  while v_end <= now() + interval '1 hour' and v_n < 60 loop          -- bỏ lỡ nhiều kỳ (cron dừng): nhảy tới kỳ còn hiệu lực
    v_start := v_start + v_step; v_end := v_end + v_step; v_n := v_n + 1;
  end loop;
  if c.format = 'TEAM' and v_start < now() + interval '15 minutes' then v_start := now() + interval '15 minutes'; end if;
  v_conquest := c.objective in ('BEST_TIME', 'BEST_PACE');
  v_payload := jsonb_build_object(
    'title', private.recur_title(c.title, c.recurrence, c.occurrence, v_start), 'description', c.description, 'format', c.format,
    -- Chinh phục: tạo như thử thách km rồi chép hạng mục (như trình tạo)
    'objective', case when v_conquest then 'DISTANCE' else c.objective end, 'game_mode', c.game_mode,
    'target_value', case when v_conquest then 1 else c.target_value end, 'min_km', c.min_km,
    'min_pace', c.min_pace, 'max_pace', c.max_pace, 'daily_cap_km', c.daily_cap_km,
    'start_date', v_start, 'end_date', v_end, 'max_slots', c.max_slots, 'audience', c.target_audience,
    'club_id', c.target_club_id, 'team_size', c.fixed_team_size, 'reward_xu', c.reward_xu,
    'reward_source', c.reward_source, 'reward_split', c.reward_split,
    'team_names', coalesce((select jsonb_agg(t.name order by t.position) from public.challenge_teams t where t.challenge_id = c.id), '[]'::jsonb));

  -- Tạo như chính người tạo bấm tạo: mọi kiểm tra quyền / phí / lượt / quỹ giữ nguyên
  perform set_config('request.jwt.claims', json_build_object('sub', c.created_by, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', c.created_by::text, true);
  begin
    v_new := (public.create_challenge_v2(v_payload, 'recur:' || c.id)->>'challenge_id')::uuid;
  exception when others then
    perform set_config('request.jwt.claims', coalesce(v_old_claims, ''), true);
    perform set_config('request.jwt.claim.sub', coalesce(v_old_sub, ''), true);
    if c.recur_error is distinct from sqlerrm then
      update public.challenges set recur_error = left(sqlerrm, 200) where id = c.id;
      perform private.notify(c.created_by, c.target_club_id, 'CHALLENGE_RECUR_FAILED', 'Chưa tạo được kỳ mới: ' || left(c.title, 80),
        case when sqlerrm like '%INSUFFICIENT%' then 'Ví / quỹ CLB không đủ Xu cho phí tạo. Nạp thêm hoặc giảm quy mô — hệ thống thử lại mỗi ngày.'
             when sqlerrm like '%FORBIDDEN%' then 'Bạn không còn là ban quản trị CLB. Tắt lặp lại hoặc nhờ ban quản trị tạo.'
             else 'Hệ thống thử lại mỗi ngày. Lý do: ' || left(sqlerrm, 120) end,
        '/challenges/' || c.id, null, true);
    end if;
    return null;
  end;
  perform set_config('request.jwt.claims', coalesce(v_old_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_old_sub, ''), true);

  -- Chép phần thiết lập thêm (nhịp tim, mục tiêu tự đăng ký, thể lệ, hạng mục chinh phục) và nối chuỗi kỳ
  update public.challenges n set
    require_hr = c.require_hr, rules_info = c.rules_info, rules_updated_at = case when c.rules_info <> '{}'::jsonb then now() end,
    pledge_enabled = c.pledge_enabled, pledge_options = c.pledge_options, pledge_min_km = c.pledge_min_km,
    pledge_max_km = c.pledge_max_km, pledge_cap_pct = c.pledge_cap_pct, pledge_team_size = c.pledge_team_size,
    game_mode = case when c.pledge_enabled and c.format = 'TEAM' then 'TEAM_SUM' else n.game_mode end,
    objective = c.objective, target_type = c.target_type, conquest_mode = c.conquest_mode,
    reward_split = case when v_conquest then 'FINISHERS' else n.reward_split end,
    min_km = case when v_conquest then c.min_km else n.min_km end,
    recurrence = c.recurrence, series_id = coalesce(c.series_id, c.id), occurrence = c.occurrence + 1
  where n.id = v_new;
  if v_conquest then
    insert into public.challenge_categories (challenge_id, position, label, distance_m, target_s)
    select v_new, cat.position, cat.label, cat.distance_m, cat.target_s
      from public.challenge_categories cat
     where cat.challenge_id = c.id
       and not exists (select 1 from public.challenge_categories x where x.challenge_id = v_new and x.position = cat.position);
  end if;
  update public.challenges set recur_next_id = v_new, recur_error = null, series_id = coalesce(series_id, id) where id = c.id;
  return v_new;
end $$;

-- ---------------------------------------------------------------------
-- 4. Vinh danh theo mục tiêu (bản 013100 + GOAL<mét>, CAT<thứ tự>)
-- ---------------------------------------------------------------------
create or replace function private.honor_compute(c public.challenges, p_cats jsonb)
returns table (category text, rank integer, user_id uuid, value numeric)
language plpgsql stable security definer set search_path = public as $$
declare
  cat jsonb;
  k text;
  n int;
  v_len interval := c.end_date - c.start_date;
begin
  for cat in select * from jsonb_array_elements(coalesce(p_cats, '[]'::jsonb)) loop
    k := cat->>'key';
    n := least(10, greatest(1, coalesce((cat->>'count')::int, 3)));
    if k = 'TOP' then
      return query select k, x.rn::int, x.pid, x.v from (
        select p.profile_id as pid, p.current_progress as v,
               row_number() over (order by p.current_progress desc, p.completed_at asc nulls last, p.joined_at) as rn
          from public.challenge_participants p
         where p.challenge_id = c.id and p.status <> 'LEFT' and p.current_progress > 0) x where x.rn <= n;
    elsif k = 'KM' then
      return query select k, x.rn::int, x.pid, x.v from (
        select p.profile_id as pid, round(p.distance_m / 1000.0, 2) as v,
               row_number() over (order by p.distance_m desc, p.joined_at) as rn
          from public.challenge_participants p
         where p.challenge_id = c.id and p.status <> 'LEFT' and p.distance_m > 0) x where x.rn <= n;
    elsif k = 'DAYS' then
      return query select k, x.rn::int, x.pid, x.v from (
        select p.profile_id as pid, p.streak_days::numeric as v,
               row_number() over (order by p.streak_days desc, p.distance_m desc) as rn
          from public.challenge_participants p
         where p.challenge_id = c.id and p.status <> 'LEFT' and p.streak_days > 0) x where x.rn <= n;
    elsif k = 'STREAK' then
      -- chuỗi ngày chạy liên tiếp dài nhất (khoảng trống & đảo)
      return query select k, x.rn::int, x.pid, x.v from (
        select s.pid, s.best::numeric as v, row_number() over (order by s.best desc, s.km desc) as rn
          from (select g.pid, max(g.len) as best, max(g.km) as km
                  from (select d.pid, d.km, count(*) over (partition by d.pid, d.grp) as len
                          from (select p.profile_id as pid, p.distance_m as km, e.day,
                                       e.day - (row_number() over (partition by p.id order by e.day))::int as grp
                                  from public.challenge_participants p
                                  join (select distinct participant_id, day from public.challenge_progress_events where challenge_id = c.id) e
                                    on e.participant_id = p.id
                                 where p.challenge_id = c.id and p.status <> 'LEFT') d) g
                 group by g.pid) s
         where s.best >= 2) x where x.rn <= n;
    elsif k = 'BREAKTHROUGH' then
      -- km trong thử thách trừ km cùng độ dài trước khi bắt đầu; cần ≥ 5 km trong thử thách
      return query select k, x.rn::int, x.pid, x.v from (
        select b.pid, round(b.gain, 2) as v, row_number() over (order by b.gain desc) as rn
          from (select p.profile_id as pid,
                       p.distance_m / 1000.0 - coalesce((select sum(coalesce(a.moving_distance_m, a.distance_m)) / 1000.0 from public.activities a
                                                           where a.user_id = p.profile_id and a.validation_status = 'APPROVED'
                                                             and a.started_at >= c.start_date - v_len and a.started_at < c.start_date), 0) as gain
                  from public.challenge_participants p
                 where p.challenge_id = c.id and p.status <> 'LEFT' and p.distance_m >= 5000) b
         where b.gain > 0) x where x.rn <= n;
    elsif k = 'SUPPORTED' then
      return query select k, x.rn::int, x.pid, x.v from (
        select t.pid, t.s as v, row_number() over (order by t.s desc) as rn
          from (select cp.profile_id as pid, sum(ch.amount) as s
                  from public.challenge_participants cp
                  join public.cheers ch on ch.to_user = cp.profile_id and ch.gift_code is not null
                                       and ch.created_at >= c.start_date and ch.created_at < c.end_date
                 where cp.challenge_id = c.id and cp.status <> 'LEFT'
                 group by cp.profile_id) t) x where x.rn <= n;
    elsif k ~ '^DIST[0-9]{3,6}$' then
      -- 013100: vinh danh theo cự ly — bài tốt nhất có cự ly ≥ D trong thời gian thử thách, thời gian quy đổi theo pace trung bình
      return query select k, x.rn::int, x.pid, x.v from (
        select b.pid, b.best as v, row_number() over (order by b.best, b.at) as rn
          from (select p.profile_id as pid,
                       min(round(a.mt * substr(k, 5)::numeric / a.dist)) as best, min(a.started_at) as at
                  from public.challenge_participants p
                  join (select x.user_id, x.started_at, coalesce(nullif(x.moving_distance_m, 0), x.distance_m) as dist,
                               coalesce(nullif(x.moving_time_s, 0), x.elapsed_time_s) as mt
                          from public.activities x
                         where x.started_at >= c.start_date and x.started_at < c.end_date
                           and x.validation_status = 'APPROVED' and public.activity_is_countable(x.status, x.validation_status)) a
                    on a.user_id = p.profile_id and a.dist >= substr(k, 5)::numeric and a.mt > 0
                 where p.challenge_id = c.id and p.status <> 'LEFT'
                 group by p.profile_id) b) x where x.rn <= n;
    elsif k ~ '^GOAL[0-9]{3,7}$' then
      -- 013300: theo mục tiêu BTC đặt (tự đăng ký mục tiêu) — chỉ người chọn đúng mục tiêu này và đã hoàn thành;
      -- km được tính nhiều hơn đứng trước, bằng nhau thì ai hoàn thành sớm hơn
      return query select k, x.rn::int, x.pid, x.v from (
        select p.profile_id as pid, p.current_progress as v,
               row_number() over (order by p.current_progress desc, p.completed_at, p.joined_at) as rn
          from public.challenge_participants p
         where p.challenge_id = c.id and p.status <> 'LEFT' and p.completed_at is not null
           and round(p.pledge_km * 1000) = substr(k, 5)::numeric) x where x.rn <= n;
    elsif k ~ '^CAT[1-8]$' then
      -- 013300: hạng mục chinh phục thứ N — người đạt mục tiêu hạng mục, kết quả nhanh nhất trước (giây, hoặc giây/km nếu chinh phục pace)
      return query select k, x.rn::int, x.pid, x.v from (
        select e.user_id as pid, (case when c.objective = 'BEST_PACE' then e.best_pace_s else e.best_time_s end)::numeric as v,
               row_number() over (order by case when c.objective = 'BEST_PACE' then e.best_pace_s else e.best_time_s end, e.best_at) as rn
          from public.challenge_category_entries e
          join public.challenge_categories ct on ct.id = e.category_id and ct.challenge_id = c.id and ct.position = substr(k, 4)::int
          join public.challenge_participants p on p.id = e.participant_id and p.status <> 'LEFT'
         where e.achieved_at is not null and e.best_time_s is not null) x where x.rn <= n;
    elsif k like 'CUSTOM%' then
      return query select k, x.ord::int, x.pid, null::numeric from (
        select u.v::uuid as pid, u.ord
          from jsonb_array_elements_text(coalesce(cat->'users', '[]'::jsonb)) with ordinality as u(v, ord)
         where exists (select 1 from public.challenge_participants p where p.challenge_id = c.id and p.profile_id = u.v::uuid and p.status <> 'LEFT')) x
       where x.ord <= 10;
    end if;
  end loop;
end $$;

create or replace function private.honor_categories(p jsonb) returns jsonb
language plpgsql immutable as $$
declare v_out jsonb := '[]'::jsonb; cat jsonb; k text; seen text[] := '{}';
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 8 then raise exception 'INVALID_HONOR_CATEGORIES'; end if;
  for cat in select * from jsonb_array_elements(p) loop
    k := cat->>'key';
    if k is null or not (k = any (array['TOP', 'KM', 'DAYS', 'STREAK', 'BREAKTHROUGH', 'SUPPORTED']) or k ~ '^CUSTOM[1-5]$'
                         or (k ~ '^DIST[0-9]{3,6}$' and substr(k, 5)::int between 400 and 250000)
                         or (k ~ '^GOAL[0-9]{3,7}$' and substr(k, 5)::int between 100 and 5000000)
                         or k ~ '^CAT[1-8]$') or k = any (seen) then
      raise exception 'INVALID_HONOR_CATEGORIES';
    end if;
    if k like 'CUSTOM%' and (jsonb_typeof(coalesce(cat->'users', '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(cat->'users', '[]'::jsonb)) > 10
        or exists (select 1 from jsonb_array_elements_text(coalesce(cat->'users', '[]'::jsonb)) u where u !~ '^[0-9a-fA-F-]{36}$')) then
      raise exception 'INVALID_HONOR_CATEGORIES';
    end if;
    seen := seen || k;
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'key', k,
      'title', coalesce(nullif(left(trim(coalesce(cat->>'title', '')), 60), ''), k),
      'count', least(10, greatest(1, coalesce(private.bib_num(cat->'count', 1, 10, 3), 3)))::int,
      'users', case when k like 'CUSTOM%' then coalesce(cat->'users', '[]'::jsonb) else null end));
  end loop;
  return v_out;
end $$;

-- ---------------------------------------------------------------------
-- 5. Đã có kết quả thì không sửa đăng ký
-- ---------------------------------------------------------------------
/** Người tham gia đã có bài chạy hợp lệ ≥ cự ly hạng mục trong thời gian thử thách (cùng điều kiện tính kết quả) */
create or replace function private.conquest_has_result(p_participant uuid, p_category uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.challenge_progress_events e
                   join public.challenge_categories cat on cat.id = p_category
                  where e.participant_id = p_participant and e.moving_s > 0 and e.distance_m >= cat.distance_m * 0.99)
$$;

-- Bản 010700 + CONQUEST_RESULT_LOCKED: đã đăng ký rồi thì không thêm / đổi mục tiêu / bỏ hạng mục mà mình đã có kết quả
create or replace function public.set_my_conquest(p_challenge_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.challenges := (select x from public.challenges x where x.id = p_challenge_id);
  v_pid uuid := (select x.id from public.challenge_participants x where x.challenge_id = p_challenge_id and x.profile_id = v_uid and x.status <> 'LEFT');
  v_items jsonb := case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end;
  v_started boolean;
begin
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if c.objective not in ('BEST_TIME', 'BEST_PACE') then raise exception 'CONQUEST_NOT_SUPPORTED'; end if;
  if v_pid is null then raise exception 'NOT_JOINED'; end if;
  if c.status <> 'ACTIVE' or now() >= c.end_date then raise exception 'CHALLENGE_CLOSED'; end if;
  if jsonb_array_length(v_items) = 0 then raise exception 'INVALID_CONQUEST'; end if;
  begin
    if exists (select 1 from jsonb_array_elements(v_items) x
                where not exists (select 1 from public.challenge_categories cat where cat.id = (x->>'category_id')::uuid and cat.challenge_id = c.id)
                   or (c.conquest_mode = 'SELF' and coalesce((x->>'target_s')::int, 0) <= 0)
                   or (c.conquest_mode = 'SELF' and c.objective = 'BEST_PACE' and (x->>'target_s')::int not between 120 and 1500)
                   or (c.conquest_mode = 'SELF' and c.objective = 'BEST_TIME' and (x->>'target_s')::int not between 60 and 172800)) then
      raise exception 'INVALID_CONQUEST';
    end if;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'INVALID_CONQUEST';
  end;
  -- 013300: sửa đăng ký (đã có đăng ký trước đó) mà cự ly đã có kết quả tương đương → không thêm, không đổi mục tiêu, không bỏ
  if exists (select 1 from public.challenge_category_entries e where e.participant_id = v_pid) and (exists (select 1 from jsonb_array_elements(v_items) x
              where private.conquest_has_result(v_pid, (x->>'category_id')::uuid)
                and (not exists (select 1 from public.challenge_category_entries e where e.participant_id = v_pid and e.category_id = (x->>'category_id')::uuid)
                     or (c.conquest_mode = 'SELF' and (select e.target_s from public.challenge_category_entries e
                                                         where e.participant_id = v_pid and e.category_id = (x->>'category_id')::uuid)
                                                      is distinct from (x->>'target_s')::int)))
     or exists (select 1 from public.challenge_category_entries e
                 where e.participant_id = v_pid and private.conquest_has_result(v_pid, e.category_id)
                   and not exists (select 1 from jsonb_array_elements(v_items) x where (x->>'category_id')::uuid = e.category_id))) then
    raise exception 'CONQUEST_RESULT_LOCKED';
  end if;
  v_started := now() >= c.start_date;
  -- Sau giờ xuất phát: được thêm hạng mục mới (người tham gia trễ) nhưng không bỏ / đổi mục tiêu đã đăng ký
  if v_started and exists (
       select 1 from public.challenge_category_entries e
        where e.participant_id = v_pid
          and (not exists (select 1 from jsonb_array_elements(v_items) x where (x->>'category_id')::uuid = e.category_id)
               or (c.conquest_mode = 'SELF' and e.target_s is distinct from
                     (select (x->>'target_s')::int from jsonb_array_elements(v_items) x where (x->>'category_id')::uuid = e.category_id)))) then
    raise exception 'CONQUEST_TARGET_LOCKED';
  end if;
  delete from public.challenge_category_entries e
   where e.participant_id = v_pid
     and not exists (select 1 from jsonb_array_elements(v_items) x where (x->>'category_id')::uuid = e.category_id);
  insert into public.challenge_category_entries (participant_id, category_id, challenge_id, user_id, target_s)
  select v_pid, (x->>'category_id')::uuid, c.id, v_uid, case when c.conquest_mode = 'SELF' then (x->>'target_s')::int end
    from jsonb_array_elements(v_items) x
  on conflict (participant_id, category_id) do update set target_s = excluded.target_s;
  perform private.challenge_recompute_participant(v_pid);
  return public.challenge_conquest_board(c.id);
end $$;

-- BXH chinh phục (bản 010700) + my_results: các hạng mục người xem đã có kết quả (giao diện khoá kèm lý do)
create or replace function public.challenge_conquest_board(p_challenge_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  c public.challenges := (select x from public.challenges x where x.id = p_challenge_id);
  v_pid uuid;
begin
  if c.id is null or not public.challenge_visible(c.id) then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  v_pid := (select x.id from public.challenge_participants x where x.challenge_id = c.id and x.profile_id = v_uid and x.status <> 'LEFT');
  return jsonb_build_object(
    'objective', c.objective, 'mode', c.conquest_mode,
    'categories', (select coalesce(jsonb_agg(jsonb_build_object(
                     'id', cat.id, 'label', cat.label, 'distance_m', cat.distance_m, 'target_s', cat.target_s, 'position', cat.position,
                     'entrants', (select count(*) from public.challenge_category_entries e join public.challenge_participants pp on pp.id = e.participant_id
                                   where e.category_id = cat.id and pp.status <> 'LEFT'),
                     'achieved', (select count(*) from public.challenge_category_entries e join public.challenge_participants pp on pp.id = e.participant_id
                                   where e.category_id = cat.id and pp.status <> 'LEFT' and e.achieved_at is not null))
                     order by cat.position), '[]'::jsonb)
                     from public.challenge_categories cat where cat.challenge_id = c.id),
    'rows', (select coalesce(jsonb_agg(jsonb_build_object(
               'category_id', r.category_id, 'user_id', r.user_id, 'display_name', r.display_name, 'avatar_url', r.avatar_url, 'level', r.level,
               'target_s', r.target_s_eff, 'best_time_s', r.best_time_s, 'best_pace_s', r.best_pace_s, 'best_activity_id', r.best_activity_id,
               'best_at', r.best_at, 'achieved', r.achieved_at is not null, 'rank', r.rk, 'me', r.user_id = v_uid)
               order by r.category_id, r.rk nulls last, r.display_name), '[]'::jsonb)
               from (select e.*, coalesce(e.target_s, cat.target_s) as target_s_eff, pr.display_name, pr.avatar_url, coalesce(pr.level, 1) as level,
                            case when e.best_time_s is not null then rank() over (partition by e.category_id, (e.best_time_s is not null)
                                                                                     order by e.best_time_s, e.best_at) end as rk
                       from public.challenge_category_entries e
                       join public.challenge_categories cat on cat.id = e.category_id
                       join public.challenge_participants pp on pp.id = e.participant_id and pp.status <> 'LEFT'
                       join public.profiles pr on pr.id = e.user_id
                      where e.challenge_id = c.id) r),
    'mine', (select coalesce(jsonb_agg(jsonb_build_object('category_id', e.category_id, 'target_s', e.target_s,
               'best_time_s', e.best_time_s, 'best_pace_s', e.best_pace_s, 'achieved', e.achieved_at is not null)), '[]'::jsonb)
               from public.challenge_category_entries e where e.challenge_id = c.id and e.user_id = v_uid),
    'my_results', (select coalesce(jsonb_agg(cat.id order by cat.position), '[]'::jsonb)
                     from public.challenge_categories cat
                    where cat.challenge_id = c.id and v_pid is not null and private.conquest_has_result(v_pid, cat.id))
  );
end $$;

-- ---------------------------------------------------------------------
-- 6. Quyền
-- ---------------------------------------------------------------------
revoke all on function private.recur_title(text, text, integer, timestamptz), private.conquest_has_result(uuid, uuid)
  from public, anon, authenticated;
revoke all on function public.update_challenge(uuid, jsonb), public.set_challenge_pledge(uuid, jsonb), public.set_challenge_conquest(uuid, jsonb),
  public.set_my_conquest(uuid, jsonb), public.challenge_conquest_board(uuid) from public, anon;
grant execute on function public.update_challenge(uuid, jsonb), public.set_challenge_pledge(uuid, jsonb), public.set_challenge_conquest(uuid, jsonb),
  public.set_my_conquest(uuid, jsonb), public.challenge_conquest_board(uuid) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001013400_strava_rule_round7.sql
-- ===================================================================
-- 013400: Chỉnh sửa lần 7 — luật bài đồng bộ từ đối tác (Strava / Garmin / COROS), Phụng chốt 06/10/2026:
--   "Luật GPS nhảy nếu Strava có GPS (mặc dù nhảy) thì RaceHub vẫn ghi nhận; chỉ không ghi nhận trường hợp nhập tay;
--    cảnh báo chạy máy (hoàn toàn không có GPS)".
-- Góp ý: "Bài GPS nhảy được ghi nhận ngay: hiện tại cập nhật xong nhưng BQT vẫn phải duyệt". Nguyên nhân (sau 013100 / lần 6):
--   • fraud.ts: dấu hiệu tốc độ (PACE_CURVE, VEHICLE_BURST…) do GPS trôi trải vài điểm chỉ bị hạ MỘT mức (DISQUALIFY → SUSPECT
--     vẫn chờ duyệt), và GPS_TELEPORT / GPS_DISTANCE_GAIN vẫn được đếm là một "cảnh báo độc lập" (+ 1 cảnh báo khác = chờ duyệt).
--     Sửa ở bộ phân tích (ac-2026.10.7): dấu hiệu do GPS nhảy chỉ còn là cảnh báo, không bao giờ giữ bài.
--   • SQL (bản này): pace TB tính trên km Strava ĐÃ cộng cú nhảy → "nhanh hơn kỷ lục" → chờ duyệt; "vận tốc tối đa" một điểm
--     (bài không có phân tích) → chờ duyệt. Nay: kiểm pace theo quãng đường đã bỏ cú nhảy; vận tốc tối đa chỉ là cảnh báo.
-- 1. ingest_provider_activity: nhập tay → REJECTED "Bài nhập tay không được ghi nhận." (không km / thử thách / BXH / Xu);
--    chạy máy / không có GPS → APPROVED + cảnh báo TREADMILL; GPS nhảy → APPROVED + cảnh báo. Km của đối tác giữ nguyên.
--    Bài đã nhập trước 013400 KHÔNG bị xét lại (bài đang chờ duyệt vẫn do ban quản trị quyết định).
-- 2. restore_activity: không khôi phục bài nhập tay của đối tác (MANUAL_NOT_COUNTED); rejected_activities trả thêm 'manual'.
-- 3. warned_activities(): "Bài có cảnh báo" — bài ĐÃ ghi nhận nhưng có cảnh báo (GPS nhảy, chạy máy…) cho admin hệ thống
--    (p_club_id null) và Ban quản trị CLB (chỉ bài của thành viên CLB mình).
-- Giữ nguyên chữ ký các hàm cũ. Cần 013100. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT,
-- không RETURNING INTO. Chạy lại an toàn.

-- ---------------------------------------------------------------------
-- 1. Nhập bài từ đối tác (bản 012600 + luật lần 7)
-- ---------------------------------------------------------------------
create or replace function public.ingest_provider_activity(
  p_user_id uuid, p_source text, p_external_id text, p_activity jsonb
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  cfg jsonb := private.economy_config();
  v_sport text := coalesce(p_activity->>'sport_type', 'Run');
  v_started timestamptz := (p_activity->>'started_at')::timestamptz;
  v_elapsed integer := greatest(coalesce((p_activity->>'elapsed_s')::numeric, 0), 0)::integer;
  v_moving integer := greatest(coalesce((p_activity->>'moving_s')::numeric, 0), 0)::integer;
  v_distance numeric := greatest(coalesce((p_activity->>'distance_m')::numeric, 0), 0);
  v_max_speed numeric := (p_activity->>'max_speed_mps')::numeric;
  v_manual boolean := coalesce((p_activity->>'manual')::boolean, false);
  v_has_gps boolean := coalesce((p_activity->>'has_gps')::boolean, true);
  v_ended timestamptz;
  v_pace integer;
  v_connected_at timestamptz;
  v_status text := 'APPROVED';
  v_reason text := 'Hợp lệ (đồng bộ tự động).';
  v_history_only boolean := false;
  v_existing public.activities%rowtype;
  v_id uuid;
  a public.activities%rowtype;
  v_level text;
  v_score integer := 0;
  v_risk jsonb := case when jsonb_typeof(p_activity->'risk') = 'object' then p_activity->'risk' end;
  -- 013400: cảnh báo lưu kèm bài (risk.flags của bộ phân tích + cảnh báo máy chủ tự thêm: chạy máy, vận tốc tối đa một điểm)
  v_flags jsonb := case when jsonb_typeof(p_activity->'risk'->'flags') = 'array' then p_activity->'risk'->'flags' else '[]'::jsonb end;
  -- Quãng đường đã bỏ cú nhảy / đoạn trôi GPS (bộ phân tích, chỉ để kiểm pace TB — km của đối tác KHÔNG đổi)
  v_pace_dist numeric := case when jsonb_typeof(p_activity->'analysis') = 'object' then nullif((p_activity->'analysis'->>'clean_distance_m')::numeric, 0) end;
  v_check_pace integer;
  v_no_gps boolean;
begin
  if p_source not in ('STRAVA', 'GARMIN', 'COROS') then raise exception 'INVALID_SOURCE'; end if;
  if p_external_id is null or v_started is null then raise exception 'INVALID_ACTIVITY'; end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then raise exception 'USER_NOT_FOUND'; end if;

  -- Đã có → chỉ cập nhật tiêu đề (Strava gửi aspect "update" khi đổi tên)
  v_existing := (select x from public.activities x where x.source = p_source and x.source_activity_id = p_external_id);
  if v_existing.id is not null then
    if v_existing.user_id <> p_user_id then raise exception 'ACTIVITY_OWNER_MISMATCH'; end if;
    update public.activities
       set title = left(coalesce(nullif(trim(p_activity->>'title'), ''), title), 120), updated_at = now()
     where id = v_existing.id and title is distinct from left(coalesce(nullif(trim(p_activity->>'title'), ''), title), 120);
    return jsonb_build_object('result', case when found then 'UPDATED' else 'DUPLICATE' end,
                              'activity_id', v_existing.id, 'validation_status', v_existing.validation_status);
  end if;

  -- Không phải chạy bộ / quá ngắn → bỏ qua, không lưu
  if v_sport not in ('Run', 'TrailRun', 'VirtualRun') then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'NOT_RUN');
  end if;
  if v_distance < 200 or v_moving <= 0 then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'TOO_SHORT');
  end if;
  if v_started > now() + interval '10 minutes' then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'FUTURE_START');
  end if;

  v_ended := v_started + make_interval(secs => greatest(v_elapsed, v_moving));
  -- 012600: km của đối tác (Strava…) giữ nguyên — cú nhảy GPS chỉ dùng để phân loại hợp lệ / nghi vấn (fraud.ts)
  v_pace := round(v_moving / (v_distance / 1000.0));
  -- 013400: pace TB "nhanh hơn kỷ lục" chỉ vì GPS nhảy cộng thêm km → kiểm theo quãng đường đã bỏ cú nhảy (nếu có phân tích)
  v_check_pace := case when v_has_gps and v_pace_dist is not null and v_pace_dist < v_distance
                       then round(v_moving / (v_pace_dist / 1000.0)) else v_pace end;
  v_no_gps := v_sport = 'VirtualRun' or not v_has_gps;

  -- Cùng một buổi chạy đã được ghi từ nguồn khác (vd GPS trong app) → không tính 2 lần.
  -- 009900: trừ khi bài này dài hơn hẳn các bài trùng giờ đang được tính (vd đồng hồ ghi đủ 2 giờ, điện thoại chỉ ghi một đoạn)
  if exists (select 1 from public.activities
              where user_id = p_user_id and coalesce(status, '') <> 'DELETED'
                and started_at < v_ended and coalesce(ended_at, started_at) > v_started)
     and v_distance <= 1.1 * private.overlap_meters(private.overlap_ids(p_user_id, v_started, v_ended)) then
    return jsonb_build_object('result', 'SKIPPED', 'reason', 'OVERLAPS_EXISTING_ACTIVITY');
  end if;

  -- Luật hợp lệ — 013400, Chỉnh sửa lần 7 (Phụng chốt 06/10/2026): "GPS nhảy nếu Strava có GPS (mặc dù nhảy) thì RaceHub vẫn
  -- ghi nhận; chỉ không ghi nhận trường hợp nhập tay; cảnh báo chạy máy (hoàn toàn không có GPS)".
  -- Chỉ bài NGHI GIAN LẬN (dấu hiệu không do GPS nhảy) mới chờ duyệt; bài chạy chậm / đi bộ vẫn được ghi nhận ngay
  if v_manual or v_risk->>'verdict' = 'REJECT' then
    -- Nhập tay: không có dữ liệu thiết bị → KHÔNG ghi nhận (không km, thử thách, BXH, Xu). Lưu lại để người chạy thấy lý do.
    v_status := 'REJECTED';
    v_reason := 'Bài nhập tay không được ghi nhận.';
    if not v_flags @> '[{"code": "MANUAL"}]'::jsonb then
      v_flags := v_flags || jsonb_build_array(jsonb_build_object('code', 'MANUAL', 'severity', 'SEVERE', 'tier', 'DISQUALIFY',
                   'message', 'Bài nhập tay không được ghi nhận'));
    end if;
  elsif v_check_pace < (cfg->>'minValidPace')::numeric * 60 then
    v_status := 'PENDING'; v_level := 'HIGH'; v_score := 75;
    v_reason := 'Pace trung bình ' || (v_check_pace / 60) || ':' || lpad((v_check_pace % 60)::text, 2, '0') || '/km — nhanh hơn kỷ lục thế giới.';
  -- 012400: "vận tốc tối đa" của Strava là MỘT điểm (hay do GPS nhảy). 013400: bài có GPS → ghi nhận, chỉ cảnh báo
  -- (có risk thì bộ phân tích — cửa sổ trượt + đường cong pace, fraud.ts — đã xét)
  elsif v_risk is null and not v_no_gps and v_max_speed is not null and v_max_speed > 12 then
    v_flags := v_flags || jsonb_build_array(jsonb_build_object('code', 'VEHICLE_BURST', 'severity', 'HIGH', 'tier', 'WARN', 'gpsJump', true,
                 'message', 'Vận tốc tối đa một điểm ' || round(v_max_speed * 3.6) || ' km/h (GPS nhảy) — bài vẫn được ghi nhận'));
  end if;
  -- Chạy máy / hoàn toàn không có GPS → vẫn ghi nhận, kèm cảnh báo cho ban quản trị (trước 013400: chờ duyệt)
  if v_status <> 'REJECTED' and v_no_gps then
    if not v_flags @> '[{"code": "TREADMILL"}]'::jsonb then
      v_flags := v_flags || jsonb_build_array(jsonb_build_object('code', 'TREADMILL', 'severity', 'HIGH', 'tier', 'WARN',
                   'message', case when v_sport = 'VirtualRun' then 'Chạy máy / chạy ảo — không có tuyến GPS để đối chiếu; bài vẫn được ghi nhận'
                                   else 'Bài hoàn toàn không có GPS — không đối chiếu được quãng đường; bài vẫn được ghi nhận' end));
    end if;
    if v_status = 'APPROVED' then v_reason := 'Hợp lệ (đồng bộ tự động) — cảnh báo: chạy máy / không có GPS.'; end if;
  end if;
  -- Bộ phân tích gian lận (máy chủ ứng dụng, xem features/activity/model/fraud.ts) → chờ ban quản trị xác minh.
  -- fraud.ts (ac-2026.10.7) không bao giờ kết luận REVIEW chỉ vì GPS nhảy / chạy máy.
  if v_status = 'APPROVED' and v_risk->>'verdict' = 'REVIEW' then
    v_status := 'PENDING';
    v_level := coalesce(v_risk->>'level', 'HIGH');
    v_score := coalesce((v_risk->>'score')::int, 65);
    v_reason := coalesce(nullif(v_risk->>'reason', ''), 'Dữ liệu bài chạy bất thường') || '.';
  end if;
  if v_status = 'PENDING' then
    v_reason := left('Mức nghi vấn: ' || private.risk_label(v_level) || '. ' || v_reason
                     || ' Bài được tính sau khi ban quản trị CLB hoặc admin xác minh.', 500);
  end if;

  -- Bài chạy trước khi kết nối: lưu lịch sử, không thưởng (tránh "đổ" hàng tháng dữ liệu cũ lấy Xu)
  v_connected_at := (select max(ca.created_at) from public.connected_accounts ca
                      where ca.user_id = p_user_id and ca.provider = p_source);
  v_history_only := v_connected_at is not null and v_started < v_connected_at;

  v_id := gen_random_uuid();
  -- Kết quả phân tích chi tiết (dữ liệu gốc rút gọn + bằng chứng) → trigger lưu vào activity_analyses cùng lúc với bài
  perform set_config('racehub.analysis', coalesce((p_activity->'analysis')::text, ''), true);
  perform set_config('racehub.reported_distance', v_distance::text, true);
  insert into public.activities (
    id, user_id, title, source, source_activity_id, sport_type, started_at, ended_at,
    elapsed_time_s, moving_time_s, distance_m, moving_distance_m, avg_pace_s,
    avg_speed_mps, max_speed_mps, avg_heartrate, elevation_gain_m, is_manual, device_name,
    status, validation_status, validation_reason, review_detail, rewarded_at, earned_xu, earned_xp,
    risk_score, risk_level, risk_flags)
  values (
    v_id, p_user_id, left(coalesce(nullif(trim(p_activity->>'title'), ''), 'Buổi chạy'), 120), p_source, p_external_id, v_sport,
    v_started, v_ended, v_elapsed, v_moving, v_distance, v_distance, v_pace,
    (p_activity->>'avg_speed_mps')::numeric, v_max_speed, (p_activity->>'avg_heartrate')::numeric,
    coalesce((p_activity->>'elevation_gain_m')::numeric, 0), v_manual, left(p_activity->>'device_name', 80),
    case v_status when 'APPROVED' then 'READY' when 'PENDING' then 'PROCESSING' else 'REJECTED' end, v_status,
    case when v_history_only then v_reason || ' Bài chạy trước khi kết nối — chỉ lưu lịch sử.' else v_reason end,
    null,
    case when v_history_only then now() end,
    case when v_history_only then 0 end,
    case when v_history_only then 0 end,
    case when v_status = 'PENDING' then v_score else (v_risk->>'score')::int end,
    case when v_status = 'PENDING' then v_level else v_risk->>'level' end,
    case when v_flags = '[]'::jsonb then v_risk->'flags' else v_flags end)
  on conflict (source, source_activity_id) where source_activity_id is not null do nothing;

  if not exists (select 1 from public.activities x where x.id = v_id) then  -- request song song đã chèn trước
    v_id := (select x.id from public.activities x where x.source = p_source and x.source_activity_id = p_external_id);
    return jsonb_build_object('result', 'DUPLICATE', 'activity_id', v_id);
  end if;

  a := (select x from public.activities x where x.id = v_id);   -- trigger đã trả thưởng nếu APPROVED
  return jsonb_build_object('result', 'IMPORTED', 'activity_id', v_id,
    'validation_status', a.validation_status, 'reason', a.validation_reason,
    'history_only', v_history_only,
    'earned_xu', coalesce(a.earned_xu, 0), 'earned_xp', coalesce(a.earned_xp, 0));
end $$;

-- ---------------------------------------------------------------------
-- 2. Khôi phục bài bị loại: không áp cho bài nhập tay (bản 012500 + kiểm tra nhập tay)
-- ---------------------------------------------------------------------
create or replace function public.restore_activity(p_activity_id uuid, p_note text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  a public.activities := (select x from public.activities x where x.id = p_activity_id);
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if a.id is null or coalesce(a.status, '') = 'DELETED' then raise exception 'ACTIVITY_NOT_FOUND'; end if;
  if a.validation_status <> 'REJECTED' then raise exception 'ACTIVITY_NOT_REJECTED'; end if;
  -- 013400: bài nhập tay từ đối tác không bao giờ được ghi nhận (Phụng chốt 06/10/2026) → không khôi phục
  if coalesce(a.is_manual, false) and a.source in ('STRAVA', 'GARMIN', 'COROS') then raise exception 'MANUAL_NOT_COUNTED'; end if;
  if a.user_id = v_uid or not private.can_review_activity(a.user_id) then raise exception 'FORBIDDEN'; end if;
  if v_note is null or length(v_note) < 5 then raise exception 'NOTE_REQUIRED'; end if;
  -- Bài bị loại vì trùng giờ với bài khác đang được tính → khôi phục sẽ tính 2 lần
  if exists (select 1 from public.activities x
              where x.user_id = a.user_id and x.id <> a.id and x.validation_status = 'APPROVED'
                and coalesce(x.status, '') <> 'DELETED'
                and x.started_at < coalesce(a.ended_at, a.started_at) and coalesce(x.ended_at, x.started_at) > a.started_at) then
    raise exception 'OVERLAPS_COUNTED_RUN';
  end if;

  perform set_config('racehub.decision_kind', 'RESTORE', true);
  update public.activities
     set validation_status = 'APPROVED', status = 'READY',
         validation_reason = 'Đã khôi phục sau khi xem xét lại.',
         review_detail = left('Khôi phục: ' || v_note || coalesce(' · Trước đó: ' || coalesce(review_detail, validation_reason), ''), 500),
         reviewed_by = v_uid, reviewed_at = now(), updated_at = now()
   where id = a.id;                      -- APPROVED → trigger trả thưởng + cộng vào thử thách
  perform set_config('racehub.decision_kind', '', true);

  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_uid, 'RESTORE_ACTIVITY', a.id::text, jsonb_build_object('note', v_note));

  perform private.notify(a.user_id, null, 'RUN_REVIEW', 'Bài chạy đã được khôi phục',
    round(coalesce(a.distance_m, 0) / 1000.0, 2) || ' km — đã xem xét lại và ghi nhận, cộng Xu, XP và thử thách.',
    '/activities/' || a.id, v_uid, true);
end $$;

/** Bài bị loại trong N ngày gần đây mà người gọi được quyền xem lại (BQT CLB của người chạy hoặc admin) */
create or replace function public.rejected_activities(p_club_id uuid default null, p_days integer default 30) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if p_club_id is not null and not public.club_is_staff(p_club_id) then raise exception 'FORBIDDEN'; end if;
  if p_club_id is null and not public.is_system_admin() then raise exception 'FORBIDDEN'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'title', a.title, 'distance_m', a.distance_m, 'moving_time_s', a.moving_time_s,
      'started_at', a.started_at, 'created_at', a.created_at, 'source', a.source,
      'validation_reason', coalesce(a.review_detail, a.validation_reason), 'risk_score', a.risk_score, 'risk_level', a.risk_level,
      'risk_flags', a.risk_flags, 'user_id', a.user_id, 'can_review', a.user_id <> auth.uid(), 'reviewed_at', a.reviewed_at,
      'overlap', coalesce(a.validation_reason, '') like 'Trùng giờ%',
      'manual', coalesce(a.is_manual, false) and a.source in ('STRAVA', 'GARMIN', 'COROS'),
      'profiles', jsonb_build_object('display_name', pr.display_name, 'avatar_url', pr.avatar_url))
      order by coalesce(a.reviewed_at, a.updated_at, a.created_at) desc), '[]'::jsonb)
    from public.activities a
    join public.profiles pr on pr.id = a.user_id
   where a.validation_status = 'REJECTED' and coalesce(a.status, '') <> 'DELETED'
     and coalesce(a.reviewed_at, a.updated_at, a.created_at) > now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 180))
     and (p_club_id is null or exists (select 1 from public.club_members m
                                        where m.club_id = p_club_id and m.user_id = a.user_id and m.status = 'APPROVED')));
end $$;

-- ---------------------------------------------------------------------
-- 3. Bài có cảnh báo (đã ghi nhận) — admin hệ thống / Ban quản trị CLB
-- ---------------------------------------------------------------------
create index if not exists activities_warned_idx on public.activities (started_at desc)
  where validation_status = 'APPROVED' and risk_flags is not null;

/** Mức của một dấu hiệu: tier (012500) hoặc suy từ severity như màn duyệt bài (PendingRunCard) */
create or replace function private.flag_tier(f jsonb) returns text
language sql immutable as $$
  select coalesce(f->>'tier', case f->>'severity' when 'SEVERE' then 'SUSPECT' when 'HIGH' then 'WARN' else 'NOTE' end)
$$;

/** Bài đã ghi nhận nhưng có cảnh báo (GPS nhảy, chạy máy…) trong N ngày — mới nhất trước, tối đa 300 bài.
 *  p_club_id null: toàn hệ thống (chỉ admin hệ thống); có p_club_id: bài của thành viên CLB (Ban quản trị CLB hoặc admin). */
create or replace function public.warned_activities(p_club_id uuid default null, p_days integer default 30) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if p_club_id is not null and not public.club_is_staff(p_club_id) then raise exception 'FORBIDDEN'; end if;
  if p_club_id is null and not public.is_system_admin() then raise exception 'FORBIDDEN'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
      'id', w.id, 'title', w.title, 'distance_m', w.distance_m, 'moving_time_s', w.moving_time_s,
      'started_at', w.started_at, 'created_at', w.created_at, 'source', w.source, 'user_id', w.user_id,
      'risk_score', w.risk_score, 'risk_level', w.risk_level, 'reviewed', w.reviewed_by is not null,
      'warnings', w.warnings,
      'profiles', jsonb_build_object('display_name', pr.display_name, 'avatar_url', pr.avatar_url))
      order by w.started_at desc), '[]'::jsonb)
    from (select a.*, row_number() over (order by a.started_at desc, a.id) as rn,
                 (select jsonb_agg(jsonb_build_object('code', f->>'code', 'tier', private.flag_tier(f), 'message', f->>'message',
                                                      'gpsJump', coalesce((f->>'gpsJump')::boolean, f->>'code' in ('GPS_TELEPORT', 'GPS_DISTANCE_GAIN'))))
                    from jsonb_array_elements(case when jsonb_typeof(a.risk_flags) = 'array' then a.risk_flags else '[]'::jsonb end) f where private.flag_tier(f) <> 'NOTE') as warnings
            from public.activities a
           where a.validation_status = 'APPROVED' and a.risk_flags is not null and jsonb_typeof(a.risk_flags) = 'array'
             and coalesce(a.status, '') <> 'DELETED'
             and a.started_at > now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 180))
             and exists (select 1 from jsonb_array_elements(case when jsonb_typeof(a.risk_flags) = 'array' then a.risk_flags else '[]'::jsonb end) f where private.flag_tier(f) <> 'NOTE')
             and (p_club_id is null or exists (select 1 from public.club_members m
                                                where m.club_id = p_club_id and m.user_id = a.user_id and m.status = 'APPROVED'))) w
    join public.profiles pr on pr.id = w.user_id
   where w.rn <= 300);
end $$;

revoke all on function public.ingest_provider_activity(uuid, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.ingest_provider_activity(uuid, text, text, jsonb) to service_role;
revoke all on function private.flag_tier(jsonb) from public, anon, authenticated;
revoke all on function public.restore_activity(uuid, text), public.rejected_activities(uuid, integer),
  public.warned_activities(uuid, integer) from public, anon;
grant execute on function public.restore_activity(uuid, text), public.rejected_activities(uuid, integer),
  public.warned_activities(uuid, integer) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001013500_quest_draw_round7.sql
-- ===================================================================
-- 013500: Chỉnh sửa lần 7 — quay thưởng: Ban tổ chức CHẤP NHẬN hoặc HUỶ kết quả trước khi kết quả thành chính thức.
--   • "Kết thúc" (finish_lucky_draw) và "Quay nhanh tất cả" (run_lucky_draw) không công bố ngay nữa: lượt quay chuyển sang
--     PENDING = chờ ban tổ chức xác nhận. Chưa báo người trúng, chưa đăng bảng tin, chưa tính là "đã trúng" chính thức.
--   • confirm_lucky_draw: người có quyền quay thưởng bấm "Chấp nhận" → DONE, ghi ai / lúc nào chấp nhận, rồi mới công bố
--     (báo người trúng + đăng bảng tin như trước).
--   • reject_lucky_draw: "Huỷ kết quả" → ghi nhật ký lucky_draw_rejections (ai huỷ, lúc nào, lý do, danh sách trúng bị huỷ, seed /
--     mã băm của lần quay đó để đối chiếu), xoá người trúng, đưa lượt quay về READY để quay lại (lần quay mới có seed mới).
--     Mọi người xem được SỐ LẦN kết quả bị huỷ (minh bạch, tránh "quay tới khi vừa ý" mà không ai biết); chi tiết chỉ ban tổ chức xem.
--   • Seed của lần quay được hiện từ lúc PENDING (thứ tự đã chốt, quay xong rồi) để ban tổ chức đối chiếu trước khi chấp nhận.
--   • Dữ liệu cũ: lượt DONE từ trước giữ nguyên = coi như đã chấp nhận (confirmed_at rỗng).
-- Giữ nguyên chữ ký, kiểu trả về và quyền gọi của finish_lucky_draw / run_lucky_draw / lucky_draws_for.
-- Cần 009500. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT, không RETURNING INTO. Chạy lại an toàn.

-- ---------------------------------------------------------------------
-- 1. Trạng thái chờ xác nhận + nhật ký huỷ kết quả
-- ---------------------------------------------------------------------
alter table public.lucky_draws drop constraint if exists lucky_draws_status_check;
alter table public.lucky_draws add constraint lucky_draws_status_check check (status in ('READY', 'LIVE', 'PENDING', 'DONE', 'CANCELLED'));
alter table public.lucky_draws add column if not exists confirmed_by uuid references public.profiles(id) on delete set null;
alter table public.lucky_draws add column if not exists confirmed_at timestamptz;

create table if not exists public.lucky_draw_rejections (
  id uuid primary key default gen_random_uuid(),
  draw_id uuid not null references public.lucky_draws(id) on delete cascade,
  rejected_by uuid references public.profiles(id) on delete set null,
  rejected_at timestamptz not null default now(),
  reason text check (reason is null or char_length(reason) <= 300),
  -- Kết quả bị huỷ: [{key, name, prize, prize_idx, position, status}]
  winners jsonb not null default '[]'::jsonb,
  seed text,
  seed_hash text,
  entrants_hash text,
  entrant_count integer,
  started_at timestamptz,
  run_at timestamptz
);
create index if not exists lucky_draw_rejections_draw_idx on public.lucky_draw_rejections (draw_id, rejected_at);
alter table public.lucky_draw_rejections enable row level security;
revoke all on public.lucky_draw_rejections from anon, authenticated;

-- ---------------------------------------------------------------------
-- 2. JSON lượt quay: thêm người chấp nhận, số lần huỷ kết quả (mọi người), chi tiết huỷ (ban tổ chức)
-- ---------------------------------------------------------------------
create or replace function private.draw_json(d public.lucky_draws, p_manage boolean) returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(d) - 'created_by' - 'run_by' - 'confirmed_by' - 'pool' - 'picked' - 'excluded' - 'seed' - 'manual_names' - 'pool_names'
    || jsonb_build_object('can_manage', p_manage,
    -- 013500: hiện seed từ lúc quay xong (PENDING) để ban tổ chức đối chiếu trước khi chấp nhận
    'seed', case when d.status in ('PENDING', 'DONE') then d.seed end,
    'creator_name', private.display_name(d.created_by),
    'confirmed_by_name', case when d.confirmed_by is not null then private.display_name(d.confirmed_by) end,
    'picked_count', cardinality(d.picked), 'excluded_count', cardinality(d.excluded), 'manual_count', cardinality(d.manual_names),
    'event', (select jsonb_build_object('id', e.id, 'title', e.title, 'starts_at', e.starts_at) from public.club_events e where e.id = d.event_id),
    'winners', coalesce((select jsonb_agg(jsonb_build_object('key', coalesce(w.user_id::text, w.entry), 'user_id', w.user_id,
                  'name', case when w.user_id is null then private.draw_entry_name(w.entry) else private.display_name(w.user_id) end,
                  'avatar_url', pr.avatar_url, 'prize', w.prize, 'prize_idx', w.prize_idx, 'position', w.position, 'status', w.status,
                  'me', w.user_id is not null and w.user_id = auth.uid()) order by w.position)
                from public.lucky_draw_winners w left join public.profiles pr on pr.id = w.user_id where w.draw_id = d.id), '[]'::jsonb),
    'eligible_now', case when d.status = 'READY' and p_manage then
                           case when d.rule = 'MANUAL' then cardinality(d.manual_names) else cardinality(private.draw_pool(d)) end
                         when d.status = 'LIVE' then coalesce(cardinality(d.pool), 0) + coalesce(cardinality(d.pool_names), 0)
                           - (select count(*)::int from public.lucky_draw_winners w where w.draw_id = d.id) end,
    'reel', case when d.status = 'LIVE' then
              case when d.rule = 'MANUAL' then
                coalesce((select jsonb_agg(jsonb_build_object('name', private.draw_entry_name(t.k), 'avatar_url', null))
                            from (select k, row_number() over (order by random()) as rn from unnest(d.pool_names) k) t where t.rn <= 40), '[]'::jsonb)
              else coalesce((select jsonb_agg(jsonb_build_object('name', private.display_name(t.u), 'avatar_url', pr.avatar_url))
                  from (select u, row_number() over (order by random()) as rn from unnest(d.pool) u) t
                  join public.profiles pr on pr.id = t.u where t.rn <= 40), '[]'::jsonb) end end,
    'reject_count', (select count(*)::int from public.lucky_draw_rejections r where r.draw_id = d.id),
    'rejections', case when p_manage then coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'at', r.rejected_at,
                      'by_name', case when r.rejected_by is not null then private.display_name(r.rejected_by) end, 'reason', r.reason,
                      'winners', r.winners, 'seed', r.seed, 'seed_hash', r.seed_hash, 'entrant_count', r.entrant_count) order by r.rejected_at)
                    from public.lucky_draw_rejections r where r.draw_id = d.id), '[]'::jsonb) end)
$$;

-- ---------------------------------------------------------------------
-- 3. Kết thúc quay → chờ xác nhận (không công bố)
-- ---------------------------------------------------------------------
create or replace function public.finish_lucky_draw(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  d public.lucky_draws := (select x from public.lucky_draws x where x.id = p_id for update);
begin
  if d.id is null or not private.draw_can_manage(d.scope, d.ref_id) then raise exception 'FORBIDDEN'; end if;
  if d.status = 'PENDING' then return private.draw_json(d, true); end if;
  if d.status <> 'LIVE' then raise exception 'DRAW_NOT_LIVE'; end if;
  if not exists (select 1 from public.lucky_draw_winners w where w.draw_id = d.id and w.status = 'WON') then raise exception 'NO_WINNERS'; end if;
  update public.lucky_draws set status = 'PENDING', run_at = now(), run_by = coalesce(run_by, v_uid) where id = d.id;
  d := (select t from public.lucky_draws t where t.id = d.id);
  return private.draw_json(d, true);
end $$;

-- ---------------------------------------------------------------------
-- 4. Chấp nhận kết quả → chính thức: báo người trúng + đăng bảng tin
-- ---------------------------------------------------------------------
create or replace function public.confirm_lucky_draw(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  d public.lucky_draws := (select x from public.lucky_draws x where x.id = p_id for update);
begin
  if d.id is null or not private.draw_can_manage(d.scope, d.ref_id) then raise exception 'FORBIDDEN'; end if;
  if d.status = 'DONE' then return private.draw_json(d, true); end if;
  if d.status <> 'PENDING' then raise exception 'DRAW_NOT_PENDING'; end if;
  if not exists (select 1 from public.lucky_draw_winners w where w.draw_id = d.id and w.status = 'WON') then raise exception 'NO_WINNERS'; end if;
  update public.lucky_draws set status = 'DONE', confirmed_by = v_uid, confirmed_at = now() where id = d.id;
  perform private.draw_announce(d.id, v_uid);
  d := (select t from public.lucky_draws t where t.id = d.id);
  return private.draw_json(d, true);
end $$;

-- ---------------------------------------------------------------------
-- 5. Huỷ kết quả → ghi nhật ký, xoá người trúng, quay lại từ đầu
-- ---------------------------------------------------------------------
create or replace function public.reject_lucky_draw(p_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  d public.lucky_draws := (select x from public.lucky_draws x where x.id = p_id for update);
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if d.id is null or not private.draw_can_manage(d.scope, d.ref_id) then raise exception 'FORBIDDEN'; end if;
  if d.status <> 'PENDING' then raise exception 'DRAW_NOT_PENDING'; end if;
  if char_length(coalesce(v_reason, '')) > 300 then raise exception 'REASON_TOO_LONG'; end if;
  insert into public.lucky_draw_rejections (draw_id, rejected_by, reason, winners, seed, seed_hash, entrants_hash, entrant_count, started_at, run_at)
  values (d.id, v_uid, v_reason,
          coalesce((select jsonb_agg(jsonb_build_object('key', coalesce(w.user_id::text, w.entry), 'user_id', w.user_id,
                      'name', case when w.user_id is null then private.draw_entry_name(w.entry) else private.display_name(w.user_id) end,
                      'prize', w.prize, 'prize_idx', w.prize_idx, 'position', w.position, 'status', w.status) order by w.position)
                     from public.lucky_draw_winners w where w.draw_id = d.id), '[]'::jsonb),
          d.seed, d.seed_hash, d.entrants_hash, d.entrant_count, d.started_at, d.run_at);
  delete from public.lucky_draw_winners where draw_id = d.id;
  -- Về READY: lần "Bắt đầu" sau chốt lại danh sách và tạo seed mới
  update public.lucky_draws set status = 'READY', pool = null, pool_names = null, seed = null, seed_hash = null, entrant_count = null,
         entrants_hash = null, started_at = null, run_at = null, run_by = null
   where id = d.id;
  d := (select t from public.lucky_draws t where t.id = d.id);
  return private.draw_json(d, true);
end $$;

-- ---------------------------------------------------------------------
-- 6. Quyền
-- ---------------------------------------------------------------------
revoke all on function private.draw_json(public.lucky_draws, boolean) from public, anon, authenticated;
revoke all on function public.finish_lucky_draw(uuid), public.confirm_lucky_draw(uuid), public.reject_lucky_draw(uuid, text) from public, anon;
grant execute on function public.finish_lucky_draw(uuid), public.confirm_lucky_draw(uuid), public.reject_lucky_draw(uuid, text) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001013600_run_reminder.sql
-- ===================================================================
-- Nhắc runner 3 ngày chưa có bài chạy (Phụng yêu cầu 2026-10-06).
-- Luật cố định, không AI (ADR-018): runner có bài hợp lệ gần nhất cách đây 3–30 ngày, chưa bị khóa,
-- và chưa được nhắc trong 7 ngày qua thì nhận 1 thông báo (chuông + push theo cài đặt "Thành tích").
-- Giờ gửi do cron quyết định (10:30 UTC = 17:30 giờ VN). Idempotent: chạy lại trong ngày không nhắc thêm.

-- Loại thông báo mới thuộc nhóm "game" để dùng chung công tắc "Thành tích", không đổi bảng cài đặt push
create or replace function private.push_category(p_kind text) returns text
language sql immutable as $$
  select case
    when p_kind like 'CLUB\_%' or p_kind = 'CHAT_MENTION' then 'club'
    when p_kind like 'POST\_%' or p_kind = 'CHEER' then 'social'
    when p_kind like 'CHALLENGE\_%' then 'challenge'
    when p_kind in ('BADGE', 'LEVEL_UP', 'LEAGUE', 'RUN_REMINDER') then 'game'
    else 'system'
  end
$$;

create or replace function public.send_run_reminders() returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in
    select u.user_id, u.last_run
      from (select a.user_id, max(a.started_at) as last_run
              from public.activities a
             where a.validation_status = 'APPROVED' and coalesce(a.status, '') <> 'DELETED'
             group by a.user_id) u
      join public.profiles p on p.id = u.user_id
     where p.banned_at is null
       and u.last_run <= now() - interval '3 days'
       and u.last_run >  now() - interval '30 days'
       and not exists (select 1 from public.notifications x
                        where x.user_id = u.user_id and x.kind = 'RUN_REMINDER' and x.created_at > now() - interval '7 days')
     order by u.last_run desc
     limit 500
  loop
    perform private.notify(r.user_id, null, 'RUN_REMINDER',
      'Đã vài ngày chưa thấy bạn chạy',
      'Một buổi nhẹ 20–30 phút cũng đủ giữ nhịp. Mở RaceHub để xem thử thách đang chờ bạn.',
      '/me');
    n := n + 1;
  end loop;
  return n;
end $$;

revoke all on function public.send_run_reminders() from public, anon, authenticated;
grant execute on function public.send_run_reminders() to service_role;
revoke all on function private.push_category(text) from public, anon, authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001013700_overlap_pending_review.sql
-- ===================================================================
-- 013700: bài trùng giờ dài hơn nhưng nghi vấn → chờ duyệt; duyệt xong thì bài trùng giờ bị loại (Phụng yêu cầu 2026-10-07).
--   • Trước: bài mới dài hơn hẳn (> 110% tổng các bài đang tính trùng giờ) nhưng đang nghi vấn chờ xác minh bị loại ngay,
--     admin cũng không khôi phục được khi bài kia còn đang tính.
--   • Nay: bài đó nằm ở trạng thái CHỜ DUYỆT (chưa tính, chưa thưởng). Admin hoặc chủ nhiệm / đội trưởng CLB duyệt "Hợp lệ" thì các bài
--     trùng giờ (đang tính hoặc đang chờ) bị loại cùng lúc, thu hồi Xu / XP / nhiệm vụ / thử thách; duyệt "Không hợp lệ" thì bài kia giữ nguyên.
--   • Người chạy tự bấm "chỉ tính phần có GPS" không được dùng khi còn bài trùng giờ (tránh tính 2 lần, không qua người duyệt).
--   • Bài ngắn hơn / dài hơn không quá 10% vẫn bị loại như 009900.
-- Cần 009900, 002400, 009700. Chạy được trong SQL Editor: không DO $$, không SELECT INTO, không LIMIT, không RETURNING INTO. Chạy lại an toàn.

create or replace function private.activity_overlap_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_end timestamptz;
  v_ids uuid[];
  v_old numeric;
  v_new numeric;
  v_id uuid;
begin
  if new.user_id is null or new.started_at is null or coalesce(new.status, '') = 'DELETED' then return new; end if;
  -- Hai máy gửi cùng lúc: bài sau chờ bài trước ghi xong rồi mới so
  perform pg_advisory_xact_lock(hashtextextended('activity_overlap:' || new.user_id::text, 0));
  v_end := coalesce(new.ended_at, new.started_at + make_interval(secs => greatest(coalesce(new.elapsed_time_s, new.moving_time_s, 0), 0)));

  -- Gửi lại đúng bài cũ (không có mã bài của nguồn) → không tạo bài mới
  if new.source_activity_id is null and exists (
       select 1 from public.activities x
        where x.user_id = new.user_id and x.source is not distinct from new.source and x.source_activity_id is null
          and x.started_at = new.started_at and coalesce(x.ended_at, x.started_at) = v_end) then
    raise exception 'ACTIVITY_DUPLICATE';
  end if;

  v_ids := private.overlap_ids(new.user_id, new.started_at, v_end, new.id);
  if cardinality(v_ids) = 0 then return new; end if;
  v_old := private.overlap_meters(v_ids);
  v_new := private.activity_meters(new.moving_distance_m, new.distance_m);

  if new.validation_status = 'APPROVED' and new.rewarded_at is null and v_new > v_old * 1.1 then
    -- Bài mới dài hơn hẳn → tính bài mới, bỏ các bài trùng giờ
    foreach v_id in array v_ids loop
      perform private.revoke_run_reward(v_id, 'Thu hồi thưởng — bài trùng giờ với bài dài hơn');
    end loop;
    update public.activities
       set validation_status = 'REJECTED', status = 'REJECTED', validation_reason = 'Trùng giờ với bài chạy khác.',
           review_detail = left('Trùng giờ với bài ' || new.id || ' (' || round(v_new / 1000.0, 2) || ' km) — chỉ tính bài dài hơn.', 500),
           updated_at = now()
     where id = any(v_ids);
    return new;
  end if;

  -- 013700: dài hơn hẳn nhưng đang nghi vấn chờ xác minh → giữ ở trạng thái chờ duyệt, không tính, không thay bài đang tính
  if new.validation_status = 'PENDING' and v_new > v_old * 1.1 then
    new.review_detail := left('Trùng giờ với ' || array_to_string(v_ids, ', ') || ' (' || round(v_old / 1000.0, 2) || ' km đang được tính). '
                              || 'Bài này dài hơn: nếu được duyệt hợp lệ, các bài trùng giờ sẽ bị loại'
                              || coalesce(' · ' || new.review_detail, '') || '.', 500);
    return new;
  end if;

  -- Ngược lại: lưu bài mới vào lịch sử nhưng không tính
  new.review_detail := left('Trùng giờ với ' || array_to_string(v_ids, ', ') || ' (' || round(v_old / 1000.0, 2) || ' km đang được tính)'
                            || coalesce(' · ' || new.review_detail, '') || '.', 500);
  new.validation_status := 'REJECTED';
  new.status := 'REJECTED';
  new.validation_reason := 'Trùng giờ với bài chạy khác.';
  return new;
end $$;

-- Duyệt bài chờ: "Hợp lệ" thì loại luôn các bài trùng giờ (đang tính hoặc đang chờ), thu hồi thưởng của chúng
create or replace function public.review_activity(p_activity_id uuid, p_status text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  a public.activities := (select x from public.activities x where x.id = p_activity_id and x.validation_status = 'PENDING');
  v_end timestamptz;
  v_ids uuid[] := '{}';
  v_id uuid;
begin
  if p_status not in ('APPROVED', 'REJECTED') then raise exception 'INVALID_STATUS'; end if;
  if a.id is null then raise exception 'ACTIVITY_NOT_PENDING'; end if;
  if a.user_id = v_uid or not private.can_review_activity(a.user_id) then raise exception 'FORBIDDEN'; end if;

  if p_status = 'APPROVED' then
    perform pg_advisory_xact_lock(hashtextextended('activity_overlap:' || a.user_id::text, 0));
    v_end := coalesce(a.ended_at, a.started_at + make_interval(secs => greatest(coalesce(a.elapsed_time_s, a.moving_time_s, 0), 0)));
    v_ids := private.overlap_ids(a.user_id, a.started_at, v_end, a.id);
    foreach v_id in array v_ids loop
      perform private.revoke_run_reward(v_id, 'Thu hồi thưởng — bài trùng giờ đã được duyệt thay thế');
    end loop;
    if cardinality(v_ids) > 0 then
      update public.activities
         set validation_status = 'REJECTED', status = 'REJECTED', validation_reason = 'Trùng giờ với bài chạy khác.',
             review_detail = left('Trùng giờ với bài ' || a.id || ' đã được ban quản trị duyệt hợp lệ — chỉ tính bài đó.', 500),
             updated_at = now()
       where id = any(v_ids);
    end if;
  end if;

  update public.activities
     set validation_status = p_status,
         status = case when p_status = 'APPROVED' then 'READY' else 'REJECTED' end,
         reviewed_by = v_uid, reviewed_at = now(), updated_at = now()
   where id = a.id;                      -- APPROVED → trigger trả thưởng + cộng vào thử thách

  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_uid, 'REVIEW_ACTIVITY', a.id::text, jsonb_build_object('status', p_status, 'rejected_overlaps', to_jsonb(v_ids)));

  perform private.notify(a.user_id, null, 'RUN_REVIEW',
    case when p_status = 'APPROVED' then 'Bài chạy đã được xác minh' else 'Bài chạy không được ghi nhận' end,
    round(coalesce(a.distance_m, 0) / 1000.0, 2) || ' km — ' ||
      case when p_status = 'APPROVED' then 'đã cộng Xu, XP và tính vào thử thách.'
           else 'ban quản trị xác định dữ liệu không hợp lệ.' end
      || case when cardinality(v_ids) > 0 then ' ' || cardinality(v_ids) || ' bài trùng giờ không còn được tính.' else '' end,
    '/activities/' || a.id, v_uid, true);
end $$;

-- Người chạy không tự duyệt "chỉ tính phần có GPS" khi còn bài trùng giờ (phải qua người duyệt)
create or replace function private.can_accept_verified(a public.activities) returns boolean
language sql stable security definer set search_path = public as $$
  select a.validation_status = 'PENDING' and coalesce(a.status, '') <> 'DELETED'
     and private.gap_meters(a.risk_flags) > 0 and coalesce(a.risk_score, 0) < 65
     and not exists (select 1 from jsonb_array_elements(case when jsonb_typeof(a.risk_flags) = 'array' then a.risk_flags else '[]'::jsonb end) f
                      where f->>'code' <> 'GPS_GAP' and f->>'severity' in ('HIGH', 'SEVERE'))
     and cardinality(private.overlap_ids(a.user_id, a.started_at,
           coalesce(a.ended_at, a.started_at + make_interval(secs => greatest(coalesce(a.elapsed_time_s, a.moving_time_s, 0), 0))), a.id)) = 0
$$;

revoke all on function private.activity_overlap_guard(), private.can_accept_verified(public.activities) from public, anon, authenticated;
revoke all on function public.review_activity(uuid, text) from public, anon;
grant execute on function public.review_activity(uuid, text) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001013800_conquest_any_mode.sql
-- ===================================================================
-- Chinh phục cự ly: thêm chế độ ANY cho thử thách chinh phục.
--   Người tạo chỉ đặt cự ly các hạng mục (không đặt thời gian/pace). Người chơi chạy MỘT bài có cự ly ≥ 99% hạng mục
--   (cùng ngưỡng với chinh phục thời gian/pace) là đạt hạng mục đó. Dùng objective BEST_TIME để mọi luật hiện có
--   (đăng ký hạng mục, chia thưởng FINISHERS, vinh danh, bài trùng giờ, chống gian lận) giữ nguyên.
alter table public.challenges drop constraint if exists challenges_conquest_mode_chk;
alter table public.challenges add constraint challenges_conquest_mode_chk
  check (conquest_mode is null or conquest_mode in ('FIXED', 'SELF', 'ANY'));

-- ---------------------------------------------------------------------
-- 1. Tính điểm: bản 010700, hạng mục ở chế độ ANY đạt ngay khi có bài đủ cự ly
-- ---------------------------------------------------------------------
create or replace function private.challenge_recompute_participant(p_participant_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  p public.challenge_participants := (select x from public.challenge_participants x where x.id = p_participant_id);
  c public.challenges;
  v_dist numeric; v_moving bigint; v_runs integer; v_days integer; v_score numeric; v_target numeric;
begin
  if p.id is null then return; end if;
  perform 1 from public.challenge_participants where id = p.id for update;
  c := (select x from public.challenges x where x.id = p.challenge_id);

  v_dist := (select coalesce(sum(e.counted_m), 0) from public.challenge_progress_events e where e.participant_id = p.id);
  v_moving := (select coalesce(sum(e.moving_s), 0) from public.challenge_progress_events e where e.participant_id = p.id);
  v_runs := (select count(*) from public.challenge_progress_events e where e.participant_id = p.id and e.counted_m > 0);
  v_days := (select count(*) from (
               select e.day from public.challenge_progress_events e where e.participant_id = p.id
                group by e.day having sum(e.distance_m) >= greatest(coalesce(c.min_km, 0), 0.2) * 1000) d);

  if c.objective in ('BEST_TIME', 'BEST_PACE') then
    -- Kết quả tốt nhất cho từng hạng mục: bài có cự ly ≥ hạng mục, quy đổi theo pace trung bình
    update public.challenge_category_entries
       set best_time_s = null, best_pace_s = null, best_activity_id = null, best_at = null, achieved_at = null
     where participant_id = p.id;
    update public.challenge_category_entries ce
       set best_time_s = b.t, best_pace_s = b.pace, best_activity_id = b.aid, best_at = b.at,
           achieved_at = case when c.conquest_mode = 'ANY' then b.at
                              when coalesce(ce.target_s, b.cat_target) is not null
                                   and (case when c.objective = 'BEST_PACE' then b.pace else b.t end) <= coalesce(ce.target_s, b.cat_target)
                              then b.at end
      from (select distinct on (cat.id) cat.id as cat_id, cat.target_s as cat_target,
                   round(e.moving_s * cat.distance_m / e.distance_m)::int as t,
                   round(e.moving_s * 1000.0 / e.distance_m)::int as pace,
                   e.activity_id as aid, a.started_at as at
              from public.challenge_categories cat
              join public.challenge_progress_events e on e.participant_id = p.id
                                                       and e.distance_m >= cat.distance_m * 0.99 and e.moving_s > 0
              join public.activities a on a.id = e.activity_id
             where cat.challenge_id = c.id
             order by cat.id, e.moving_s / e.distance_m, a.started_at) b
     where ce.participant_id = p.id and ce.category_id = b.cat_id;
    v_score := (select count(*) from public.challenge_category_entries ce where ce.participant_id = p.id and ce.achieved_at is not null);
    v_target := (select count(*) from public.challenge_category_entries ce where ce.participant_id = p.id);
  else
    v_score := case c.objective
      when 'RUNS' then v_runs
      when 'DURATION' then round(v_moving / 60.0, 1)
      when 'STREAK_DAYS' then v_days
      else round(v_dist / 1000.0, 2) end;

    v_target := coalesce(c.target_value, 0);
    if c.pledge_enabled then
      v_target := coalesce(p.pledge_km, 0);           -- chưa đăng ký mục tiêu → chưa thể hoàn thành
      if v_target > 0 and c.pledge_cap_pct is not null then
        v_score := least(v_score, round(v_target * (1 + c.pledge_cap_pct / 100.0), 2));
      end if;
    end if;
  end if;

  update public.challenge_participants
     set distance_m = v_dist, moving_s = v_moving, run_count = v_runs, streak_days = v_days,
         current_progress = v_score,
         completed_at = case when v_target > 0 and v_score >= v_target then coalesce(completed_at, now()) end,
         status = case when status = 'LEFT' then 'LEFT'
                       when v_target > 0 and v_score >= v_target then 'COMPLETED'
                       else 'JOINED' end,
         updated_at = now()
   where id = p.id;
end $$;

-- ---------------------------------------------------------------------
-- 2. Người tạo: chấp nhận mode ANY (không cần target_s)
-- ---------------------------------------------------------------------
create or replace function public.set_challenge_conquest(p_challenge_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.challenges := (select x from public.challenges x where x.id = p_challenge_id);
  v_obj text := upper(coalesce(p->>'objective', ''));
  v_mode text := upper(coalesce(p->>'mode', 'FIXED'));
  v_cats jsonb := case when jsonb_typeof(p->'categories') = 'array' then p->'categories' else '[]'::jsonb end;
  v_n integer := jsonb_array_length(case when jsonb_typeof(p->'categories') = 'array' then p->'categories' else '[]'::jsonb end);
  v_min_m numeric;
  v_before uuid[];
  m record;
begin
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not private.challenge_is_manager(c) then raise exception 'FORBIDDEN'; end if;
  if c.status <> 'ACTIVE' or now() >= c.end_date then raise exception 'CHALLENGE_CLOSED'; end if;
  if c.format <> 'SOLO_GOAL' then raise exception 'CONQUEST_NOT_SUPPORTED'; end if;
  if v_obj not in ('BEST_TIME', 'BEST_PACE') or v_mode not in ('FIXED', 'SELF', 'ANY') then raise exception 'INVALID_CONQUEST'; end if;
  if v_n not between 1 and 8 then raise exception 'INVALID_CONQUEST'; end if;
  if now() >= c.start_date and exists (select 1 from public.challenge_category_entries e where e.challenge_id = c.id) then
    raise exception 'CONQUEST_LOCKED';
  end if;
  begin
    if exists (select 1 from jsonb_array_elements(v_cats) x
                where char_length(trim(coalesce(x->>'label', ''))) not between 1 and 40
                   or (x->>'distance_km')::numeric not between 0.4 and 250
                   or (v_mode = 'FIXED' and coalesce((x->>'target_s')::int, 0) <= 0)
                   or (v_mode = 'FIXED' and v_obj = 'BEST_PACE' and (x->>'target_s')::int not between 120 and 1500)
                   or (v_mode = 'FIXED' and v_obj = 'BEST_TIME' and (x->>'target_s')::int not between 60 and 172800)) then
      raise exception 'INVALID_CONQUEST';
    end if;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'INVALID_CONQUEST';
  end;

  -- Ai đang có đăng ký (để nhắc nếu mất)
  v_before := (select coalesce(array_agg(distinct e.user_id), '{}') from public.challenge_category_entries e where e.challenge_id = c.id);
  -- Đổi kiểu tính / ai đặt mục tiêu: mục tiêu tự đặt cũ không còn ý nghĩa
  if c.objective is distinct from v_obj or c.conquest_mode is distinct from v_mode then
    delete from public.challenge_category_entries where challenge_id = c.id;
  end if;
  -- Hạng mục bị bỏ (vị trí > số hạng mục mới) — xoá kèm đăng ký
  delete from public.challenge_categories where challenge_id = c.id and position > v_n;
  -- Hạng mục đổi cự ly: bỏ đăng ký của hạng mục đó
  delete from public.challenge_category_entries e
   using public.challenge_categories cat, jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where e.category_id = cat.id and cat.challenge_id = c.id and cat.position = t.ord
     and cat.distance_m <> round((t.x->>'distance_km')::numeric * 1000);
  update public.challenge_categories cat
     set label = trim(t.x->>'label'), distance_m = round((t.x->>'distance_km')::numeric * 1000),
         target_s = case when v_mode = 'FIXED' then (t.x->>'target_s')::int end
    from jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where cat.challenge_id = c.id and cat.position = t.ord;
  insert into public.challenge_categories (challenge_id, position, label, distance_m, target_s)
  select c.id, t.ord, trim(t.x->>'label'), round((t.x->>'distance_km')::numeric * 1000),
         case when v_mode = 'FIXED' then (t.x->>'target_s')::int end
    from jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where not exists (select 1 from public.challenge_categories x where x.challenge_id = c.id and x.position = t.ord);

  v_min_m := (select min(distance_m) from public.challenge_categories where challenge_id = c.id);
  update public.challenges
     set objective = v_obj, conquest_mode = v_mode, target_value = 1, target_type = v_obj, target_km = 0,
         pledge_enabled = false, reward_split = 'FINISHERS', game_mode = 'ACCUMULATE',
         -- bài ngắn hơn hạng mục nhỏ nhất không thể cho kết quả → không cần ghi nhận
         min_km = round(v_min_m * 0.99 / 1000.0, 2)
   where id = c.id;
  update public.challenge_participants set pledge_km = null where challenge_id = c.id and pledge_km is not null;

  for m in select u.uid from unnest(v_before) as u(uid)
            where not exists (select 1 from public.challenge_category_entries e where e.challenge_id = c.id and e.user_id = u.uid) loop
    perform private.notify(m.uid, c.target_club_id, 'CHALLENGE_UPDATED', 'Chọn lại hạng mục: ' || left(c.title, 80),
      'Ban tổ chức đã đổi các hạng mục chinh phục, đăng ký cũ của bạn không còn. Vào chọn lại trước giờ bắt đầu.',
      '/challenges/' || c.id, v_uid, true);
  end loop;
  perform private.challenge_recompute_all(c.id);
  return public.challenge_conquest_board(c.id);
end $$;

-- ===================================================================
-- 20261001013900_quote_solo_goal_slots.sql
-- ===================================================================
-- Báo giá thử thách Chinh phục cá nhân nhiều người (vd chinh phục cự ly mừng sự kiện): tính theo số chỗ thật.
--   Trước: quote_challenge luôn coi SOLO_GOAL là 1 chỗ nên báo "miễn phí / đủ hạn mức gói CLB", nhưng khi tạo
--   (create_challenge_v2) phí và hạn mức gói CLB (Free ≤ 50 người, Pro ≤ 1.000) tính theo số chỗ thật → báo giá sai,
--   bấm tạo mới bị từ chối INSUFFICIENT_TREASURY. "Cá nhân tôi" vẫn tính 1 chỗ vì app gửi p_max_slots = 1.
create or replace function public.quote_challenge(p_max_slots integer, p_format text default 'RANKED', p_club_id uuid default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_slots integer := case when p_format = 'DUEL' then 2 else greatest(coalesce(p_max_slots, 1), 1) end;
  v_fee integer := private.challenge_creation_fee(p_format = 'TEAM', v_slots, now(), now() + interval '1 day');
  v_payer uuid := case when p_club_id is not null and public.club_is_staff(p_club_id) then p_club_id else v_uid end;
  v_quota jsonb := case when v_payer <> v_uid then private.club_challenge_quota_json(v_payer, v_slots) end;
  v_list_fee integer := v_fee;
  v_pass public.challenge_passes;
begin
  if v_fee > 0 and coalesce((v_quota->>'eligible')::boolean, false) then v_fee := 0; end if;
  perform private.issue_credits(case when v_payer = v_uid then 'USER' else 'CLUB' end, v_payer);
  v_pass := (select t.x from (select x, row_number() over (order by x.expires_at nulls last, x.max_slots, x.created_at) as rn
                                from public.challenge_passes x
                               where x.owner_id = v_payer and x.remaining > 0 and x.max_slots >= v_slots
                                 and (x.expires_at is null or x.expires_at > now())) t where t.rn = 1);
  return jsonb_build_object(
    'fee', v_fee, 'list_fee', v_list_fee, 'tier', private.capacity_tier(v_slots), 'custom', private.capacity_tier(v_slots)->>'xu' is null,
    'payer', case when v_payer = v_uid then 'USER' else 'CLUB' end,
    'payer_balance', private.balance(v_payer), 'wallet_balance', private.balance(v_uid),
    'pass', case when v_pass.id is null or v_fee = 0 then null
                 else jsonb_build_object('id', v_pass.id, 'remaining', v_pass.remaining, 'max_slots', v_pass.max_slots,
                                         'expires_at', v_pass.expires_at, 'note', v_pass.note) end,
    'plan', private.plan_badge(v_payer, v_payer <> v_uid),
    'club_quota', v_quota,
    'best_pass_slots', coalesce((select max(x.max_slots) from public.challenge_passes x
                                  where x.owner_id = v_payer and x.remaining > 0 and (x.expires_at is null or x.expires_at > now())), 0),
    'xu_vnd', (private.economy_config()->>'xuVnd')::numeric,
    'policy', private.economy_config());
end $$;

-- ===================================================================
-- 20261001014000_admin_save_plan_fix.sql
-- ===================================================================
-- 014000: Sửa lỗi lưu gói ở trang admin (mã UNK-FSZ, "column reference "e" is ambiguous").
-- admin_save_plan (003800) khai báo biến e jsonb rồi lại đặt bí danh e cho jsonb_array_elements ở phần lượt tạo,
-- nên mọi lần lưu có gửi lượt tạo (credits) đều lỗi. Đổi bí danh; trùng quy mô thì lấy dòng sau cùng thay vì lỗi khóa chính.
-- Chạy riêng được ngay; chạy lại 3500.

create or replace function public.admin_save_plan(p jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_admin(); v_code text := upper(trim(coalesce(p->>'code', ''))); e jsonb;
begin
  if not exists (select 1 from public.plans x where x.code = v_code) then raise exception 'INVALID_PLAN'; end if;
  update public.plans set name = coalesce(nullif(trim(p->>'name'), ''), name), description = coalesce(p->>'description', description),
         perks = coalesce(p->'perks', perks), active = coalesce((p->>'active')::boolean, active) where code = v_code;
  if p ? 'prices' then
    for e in select value from jsonb_array_elements(p->'prices') loop
      insert into public.plan_prices (plan_code, months, price_vnd, active)
      values (v_code, (e->>'months')::int, (e->>'price_vnd')::int, coalesce((e->>'active')::boolean, true))
      on conflict (plan_code, months) do update set price_vnd = excluded.price_vnd, active = excluded.active;
    end loop;
  end if;
  if p ? 'credits' then
    delete from public.plan_credits where plan_code = v_code;
    for e in select value from jsonb_array_elements(p->'credits') loop
      if coalesce((e->>'per_month')::int, 0) > 0 then
        insert into public.plan_credits (plan_code, capacity, per_month)
        values (v_code, (e->>'capacity')::int, (e->>'per_month')::int)
        on conflict (plan_code, capacity) do update set per_month = excluded.per_month;
      end if;
    end loop;
  end if;
  insert into public.admin_audit_log (actor_id, action, target, new_value) values (v_uid, 'SAVE_PLAN', v_code, p);
end $$;

-- ===================================================================
-- 20261001014100_club_public_challenge.sql
-- ===================================================================
-- 014100: Thử thách Công khai do CLB tổ chức.
--   Trước: ban quản trị mở tab Thử thách của CLB nhưng chọn "Công khai" thì thử thách thành của cá nhân
--   (trừ ví / lượt gói cá nhân, không mang tên CLB). Nay ban quản trị tạo được thử thách Công khai mang tên CLB:
--   phí trừ quỹ CLB hoặc dùng lượt gói CLB (CLB Pro); hạn mức miễn phí nội bộ (Free ≤ 50, Pro ≤ 1.000 người)
--   chỉ áp dụng cho thử thách nội bộ. Ai cũng tham gia được; thử thách hiện ở tab Thử thách của CLB và ở Khám phá.
--   quote_challenge thêm bản 4 tham số (p_audience); bản 3 tham số giữ nguyên hành vi cũ (nội bộ) cho app cũ.
-- Chạy riêng được ngay; chạy lại 3500.

create or replace function public.create_challenge_v2(p jsonb, p_idempotency_key text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid uuid := private.require_uid();
  v_key text := 'challenge_create:' || v_uid || ':' || coalesce(p_idempotency_key, '');
  v_existing uuid;
  v_title text := trim(coalesce(p->>'title', ''));
  v_desc text := nullif(trim(coalesce(p->>'description', '')), '');
  v_format text := coalesce(p->>'format', 'RANKED');
  v_objective text := coalesce(p->>'objective', 'DISTANCE');
  v_mode text := p->>'game_mode';
  v_target numeric := coalesce((p->>'target_value')::numeric, 0);
  v_min_km numeric := coalesce((p->>'min_km')::numeric, 0);
  v_min_pace numeric := coalesce((p->>'min_pace')::numeric, 3);
  v_max_pace numeric := coalesce((p->>'max_pace')::numeric, 15);
  v_cap numeric := nullif((p->>'daily_cap_km')::numeric, 0);
  v_start timestamptz := (p->>'start_date')::timestamptz;
  v_end timestamptz := (p->>'end_date')::timestamptz;
  v_slots integer := coalesce((p->>'max_slots')::int, 100);
  v_audience text := coalesce(p->>'audience', 'PUBLIC');
  v_club uuid := (p->>'club_id')::uuid;
  v_team_size integer := greatest(coalesce((p->>'team_size')::int, 0), 0);
  v_reward numeric := round(coalesce((p->>'reward_xu')::numeric, 0), 1);
  v_source text := coalesce(p->>'reward_source', 'NONE');
  v_split text := coalesce(p->>'reward_split', 'WINNER');
  v_teams text[];
  v_fee integer := 0;
  v_id uuid;
  v_code text;
  v_club_name text;
  i integer;
  m record;
  v_colors text[] := array['#b6ff3b', '#38bdf8', '#f472b6', '#fb923c', '#a78bfa', '#facc15', '#34d399', '#f87171'];
  v_payer uuid;
  v_pass uuid;
  v_fee_waived integer := 0;
  v_need_user numeric;
  v_need_club numeric;
  v_quota jsonb;
  v_free_reason text;
begin
  if p_idempotency_key is null or length(p_idempotency_key) < 8 then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
  if exists (select 1 from public.ledger_transactions lt where lt.idempotency_key = v_key) then
    v_existing := (select lt.campaign_id from public.ledger_transactions lt where lt.idempotency_key = v_key);
    return jsonb_build_object('challenge_id', v_existing, 'duplicate', true,
                              'invite_code', (select code from public.challenge_invites where challenge_id = v_existing));
  end if;

  -- Kiểm tra dữ liệu (không tin client)
  if char_length(v_title) not between 3 and 120 then raise exception 'INVALID_TITLE'; end if;
  if v_desc is not null and char_length(v_desc) > 2000 then raise exception 'DESC_TOO_LONG'; end if;
  if v_format not in ('SOLO_GOAL', 'RANKED', 'DUEL', 'TEAM', 'COLLECTIVE') then raise exception 'INVALID_FORMAT'; end if;
  if v_objective not in ('DISTANCE', 'RUNS', 'DURATION', 'STREAK_DAYS') then raise exception 'INVALID_OBJECTIVE'; end if;
  if v_start is null or v_end is null or v_end <= v_start then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_end - v_start > interval '366 days' or v_end - v_start < interval '1 hour' then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_end <= now() then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_target < 0 or v_min_km < 0 or v_min_km > 100 or coalesce(v_cap, 0) < 0 then raise exception 'INVALID_DISTANCE'; end if;
  if v_min_pace <= 0 or v_max_pace < v_min_pace or v_max_pace > 30 then raise exception 'INVALID_PACE'; end if;
  if v_format in ('SOLO_GOAL', 'COLLECTIVE') and v_target <= 0 then raise exception 'TARGET_REQUIRED'; end if;
  if v_objective = 'STREAK_DAYS' and (v_min_km <= 0 or v_target > ceil(extract(epoch from v_end - v_start) / 86400)) then
    raise exception 'INVALID_STREAK';
  end if;
  if v_format = 'DUEL' then v_slots := 2; end if;
  if v_slots not between 1 and 10000 then raise exception 'INVALID_MAX_SLOTS'; end if;

  if v_format = 'TEAM' then
    if v_mode not in ('TEAM_SUM', 'TEAM_AVG', 'TEAM_GAP', 'LAST_MEMBER') then raise exception 'INVALID_GAME_MODE'; end if;
    v_teams := (select array_agg(trim(t.v)) from jsonb_array_elements_text(coalesce(p->'team_names', '[]'::jsonb)) as t(v)
                 where trim(t.v) <> '');
    if coalesce(array_length(v_teams, 1), 0) not between 2 and 8 then raise exception 'INVALID_TEAMS'; end if;
    if exists (select 1 from unnest(v_teams) as t(v) where char_length(v) > 40) then raise exception 'INVALID_TEAMS'; end if;
    if v_start < now() + interval '10 minutes' then raise exception 'TEAM_START_TOO_SOON'; end if;
    if v_team_size > 0 then v_slots := least(v_slots, v_team_size * array_length(v_teams, 1)); end if;
  else
    v_mode := case v_objective when 'STREAK_DAYS' then 'STREAK' else 'ACCUMULATE' end;
  end if;

  if v_audience not in ('PUBLIC', 'CLUB_ONLY', 'INVITE_ONLY') then raise exception 'INVALID_AUDIENCE'; end if;
  -- 014100: thử thách Công khai do CLB tổ chức (ban quản trị tạo, quỹ / lượt gói CLB trả phí, ai cũng tham gia được)
  if v_audience = 'CLUB_ONLY' or (v_audience = 'PUBLIC' and v_club is not null and v_format <> 'DUEL') then
    if v_club is null or not public.club_is_staff(v_club) then raise exception 'FORBIDDEN'; end if;
    v_club_name := (select cl.name from public.clubs cl where cl.id = v_club);
  else
    v_club := null;
  end if;

  if v_reward < 0 or v_reward > 100000 then raise exception 'INVALID_AMOUNT'; end if;
  if v_reward = 0 then v_source := 'NONE'; end if;
  if v_source not in ('NONE', 'CREATOR', 'CLUB') then raise exception 'INVALID_REWARD'; end if;
  if v_source = 'CLUB' and v_club is null then raise exception 'FORBIDDEN'; end if;
  if v_split not in ('WINNER', 'TOP3', 'FINISHERS', 'TEAM') then raise exception 'INVALID_REWARD'; end if;
  v_split := case when v_format = 'TEAM' then 'TEAM'
                  when v_format in ('SOLO_GOAL', 'COLLECTIVE') then 'FINISHERS'
                  when v_format = 'DUEL' then 'WINNER'
                  when v_split in ('WINNER', 'TOP3') then v_split else 'WINNER' end;

  -- Phí khởi tạo theo số người tối đa (Admin → Chính sách). Thử thách CLB trả bằng quỹ CLB.
  v_fee := private.challenge_creation_fee(v_format = 'TEAM', v_slots, v_start, v_end);
  v_payer := coalesce(v_club, v_uid);
  -- 008200: thử thách nội bộ CLB (không áp dụng cho Công khai do CLB tổ chức) miễn phí trong hạn mức gói (Free / Pro) — khoá theo CLB để hai người tạo cùng lúc không vượt hạn mức
  if v_club is not null and v_audience = 'CLUB_ONLY' and v_fee > 0 then
    perform pg_advisory_xact_lock(hashtext('club_challenge:' || v_club));
    v_quota := private.club_challenge_quota_json(v_club, v_slots);
    if (v_quota->>'eligible')::boolean then v_fee_waived := v_fee; v_fee := 0; v_free_reason := v_quota->>'plan'; end if;
  end if;
  -- Vé tạo miễn phí (gói VIP / Pro, admin tặng): dùng vé sắp hết hạn trước, vé nhỏ nhất đủ số người
  if v_fee > 0 then
    v_pass := (select t.id from (select x.id, row_number() over (order by x.expires_at nulls last, x.max_slots, x.created_at) as rn
                                   from public.challenge_passes x
                                  where x.owner_id = v_payer and x.remaining > 0 and x.max_slots >= v_slots
                                    and (x.expires_at is null or x.expires_at > now())) t where t.rn = 1);
    if v_pass is not null then
      perform 1 from public.challenge_passes x where x.id = v_pass for update;
      v_fee_waived := v_fee; v_fee := 0;
    end if;
  end if;
  v_need_user := case when v_club is null then v_fee else 0 end + case when v_source = 'CREATOR' then v_reward else 0 end;
  v_need_club := case when v_club is not null then v_fee else 0 end + case when v_source = 'CLUB' then v_reward else 0 end;
  if v_need_user > private.balance(v_uid) then raise exception 'INSUFFICIENT_BALANCE'; end if;
  if v_club is not null and v_need_club > private.balance(v_club) then raise exception 'INSUFFICIENT_TREASURY'; end if;

  v_id := gen_random_uuid();
  insert into public.challenges (id, 
    title, description, format, objective, challenge_type, game_mode, target_type, target_value, target_km,
    min_km, min_pace, max_pace, daily_cap_km, fixed_team_size, min_members, target_audience, target_club_id,
    creator_role, start_date, end_date, reg_deadline, max_slots, calculated_fee, fee_charged,
    reward_xu, reward_source, reward_split, status, created_by)
  values (v_id, 
    v_title, v_desc, v_format, v_objective, case when v_format = 'TEAM' then 'TEAM' else 'INDIVIDUAL' end, v_mode,
    v_objective, v_target, case when v_objective = 'DISTANCE' then v_target else 0 end,
    v_min_km, v_min_pace, v_max_pace, v_cap, v_team_size, 1, v_audience, v_club,
    case when v_club is not null then 'CLUB' else 'MEMBER' end, v_start, v_end,
    case when v_format in ('TEAM') then v_start else v_end end, v_slots, v_fee, v_fee,
    v_reward, v_source, v_split, 'ACTIVE', v_uid);

  -- Phí + dấu idempotency (cùng khóa → trả lại thử thách này)
  if v_fee > 0 then
    perform private.ledger_post('CHALLENGE_CREATION_FEE', v_key,
      case when v_club is not null then 'Phí tạo thử thách (quỹ CLB)' else 'Phí khởi tạo thử thách' end, v_uid,
      private.debit_entries(v_payer, v_fee, private.system_account()), v_id);
    if v_club is not null then
      insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
      values (v_club, v_uid, -v_fee, 'SPEND', left('Phí tạo thử thách: ' || v_title, 200));
    end if;
  else
    insert into public.ledger_transactions (type, idempotency_key, reason, created_by, campaign_id)
    values ('CHALLENGE_CREATION_FEE', v_key,
            case v_free_reason when 'PRO' then 'Miễn phí (hạn mức CLB Pro)' when 'FREE' then 'Miễn phí (hạn mức CLB)' else 'Miễn phí' end, v_uid, v_id);
  end if;

  -- Ký quỹ giải thưởng (giữ ở tài khoản hệ thống tới khi tất toán)
  if v_source = 'CREATOR' then
    perform private.ledger_post('CHALLENGE_ESCROW', 'challenge_escrow:' || v_id, 'Treo thưởng thử thách', v_uid,
      private.debit_entries(v_uid, v_reward, private.system_account()), v_id);
  elsif v_source = 'CLUB' then
    perform private.ledger_post('CHALLENGE_ESCROW', 'challenge_escrow:' || v_id, 'Treo thưởng thử thách (quỹ CLB)', v_uid,
      private.debit_entries(v_club, v_reward, private.system_account()), v_id);
    insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
    values (v_club, v_uid, -v_reward, 'REWARD', left('Treo thưởng: ' || v_title, 200));
  end if;

  if v_format = 'TEAM' then
    for i in 1 .. array_length(v_teams, 1) loop
      insert into public.challenge_teams (challenge_id, name, color, position)
      values (v_id, v_teams[i], v_colors[1 + (i - 1) % array_length(v_colors, 1)], i);
    end loop;
  end if;

  if v_audience <> 'PUBLIC' or v_format = 'DUEL' then
    loop
      v_code := substr(md5(gen_random_uuid()::text), 1, 8);
      exit when not exists (select 1 from public.challenge_invites where code = v_code);
    end loop;
    insert into public.challenge_invites (challenge_id, code) values (v_id, v_code);
  end if;

  -- Người tạo tự vào (trừ thử thách đội — người tạo chọn đội sau — và thử thách CLB do ban quản trị tổ chức)
  if v_format <> 'TEAM' and v_club is null then
    insert into public.challenge_participants (challenge_id, profile_id, status) values (v_id, v_uid, 'JOINED');
  end if;

  -- Thử thách nội bộ CLB: đăng lên bảng tin + báo cả CLB
  if v_club is not null then
    insert into public.club_posts (club_id, author_id, kind, title, body, meta, is_pinned)
    values (v_club, v_uid, 'CHALLENGE', v_title, coalesce(v_desc, ''),
            jsonb_build_object('challenge_id', v_id, 'format', v_format, 'objective', v_objective,
                               'target_value', v_target, 'start_date', v_start, 'end_date', v_end,
                               'reward_xu', v_reward), false);
    for m in select user_id from public.club_members where club_id = v_club and status = 'APPROVED' loop
      perform private.notify(m.user_id, v_club, 'CHALLENGE_NEW',
        'Thử thách mới trong ' || coalesce(v_club_name, 'CLB') || ': ' || v_title,
        case when v_reward > 0 then 'Giải thưởng ' || v_reward || ' Xu. Vào tham gia ngay!' else 'Vào tham gia ngay!' end,
        '/challenges/' || v_id, v_uid, true);
    end loop;
  end if;

  if v_pass is not null then
    update public.challenge_passes set remaining = remaining - 1, updated_at = now() where id = v_pass and remaining > 0;
    update public.challenges set pass_id = v_pass where id = v_id;
  end if;

  return jsonb_build_object('challenge_id', v_id, 'fee', v_fee, 'fee_waived', v_fee_waived, 'pass_used', v_pass is not null, 'club_free', v_free_reason,
                            'invite_code', v_code, 'remaining_balance', private.balance(v_uid));
end $$;

create or replace function public.quote_challenge(p_max_slots integer, p_format text, p_club_id uuid, p_audience text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_slots integer := case when p_format = 'DUEL' then 2 else greatest(coalesce(p_max_slots, 1), 1) end;
  v_fee integer := private.challenge_creation_fee(p_format = 'TEAM', v_slots, now(), now() + interval '1 day');
  v_payer uuid := case when p_club_id is not null and coalesce(p_audience, 'CLUB_ONLY') in ('CLUB_ONLY', 'PUBLIC') and p_format <> 'DUEL'
                          and public.club_is_staff(p_club_id) then p_club_id else v_uid end;
  v_quota jsonb := case when v_payer <> v_uid and coalesce(p_audience, 'CLUB_ONLY') = 'CLUB_ONLY' then private.club_challenge_quota_json(v_payer, v_slots) end;
  v_list_fee integer := v_fee;
  v_pass public.challenge_passes;
begin
  if v_fee > 0 and coalesce((v_quota->>'eligible')::boolean, false) then v_fee := 0; end if;
  perform private.issue_credits(case when v_payer = v_uid then 'USER' else 'CLUB' end, v_payer);
  v_pass := (select t.x from (select x, row_number() over (order by x.expires_at nulls last, x.max_slots, x.created_at) as rn
                                from public.challenge_passes x
                               where x.owner_id = v_payer and x.remaining > 0 and x.max_slots >= v_slots
                                 and (x.expires_at is null or x.expires_at > now())) t where t.rn = 1);
  return jsonb_build_object(
    'fee', v_fee, 'list_fee', v_list_fee, 'tier', private.capacity_tier(v_slots), 'custom', private.capacity_tier(v_slots)->>'xu' is null,
    'payer', case when v_payer = v_uid then 'USER' else 'CLUB' end,
    'payer_balance', private.balance(v_payer), 'wallet_balance', private.balance(v_uid),
    'pass', case when v_pass.id is null or v_fee = 0 then null
                 else jsonb_build_object('id', v_pass.id, 'remaining', v_pass.remaining, 'max_slots', v_pass.max_slots,
                                         'expires_at', v_pass.expires_at, 'note', v_pass.note) end,
    'plan', private.plan_badge(v_payer, v_payer <> v_uid),
    'club_quota', v_quota,
    'best_pass_slots', coalesce((select max(x.max_slots) from public.challenge_passes x
                                  where x.owner_id = v_payer and x.remaining > 0 and (x.expires_at is null or x.expires_at > now())), 0),
    'xu_vnd', (private.economy_config()->>'xuVnd')::numeric,
    'policy', private.economy_config());
end $$;

-- Bản 3 tham số (app cũ): như trước, coi là thử thách nội bộ CLB
create or replace function public.quote_challenge(p_max_slots integer, p_format text default 'RANKED', p_club_id uuid default null)
returns jsonb language sql security definer set search_path = public as $$
  select public.quote_challenge(p_max_slots, p_format, p_club_id, 'CLUB_ONLY')
$$;

revoke all on function public.quote_challenge(integer, text, uuid, text), public.quote_challenge(integer, text, uuid) from public, anon;
grant execute on function public.quote_challenge(integer, text, uuid, text), public.quote_challenge(integer, text, uuid) to authenticated;

create or replace function public.update_challenge(p_challenge_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid uuid := private.require_uid();
  c public.challenges;
  v_title text;
  v_desc text;
  v_target numeric;
  v_min_km numeric;
  v_min_pace numeric;
  v_max_pace numeric;
  v_cap numeric;
  v_start timestamptz;
  v_end timestamptz;
  v_objective text;
  v_conquest boolean;
  v_pledge boolean;
  v_mode text;
  v_slots integer;
  v_joined integer;
  v_audience text;
  v_reward numeric;
  v_diff numeric;
  v_require_hr boolean;
  v_fee integer;
  v_extra integer := 0;
  v_free boolean := false;
  v_quota jsonb;
  v_payer uuid;
  v_names text[];
  v_code text;
  m record;
begin
  perform 1 from public.challenges where id = p_challenge_id for update;
  c := (select x from public.challenges x where x.id = p_challenge_id);
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not private.challenge_is_manager(c) then raise exception 'FORBIDDEN'; end if;
  if c.status <> 'ACTIVE' then raise exception 'CHALLENGE_CLOSED'; end if;
  -- Sau giờ bắt đầu: giữ luật cũ, không sửa được nữa
  if now() >= c.start_date then raise exception 'CHALLENGE_STARTED'; end if;

  v_title := trim(coalesce(p->>'title', c.title));
  v_desc := case when p ? 'description' then nullif(trim(coalesce(p->>'description', '')), '') else c.description end;
  v_target := coalesce((p->>'target_value')::numeric, c.target_value);
  v_min_km := coalesce((p->>'min_km')::numeric, c.min_km);
  v_min_pace := coalesce((p->>'min_pace')::numeric, c.min_pace);
  v_max_pace := coalesce((p->>'max_pace')::numeric, c.max_pace);
  v_cap := case when p ? 'daily_cap_km' then nullif((p->>'daily_cap_km')::numeric, 0) else c.daily_cap_km end;
  v_start := coalesce((p->>'start_date')::timestamptz, c.start_date);
  v_end := coalesce((p->>'end_date')::timestamptz, c.end_date);
  v_conquest := case when jsonb_typeof(p->'conquest') = 'object' then true
                     when p ? 'objective' then upper(p->>'objective') in ('BEST_TIME', 'BEST_PACE')
                     else c.objective in ('BEST_TIME', 'BEST_PACE') end;
  v_objective := case when jsonb_typeof(p->'conquest') = 'object' then upper(coalesce(p->'conquest'->>'objective', ''))
                      else upper(coalesce(nullif(p->>'objective', ''), c.objective)) end;
  v_pledge := case when p ? 'pledge' then jsonb_typeof(p->'pledge') = 'object' else coalesce(c.pledge_enabled, false) end;
  v_require_hr := coalesce((p->>'require_hr')::boolean, c.require_hr);
  v_reward := round(coalesce((p->>'reward_xu')::numeric, c.reward_xu, 0), 1);
  v_audience := upper(coalesce(nullif(p->>'audience', ''), c.target_audience));

  -- Kiểm tra như lúc tạo (create_challenge_v2)
  if char_length(v_title) not between 3 and 120 then raise exception 'INVALID_TITLE'; end if;
  if v_desc is not null and char_length(v_desc) > 2000 then raise exception 'DESC_TOO_LONG'; end if;
  if v_end <= v_start or v_end - v_start < interval '1 hour' or v_end - v_start > interval '366 days' then raise exception 'INVALID_TIME_RANGE'; end if;
  if v_start < now() then raise exception 'INVALID_TIME_RANGE'; end if;
  if c.format = 'TEAM' and v_start < now() + interval '10 minutes' then raise exception 'TEAM_START_TOO_SOON'; end if;
  if v_target < 0 or v_min_km < 0 or v_min_km > 100 or coalesce(v_cap, 0) < 0 then raise exception 'INVALID_DISTANCE'; end if;
  if v_min_pace <= 0 or v_max_pace < v_min_pace or v_max_pace > 30 then raise exception 'INVALID_PACE'; end if;

  -- Cách tính điểm: mỗi thể thức có lựa chọn riêng (như trình tạo)
  if v_objective is distinct from c.objective and not (
       (c.format = 'SOLO_GOAL' and v_objective in ('DISTANCE', 'BEST_TIME', 'BEST_PACE', 'STREAK_DAYS'))
    or (c.format in ('RANKED', 'COLLECTIVE') and v_objective = 'DISTANCE')
    or (c.format = 'TEAM' and v_objective in ('DISTANCE', 'RUNS', 'DURATION'))
    or (c.format = 'DUEL' and v_objective in ('DISTANCE', 'RUNS', 'DURATION', 'STREAK_DAYS'))) then
    raise exception 'INVALID_OBJECTIVE';
  end if;
  -- Chuyển sang chinh phục phải kèm các hạng mục
  if v_conquest and c.objective not in ('BEST_TIME', 'BEST_PACE') and jsonb_typeof(p->'conquest') is distinct from 'object' then
    raise exception 'INVALID_CONQUEST';
  end if;
  if v_pledge and (v_conquest or v_objective <> 'DISTANCE' or c.format not in ('SOLO_GOAL', 'TEAM')) then raise exception 'PLEDGE_NOT_SUPPORTED'; end if;
  -- Đua đội theo mục tiêu ↔ đua đội thường: cách chia đội khác hẳn → tạo thử thách mới
  if c.format = 'TEAM' and v_pledge is distinct from coalesce(c.pledge_enabled, false) then raise exception 'TEAM_MODE_LOCKED'; end if;
  if c.format in ('SOLO_GOAL', 'COLLECTIVE') and not v_conquest and not v_pledge and v_target <= 0 then raise exception 'TARGET_REQUIRED'; end if;
  if v_objective = 'STREAK_DAYS' and (v_min_km <= 0 or v_target > ceil(extract(epoch from v_end - v_start) / 86400)) then
    raise exception 'INVALID_STREAK';
  end if;
  v_mode := case when c.format = 'TEAM' then case when v_pledge then 'TEAM_SUM' else coalesce(nullif(p->>'game_mode', ''), c.game_mode) end
                 when v_objective = 'STREAK_DAYS' then 'STREAK' else 'ACCUMULATE' end;
  if c.format = 'TEAM' and v_mode not in ('TEAM_SUM', 'TEAM_AVG', 'TEAM_GAP', 'LAST_MEMBER') then raise exception 'INVALID_GAME_MODE'; end if;

  -- Tên đội (đua đội thường): đổi tên đúng số đội hiện có
  if c.format = 'TEAM' and not v_pledge and jsonb_typeof(p->'team_names') = 'array' then
    v_names := array(select trim(t.v) from jsonb_array_elements_text(p->'team_names') with ordinality as t(v, ord) order by t.ord);
    if cardinality(v_names) <> (select count(*) from public.challenge_teams where challenge_id = c.id)
       or exists (select 1 from unnest(v_names) as t(v) where char_length(t.v) not between 1 and 40)
       or (select count(distinct lower(t.v)) from unnest(v_names) as t(v)) <> cardinality(v_names) then
      raise exception 'INVALID_TEAMS';
    end if;
  end if;

  -- Số người tối đa: không nhỏ hơn số người đã tham gia
  v_slots := case when c.format = 'DUEL' then 2 else coalesce((p->>'max_slots')::int, c.max_slots) end;
  if v_slots not between 1 and 10000 then raise exception 'INVALID_MAX_SLOTS'; end if;
  if c.format = 'TEAM' and coalesce(c.fixed_team_size, 0) > 0 then
    v_slots := least(v_slots, c.fixed_team_size * greatest((select count(*)::int from public.challenge_teams where challenge_id = c.id), 1));
  end if;
  v_joined := (select count(*)::int from public.challenge_participants where challenge_id = c.id and status <> 'LEFT');
  if v_slots < v_joined then raise exception 'SLOTS_BELOW_JOINED'; end if;

  -- Đối tượng: chỉ đổi Công khai ↔ Có mã mời (thử thách CLB / 1-1 giữ nguyên vì liên quan quỹ CLB và lời mời)
  if v_audience is distinct from c.target_audience
     and (c.target_club_id is not null or c.format = 'DUEL' or v_audience not in ('PUBLIC', 'INVITE_ONLY')) then
    raise exception 'AUDIENCE_LOCKED';
  end if;

  -- Phí quy mô: chỉ thu thêm khi lên mức phí cao hơn mức đã trả (hạn mức CLB / lượt miễn phí còn bao được thì miễn)
  v_payer := coalesce(c.target_club_id, c.created_by);
  if v_slots > c.max_slots then
    v_fee := private.challenge_creation_fee(c.format = 'TEAM', v_slots, v_start, v_end);
    if v_fee > coalesce(c.fee_charged, 0) then
      if c.target_club_id is not null and c.target_audience = 'CLUB_ONLY' then
        perform pg_advisory_xact_lock(hashtext('club_challenge:' || c.target_club_id));
        v_quota := private.club_challenge_quota_json(c.target_club_id, v_slots);
        -- Thử thách này đã nằm trong số đang mở → không tính chính nó khi xét số thử thách đồng thời
        v_free := (v_quota->>'reason') is null
               or ((v_quota->>'reason') = 'OPEN_LIMIT' and (v_quota->>'open')::int - 1 < (v_quota->>'max_open')::int
                   and v_slots <= (v_quota->>'max_slots')::int);
      end if;
      if not v_free and c.pass_id is not null then
        v_free := coalesce((select x.max_slots from public.challenge_passes x where x.id = c.pass_id), 0) >= v_slots;
      end if;
      if not v_free then v_extra := v_fee - coalesce(c.fee_charged, 0); end if;
    end if;
  end if;

  -- Thưởng: chỉ quỹ CLB treo thưởng; tối đa 50% (quỹ hiện có + phần đang ký quỹ) như lúc tạo
  v_diff := v_reward - coalesce(c.reward_xu, 0);
  if v_reward < 0 or v_reward > 100000 then raise exception 'INVALID_AMOUNT'; end if;
  if v_diff <> 0 and (c.target_club_id is null or c.reward_source = 'CREATOR') then raise exception 'REWARD_NOT_ALLOWED'; end if;
  if v_diff > 0 and v_reward > (private.balance(c.target_club_id) + coalesce(c.reward_xu, 0)) * 0.5 then raise exception 'REWARD_TOO_LARGE'; end if;
  if c.target_club_id is not null and (case when v_payer = c.target_club_id then v_extra else 0 end) + greatest(v_diff, 0) > private.balance(c.target_club_id) then
    raise exception 'INSUFFICIENT_TREASURY';
  end if;
  if c.target_club_id is null and v_extra > private.balance(v_payer) then raise exception 'INSUFFICIENT_BALANCE'; end if;

  -- Sổ cái: phí chênh + ký quỹ chênh (mỗi lần sửa một mã giao dịch riêng, không đụng mã của lúc tạo / huỷ)
  if v_extra > 0 then
    perform private.ledger_post('CHALLENGE_CREATION_FEE', 'challenge_edit_fee:' || c.id || ':' || gen_random_uuid(),
      case when c.target_club_id is not null then 'Phí tăng quy mô thử thách (quỹ CLB)' else 'Phí tăng quy mô thử thách' end, v_uid,
      private.debit_entries(v_payer, v_extra, private.system_account()), c.id);
    if c.target_club_id is not null then
      insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
      values (c.target_club_id, v_uid, -v_extra, 'SPEND', left('Phí tăng quy mô thử thách: ' || v_title, 200));
    end if;
  end if;
  if v_diff > 0 then
    perform private.ledger_post('CHALLENGE_ESCROW', 'challenge_escrow_adj:' || c.id || ':' || gen_random_uuid(), 'Tăng treo thưởng thử thách (quỹ CLB)', v_uid,
      private.debit_entries(c.target_club_id, v_diff, private.system_account()), c.id);
    insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
    values (c.target_club_id, v_uid, -v_diff, 'REWARD', left('Tăng treo thưởng: ' || v_title, 200));
  elsif v_diff < 0 then
    perform private.ledger_post('CHALLENGE_REFUND', 'challenge_refund_adj:' || c.id || ':' || gen_random_uuid(), 'Giảm treo thưởng thử thách — hoàn quỹ CLB', v_uid,
      jsonb_build_array(
        jsonb_build_object('account_id', c.target_club_id, 'coin_kind', 'BONUS', 'amount', -v_diff),
        jsonb_build_object('account_id', private.system_account(), 'coin_kind', 'BONUS', 'amount', v_diff)), c.id);
    insert into public.club_treasury_log (club_id, user_id, amount, kind, note)
    values (c.target_club_id, v_uid, -v_diff, 'CONTRIBUTE', left('Hoàn bớt treo thưởng: ' || v_title, 200));
  end if;

  update public.challenges
     set title = v_title, description = v_desc, target_value = v_target,
         objective = case when v_conquest then objective else v_objective end,
         target_type = case when v_conquest then target_type else v_objective end,
         target_km = case when not v_conquest and v_objective = 'DISTANCE' then v_target else 0 end,
         game_mode = v_mode,
         min_km = v_min_km, min_pace = v_min_pace, max_pace = v_max_pace, daily_cap_km = v_cap,
         start_date = v_start, end_date = v_end,
         reg_deadline = case when format = 'TEAM' then least(coalesce(reg_deadline, v_start), v_start)
                             when reg_deadline is null or reg_deadline = c.end_date or reg_deadline > v_end then v_end
                             else reg_deadline end,
         max_slots = v_slots,
         calculated_fee = case when v_slots > c.max_slots then greatest(coalesce(calculated_fee, 0), coalesce(v_fee, 0)) else calculated_fee end,
         fee_charged = coalesce(fee_charged, 0) + v_extra,
         reward_xu = v_reward,
         reward_source = case when v_diff = 0 then reward_source when v_reward > 0 then 'CLUB' else 'NONE' end,
         target_audience = v_audience,
         require_hr = v_require_hr
   where id = c.id;

  -- Bỏ chinh phục → bỏ các hạng mục (kèm đăng ký)
  if not v_conquest and c.objective in ('BEST_TIME', 'BEST_PACE') then
    delete from public.challenge_categories where challenge_id = c.id;
    update public.challenges set conquest_mode = null where id = c.id;
  end if;
  if jsonb_typeof(p->'conquest') = 'object' then
    perform public.set_challenge_conquest(c.id, p->'conquest');
  end if;
  -- Mục tiêu tự đăng ký: bật / đổi mốc (set_challenge_pledge) hoặc tắt (bỏ mục tiêu đã chọn)
  if jsonb_typeof(p->'pledge') = 'object' then
    perform public.set_challenge_pledge(c.id, p->'pledge');
  elsif p ? 'pledge' and coalesce(c.pledge_enabled, false) then
    update public.challenges
       set pledge_enabled = false, pledge_options = null, pledge_min_km = null, pledge_max_km = null, pledge_cap_pct = null
     where id = c.id;
    update public.challenge_participants set pledge_km = null, pledged_at = null where challenge_id = c.id;
  end if;
  -- Chinh phục cá nhân theo mục tiêu: mục tiêu chung = mốc thấp nhất (như lúc tạo)
  update public.challenges x
     set target_value = coalesce((select min(o) from unnest(x.pledge_options) as o), x.pledge_min_km, x.target_value),
         target_km = coalesce((select min(o) from unnest(x.pledge_options) as o), x.pledge_min_km, x.target_value)
   where x.id = c.id and x.pledge_enabled and x.format = 'SOLO_GOAL';

  -- Tên đội
  if v_names is not null then
    update public.challenge_teams t set name = v_names[t.position]
     where t.challenge_id = c.id and t.position between 1 and cardinality(v_names);
  end if;
  -- Có mã mời: tạo mã nếu chưa có
  if v_audience <> 'PUBLIC' and not exists (select 1 from public.challenge_invites where challenge_id = c.id) then
    loop
      v_code := substr(md5(gen_random_uuid()::text), 1, 8);
      exit when not exists (select 1 from public.challenge_invites where code = v_code);
    end loop;
    insert into public.challenge_invites (challenge_id, code) values (c.id, v_code);
  end if;

  perform private.challenge_recompute_all(c.id);

  -- Bài giới thiệu thử thách trên bảng tin CLB
  update public.club_posts
     set title = v_title, body = coalesce(v_desc, ''),
         meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('target_value', v_target, 'start_date', v_start, 'end_date', v_end,
                                                                 'reward_xu', v_reward, 'objective', (select x.objective from public.challenges x where x.id = c.id))
   where kind = 'CHALLENGE' and deleted_at is null and meta->>'challenge_id' = c.id::text;

  for m in select profile_id from public.challenge_participants
            where challenge_id = c.id and profile_id is not null and coalesce(status, 'JOINED') <> 'LEFT' and profile_id <> v_uid loop
    perform private.notify(m.profile_id, c.target_club_id, 'CHALLENGE_UPDATED', 'Thử thách "' || left(v_title, 80) || '" vừa được cập nhật',
      'Xem lại thời gian, luật và giải thưởng trước khi bắt đầu.', '/challenges/' || c.id, v_uid, true);
  end loop;

  return jsonb_build_object('id', c.id, 'title', v_title, 'start_date', v_start, 'end_date', v_end,
                            'fee_extra', v_extra, 'reward_diff', v_diff, 'invite_code', (select code from public.challenge_invites where challenge_id = c.id));
end $$;

create or replace function public.list_challenges(p_tab text default 'MINE', p_club_id uuid default null)
returns table (
  id uuid, title text, description text, format text, objective text, game_mode text, target_value numeric,
  start_date timestamptz, end_date timestamptz, status text, target_audience text, target_club_id uuid,
  club_name text, club_accent text, reward_xu numeric, participant_count integer, max_slots integer,
  my_status text, my_score numeric, my_rank integer, total_score numeric, created_by uuid
)
language sql stable security definer set search_path = public as $$
  with base as (
    select c.*,
           (select count(*)::int from public.challenge_participants p where p.challenge_id = c.id and p.status <> 'LEFT') as n,
           (select coalesce(sum(p.current_progress), 0) from public.challenge_participants p where p.challenge_id = c.id and p.status <> 'LEFT') as total,
           me.status as my_status, me.current_progress as my_score,
           case when me.status <> 'LEFT' then me.pledge_km end as my_pledge,
           case when me.id is not null then (select count(*)::int + 1 from public.challenge_participants o
                  where o.challenge_id = c.id and o.status <> 'LEFT' and o.current_progress > me.current_progress) end as my_rank
      from public.challenges c
      left join public.challenge_participants me on me.challenge_id = c.id and me.profile_id = auth.uid()
     where c.status in ('ACTIVE', 'FINISHED', 'CANCELLED')
       and case upper(coalesce(p_tab, 'MINE'))
         when 'MINE' then c.status <> 'CANCELLED'
                          and ((me.id is not null and me.status <> 'LEFT') or c.created_by = auth.uid())
                          and (c.status = 'ACTIVE' or c.end_date > now() - interval '30 days')
         when 'DISCOVER' then c.target_audience = 'PUBLIC' and c.status = 'ACTIVE' and c.end_date > now()
                          and (c.format <> 'TEAM' or c.start_date > now())
                          and (me.id is null or me.status = 'LEFT')
         when 'CLUB' then c.status <> 'CANCELLED'
                          and ((c.target_audience = 'CLUB_ONLY' and public.club_is_member(c.target_club_id))
                               or (c.target_audience = 'PUBLIC' and c.target_club_id is not null
                                   and (p_club_id is not null or public.club_is_member(c.target_club_id))))
                          and (p_club_id is null or c.target_club_id = p_club_id)
                          and (c.status = 'ACTIVE' or c.end_date > now() - interval '60 days')
         when 'ENDED' then me.id is not null and (c.status <> 'ACTIVE' or c.end_date <= now())
         else false end
  ), ranked as (
    select b.*, row_number() over (
             order by (b.status = 'ACTIVE' and b.end_date > now()) desc,
                      case when upper(coalesce(p_tab, 'MINE')) = 'DISCOVER' then -b.n else 0 end,
                      b.end_date) as rn
      from base b
  )
  select b.id, b.title, b.description, b.format, b.objective, b.game_mode,
         -- 013300: thử thách tự đăng ký mục tiêu → mục tiêu người xem đã chọn (chưa chọn: mốc thấp nhất như cũ)
         case when coalesce(b.pledge_enabled, false) and b.my_pledge is not null then b.my_pledge else b.target_value end,
         b.start_date, b.end_date,
         b.status, b.target_audience, b.target_club_id, cl.name, cl.accent_color, b.reward_xu, b.n, b.max_slots,
         b.my_status, b.my_score, b.my_rank, round(b.total, 2), b.created_by
    from ranked b left join public.clubs cl on cl.id = b.target_club_id
   where b.rn <= 60
   order by b.rn
$$;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001014200_conquest_tolerance.sql
-- ===================================================================
-- 014200: Sai số cự ly của thử thách chinh phục do người tạo đặt.
--   Trước: bài chạy được tính cho hạng mục khi cự ly ≥ 99% hạng mục (sai số cố định 1%).
--   Nay: người tạo đặt sai số 0–10% (mặc định 1%, thử thách cũ giữ 1%). Áp dụng cho cả chinh phục thời gian, pace, cự ly.
-- Chạy riêng được ngay; chạy lại 3500.

alter table public.challenges add column if not exists conquest_tolerance_pct numeric(3,1) not null default 1;
alter table public.challenges drop constraint if exists challenges_conquest_tolerance_chk;
alter table public.challenges add constraint challenges_conquest_tolerance_chk check (conquest_tolerance_pct between 0 and 10);

create or replace function private.challenge_recompute_participant(p_participant_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  p public.challenge_participants := (select x from public.challenge_participants x where x.id = p_participant_id);
  c public.challenges;
  v_dist numeric; v_moving bigint; v_runs integer; v_days integer; v_score numeric; v_target numeric;
begin
  if p.id is null then return; end if;
  perform 1 from public.challenge_participants where id = p.id for update;
  c := (select x from public.challenges x where x.id = p.challenge_id);

  v_dist := (select coalesce(sum(e.counted_m), 0) from public.challenge_progress_events e where e.participant_id = p.id);
  v_moving := (select coalesce(sum(e.moving_s), 0) from public.challenge_progress_events e where e.participant_id = p.id);
  v_runs := (select count(*) from public.challenge_progress_events e where e.participant_id = p.id and e.counted_m > 0);
  v_days := (select count(*) from (
               select e.day from public.challenge_progress_events e where e.participant_id = p.id
                group by e.day having sum(e.distance_m) >= greatest(coalesce(c.min_km, 0), 0.2) * 1000) d);

  if c.objective in ('BEST_TIME', 'BEST_PACE') then
    -- Kết quả tốt nhất cho từng hạng mục: bài có cự ly ≥ hạng mục, quy đổi theo pace trung bình
    update public.challenge_category_entries
       set best_time_s = null, best_pace_s = null, best_activity_id = null, best_at = null, achieved_at = null
     where participant_id = p.id;
    update public.challenge_category_entries ce
       set best_time_s = b.t, best_pace_s = b.pace, best_activity_id = b.aid, best_at = b.at,
           achieved_at = case when c.conquest_mode = 'ANY' then b.at
                              when coalesce(ce.target_s, b.cat_target) is not null
                                   and (case when c.objective = 'BEST_PACE' then b.pace else b.t end) <= coalesce(ce.target_s, b.cat_target)
                              then b.at end
      from (select distinct on (cat.id) cat.id as cat_id, cat.target_s as cat_target,
                   round(e.moving_s * cat.distance_m / e.distance_m)::int as t,
                   round(e.moving_s * 1000.0 / e.distance_m)::int as pace,
                   e.activity_id as aid, a.started_at as at
              from public.challenge_categories cat
              join public.challenge_progress_events e on e.participant_id = p.id
                                                       and e.distance_m >= cat.distance_m * (1 - coalesce(c.conquest_tolerance_pct, 1) / 100.0) and e.moving_s > 0
              join public.activities a on a.id = e.activity_id
             where cat.challenge_id = c.id
             order by cat.id, e.moving_s / e.distance_m, a.started_at) b
     where ce.participant_id = p.id and ce.category_id = b.cat_id;
    v_score := (select count(*) from public.challenge_category_entries ce where ce.participant_id = p.id and ce.achieved_at is not null);
    v_target := (select count(*) from public.challenge_category_entries ce where ce.participant_id = p.id);
  else
    v_score := case c.objective
      when 'RUNS' then v_runs
      when 'DURATION' then round(v_moving / 60.0, 1)
      when 'STREAK_DAYS' then v_days
      else round(v_dist / 1000.0, 2) end;

    v_target := coalesce(c.target_value, 0);
    if c.pledge_enabled then
      v_target := coalesce(p.pledge_km, 0);           -- chưa đăng ký mục tiêu → chưa thể hoàn thành
      if v_target > 0 and c.pledge_cap_pct is not null then
        v_score := least(v_score, round(v_target * (1 + c.pledge_cap_pct / 100.0), 2));
      end if;
    end if;
  end if;

  update public.challenge_participants
     set distance_m = v_dist, moving_s = v_moving, run_count = v_runs, streak_days = v_days,
         current_progress = v_score,
         completed_at = case when v_target > 0 and v_score >= v_target then coalesce(completed_at, now()) end,
         status = case when status = 'LEFT' then 'LEFT'
                       when v_target > 0 and v_score >= v_target then 'COMPLETED'
                       else 'JOINED' end,
         updated_at = now()
   where id = p.id;
end $$;

create or replace function public.set_challenge_conquest(p_challenge_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  c public.challenges := (select x from public.challenges x where x.id = p_challenge_id);
  v_obj text := upper(coalesce(p->>'objective', ''));
  v_mode text := upper(coalesce(p->>'mode', 'FIXED'));
  v_cats jsonb := case when jsonb_typeof(p->'categories') = 'array' then p->'categories' else '[]'::jsonb end;
  v_n integer := jsonb_array_length(case when jsonb_typeof(p->'categories') = 'array' then p->'categories' else '[]'::jsonb end);
  v_min_m numeric;
  v_tol numeric;
  v_before uuid[];
  m record;
begin
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if not private.challenge_is_manager(c) then raise exception 'FORBIDDEN'; end if;
  if c.status <> 'ACTIVE' or now() >= c.end_date then raise exception 'CHALLENGE_CLOSED'; end if;
  if c.format <> 'SOLO_GOAL' then raise exception 'CONQUEST_NOT_SUPPORTED'; end if;
  if v_obj not in ('BEST_TIME', 'BEST_PACE') or v_mode not in ('FIXED', 'SELF', 'ANY') then raise exception 'INVALID_CONQUEST'; end if;
  if v_n not between 1 and 8 then raise exception 'INVALID_CONQUEST'; end if;
  -- 014200: sai số cự ly do người tạo đặt (0–10%), không gửi thì giữ như cũ
  begin
    v_tol := coalesce(round((p->>'tolerance_pct')::numeric, 1), c.conquest_tolerance_pct, 1);
  exception when invalid_text_representation then raise exception 'INVALID_CONQUEST';
  end;
  if v_tol not between 0 and 10 then raise exception 'INVALID_CONQUEST'; end if;
  if now() >= c.start_date and exists (select 1 from public.challenge_category_entries e where e.challenge_id = c.id) then
    raise exception 'CONQUEST_LOCKED';
  end if;
  begin
    if exists (select 1 from jsonb_array_elements(v_cats) x
                where char_length(trim(coalesce(x->>'label', ''))) not between 1 and 40
                   or (x->>'distance_km')::numeric not between 0.4 and 250
                   or (v_mode = 'FIXED' and coalesce((x->>'target_s')::int, 0) <= 0)
                   or (v_mode = 'FIXED' and v_obj = 'BEST_PACE' and (x->>'target_s')::int not between 120 and 1500)
                   or (v_mode = 'FIXED' and v_obj = 'BEST_TIME' and (x->>'target_s')::int not between 60 and 172800)) then
      raise exception 'INVALID_CONQUEST';
    end if;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'INVALID_CONQUEST';
  end;

  -- Ai đang có đăng ký (để nhắc nếu mất)
  v_before := (select coalesce(array_agg(distinct e.user_id), '{}') from public.challenge_category_entries e where e.challenge_id = c.id);
  -- Đổi kiểu tính / ai đặt mục tiêu: mục tiêu tự đặt cũ không còn ý nghĩa
  if c.objective is distinct from v_obj or c.conquest_mode is distinct from v_mode then
    delete from public.challenge_category_entries where challenge_id = c.id;
  end if;
  -- Hạng mục bị bỏ (vị trí > số hạng mục mới) — xoá kèm đăng ký
  delete from public.challenge_categories where challenge_id = c.id and position > v_n;
  -- Hạng mục đổi cự ly: bỏ đăng ký của hạng mục đó
  delete from public.challenge_category_entries e
   using public.challenge_categories cat, jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where e.category_id = cat.id and cat.challenge_id = c.id and cat.position = t.ord
     and cat.distance_m <> round((t.x->>'distance_km')::numeric * 1000);
  update public.challenge_categories cat
     set label = trim(t.x->>'label'), distance_m = round((t.x->>'distance_km')::numeric * 1000),
         target_s = case when v_mode = 'FIXED' then (t.x->>'target_s')::int end
    from jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where cat.challenge_id = c.id and cat.position = t.ord;
  insert into public.challenge_categories (challenge_id, position, label, distance_m, target_s)
  select c.id, t.ord, trim(t.x->>'label'), round((t.x->>'distance_km')::numeric * 1000),
         case when v_mode = 'FIXED' then (t.x->>'target_s')::int end
    from jsonb_array_elements(v_cats) with ordinality as t(x, ord)
   where not exists (select 1 from public.challenge_categories x where x.challenge_id = c.id and x.position = t.ord);

  v_min_m := (select min(distance_m) from public.challenge_categories where challenge_id = c.id);
  update public.challenges
     set objective = v_obj, conquest_mode = v_mode, target_value = 1, target_type = v_obj, target_km = 0,
         pledge_enabled = false, reward_split = 'FINISHERS', game_mode = 'ACCUMULATE',
         -- bài ngắn hơn hạng mục nhỏ nhất không thể cho kết quả → không cần ghi nhận
         conquest_tolerance_pct = v_tol,
         min_km = round(v_min_m * (1 - v_tol / 100.0) / 1000.0, 2)
   where id = c.id;
  update public.challenge_participants set pledge_km = null where challenge_id = c.id and pledge_km is not null;

  for m in select u.uid from unnest(v_before) as u(uid)
            where not exists (select 1 from public.challenge_category_entries e where e.challenge_id = c.id and e.user_id = u.uid) loop
    perform private.notify(m.uid, c.target_club_id, 'CHALLENGE_UPDATED', 'Chọn lại hạng mục: ' || left(c.title, 80),
      'Ban tổ chức đã đổi các hạng mục chinh phục, đăng ký cũ của bạn không còn. Vào chọn lại trước giờ bắt đầu.',
      '/challenges/' || c.id, v_uid, true);
  end loop;
  perform private.challenge_recompute_all(c.id);
  return public.challenge_conquest_board(c.id);
end $$;

create or replace function private.conquest_has_result(p_participant uuid, p_category uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.challenge_progress_events e
                   join public.challenge_categories cat on cat.id = p_category
                   join public.challenges c on c.id = cat.challenge_id
                  where e.participant_id = p_participant and e.moving_s > 0 and e.distance_m >= cat.distance_m * (1 - coalesce(c.conquest_tolerance_pct, 1) / 100.0))
$$;

create or replace function public.challenge_conquest_board(p_challenge_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  c public.challenges := (select x from public.challenges x where x.id = p_challenge_id);
  v_pid uuid;
begin
  if c.id is null or not public.challenge_visible(c.id) then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  v_pid := (select x.id from public.challenge_participants x where x.challenge_id = c.id and x.profile_id = v_uid and x.status <> 'LEFT');
  return jsonb_build_object(
    'objective', c.objective, 'mode', c.conquest_mode, 'tolerance_pct', coalesce(c.conquest_tolerance_pct, 1),
    'categories', (select coalesce(jsonb_agg(jsonb_build_object(
                     'id', cat.id, 'label', cat.label, 'distance_m', cat.distance_m, 'target_s', cat.target_s, 'position', cat.position,
                     'entrants', (select count(*) from public.challenge_category_entries e join public.challenge_participants pp on pp.id = e.participant_id
                                   where e.category_id = cat.id and pp.status <> 'LEFT'),
                     'achieved', (select count(*) from public.challenge_category_entries e join public.challenge_participants pp on pp.id = e.participant_id
                                   where e.category_id = cat.id and pp.status <> 'LEFT' and e.achieved_at is not null))
                     order by cat.position), '[]'::jsonb)
                     from public.challenge_categories cat where cat.challenge_id = c.id),
    'rows', (select coalesce(jsonb_agg(jsonb_build_object(
               'category_id', r.category_id, 'user_id', r.user_id, 'display_name', r.display_name, 'avatar_url', r.avatar_url, 'level', r.level,
               'target_s', r.target_s_eff, 'best_time_s', r.best_time_s, 'best_pace_s', r.best_pace_s, 'best_activity_id', r.best_activity_id,
               'best_at', r.best_at, 'achieved', r.achieved_at is not null, 'rank', r.rk, 'me', r.user_id = v_uid)
               order by r.category_id, r.rk nulls last, r.display_name), '[]'::jsonb)
               from (select e.*, coalesce(e.target_s, cat.target_s) as target_s_eff, pr.display_name, pr.avatar_url, coalesce(pr.level, 1) as level,
                            case when e.best_time_s is not null then rank() over (partition by e.category_id, (e.best_time_s is not null)
                                                                                     order by e.best_time_s, e.best_at) end as rk
                       from public.challenge_category_entries e
                       join public.challenge_categories cat on cat.id = e.category_id
                       join public.challenge_participants pp on pp.id = e.participant_id and pp.status <> 'LEFT'
                       join public.profiles pr on pr.id = e.user_id
                      where e.challenge_id = c.id) r),
    'mine', (select coalesce(jsonb_agg(jsonb_build_object('category_id', e.category_id, 'target_s', e.target_s,
               'best_time_s', e.best_time_s, 'best_pace_s', e.best_pace_s, 'achieved', e.achieved_at is not null)), '[]'::jsonb)
               from public.challenge_category_entries e where e.challenge_id = c.id and e.user_id = v_uid),
    'my_results', (select coalesce(jsonb_agg(cat.id order by cat.position), '[]'::jsonb)
                     from public.challenge_categories cat
                    where cat.challenge_id = c.id and v_pid is not null and private.conquest_has_result(v_pid, cat.id))
  );
end $$;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001014300_club_event_feed_post.sql
-- ===================================================================
-- Lịch CLB mới tạo → tự lên bảng tin CLB (club_posts.kind = 'NEWS', chuyên mục EVENT, meta.event_id).
-- Trước đây create_club_event chỉ gửi thông báo, không có bài trên bảng tin nên lịch vừa tạo không hiện ở đó.
-- Dùng trigger để không phải sao lại các RPC tạo/sửa/hủy: sửa lịch thì cập nhật bài, hủy lịch thì gỡ bài.

create or replace function private.club_event_post_body(e public.club_events) returns text
language sql immutable set search_path = public as $$
  select to_char(e.starts_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM/YYYY')
      || coalesce(E'\n' || e.location_name, '')
      || coalesce(E'\n' || nullif(trim(e.description), ''), '')
$$;

create or replace function private.club_event_to_post() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.status = 'SCHEDULED' then
      insert into public.club_posts (club_id, author_id, kind, title, body, meta)
      values (new.club_id, new.created_by, 'NEWS', 'Lịch chạy: ' || new.title, private.club_event_post_body(new),
              jsonb_build_object('category', 'EVENT', 'event_id', new.id));
    end if;
  elsif new.status = 'CANCELLED' then
    delete from public.club_posts where kind = 'NEWS' and meta->>'event_id' = new.id::text;
  else
    update public.club_posts set title = 'Lịch chạy: ' || new.title, body = private.club_event_post_body(new)
     where kind = 'NEWS' and meta->>'event_id' = new.id::text;
  end if;
  return new;
end $$;

drop trigger if exists club_event_post_trg on public.club_events;
create trigger club_event_post_trg after insert or update of title, description, starts_at, location_name, status
  on public.club_events for each row execute function private.club_event_to_post();

revoke all on function private.club_event_to_post() from public, anon, authenticated;

-- Lịch sắp tới đã tạo trước đây
insert into public.club_posts (club_id, author_id, kind, title, body, meta, created_at)
select e.club_id, e.created_by, 'NEWS', 'Lịch chạy: ' || e.title, private.club_event_post_body(e),
       jsonb_build_object('category', 'EVENT', 'event_id', e.id), e.created_at
  from public.club_events e
 where e.status = 'SCHEDULED' and e.starts_at > now()
   and not exists (select 1 from public.club_posts p where p.kind = 'NEWS' and p.meta->>'event_id' = e.id::text);

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001014400_order_payment_reminder.sql
-- ===================================================================
-- Admin nhắc người mua hoàn tất thanh toán đơn đang chờ: gửi thông báo trong app (không tự động hàng loạt).
alter table public.orders add column if not exists reminded_at timestamptz;

create or replace function public.admin_remind_order(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_admin();
  o public.orders := (select x from public.orders x where x.id = p_order_id for update);
  v_plan text; v_what text; v_body text;
begin
  if o.id is null then raise exception 'ORDER_NOT_FOUND'; end if;
  if o.status <> 'PENDING' or o.expires_at <= now() then raise exception 'ORDER_NOT_PENDING'; end if;
  if o.reminded_at is not null and o.reminded_at > now() - interval '6 hours' then raise exception 'ORDER_REMIND_TOO_SOON'; end if;
  if o.kind = 'PLAN' then
    v_plan := coalesce((select name from public.plans where code = o.plan_code), 'gói');
    v_what := 'kích hoạt ' || v_plan || coalesce(' ' || o.months || ' tháng', '');
  else
    v_what := 'nhận ' || (o.xu + o.bonus_xu) || ' Xu';
  end if;
  v_body := 'Hãy liên hệ với RaceHub và hoàn thành thủ tục thanh toán để ' || v_what
         || '. Chuyển khoản đúng nội dung ' || o.code || ' hoặc nhắn admin qua mục Liên hệ trong trang Gói.';
  perform private.notify(o.buyer_id, null, 'ORDER_REMINDER', 'Đơn ' || o.code || ' đang chờ thanh toán', v_body, '/goi', v_uid, true);
  update public.orders set reminded_at = now() where id = o.id;
  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_uid, 'REMIND_ORDER', o.code, jsonb_build_object('kind', o.kind, 'amount_vnd', o.amount_vnd));
  return private.order_json((select x from public.orders x where x.id = o.id));
end $$;

revoke all on function public.admin_remind_order(uuid) from public, anon;
grant execute on function public.admin_remind_order(uuid) to authenticated;
notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001014500_admin_delete_rejected_runs.sql
-- ===================================================================
-- Admin xóa hàng loạt bài chạy đang ở trạng thái BỊ LOẠI (REJECTED) khỏi danh sách duyệt.
-- Xóa MỀM (status = 'DELETED', giống người dùng xóa bài): giữ nguyên dòng để lịch sử quyết định chống gian lận còn nguyên.
-- Bài bị loại chưa từng cộng Xu / XP / điểm thử thách nên xóa không hoàn hay trừ gì. Bài không còn ở trạng thái bị loại thì bỏ qua.
create or replace function public.admin_delete_rejected_activities(p_ids uuid[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_admin();
  v_ids uuid[];
begin
  if p_ids is null or coalesce(array_length(p_ids, 1), 0) = 0 then raise exception 'NO_IDS'; end if;
  if array_length(p_ids, 1) > 500 then raise exception 'TOO_MANY'; end if;
  with d as (
    update public.activities a
       set status = 'DELETED', updated_at = now()
     where a.id = any (p_ids) and a.validation_status = 'REJECTED' and coalesce(a.status, '') <> 'DELETED'
    returning a.id)
  select coalesce(array_agg(id), '{}') into v_ids from d;
  if cardinality(v_ids) > 0 then
    insert into public.admin_audit_log (actor_id, action, target, new_value)
    values (v_uid, 'DELETE_REJECTED_ACTIVITIES', cardinality(v_ids)::text,
            jsonb_build_object('requested', cardinality(p_ids), 'deleted_ids', to_jsonb(v_ids)));
  end if;
  return jsonb_build_object('requested', cardinality(p_ids), 'deleted', cardinality(v_ids));
end $$;

revoke all on function public.admin_delete_rejected_activities(uuid[]) from public, anon;
grant execute on function public.admin_delete_rejected_activities(uuid[]) to authenticated;
notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001014600_admin_banned_users.sql
-- ===================================================================
-- Danh sách tài khoản đang khóa cho admin (thẻ "N tài khoản đang khóa" ở Tổng quan bấm được).
-- Khớp cách đếm của admin_inbox: profiles.banned_at is not null.
-- Phân loại: SELF_DELETED = người dùng tự xóa (banned_reason = 'ACCOUNT_DELETED'), ADMIN = admin khóa tay.
create or replace function public.admin_banned_users() returns jsonb
language plpgsql stable security definer set search_path = public, auth as $$
begin
  perform private.require_admin();
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', pr.id, 'name', pr.display_name, 'avatar_url', pr.avatar_url, 'email', u.email,
      'banned_at', pr.banned_at, 'reason', pr.banned_reason,
      'kind', case when pr.banned_reason = 'ACCOUNT_DELETED' then 'SELF_DELETED' else 'ADMIN' end,
      'banned_by', (select private.display_name(l.actor_id) from public.admin_audit_log l
                     where l.action = 'USER_BAN' and l.target in ('user:' || pr.id, pr.id::text)
                     order by l.created_at desc limit 1)
    ) order by pr.banned_at desc)
    from public.profiles pr left join auth.users u on u.id = pr.id
    where pr.banned_at is not null), '[]'::jsonb);
end $$;

revoke all on function public.admin_banned_users() from public, anon;
grant execute on function public.admin_banned_users() to authenticated;
notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001014700_dm_delete.sql
-- ===================================================================
-- Xóa tin nhắn 1-1 kiểu Zalo (xóa mềm, không mất dữ liệu gốc):
--  * Thu hồi (xóa với mọi người): chỉ tin của mình, trong 24 giờ kể từ lúc gửi; hai bên thấy "Tin nhắn đã được thu hồi".
--  * Xóa ở phía tôi: ẩn một tin (của mình hoặc của người khác) chỉ với riêng mình.
--  * Xóa cuộc trò chuyện: ẩn toàn bộ tin tới thời điểm bấm, chỉ với riêng mình; tin mới sau đó vẫn hiện lại bình thường.
-- Mọi bảng mới bật RLS, không cấp quyền trực tiếp; chỉ đi qua RPC security definer có kiểm tra người tham gia.
create table if not exists public.direct_message_hidden (
  message_id uuid not null references public.direct_messages(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (message_id, user_id)
);
alter table public.direct_message_hidden enable row level security;
revoke all on public.direct_message_hidden from anon, authenticated;

alter table public.direct_threads add column if not exists a_cleared_at timestamptz;
alter table public.direct_threads add column if not exists b_cleared_at timestamptz;

-- Tin nhắn người dùng này còn nhìn thấy: chưa bị xóa phía mình, và sau mốc xóa cuộc trò chuyện
create or replace function private.dm_visible(m public.direct_messages, p_uid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select not exists (select 1 from public.direct_message_hidden h where h.message_id = m.id and h.user_id = p_uid)
     and m.created_at > coalesce((select case when t.user_a = p_uid then t.a_cleared_at else t.b_cleared_at end
                                    from public.direct_threads t where t.id = m.thread_id), '-infinity'::timestamptz)
$$;
revoke all on function private.dm_visible(public.direct_messages, uuid) from public, anon, authenticated;

-- Mở cuộc trò chuyện: chỉ tin còn nhìn thấy
create or replace function public.direct_thread(p_user uuid, p_before timestamptz default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  t public.direct_threads := (select x from public.direct_threads x where x.user_a = least(v_uid, p_user) and x.user_b = greatest(v_uid, p_user));
  pr public.profiles := (select x from public.profiles x where x.id = p_user);
begin
  if pr.id is null or p_user = v_uid then raise exception 'USER_NOT_FOUND'; end if;
  if t.id is not null then
    update public.direct_threads set a_read_at = case when user_a = v_uid then now() else a_read_at end,
                                     b_read_at = case when user_b = v_uid then now() else b_read_at end where id = t.id;
  end if;
  return jsonb_build_object(
    'user', jsonb_build_object('id', pr.id, 'display_name', pr.display_name, 'avatar_url', pr.avatar_url, 'level', coalesce(pr.level, 1)),
    'can_message', private.can_dm(v_uid, p_user),
    'blocked', private.is_blocked(v_uid, p_user),
    'blocked_by_me', exists (select 1 from public.user_blocks b where b.blocker = v_uid and b.blocked = p_user),
    'messages', coalesce((select jsonb_agg(private.dm_json(m, v_uid) order by m.created_at)
                  from (select x.id, row_number() over (order by x.created_at desc) as rn from public.direct_messages x
                         where x.thread_id = t.id and x.created_at < coalesce(p_before, now() + interval '1 day')
                           and private.dm_visible(x, v_uid)) r
                  join public.direct_messages m on m.id = r.id
                 where r.rn <= 60), '[]'::jsonb));
end $$;

-- Hộp thư: chỉ cuộc trò chuyện còn tin nhìn thấy; tin cuối và số chưa đọc cũng chỉ tính tin nhìn thấy
create or replace function public.direct_inbox() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  return coalesce((select jsonb_agg(jsonb_build_object(
            'user', jsonb_build_object('id', pr.id, 'display_name', pr.display_name, 'avatar_url', pr.avatar_url),
            'last_message_at', (lm.x).created_at,
            'last', private.dm_json(lm.x, v_uid),
            'unread', (select count(*) from public.direct_messages m where m.thread_id = t.id and m.sender_id <> v_uid and m.deleted_at is null
                         and private.dm_visible(m, v_uid)
                         and m.created_at > coalesce(case when t.user_a = v_uid then t.a_read_at else t.b_read_at end, '-infinity'::timestamptz)))
          order by (lm.x).created_at desc)
    from public.direct_threads t
    join public.profiles pr on pr.id = case when t.user_a = v_uid then t.user_b else t.user_a end
    cross join lateral (select x from public.direct_messages x where x.thread_id = t.id and private.dm_visible(x, v_uid)
                         order by x.created_at desc limit 1) lm
   where (t.user_a = v_uid or t.user_b = v_uid) and t.last_message_at is not null
     and not exists (select 1 from public.user_blocks b where b.blocker = v_uid and b.blocked = pr.id)), '[]'::jsonb);
end $$;

create or replace function public.direct_unread_count() returns integer
language sql stable security definer set search_path = public as $$
  select count(*)::int from public.direct_messages m join public.direct_threads t on t.id = m.thread_id
   where (t.user_a = auth.uid() or t.user_b = auth.uid()) and m.sender_id <> auth.uid() and m.deleted_at is null
     and private.dm_visible(m, auth.uid())
     and m.created_at > coalesce(case when t.user_a = auth.uid() then t.a_read_at else t.b_read_at end, '-infinity'::timestamptz)
     and not exists (select 1 from public.user_blocks b where b.blocker = auth.uid() and b.blocked = m.sender_id)
$$;

-- Thu hồi tin của mình: trong 24 giờ kể từ lúc gửi (quá hạn → RECALL_EXPIRED). Thu hồi lại tin đã thu hồi: không đổi gì.
create or replace function public.delete_direct_message(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare m public.direct_messages := (select x from public.direct_messages x where x.id = p_id);
begin
  if m.id is null then raise exception 'NOT_FOUND'; end if;
  if m.sender_id is distinct from private.require_uid() then raise exception 'NOT_AUTHOR'; end if;
  if m.deleted_at is not null then return; end if;
  if m.created_at < now() - interval '24 hours' then raise exception 'RECALL_EXPIRED'; end if;
  update public.direct_messages set deleted_at = now() where id = p_id;
end $$;

-- Xóa ở phía tôi: ẩn một tin với riêng mình (người tham gia cuộc trò chuyện, tin của ai cũng được)
create or replace function public.hide_direct_message(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  m public.direct_messages := (select x from public.direct_messages x where x.id = p_id);
begin
  if m.id is null or not exists (select 1 from public.direct_threads t where t.id = m.thread_id and v_uid in (t.user_a, t.user_b)) then
    raise exception 'NOT_FOUND';
  end if;
  insert into public.direct_message_hidden (message_id, user_id) values (m.id, v_uid) on conflict do nothing;
end $$;

-- Xóa cả cuộc trò chuyện ở phía tôi: ẩn mọi tin tới bây giờ; người kia vẫn giữ nguyên
create or replace function public.clear_direct_thread(p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  if p_user is null or p_user = v_uid then raise exception 'INVALID_TARGET'; end if;
  update public.direct_threads set a_cleared_at = case when user_a = v_uid then now() else a_cleared_at end,
                                   b_cleared_at = case when user_b = v_uid then now() else b_cleared_at end,
                                   a_read_at = case when user_a = v_uid then now() else a_read_at end,
                                   b_read_at = case when user_b = v_uid then now() else b_read_at end
   where user_a = least(v_uid, p_user) and user_b = greatest(v_uid, p_user);
end $$;

revoke all on function public.direct_thread(uuid, timestamptz), public.direct_inbox(), public.direct_unread_count(),
  public.delete_direct_message(uuid), public.hide_direct_message(uuid), public.clear_direct_thread(uuid) from public, anon;
grant execute on function public.direct_thread(uuid, timestamptz), public.direct_inbox(), public.direct_unread_count(),
  public.delete_direct_message(uuid), public.hide_direct_message(uuid), public.clear_direct_thread(uuid) to authenticated;
notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001014800_event_checkin_window.sql
-- ===================================================================
-- Điểm danh sự kiện CLB: chỉ mở trong khung giờ của sự kiện + điểm danh bằng GPS.
-- Trước đây: ban quản trị tích điểm danh tay được bất cứ lúc nào (kể cả sự kiện chưa diễn ra), QR/"mở điểm danh" từ 2 giờ trước đến 2 giờ sau khi kết thúc,
-- và thành viên không có cách tự điểm danh bằng vị trí (chỉ có tự động sau khi chạy xong).
-- Quy tắc mới:
--   * Khung điểm danh: từ 30 phút trước giờ hẹn đến khi sự kiện kết thúc (starts_at + duration_min). Sự kiện đã hủy thì không mở.
--   * Thành viên tự điểm danh bằng GPS: trong khung trên, cách điểm hẹn ≤ 300 m, sai số GPS ≤ 100 m; sự kiện phải có tọa độ.
--   * QR: cùng khung giờ.
--   * Ban quản trị điểm danh tay: chỉ khi sự kiện đã bắt đầu (không giới hạn lúc kết thúc để còn bổ sung sau buổi chạy). Bỏ điểm danh thì luôn được.
alter table public.club_event_rsvps drop constraint if exists club_event_rsvps_checkin_method_check;
alter table public.club_event_rsvps add constraint club_event_rsvps_checkin_method_check
  check (checkin_method is null or checkin_method in ('QR', 'AUTO', 'STAFF', 'GPS'));

create or replace function private.event_checkin_open(e public.club_events) returns boolean
language sql stable set search_path = public as $$
  select e.status = 'SCHEDULED'
     and now() between e.starts_at - interval '30 minutes' and e.starts_at + make_interval(mins => e.duration_min)
$$;

-- Chi tiết sự kiện: checkin_open theo khung giờ mới (còn lại giữ nguyên bản 006100)
create or replace function public.club_event(p_event_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e public.club_events := (select x from public.club_events x where x.id = p_event_id);
  v_uid uuid := private.require_uid();
  v_member boolean;
begin
  if e.id is null then raise exception 'EVENT_NOT_FOUND'; end if;
  v_member := exists (select 1 from public.club_members m where m.club_id = e.club_id and m.user_id = v_uid and m.status = 'APPROVED');
  if not v_member and e.visibility <> 'PUBLIC' and not public.is_system_admin() then
    perform private.require_member(e.club_id);
  end if;
  return private.event_json(e, v_uid) || jsonb_build_object(
    'is_member', v_member,
    'club_name', (select c.name from public.clubs c where c.id = e.club_id),
    'club_avatar', (select c.avatar_url from public.clubs c where c.id = e.club_id),
    'can_manage', public.club_is_staff(e.club_id),
    'checkin_open', private.event_checkin_open(e),
    'staff_can_mark', e.status = 'SCHEDULED' and now() >= e.starts_at,
    'attendees', case when v_member or public.is_system_admin() then (select coalesce(jsonb_agg(jsonb_build_object(
        'user_id', r.user_id, 'display_name', p.display_name, 'avatar_url', p.avatar_url, 'status', r.status,
        'checked_in_at', r.checked_in_at, 'checkin_method', r.checkin_method)
        order by (r.checked_in_at is null), r.status, p.display_name), '[]'::jsonb)
      from public.club_event_rsvps r join public.profiles p on p.id = r.user_id
     where r.event_id = e.id and r.status <> 'NOT_GOING') else '[]'::jsonb end);
end $$;

-- QR: lấy mã và quét mã đều theo khung giờ mới
create or replace function public.event_checkin_token(p_event_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e public.club_events := (select x from public.club_events x where x.id = p_event_id);
  v_exp bigint := extract(epoch from now() + interval '15 minutes')::bigint;
begin
  if e.id is null then raise exception 'EVENT_NOT_FOUND'; end if;
  perform private.require_staff(e.club_id);
  if e.status = 'CANCELLED' then raise exception 'EVENT_CANCELLED'; end if;
  if not private.event_checkin_open(e) then raise exception 'CHECKIN_CLOSED'; end if;
  return jsonb_build_object('token', e.id || '.' || v_exp || '.' || private.event_sig(e.id, v_exp),
                            'expires_at', to_timestamp(v_exp));
end $$;

create or replace function public.checkin_club_event(p_token text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_parts text[] := string_to_array(coalesce(p_token, ''), '.');
  v_event uuid;
  v_exp bigint;
  e public.club_events;
begin
  if cardinality(v_parts) <> 3 then raise exception 'INVALID_TOKEN'; end if;
  begin
    v_event := v_parts[1]::uuid;
    v_exp := v_parts[2]::bigint;
  exception when others then
    raise exception 'INVALID_TOKEN';
  end;
  e := (select x from public.club_events x where x.id = v_event);
  if e.id is null or private.event_sig(v_event, v_exp) is distinct from v_parts[3] then raise exception 'INVALID_TOKEN'; end if;
  if extract(epoch from now()) > v_exp then raise exception 'TOKEN_EXPIRED'; end if;
  if not public.club_is_member(e.club_id) then raise exception 'NOT_A_MEMBER'; end if;
  if e.status = 'CANCELLED' then raise exception 'EVENT_CANCELLED'; end if;
  if not private.event_checkin_open(e) then raise exception 'CHECKIN_CLOSED'; end if;
  return jsonb_build_object('new', private.event_mark_checkin(e.id, v_uid, 'QR'), 'event_id', e.id, 'club_id', e.club_id, 'title', e.title);
end $$;

-- Thành viên tự điểm danh bằng vị trí GPS hiện tại
create or replace function public.gps_checkin_club_event(p_event_id uuid, p_lat double precision, p_lng double precision,
                                                         p_accuracy_m double precision default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  e public.club_events := (select x from public.club_events x where x.id = p_event_id);
  v_dist numeric;
begin
  if e.id is null then raise exception 'EVENT_NOT_FOUND'; end if;
  if not public.club_is_member(e.club_id) then raise exception 'NOT_A_MEMBER'; end if;
  if e.status = 'CANCELLED' then raise exception 'EVENT_CANCELLED'; end if;
  if not private.event_checkin_open(e) then raise exception 'CHECKIN_CLOSED'; end if;
  if e.lat is null or e.lng is null then raise exception 'NO_EVENT_LOCATION'; end if;
  if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then raise exception 'INVALID_LOCATION'; end if;
  if p_accuracy_m is not null and p_accuracy_m > 100 then raise exception 'LOW_ACCURACY'; end if;
  v_dist := private.haversine_m(p_lat::numeric, p_lng::numeric, e.lat::numeric, e.lng::numeric);
  if v_dist > 300 then raise exception 'TOO_FAR'; end if;
  return jsonb_build_object('new', private.event_mark_checkin(e.id, v_uid, 'GPS'), 'event_id', e.id, 'club_id', e.club_id,
                            'title', e.title, 'distance_m', round(v_dist));
end $$;

-- Ban quản trị điểm danh tay: chỉ khi sự kiện đã bắt đầu
create or replace function public.staff_checkin(p_event_id uuid, p_user_id uuid, p_checked boolean) returns void
language plpgsql security definer set search_path = public as $$
declare e public.club_events := (select x from public.club_events x where x.id = p_event_id);
begin
  if e.id is null then raise exception 'EVENT_NOT_FOUND'; end if;
  perform private.require_staff(e.club_id);
  if not exists (select 1 from public.club_members where club_id = e.club_id and user_id = p_user_id and status = 'APPROVED') then
    raise exception 'NOT_A_MEMBER';
  end if;
  if p_checked then
    if e.status = 'CANCELLED' then raise exception 'EVENT_CANCELLED'; end if;
    if now() < e.starts_at then raise exception 'EVENT_NOT_STARTED'; end if;
    perform private.event_mark_checkin(e.id, p_user_id, 'STAFF');
  else
    update public.club_event_rsvps set checked_in_at = null, checkin_method = null, activity_id = null, updated_at = now()
     where event_id = e.id and user_id = p_user_id;
  end if;
end $$;

revoke all on function public.gps_checkin_club_event(uuid, double precision, double precision, double precision) from public, anon;
grant execute on function public.gps_checkin_club_event(uuid, double precision, double precision, double precision) to authenticated;
revoke all on function private.event_checkin_open(public.club_events) from public, anon, authenticated;
notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001014900_join_conquest.sql
-- ===================================================================
-- 014900: Thử thách chinh phục: tham gia BẮT BUỘC có hạng mục (như thử thách theo mục tiêu, 012000).
--   join_challenge_conquest(id, items, code): vào thử thách + đăng ký hạng mục trong CÙNG một giao dịch.
--   - Nhiều hạng mục: phải chọn ít nhất 1, không chọn thì không vào (CONQUEST_REQUIRED).
--   - Chỉ 1 hạng mục và không cần đặt mục tiêu riêng (FIXED / ANY): tự đăng ký hạng mục đó, items để trống.
--   - Chế độ SELF: luôn phải nhập mục tiêu của mình, kể cả khi chỉ có 1 hạng mục.
--   Dọn dữ liệu cũ: người đã tham gia nhưng chưa có hạng mục, ở thử thách chỉ có 1 hạng mục (FIXED / ANY) → tự đăng ký.
-- Chạy được trong SQL Editor, chạy lại an toàn.

create or replace function public.join_challenge_conquest(p_challenge_id uuid, p_items jsonb default null, p_code text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  c public.challenges;
  v_items jsonb := case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end;
  v_cats uuid[];
  v_join jsonb;
begin
  perform private.require_uid();
  c := (select x from public.challenges x where x.id = p_challenge_id);
  if c.id is null then raise exception 'CHALLENGE_NOT_FOUND'; end if;
  if c.objective not in ('BEST_TIME', 'BEST_PACE') then raise exception 'CONQUEST_NOT_SUPPORTED'; end if;
  if jsonb_array_length(v_items) = 0 then
    v_cats := array(select id from public.challenge_categories where challenge_id = c.id);
    if coalesce(array_length(v_cats, 1), 0) = 1 and c.conquest_mode in ('FIXED', 'ANY') then
      v_items := jsonb_build_array(jsonb_build_object('category_id', v_cats[1]));
    else
      raise exception 'CONQUEST_REQUIRED';
    end if;
  end if;
  v_join := public.join_challenge(p_challenge_id, p_code, null);
  perform public.set_my_conquest(p_challenge_id, v_items);   -- sai hạng mục / mục tiêu → cả giao dịch hoàn tác, không vào
  return coalesce(v_join, '{}'::jsonb) || jsonb_build_object('categories', jsonb_array_length(v_items));
end $$;

revoke all on function public.join_challenge_conquest(uuid, jsonb, text) from public, anon;
grant execute on function public.join_challenge_conquest(uuid, jsonb, text) to authenticated;

-- Dọn dữ liệu cũ: thử thách chỉ có 1 hạng mục, không cần mục tiêu riêng → người đã tham gia mà chưa chọn được gán hạng mục đó
do $$
declare
  r record;
begin
  for r in
    select p.id as pid, p.profile_id, p.challenge_id, cat.id as cat_id
      from public.challenges c
      join public.challenge_categories cat on cat.challenge_id = c.id
      join public.challenge_participants p on p.challenge_id = c.id and p.status <> 'LEFT'
     where c.objective in ('BEST_TIME', 'BEST_PACE') and c.conquest_mode in ('FIXED', 'ANY')
       and (select count(*) from public.challenge_categories x where x.challenge_id = c.id) = 1
       and not exists (select 1 from public.challenge_category_entries e where e.participant_id = p.id)
  loop
    insert into public.challenge_category_entries (participant_id, category_id, challenge_id, user_id)
    values (r.pid, r.cat_id, r.challenge_id, r.profile_id) on conflict do nothing;
    perform private.challenge_recompute_participant(r.pid);
  end loop;
end $$;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001015000_order_reminder_message.sql
-- ===================================================================
-- Admin tự nhập nội dung nhắc thanh toán (ví dụ kèm số tài khoản); bỏ trống thì dùng câu mặc định.
drop function if exists public.admin_remind_order(uuid);

create or replace function public.admin_remind_order(p_order_id uuid, p_message text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_admin();
  o public.orders := (select x from public.orders x where x.id = p_order_id for update);
  v_plan text; v_what text; v_body text := nullif(trim(coalesce(p_message, '')), '');
begin
  if o.id is null then raise exception 'ORDER_NOT_FOUND'; end if;
  if o.status <> 'PENDING' or o.expires_at <= now() then raise exception 'ORDER_NOT_PENDING'; end if;
  if o.reminded_at is not null and o.reminded_at > now() - interval '6 hours' then raise exception 'ORDER_REMIND_TOO_SOON'; end if;
  if v_body is not null and char_length(v_body) > 300 then raise exception 'MESSAGE_TOO_LONG'; end if;
  if v_body is null then
    if o.kind = 'PLAN' then
      v_plan := coalesce((select name from public.plans where code = o.plan_code), 'gói');
      v_what := 'kích hoạt ' || v_plan || coalesce(' ' || o.months || ' tháng', '');
    else
      v_what := 'nhận ' || (o.xu + o.bonus_xu) || ' Xu';
    end if;
    v_body := 'Hãy liên hệ với RaceHub và hoàn thành thủ tục thanh toán để ' || v_what
           || '. Chuyển khoản đúng nội dung ' || o.code || ' hoặc nhắn admin qua mục Liên hệ trong trang Gói.';
  end if;
  perform private.notify(o.buyer_id, null, 'ORDER_REMINDER', 'Đơn ' || o.code || ' đang chờ thanh toán', v_body, '/goi', v_uid, true);
  update public.orders set reminded_at = now() where id = o.id;
  insert into public.admin_audit_log (actor_id, action, target, new_value)
  values (v_uid, 'REMIND_ORDER', o.code, jsonb_build_object('kind', o.kind, 'amount_vnd', o.amount_vnd, 'custom_message', p_message is not null and trim(p_message) <> ''));
  return private.order_json((select x from public.orders x where x.id = o.id));
end $$;

revoke all on function public.admin_remind_order(uuid, text) from public, anon;
grant execute on function public.admin_remind_order(uuid, text) to authenticated;
notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001015100_feedback_bubble.sql
-- ===================================================================
-- 015100: HỘP THƯ GÓP Ý (bong bóng nổi trong app)
-- Người dùng gửi góp ý / điểm hài lòng / báo lỗi; admin xem và đánh dấu đã xử lý (Quản trị → Cộng đồng → Góp ý).
-- Chỉ ghi qua RPC (client không đụng bảng). Mỗi người tối đa 5 góp ý / 24 giờ. Chạy lại an toàn.
create table if not exists public.app_feedback (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  kind text not null check (kind in ('IDEA', 'BUG', 'LOVE', 'OTHER')),
  rating smallint check (rating between 1 and 5),
  body text not null default '' check (char_length(body) <= 1000),
  platform text,
  page text,
  status text not null default 'NEW' check (status in ('NEW', 'DONE')),
  admin_note text,
  handled_by uuid references public.profiles(id) on delete set null,
  handled_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists app_feedback_status_idx on public.app_feedback (status, created_at desc);
create index if not exists app_feedback_user_idx on public.app_feedback (user_id, created_at desc);
alter table public.app_feedback enable row level security;
revoke all on public.app_feedback from anon, authenticated;

-- Gửi góp ý: cần điểm hài lòng HOẶC lời nhắn (≥ 3 ký tự)
create or replace function public.submit_feedback(p_kind text, p_rating integer default null, p_body text default null,
                                                  p_platform text default null, p_page text default null) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_body text := trim(coalesce(p_body, ''));
begin
  if upper(coalesce(p_kind, '')) not in ('IDEA', 'BUG', 'LOVE', 'OTHER') then raise exception 'INVALID_FEEDBACK_KIND'; end if;
  if p_rating is not null and (p_rating < 1 or p_rating > 5) then raise exception 'INVALID_FEEDBACK_RATING'; end if;
  if char_length(v_body) > 1000 then raise exception 'FEEDBACK_TOO_LONG'; end if;
  if p_rating is null and char_length(v_body) < 3 then raise exception 'FEEDBACK_EMPTY'; end if;
  if (select count(*) from public.app_feedback f where f.user_id = v_uid and f.created_at > now() - interval '24 hours') >= 5 then
    raise exception 'FEEDBACK_RATE_LIMIT';
  end if;
  insert into public.app_feedback (user_id, kind, rating, body, platform, page)
  values (v_uid, upper(p_kind), p_rating, v_body, left(nullif(trim(coalesce(p_platform, '')), ''), 30), left(nullif(trim(coalesce(p_page, '')), ''), 120));
end $$;

-- Admin: danh sách góp ý (p_status: NEW | DONE | ALL) + số liệu tóm tắt
create or replace function public.admin_feedback_list(p_status text default 'NEW') returns jsonb
language plpgsql stable security definer set search_path = public, auth as $$
begin
  perform private.require_admin();
  return jsonb_build_object(
    'new_count', (select count(*) from public.app_feedback where status = 'NEW'),
    'avg_rating', (select round(avg(rating)::numeric, 2) from public.app_feedback where rating is not null),
    'rating_count', (select count(*) from public.app_feedback where rating is not null),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', x.id, 'user_id', x.user_id, 'name', private.display_name(x.user_id), 'email', u.email,
        'kind', x.kind, 'rating', x.rating, 'body', x.body, 'platform', x.platform, 'page', x.page,
        'status', x.status, 'admin_note', x.admin_note, 'handled_by', private.display_name(x.handled_by),
        'handled_at', x.handled_at, 'created_at', x.created_at) order by x.created_at desc)
      from (select * from public.app_feedback f
             where upper(coalesce(p_status, 'ALL')) = 'ALL' or f.status = upper(p_status)
             order by f.created_at desc limit 300) x
      left join auth.users u on u.id = x.user_id), '[]'::jsonb));
end $$;

-- Admin: đánh dấu đã xử lý / mở lại (kèm ghi chú)
create or replace function public.admin_feedback_set_status(p_id uuid, p_status text, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare v_admin uuid := private.require_admin();
begin
  if upper(coalesce(p_status, '')) not in ('NEW', 'DONE') then raise exception 'INVALID_FEEDBACK_STATUS'; end if;
  if not exists (select 1 from public.app_feedback where id = p_id) then raise exception 'FEEDBACK_NOT_FOUND'; end if;
  update public.app_feedback
     set status = upper(p_status), admin_note = nullif(trim(coalesce(p_note, '')), ''),
         handled_by = case when upper(p_status) = 'DONE' then v_admin end,
         handled_at = case when upper(p_status) = 'DONE' then now() end
   where id = p_id;
end $$;

revoke all on function public.submit_feedback(text, integer, text, text, text),
  public.admin_feedback_list(text), public.admin_feedback_set_status(uuid, text, text) from public, anon;
grant execute on function public.submit_feedback(text, integer, text, text, text),
  public.admin_feedback_list(text), public.admin_feedback_set_status(uuid, text, text) to authenticated;
notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001015200_strava_account_identity.sql
-- ===================================================================
-- 015200: HIỂN THỊ TÀI KHOẢN STRAVA ĐÃ LIÊN KẾT
-- Trước đây chỉ lưu athlete id → người dùng không biết mình nối với Strava nào, admin không kiểm tra được.
-- Nay lưu thêm tên, username, ảnh đại diện (lấy từ Strava lúc nối / lúc đồng bộ):
--   • my_provider_connections() trả thêm tên, username, ảnh → trang Tôi hiển thị cho người dùng
--   • admin_user_detail() trả thêm object "strava" → Quản trị → Người dùng
-- Kết nối cũ chưa có tên: app tự bổ sung ở lần đồng bộ kế tiếp (set_provider_identity).

alter table public.connected_accounts add column if not exists external_name text;
alter table public.connected_accounts add column if not exists external_username text;
alter table public.connected_accounts add column if not exists external_avatar_url text;
alter table public.connected_accounts add column if not exists identity_synced_at timestamptz;

-- Chuẩn hóa thông tin hồ sơ nhà cung cấp: cắt độ dài, ảnh chỉ nhận https
create or replace function private.provider_identity_clean(p_identity jsonb) returns jsonb
language sql immutable as $$
  select jsonb_build_object(
    'name', nullif(left(trim(coalesce(p_identity->>'name', '')), 80), ''),
    'username', nullif(left(trim(coalesce(p_identity->>'username', '')), 60), ''),
    'avatar_url', case when coalesce(p_identity->>'avatar_url', '') ~ '^https://' then left(p_identity->>'avatar_url', 500) end)
$$;

-- Nối tài khoản (chỉ server gọi): thêm p_identity {name, username, avatar_url}. Thay hàm 7 tham số cũ.
drop function if exists public.link_provider_connection(uuid, text, text, text, text, timestamptz, text[]);
create or replace function public.link_provider_connection(
  p_user_id uuid, p_provider text, p_external_user_id text, p_access_token text,
  p_refresh_token text, p_expires_at timestamptz, p_scopes text[] default null, p_identity jsonb default null
) returns void
language plpgsql security definer set search_path = public as $$
declare v_id jsonb := private.provider_identity_clean(p_identity);
begin
  if exists (select 1 from public.connected_accounts
              where provider = p_provider and provider_user_id = p_external_user_id and user_id <> p_user_id) then
    raise exception 'PROVIDER_ACCOUNT_CONFLICT';
  end if;
  delete from public.connected_accounts where user_id = p_user_id and provider = p_provider;
  insert into public.connected_accounts (user_id, provider, provider_user_id, access_token, refresh_token, expires_at,
                                         external_name, external_username, external_avatar_url, identity_synced_at)
  values (p_user_id, p_provider, p_external_user_id, p_access_token, p_refresh_token, p_expires_at,
          v_id->>'name', v_id->>'username', v_id->>'avatar_url', case when p_identity is not null then now() end);
  if p_provider = 'STRAVA' then
    update public.profiles set strava_connected = true, strava_athlete_id = p_external_user_id, updated_at = now()
     where id = p_user_id;
  end if;
end $$;
revoke all on function public.link_provider_connection(uuid, text, text, text, text, timestamptz, text[], jsonb) from public, anon, authenticated;
grant execute on function public.link_provider_connection(uuid, text, text, text, text, timestamptz, text[], jsonb) to service_role;

-- Bổ sung / cập nhật tên + ảnh cho kết nối đã có (chỉ server gọi)
create or replace function public.set_provider_identity(p_user_id uuid, p_provider text, p_identity jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare v_id jsonb := private.provider_identity_clean(p_identity);
begin
  update public.connected_accounts
     set external_name = v_id->>'name', external_username = v_id->>'username',
         external_avatar_url = v_id->>'avatar_url', identity_synced_at = now()
   where user_id = p_user_id and provider = p_provider;
end $$;
revoke all on function public.set_provider_identity(uuid, text, jsonb) from public, anon, authenticated;
grant execute on function public.set_provider_identity(uuid, text, jsonb) to service_role;

-- Người dùng tự xem nguồn đã kết nối (không lộ token)
drop function if exists public.my_provider_connections();
create or replace function public.my_provider_connections() returns table (
  provider text, provider_user_id text, connected_at timestamptz, last_synced_at timestamptz,
  external_name text, external_username text, external_avatar_url text)
language sql stable security definer set search_path = public as $$
  select provider, provider_user_id, created_at, last_synced_at, external_name, external_username, external_avatar_url
    from public.connected_accounts where user_id = auth.uid()
$$;
revoke all on function public.my_provider_connections() from public, anon;
grant execute on function public.my_provider_connections() to authenticated;

-- Admin: hồ sơ người dùng kèm tài khoản Strava đã nối (bản 005600 + khóa "strava")
create or replace function public.admin_user_detail(p_user uuid) returns jsonb
language plpgsql stable security definer set search_path = public, auth as $$
declare
  pr public.profiles := (select x from public.profiles x where x.id = p_user);
  au jsonb := (select to_jsonb(u) from auth.users u where u.id = p_user);
begin
  perform private.require_admin();
  if pr.id is null then raise exception 'USER_NOT_FOUND'; end if;
  return jsonb_build_object(
    'id', pr.id, 'display_name', pr.display_name, 'avatar_url', pr.avatar_url, 'role', coalesce(pr.role, 'MEMBER'),
    'level', pr.level, 'xp', pr.xp, 'balance', private.balance(pr.id), 'created_at', pr.created_at,
    'email', au->>'email', 'last_sign_in_at', au->>'last_sign_in_at', 'banned_until', au->>'banned_until',
    'banned_at', pr.banned_at, 'banned_reason', pr.banned_reason,
    'strava_connected', coalesce((to_jsonb(pr)->>'strava_connected')::boolean, false),
    'strava', (select jsonb_build_object('athlete_id', c.provider_user_id, 'name', c.external_name, 'username', c.external_username,
                      'avatar_url', c.external_avatar_url, 'connected_at', c.created_at, 'last_synced_at', c.last_synced_at)
                 from public.connected_accounts c where c.user_id = pr.id and c.provider = 'STRAVA' limit 1),
    'referral_code', to_jsonb(pr)->>'referral_code',
    'referred_by', (select r.display_name from public.profiles r where r.id = (to_jsonb(pr)->>'referred_by')::uuid),
    'plan', private.active_plan(pr.id),
    'stats', jsonb_build_object(
      'runs', (select count(*) from public.activities a where a.user_id = pr.id and a.validation_status = 'APPROVED'),
      'km', (select round(coalesce(sum(coalesce(nullif(a.moving_distance_m, 0), a.distance_m, 0)), 0) / 1000.0, 1)
               from public.activities a where a.user_id = pr.id and a.validation_status = 'APPROVED'),
      'pending_runs', (select count(*) from public.activities a where a.user_id = pr.id and a.validation_status = 'PENDING'),
      'last_run_at', (select max(a.started_at) from public.activities a where a.user_id = pr.id),
      'challenges', (select count(*) from public.challenge_participants c where c.profile_id = pr.id and c.status <> 'LEFT'),
      'orders_paid_vnd', (select coalesce(sum(o.amount_vnd), 0) from public.orders o where o.buyer_id = pr.id and o.status = 'PAID')),
    'clubs', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'role', m.role, 'status', m.status) order by c.name), '[]'::jsonb)
                from public.club_members m join public.clubs c on c.id = m.club_id where m.user_id = pr.id and m.status in ('APPROVED', 'PENDING')),
    'ledger', (select coalesce(jsonb_agg(jsonb_build_object('type', x.type, 'description', x.description, 'amount', x.amount, 'at', x.created_at) order by x.created_at desc), '[]'::jsonb)
                 from (select t.type, t.reason as description, e.amount, t.created_at, row_number() over (order by t.created_at desc) as rn
                         from public.ledger_entries e join public.ledger_transactions t on t.id = e.transaction_id where e.account_id = pr.id) x where x.rn <= 15),
    'audit', (select coalesce(jsonb_agg(jsonb_build_object('action', x.action, 'actor', x.actor, 'reason', x.reason, 'at', x.created_at) order by x.created_at desc), '[]'::jsonb)
                from (select l.action, private.display_name(l.actor_id) as actor, coalesce(l.reason, l.new_value->>'reason', l.new_value->>'note') as reason, l.created_at,
                             row_number() over (order by l.created_at desc) as rn
                        from public.admin_audit_log l where l.target in ('user:' || pr.id, pr.id::text)) x where x.rn <= 15));
end $$;

revoke all on function public.admin_user_detail(uuid) from public, anon;
grant execute on function public.admin_user_detail(uuid) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001015300_my_upcoming_events.sql
-- ===================================================================
-- Khối "Sắp tới" ở trang chủ: lịch CLB chưa kết thúc của mọi CLB tôi là thành viên (đã duyệt), gần nhất trước.
-- Chỉ đọc; trả cùng dạng với club_events() kèm tên và màu CLB.
create or replace function public.my_upcoming_events(p_limit int default 5) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := private.require_uid();
begin
  return (select coalesce(jsonb_agg(x.j order by x.starts_at), '[]'::jsonb)
            from (select e.starts_at,
                         private.event_json(e, v_uid) || jsonb_build_object('club_name', c.name, 'club_accent', c.accent_color) as j
                    from public.club_events e
                    join public.club_members m on m.club_id = e.club_id and m.user_id = v_uid and m.status = 'APPROVED'
                    join public.clubs c on c.id = e.club_id
                   where e.status = 'SCHEDULED'
                     and e.starts_at + make_interval(mins => e.duration_min) >= now()
                   order by e.starts_at
                   limit greatest(1, least(coalesce(p_limit, 5), 20))) x);
end $$;

revoke all on function public.my_upcoming_events(int) from public, anon;
grant execute on function public.my_upcoming_events(int) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001015400_remind_club_event.sql
-- ===================================================================
-- Ban quản trị nhắc thành viên chưa đăng ký lịch CLB (thông báo đẩy "Chưa đăng ký: …").
-- Người nhận: thành viên đã duyệt chưa trả lời (hoặc còn dữ liệu cũ "Có thể"), trừ người bấm. Mỗi lịch nhắc tối đa 1 lần / 6 giờ.
alter table public.club_events add column if not exists nudged_at timestamptz;

create or replace function public.remind_club_event(p_event_id uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  e public.club_events := (select x from public.club_events x where x.id = p_event_id);
  v_uid uuid;
  r record;
  v_n integer := 0;
begin
  if e.id is null then raise exception 'EVENT_NOT_FOUND'; end if;
  v_uid := private.require_staff(e.club_id);
  if e.status = 'CANCELLED' then raise exception 'EVENT_CANCELLED'; end if;
  if e.starts_at + make_interval(mins => e.duration_min) < now() then raise exception 'EVENT_ENDED'; end if;
  if e.nudged_at is not null and e.nudged_at > now() - interval '6 hours' then raise exception 'EVENT_REMIND_TOO_SOON'; end if;
  for r in select m.user_id
             from public.club_members m
             left join public.club_event_rsvps s on s.event_id = e.id and s.user_id = m.user_id
            where m.club_id = e.club_id and m.status = 'APPROVED' and m.user_id <> v_uid
              and (s.user_id is null or s.status = 'MAYBE') loop
    perform private.notify(r.user_id, e.club_id, 'CLUB_EVENT', 'Chưa đăng ký: ' || e.title,
      to_char(e.starts_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM') || coalesce(' · ' || e.location_name, '') || ' · bấm để chọn Tham gia hoặc Không tham gia',
      '/clubs/' || e.club_id || '/events/' || e.id, v_uid, true);
    v_n := v_n + 1;
  end loop;
  if v_n > 0 then update public.club_events set nudged_at = now() where id = e.id; end if;
  return v_n;
end $$;

revoke all on function public.remind_club_event(uuid) from public, anon;
grant execute on function public.remind_club_event(uuid) to authenticated;

notify pgrst, 'reload schema';

-- ===================================================================
-- 20261001015500_prize_shipping.sql
-- ===================================================================
-- 015500: Tặng phẩm (hiện vật) cho thử thách và giải chạy — người tham gia điền thông tin nhận, BTC xem danh sách.
-- • BTC (người tạo / ban quản trị CLB; giải chạy: cả admin hệ thống) khai báo tặng phẩm: mô tả, có cần cỡ áo không (+ các cỡ), hạn điền.
-- • Người đang tham gia (thử thách: chưa rời; giải chạy: chưa rút) điền họ tên, SĐT, địa chỉ, cỡ áo, ghi chú — sửa được tới hạn điền.
-- • BTC xem danh sách đầy đủ (kể cả người chưa điền) để đóng gói / xuất Excel. Người khác không đọc được SĐT, địa chỉ.
-- scope: 'CHALLENGE' | 'RACE'. Chạy lại nhiều lần vẫn an toàn. Không dùng SELECT … INTO, khối DO, LIMIT (SQL Editor).

create table if not exists public.prize_gifts (
  scope text not null,
  ref_id uuid not null,
  description text not null,
  needs_size boolean not null default false,
  size_options text[] not null default '{}',
  deadline timestamptz,
  created_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now(),
  primary key (scope, ref_id)
);
alter table public.prize_gifts drop constraint if exists prize_gifts_chk;
alter table public.prize_gifts add constraint prize_gifts_chk check (scope in ('CHALLENGE', 'RACE')
  and char_length(description) between 2 and 500 and cardinality(size_options) <= 12);

create table if not exists public.prize_addresses (
  scope text not null,
  ref_id uuid not null,
  user_id uuid not null references public.profiles(id) on delete cascade,
  full_name text not null,
  phone text not null,
  address text not null,
  size text,
  note text,
  updated_at timestamptz not null default now(),
  primary key (scope, ref_id, user_id)
);
alter table public.prize_addresses drop constraint if exists prize_addresses_chk;
alter table public.prize_addresses add constraint prize_addresses_chk check (scope in ('CHALLENGE', 'RACE'));
create index if not exists prize_addresses_user_idx on public.prize_addresses (user_id);

alter table public.prize_gifts enable row level security;
alter table public.prize_addresses enable row level security;
revoke all on public.prize_gifts, public.prize_addresses from anon, authenticated;

-- Quyền: 'MANAGER' | 'MEMBER' | null
create or replace function private.prize_role(p_scope text, p_ref uuid) returns text
language plpgsql stable security definer set search_path = public as $$
declare
  c public.challenges;
  r public.virtual_races;
begin
  if auth.uid() is null then return null; end if;
  if p_scope = 'CHALLENGE' then
    c := (select x from public.challenges x where x.id = p_ref);
    if c.id is null then return null; end if;
    if private.challenge_is_manager(c) or public.is_system_admin() then return 'MANAGER'; end if;
    if exists (select 1 from public.challenge_participants p
                where p.challenge_id = p_ref and p.profile_id = auth.uid() and p.status <> 'LEFT') then return 'MEMBER'; end if;
  elsif p_scope = 'RACE' then
    r := (select x from public.virtual_races x where x.id = p_ref);
    if r.id is null then return null; end if;
    if private.race_is_manager(r) then return 'MANAGER'; end if;
    if exists (select 1 from public.race_registrations g
                where g.race_id = p_ref and g.user_id = auth.uid() and g.status <> 'WITHDRAWN') then return 'MEMBER'; end if;
  end if;
  return null;
end $$;

-- p = { description, needs_size, size_options: ["S","M"…], deadline }. Mô tả rỗng = gỡ khai báo tặng phẩm (thông tin đã điền được giữ).
create or replace function public.set_prize_gift(p_scope text, p_ref uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  v_desc text := left(trim(coalesce(p->>'description', '')), 500);
  v_needs boolean := coalesce((p->>'needs_size')::boolean, false);
  v_sizes text[] := '{}';
  v_deadline timestamptz := nullif(p->>'deadline', '')::timestamptz;
  v_title text;
  v_new boolean;
  m record;
begin
  if p_scope not in ('CHALLENGE', 'RACE') then raise exception 'BAD_SCOPE'; end if;
  if private.prize_role(p_scope, p_ref) is distinct from 'MANAGER' then raise exception 'FORBIDDEN'; end if;
  if v_desc = '' then
    delete from public.prize_gifts where scope = p_scope and ref_id = p_ref;
    return jsonb_build_object('enabled', false);
  end if;
  if char_length(v_desc) < 2 then raise exception 'PRIZE_DESC_SHORT'; end if;
  if v_needs then
    v_sizes := (select coalesce(array_agg(s order by o), '{}')
                  from (select left(trim(e), 10) as s, min(o) as o
                          from jsonb_array_elements_text(coalesce(p->'size_options', '[]'::jsonb)) with ordinality t(e, o)
                         where trim(e) <> '' group by left(trim(e), 10)) z);
    if cardinality(v_sizes) = 0 then raise exception 'PRIZE_SIZES_EMPTY'; end if;
    if cardinality(v_sizes) > 12 then v_sizes := v_sizes[1:12]; end if;
  end if;
  v_new := not exists (select 1 from public.prize_gifts where scope = p_scope and ref_id = p_ref);
  insert into public.prize_gifts (scope, ref_id, description, needs_size, size_options, deadline, created_by, updated_at)
    values (p_scope, p_ref, v_desc, v_needs, v_sizes, v_deadline, v_uid, now())
  on conflict (scope, ref_id) do update set description = excluded.description, needs_size = excluded.needs_size,
    size_options = excluded.size_options, deadline = excluded.deadline, updated_at = now();
  if v_new then
    if p_scope = 'CHALLENGE' then
      v_title := (select title from public.challenges where id = p_ref);
      for m in select p2.profile_id as uid from public.challenge_participants p2
                where p2.challenge_id = p_ref and p2.status <> 'LEFT' and p2.profile_id <> v_uid loop
        perform private.notify(m.uid, null, 'PRIZE_INFO', 'Có tặng phẩm: ' || v_title,
          'Vào thử thách, điền thông tin nhận tặng phẩm.', '/challenges/' || p_ref, v_uid, false);
      end loop;
    else
      v_title := (select title from public.virtual_races where id = p_ref);
      for m in select g.user_id as uid from public.race_registrations g
                where g.race_id = p_ref and g.status <> 'WITHDRAWN' and g.user_id <> v_uid loop
        perform private.notify(m.uid, null, 'PRIZE_INFO', 'Có tặng phẩm: ' || v_title,
          'Vào giải chạy, điền thông tin nhận tặng phẩm.', '/races/' || p_ref, v_uid, false);
      end loop;
    end if;
  end if;
  return jsonb_build_object('enabled', true);
end $$;

-- Trạng thái cho màn hình: người tham gia / BTC. Người ngoài nhận null.
create or replace function public.prize_gift_get(p_scope text, p_ref uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_role text := private.prize_role(p_scope, p_ref);
  g public.prize_gifts := (select x from public.prize_gifts x where x.scope = p_scope and x.ref_id = p_ref);
  a public.prize_addresses := (select x from public.prize_addresses x where x.scope = p_scope and x.ref_id = p_ref and x.user_id = auth.uid());
begin
  if v_role is null then return null; end if;
  if g.ref_id is null then
    return jsonb_build_object('enabled', false, 'can_manage', v_role = 'MANAGER');
  end if;
  return jsonb_build_object(
    'enabled', true, 'can_manage', v_role = 'MANAGER', 'is_member', v_role = 'MEMBER',
    'description', g.description, 'needs_size', g.needs_size, 'size_options', to_jsonb(g.size_options), 'deadline', g.deadline,
    'closed', g.deadline is not null and now() > g.deadline,
    'mine', case when a.user_id is null then null else jsonb_build_object(
      'full_name', a.full_name, 'phone', a.phone, 'address', a.address, 'size', a.size, 'note', a.note, 'updated_at', a.updated_at) end,
    'filled_count', case when v_role = 'MANAGER' then (select count(*) from public.prize_addresses x where x.scope = p_scope and x.ref_id = p_ref) end);
end $$;

-- p = { full_name, phone, address, size, note }
create or replace function public.save_prize_address(p_scope text, p_ref uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := private.require_uid();
  g public.prize_gifts := (select x from public.prize_gifts x where x.scope = p_scope and x.ref_id = p_ref);
  v_name text := left(trim(coalesce(p->>'full_name', '')), 80);
  v_phone text := regexp_replace(coalesce(p->>'phone', ''), '[\s.\-()]', '', 'g');
  v_addr text := left(trim(coalesce(p->>'address', '')), 300);
  v_size text := nullif(left(trim(coalesce(p->>'size', '')), 10), '');
  v_note text := nullif(left(trim(coalesce(p->>'note', '')), 200), '');
begin
  if g.ref_id is null then raise exception 'PRIZE_NOT_ENABLED'; end if;
  if private.prize_role(p_scope, p_ref) is null then raise exception 'FORBIDDEN'; end if;
  if g.deadline is not null and now() > g.deadline then raise exception 'PRIZE_CLOSED'; end if;
  if char_length(v_name) < 2 then raise exception 'PRIZE_NAME_INVALID'; end if;
  if v_phone !~ '^\+?[0-9]{9,12}$' then raise exception 'PRIZE_PHONE_INVALID'; end if;
  if char_length(v_addr) < 10 then raise exception 'PRIZE_ADDRESS_INVALID'; end if;
  if g.needs_size then
    if v_size is null or not (v_size = any (g.size_options)) then raise exception 'PRIZE_SIZE_INVALID'; end if;
  else
    v_size := null;
  end if;
  insert into public.prize_addresses (scope, ref_id, user_id, full_name, phone, address, size, note, updated_at)
    values (p_scope, p_ref, v_uid, v_name, v_phone, v_addr, v_size, v_note, now())
  on conflict (scope, ref_id, user_id) do update set full_name = excluded.full_name, phone = excluded.phone,
    address = excluded.address, size = excluded.size, note = excluded.note, updated_at = now();
  return public.prize_gift_get(p_scope, p_ref);
end $$;

-- Danh sách cho BTC: mọi người đang tham gia, kèm thông tin nhận (nếu đã điền). Dễ nối vào file xuất Excel.
create or replace function public.prize_recipients(p_scope text, p_ref uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if private.prize_role(p_scope, p_ref) is distinct from 'MANAGER' then raise exception 'FORBIDDEN'; end if;
  if p_scope = 'CHALLENGE' then
    return (select coalesce(jsonb_agg(jsonb_build_object(
        'user_id', p.profile_id, 'display_name', pr.display_name, 'status', p.status, 'ref_label', null::text,
        'filled', a.user_id is not null, 'full_name', a.full_name, 'phone', a.phone, 'address', a.address,
        'size', a.size, 'note', a.note, 'updated_at', a.updated_at)
        order by (a.user_id is null), pr.display_name), '[]'::jsonb)
      from public.challenge_participants p
      join public.profiles pr on pr.id = p.profile_id
      left join public.prize_addresses a on a.scope = 'CHALLENGE' and a.ref_id = p.challenge_id and a.user_id = p.profile_id
     where p.challenge_id = p_ref and p.status <> 'LEFT');
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
      'user_id', g.user_id, 'display_name', pr.display_name, 'status', g.status, 'ref_label', g.bib || ' · ' || g.distance_km || ' km',
      'filled', a.user_id is not null, 'full_name', a.full_name, 'phone', a.phone, 'address', a.address,
      'size', a.size, 'note', a.note, 'updated_at', a.updated_at)
      order by (a.user_id is null), g.bib), '[]'::jsonb)
    from public.race_registrations g
    join public.profiles pr on pr.id = g.user_id
    left join public.prize_addresses a on a.scope = 'RACE' and a.ref_id = g.race_id and a.user_id = g.user_id
   where g.race_id = p_ref and g.status <> 'WITHDRAWN');
end $$;

revoke all on function private.prize_role(text, uuid) from public, anon, authenticated;
revoke all on function public.set_prize_gift(text, uuid, jsonb), public.prize_gift_get(text, uuid),
  public.save_prize_address(text, uuid, jsonb), public.prize_recipients(text, uuid) from public, anon;
grant execute on function public.set_prize_gift(text, uuid, jsonb), public.prize_gift_get(text, uuid),
  public.save_prize_address(text, uuid, jsonb), public.prize_recipients(text, uuid) to authenticated;

